	/** Register private admin and REST surfaces. */
	public static function boot() {
		add_action( 'admin_menu', array( __CLASS__, 'admin_menu' ) );
		add_action( 'admin_enqueue_scripts', array( __CLASS__, 'enqueue_admin_assets' ) );
		add_action( 'rest_api_init', array( __CLASS__, 'register_routes' ) );
		add_action( 'complete99_campaign_activate', array( __CLASS__, 'cron_activate' ), 10, 3 );
		add_action( 'complete99_campaign_expire', array( __CLASS__, 'cron_expire' ), 10, 3 );
		add_action( 'complete99_campaign_verify_readback', array( __CLASS__, 'cron_verify_readback' ), 10, 3 );
		add_action( 'complete99_campaign_reconcile_schedules', array( __CLASS__, 'reconcile_schedules' ) );
		add_action( 'wp_footer', array( __CLASS__, 'render_public_placement' ), 20 );
		add_action( 'init', array( __CLASS__, 'ensure_reconcile_trigger' ), 45 );
		add_action( 'admin_init', array( __CLASS__, 'ensure_reconcile_trigger' ), 45 );
		add_action( 'template_redirect', array( __CLASS__, 'enforce_public_slot_no_cache' ), 0 );
		add_action( 'admin_post_complete99_campaign_evidence', array( __CLASS__, 'serve_private_evidence' ) );
		add_action( 'wp_enqueue_scripts', array( __CLASS__, 'enqueue_public_assets' ) );
		add_filter( 'pre_delete_attachment', array( __CLASS__, 'guard_private_evidence_delete' ), 10, 3 );
		add_filter( 'pre_trash_post', array( __CLASS__, 'guard_private_evidence_trash' ), 10, 3 );
		add_filter( 'wp_insert_post_data', array( __CLASS__, 'guard_private_evidence_post_update' ), 10, 2 );
		add_filter( 'update_attached_file', array( __CLASS__, 'guard_private_evidence_file_move' ), 10, 2 );
		add_filter( 'map_meta_cap', array( __CLASS__, 'map_private_evidence_meta_cap' ), 10, 4 );
		add_filter( 'ajax_query_attachments_args', array( __CLASS__, 'exclude_private_evidence_query' ) );
		add_filter( 'rest_attachment_query', array( __CLASS__, 'exclude_private_evidence_query' ) );
		add_filter( 'posts_results', array( __CLASS__, 'exclude_private_evidence_posts' ), 10, 2 );
		add_filter( 'wp_prepare_attachment_for_js', array( __CLASS__, 'hide_private_evidence_attachment_js' ), 10, 3 );
		add_filter( 'wp_get_attachment_url', array( __CLASS__, 'hide_private_evidence_attachment_url' ), 10, 2 );
		add_filter( 'rest_prepare_attachment', array( __CLASS__, 'deny_private_evidence_rest_item' ), 10, 3 );
		add_action( 'woocommerce_before_product_object_save', array( __CLASS__, 'begin_woocommerce_authority_write' ), PHP_INT_MIN );
		add_action( 'woocommerce_after_product_object_save', array( __CLASS__, 'end_woocommerce_authority_write' ), PHP_INT_MAX );
		add_action( 'woocommerce_product_before_set_stock', array( __CLASS__, 'begin_woocommerce_authority_write' ), PHP_INT_MIN );
		add_action( 'woocommerce_variation_before_set_stock', array( __CLASS__, 'begin_woocommerce_authority_write' ), PHP_INT_MIN );
		add_action( 'woocommerce_product_set_stock', array( __CLASS__, 'end_woocommerce_authority_write' ), PHP_INT_MAX );
		add_action( 'woocommerce_variation_set_stock', array( __CLASS__, 'end_woocommerce_authority_write' ), PHP_INT_MAX );
		/* Core writers can run before init; install their fence before any plugin boot callback can mutate authority. */
		self::register_runtime_authority_writer_hooks();
	}

	/**
	 * Fence normal WordPress metadata, role and accountable-user writers.
	 *
	 * Registration is immediate and idempotent. Platform migrations retain one
	 * outer Campaign authority fence across their transaction, so these hooks
	 * nest under the same advisory boundary instead of leaving a pre-init gap.
	 */
	public static function register_runtime_authority_writer_hooks() {
		if ( self::$authority_hooks_registered ) { return; }
		self::$authority_hooks_registered = true;
		foreach ( array( 'add_post_meta', 'update_post_meta', 'delete_post_meta' ) as $hook ) {
			add_action( $hook, array( __CLASS__, 'begin_governed_post_meta_write' ), PHP_INT_MIN, 4 );
		}
		foreach ( array( 'added_post_meta', 'updated_post_meta', 'deleted_post_meta' ) as $hook ) {
			add_action( $hook, array( __CLASS__, 'end_governed_post_meta_write' ), PHP_INT_MAX, 4 );
		}
		foreach ( array( 'add_user_meta', 'update_user_meta', 'delete_user_meta' ) as $hook ) {
			add_action( $hook, array( __CLASS__, 'begin_accountable_user_meta_write' ), PHP_INT_MIN, 4 );
		}
		foreach ( array( 'added_user_meta', 'updated_user_meta', 'deleted_user_meta' ) as $hook ) {
			add_action( $hook, array( __CLASS__, 'end_accountable_user_meta_write' ), PHP_INT_MAX, 4 );
		}
		foreach ( array( 'add_option', 'update_option', 'delete_option' ) as $hook ) {
			add_action( $hook, array( __CLASS__, 'begin_governed_authority_option_write' ), PHP_INT_MIN, 3 );
		}
		foreach ( array( 'added_option', 'updated_option', 'deleted_option' ) as $hook ) {
			add_action( $hook, array( __CLASS__, 'end_governed_authority_option_write' ), PHP_INT_MAX, 3 );
		}
		add_action( 'pre_post_update', array( __CLASS__, 'begin_governed_post_row_write' ), PHP_INT_MIN, 2 );
		add_action( 'post_updated', array( __CLASS__, 'end_governed_post_row_write' ), PHP_INT_MAX, 3 );
		add_action( 'attachment_updated', array( __CLASS__, 'end_governed_post_row_write' ), PHP_INT_MAX, 3 );
		foreach ( array( 'wp_trash_post', 'untrash_post', 'before_delete_post', 'delete_attachment' ) as $hook ) {
			add_action( $hook, array( __CLASS__, 'begin_governed_post_row_write' ), PHP_INT_MIN, 2 );
		}
		foreach ( array( 'trashed_post', 'untrashed_post', 'deleted_post' ) as $hook ) {
			add_action( $hook, array( __CLASS__, 'end_governed_post_row_write' ), PHP_INT_MAX, 3 );
		}
		add_filter( 'wp_pre_insert_user_data', array( __CLASS__, 'begin_accountable_user_row_write' ), PHP_INT_MIN, 4 );
		add_action( 'profile_update', array( __CLASS__, 'end_accountable_user_row_write' ), PHP_INT_MAX, 3 );
		add_action( 'user_register', array( __CLASS__, 'end_accountable_user_row_write' ), PHP_INT_MAX, 2 );
		add_action( 'delete_user', array( __CLASS__, 'begin_accountable_user_delete' ), PHP_INT_MIN, 3 );
		add_action( 'wpmu_delete_user', array( __CLASS__, 'begin_accountable_user_delete' ), PHP_INT_MIN, 2 );
		add_action( 'deleted_user', array( __CLASS__, 'end_accountable_user_delete' ), PHP_INT_MAX, 3 );
	}

	private static function governed_authority_meta_keys() {
		return array_fill_keys(
			array(
				'_sku', '_price', '_stock_status', '_stock', '_backorders', '_thumbnail_id',
				'_wp_attached_file', '_complete99_live_catalog_asset_sha256', '_complete99_live_catalog_relation_digest',
				Complete99_Live_Catalog::META_ASSET_MANAGED,
				'_complete99_campaign_asset_scope', '_complete99_campaign_asset_location_id', '_complete99_campaign_public_use',
				'_complete99_source_sha256', '_complete99_rights_status', '_complete99_scan_status', '_complete99_ai_generated_food_photo',
				Complete99_Commerce::PRODUCT_APPROVED, Complete99_Commerce::MEDIA_PUBLIC_SAFE, Complete99_Commerce::LABEL_REVIEWED,
				Complete99_Commerce::ALLERGENS_HE, Complete99_Commerce::ALLERGENS_EN, Complete99_Commerce::NAME_HE,
				Complete99_Commerce::NAME_EN, Complete99_Commerce::DESCRIPTION_HE, Complete99_Commerce::DESCRIPTION_EN,
			),
			true
		);
	}

	private static function authority_hook_meta_key( $args ) {
		$args = array_values( (array) $args );
		/* add_*_meta carries object,key; every other core metadata hook carries meta-id(s),object,key. */
		$candidate = isset( $args[0], $args[1] ) && is_numeric( $args[0] ) && is_string( $args[1] )
			? $args[1]
			: ( isset( $args[1], $args[2] ) && is_numeric( $args[1] ) && is_string( $args[2] ) ? $args[2] : '' );
		return (string) $candidate;
	}

	/** Push every before-hook frame so a nested ungoverned write cannot release its governed parent. */
	private static function begin_runtime_authority_hook( $scope, $source, $governed ) {
		$scope = (string) $scope;
		$governed = true === $governed;
		if ( $governed ) {
			$fenced = self::begin_authority_write( (string) $source );
			if ( is_wp_error( $fenced ) ) { throw new \RuntimeException( $fenced->get_error_message() ); }
			/* Keep authority and origin truth immutable throughout a global quarantine epoch. */
			$quarantine = self::public_quarantine_status( false );
			if ( ! empty( $quarantine['active'] ) ) {
				self::end_authority_write();
				throw new \RuntimeException( 'Governed authority writes are paused while public quarantine reconciliation is active.' );
			}
		}
		if ( ! isset( self::$authority_hook_pending[ $scope ] ) || ! is_array( self::$authority_hook_pending[ $scope ] ) ) {
			self::$authority_hook_pending[ $scope ] = array();
		}
		self::$authority_hook_pending[ $scope ][] = array( 'governed' => $governed, 'source' => $governed ? (string) $source : '' );
	}

	private static function end_runtime_authority_hook( $scope ) {
		$scope = (string) $scope;
		if ( empty( self::$authority_hook_pending[ $scope ] ) || ! is_array( self::$authority_hook_pending[ $scope ] ) ) {
			throw new \RuntimeException( 'Authority hook nesting could not be proven.' );
		}
		$frame = array_pop( self::$authority_hook_pending[ $scope ] );
		if ( empty( self::$authority_hook_pending[ $scope ] ) ) { unset( self::$authority_hook_pending[ $scope ] ); }
		if ( true === ( $frame['governed'] ?? false ) && ! self::end_authority_write() ) { throw new \RuntimeException( 'Authority lock release could not be proven.' ); }
	}

	private static function governed_post_meta_write_identity( $args ) {
		$args = array_values( (array) $args );
		$post_id = 0;
		$meta_key = '';
		if ( isset( $args[0], $args[1] ) && is_numeric( $args[0] ) && is_string( $args[1] ) ) {
			$post_id = (int) $args[0];
			$meta_key = (string) $args[1];
		} elseif ( isset( $args[1], $args[2] ) && is_numeric( $args[1] ) && is_string( $args[2] ) ) {
			$post_id = (int) $args[1];
			$meta_key = (string) $args[2];
		}
		if ( '' === $meta_key ) { return array( 'postId' => 0, 'metaKey' => '', 'postType' => '', 'deleteAll' => false ); }
		return array( 'postId' => $post_id, 'metaKey' => $meta_key, 'postType' => 0 < $post_id ? self::governed_authority_post_type( $post_id ) : '', 'deleteAll' => 0 === $post_id );
	}

	public static function begin_governed_post_meta_write( ...$args ) {
		$identity = self::governed_post_meta_write_identity( $args );
		/* delete_metadata(..., delete_all=true) has object_id=0 and can span governed posts. */
		$governed = true === ( $identity['deleteAll'] ?? false ) || '' !== (string) $identity['postType'];
		self::begin_runtime_authority_hook( 'post_meta', 'wordpress_authority', $governed );
	}

	public static function end_governed_post_meta_write( ...$args ) {
		self::end_runtime_authority_hook( 'post_meta' );
	}

	private static function is_accountable_user_meta_key( $key ) {
		global $wpdb;
		$key = (string) $key;
		$base = (string) ( $wpdb->base_prefix ?? $wpdb->prefix );
		if ( '' === $base ) { return false; }
		return 1 === preg_match( '/\A' . preg_quote( $base, '/' ) . '(?:[1-9][0-9]*_)?(?:capabilities|user_level)\z/D', $key );
	}

	public static function begin_accountable_user_meta_write( ...$args ) {
		self::begin_runtime_authority_hook( 'user_meta', 'accountable_user', self::is_accountable_user_meta_key( self::authority_hook_meta_key( $args ) ) );
	}

	public static function end_accountable_user_meta_write( ...$args ) {
		self::end_runtime_authority_hook( 'user_meta' );
	}

	private static function governed_authority_option_keys() {
		global $wpdb;
		$catalog_receipt = class_exists( 'Complete99_Live_Catalog', false ) ? Complete99_Live_Catalog::OPTION_RECEIPT : 'complete99_live_catalog_receipt';
		$catalog_recovery = class_exists( 'Complete99_Live_Catalog', false ) ? Complete99_Live_Catalog::OPTION_RECOVERY : 'complete99_live_catalog_recovery_required';
		return array_fill_keys( array( $wpdb->get_blog_prefix( get_current_blog_id() ) . 'user_roles', 'home', 'siteurl', 'permalink_structure', 'woocommerce_shop_page_id', 'woocommerce_currency', $catalog_receipt, $catalog_recovery ), true );
	}

	private static function args_contain_governed_authority_option( $args ) {
		$allowed = self::governed_authority_option_keys();
		$args = array_values( (array) $args );
		return isset( $args[0] ) && is_string( $args[0] ) && isset( $allowed[ $args[0] ] );
	}

	/** Origin mutation is serialized behind every durable public-absence cleanup obligation. */
	private static function pending_public_cleanup_exists() {
		global $wpdb;
		$empty_digest = hash( 'sha256', self::canonical_json( self::empty_cleanup_queue() ) );
		$wpdb->last_error = '';
		$pending = $wpdb->get_var( $wpdb->prepare( "SELECT id FROM " . self::table_names()['campaigns'] . " WHERE cleanup_queue_digest<>%s OR cleanup_due_at IS NOT NULL ORDER BY id ASC LIMIT 1", $empty_digest ) );
		if ( '' !== (string) $wpdb->last_error ) { throw new \RuntimeException( 'Campaign cleanup origin fence could not be inspected.' ); }
		return null !== $pending;
	}

	public static function begin_governed_authority_option_write( ...$args ) {
		$governed = self::args_contain_governed_authority_option( $args );
		self::begin_runtime_authority_hook( 'authority_option', 'wordpress_authority', $governed );
		$key = isset( $args[0] ) && is_string( $args[0] ) ? (string) $args[0] : '';
		if ( $governed && in_array( $key, array( 'home', 'siteurl', 'permalink_structure', 'woocommerce_shop_page_id' ), true ) ) {
			try { $pending = self::pending_public_cleanup_exists(); } catch ( \Throwable $error ) { self::end_runtime_authority_hook( 'authority_option' ); throw $error; }
			if ( $pending ) { self::end_runtime_authority_hook( 'authority_option' ); throw new \RuntimeException( 'Public origin changes are paused until exact campaign cleanup proof is complete.' ); }
		}
	}

	public static function end_governed_authority_option_write( ...$args ) {
		self::end_runtime_authority_hook( 'authority_option' );
	}

	private static function governed_authority_post_type( $post_id, $post = null ) {
		global $wpdb;
		$post_id = (int) $post_id;
		$post_type = is_object( $post ) && is_string( $post->post_type ?? null ) ? (string) $post->post_type : '';
		if ( '' === $post_type && is_array( $post ) && is_string( $post['post_type'] ?? null ) ) { $post_type = (string) $post['post_type']; }
		$governed = array( 'product', 'product_variation', 'attachment' );
		if ( in_array( $post_type, $governed, true ) ) { return $post_type; }
		/* The exact Woo shop page is itself a public placement authority row. */
		$shop_page_id = function_exists( 'get_option' ) ? (int) get_option( 'woocommerce_shop_page_id', 0 ) : 0;
		if ( 0 < $post_id && 0 < $shop_page_id && $post_id === $shop_page_id ) { return 'complete99_shop_page'; }
		/* A pre-update may try to change a governed row to an ungoverned type. */
		if ( 0 < $post_id ) {
			$wpdb->last_error = '';
			$persisted_type = (string) $wpdb->get_var( $wpdb->prepare( "SELECT post_type FROM {$wpdb->posts} WHERE ID=%d LIMIT 1", $post_id ) );
			if ( '' !== (string) $wpdb->last_error ) { throw new \RuntimeException( 'Authority post type could not be inspected.' ); }
			if ( in_array( $persisted_type, $governed, true ) ) { return $persisted_type; }
		}
		return '';
	}

	public static function begin_governed_post_row_write( $post_id, $post = null ) {
		$post_type = self::governed_authority_post_type( $post_id, $post );
