		}
		$suppression_backlog = self::public_suppression_backlog_status();
		if ( empty( $suppression_backlog['ready'] ) || empty( $suppression_backlog['inspectable'] ) ) {
			throw new \RuntimeException( 'The Complete99 public-suppression aggregate backlog requires recovery.' );
		}
		self::assert_capabilities();
		return true;
	}

