	private static function prove_aggregate_cleanup_absence_records( $urls, $verified_at, $scope ) {
		$urls = array_values( array_unique( (array) $urls ) ); sort( $urls, SORT_STRING );
		if ( self::AGGREGATE_CLEANUP_MAX_URLS < count( $urls ) || count( $urls ) !== count( array_filter( $urls, array( __CLASS__, 'public_quarantine_url_is_safe' ) ) ) ) { return new WP_Error( 'complete99_campaign_aggregate_cleanup_urls', 'Aggregate cleanup page URLs are invalid.', array( 'status' => 503 ) ); }
