			try { do_action( 'litespeed_purge_url', $url ); } catch ( \Throwable $error ) { return new WP_Error( 'complete99_campaign_aggregate_cleanup_purge', 'Aggregate cleanup could not purge an exact historical surface.', array( 'status' => 503 ) ); }
			$response = wp_safe_remote_get( $url, array( 'timeout' => 5, 'redirection' => 0, 'limit_response_size' => 1048577, 'headers' => array( 'Cache-Control' => 'no-cache' ) ) );
			$code = is_wp_error( $response ) ? 0 : (int) wp_remote_retrieve_response_code( $response ); $body = is_wp_error( $response ) ? '' : (string) wp_remote_retrieve_body( $response );
