					if ( ! in_array( $scope, array( 'quarantine', 'lifecycle' ), true ) || ! in_array( $kind, array( 'cohort', 'page' ), true ) || ( 'cohort' === $kind ? -1 !== $page_index : 0 > $page_index ) ) { return new WP_Error( 'complete99_campaign_receipt_inventory_request', 'Aggregate receipt phase inventory request is malformed.', array( 'status' => 503 ) ); }
