					if ( 'public_quarantine' !== $scope || 1 > $request_generation || '' === self::public_quarantine_receipt_external_state( $phase ) ) { return new WP_Error( 'complete99_campaign_receipt_inventory_request', 'Quarantine receipt phase inventory request is malformed.', array( 'status' => 503 ) ); }
					$fixed = self::public_quarantine_receipt_fixed_identity( $request_generation, $phase ); $provider = 'complete99-public-quarantine';
					$expected[ $key ] = array( 'fixed' => $fixed, 'generation' => $request_generation, 'kind' => '', 'pageIndex' => -1, 'phase' => $phase );
				}
				if ( isset( $by_receipt[ $fixed['receiptId'] ] ) || isset( $by_external[ $fixed['externalId'] ] ) || isset( $by_event[ $fixed['eventId'] ] ) ) { return new WP_Error( 'complete99_campaign_receipt_inventory_identity', 'Receipt phase inventory identity collided.', array( 'status' => 503 ) ); }
				$by_receipt[ $fixed['receiptId'] ] = $key; $by_external[ $fixed['externalId'] ] = $key; $by_event[ $fixed['eventId'] ] = $key; $receipt_ids[] = $fixed['receiptId']; $external_ids[] = $fixed['externalId']; $event_ids[] = $fixed['eventId'];
			}
