			if ( '' !== $provider_error || '' !== (string) $wpdb->last_error || ! is_array( $provider_rows ) || ! is_array( $audit_rows ) || $provider_limit <= count( $provider_rows ) || $audit_limit <= count( $audit_rows ) ) { return new WP_Error( 'complete99_campaign_receipt_inventory_query', 'Receipt phase inventory is unavailable or exceeds its exact cardinality bound.', array( 'status' => 503 ) ); }
			$providers = array(); $audits = array();
			foreach ( $provider_rows as $row ) {
				$receipt_key = $by_receipt[ (string) ( $row['receipt_id'] ?? '' ) ] ?? null; $external_key = hash_equals( $provider, (string) ( $row['provider_key'] ?? '' ) ) ? ( $by_external[ (string) ( $row['external_id'] ?? '' ) ] ?? null ) : null;
				$keys = array_values( array_unique( array_filter( array( $receipt_key, $external_key ), 'is_string' ) ) );
				if ( 1 !== count( $keys ) ) { return new WP_Error( 'complete99_campaign_receipt_inventory_provider_collision', 'Receipt phase inventory provider selectors collide.', array( 'status' => 503 ) ); }
				$providers[ $keys[0] ][] = $row;
