				if ( 0 === $provider_count && 0 === $audit_count ) { $inventory[ $key ] = null; continue; }
				if ( 1 !== $provider_count || 1 !== $audit_count ) { return new WP_Error( 'complete99_campaign_receipt_inventory_cardinality', 'Receipt phase inventory contains a missing, duplicate, or asymmetric logical pair.', array( 'status' => 503 ) ); }
