				$expected_generation = (int) ( $request['generation'] ?? $generation );
				if ( ! is_array( $payload ) || 60000 < strlen( $json ) || ! hash_equals( $json, self::canonical_json( $payload ) ) || $expected_generation !== (int) ( $payload['epoch'] ?? $payload['generation'] ?? 0 ) ) { return new WP_Error( 'complete99_campaign_receipt_inventory_corrupt', 'Receipt phase inventory contains a noncanonical or wrongly versioned payload.', array( 'status' => 503 ) ); }
				if ( 'aggregate' === $family ) {
					$kind = $request['kind']; $identity = self::aggregate_cleanup_receipt_identity( $payload, $kind ); $exact_page = 'cohort' === $kind || (int) ( $payload['pageIndex'] ?? -1 ) === (int) $request['pageIndex'];
					$valid = $exact_page && hash_equals( $scope, (string) ( $payload['scope'] ?? '' ) ) && self::aggregate_cleanup_payload_valid( $payload, $kind ) && self::aggregate_cleanup_provider_row_matches( $provider_row, $payload, $kind, $identity ) && self::aggregate_cleanup_audit_row_matches( $audit_row, $identity );
				} else {
					$phase = $request['phase']; $identity = self::public_quarantine_receipt_identity( $payload, $phase );
					$valid = self::public_quarantine_provider_receipt_row_matches( $provider_row, $payload, $phase, $identity ) && self::public_quarantine_audit_row_matches( $audit_row, $identity );
				}
