				$inventory[ $key ] = $payload;
			}
		}
		if ( count( $inventory ) !== count( $requests ) ) { return new WP_Error( 'complete99_campaign_receipt_inventory_order', 'Receipt phase inventory does not cover its exact requested order.', array( 'status' => 503 ) ); }
		if ( ! isset( self::$receipt_phase_inventory_cache[ $cache_key ] ) && self::RECEIPT_PHASE_INVENTORY_CACHE_MAX <= count( self::$receipt_phase_inventory_cache ) ) { array_shift( self::$receipt_phase_inventory_cache ); }
		self::$receipt_phase_inventory_cache[ $cache_key ] = $inventory;
		return $inventory;
	}

	/** Bootstrap only the canonical cohort body; the batch verifier re-loads its provider and audit rows. */
