		$fixed = self::aggregate_cleanup_fixed_identity( (string) $scope, (int) $generation, (string) $kind, (int) $page_index ); $lock = $for_update && ! self::is_sqlite_database() ? ' FOR UPDATE' : ''; $table = self::table_names()['provider_receipts'];
