		return is_array( $payload ) && hash_equals( $json, self::canonical_json( $payload ) ) && (int) ( $payload['generation'] ?? 0 ) === (int) $generation && hash_equals( (string) ( $payload['scope'] ?? '' ), (string) $scope ) && self::aggregate_cleanup_payload_valid( $payload, $kind ) && self::aggregate_cleanup_receipt_matches( $payload, $kind, $for_update ) ? $payload : new WP_Error( 'complete99_campaign_aggregate_cleanup_receipt_corrupt', 'Aggregate cleanup receipt failed exact canonical binding.', array( 'status' => 503 ) );
