			foreach ( $inventory['pages'] as $page ) { $page_digests .= hex2bin( hash( 'sha256', self::canonical_json( $page ) ) ); }
			$page_count = count( $snapshot['pages'] );
			$stored_page_digests = self::AGGREGATE_CLEANUP_DIGEST_VECTOR_MAX_PAGES < $page_count ? hex2bin( self::aggregate_cleanup_page_digest_chain( (string) $scope, (int) $generation, $page_digests ) ) : $page_digests;
			$completed_at = gmdate( 'Y-m-d\TH:i:s\Z' ); $cohort = array( 'bindingDigest' => (string) $binding, 'cohortDigest' => (string) $snapshot['cohortDigest'], 'completedAt' => $completed_at, 'generation' => (int) $generation, 'obligationCount' => (int) $snapshot['obligationCount'], 'pageCount' => $page_count, 'pageDigestsBase64' => base64_encode( $stored_page_digests ), 'queueCount' => (int) $snapshot['queueCount'], 'schemaVersion' => 'complete99-aggregate-cleanup-cohort/v1', 'scope' => (string) $scope );
			$stored = self::store_aggregate_cleanup_receipt( $cohort, 'cohort' );
			return is_wp_error( $stored ) ? $stored : array( 'done' => false, 'progress' => true, 'kind' => 'receipt_cohort' );
		}
		if ( is_wp_error( $cohort ) || ! hash_equals( (string) $binding, (string) ( $cohort['bindingDigest'] ?? '' ) ) ) { return is_wp_error( $cohort ) ? $cohort : new WP_Error( 'complete99_campaign_aggregate_cleanup_cohort_stale', 'Aggregate cleanup cohort binding changed.', array( 'status' => 409 ) ); }
		$verified = self::verify_aggregate_cleanup_chain( (string) $scope, (int) $generation, hash( 'sha256', self::canonical_json( $cohort ) ), false );
		return is_wp_error( $verified ) ? $verified : self::aggregate_cleanup_clear_queue_batch( $verified['cohort'], array( 'pages' => $verified['pages'], 'queues' => $verified['queues'] ) );
	}

	/** qtn rows are deletable only as one class after every member is qtr and cleanup is empty. */
	private static function public_quarantine_qtr_gc_ready( $manifest ) {
		global $wpdb;
		$ids = array();
		foreach ( $manifest['ids'] as $index => $id ) { if ( false === ( $manifest['orphan'][ $index ] ?? true ) ) { $ids[] = (int) $id; } }
		foreach ( array_chunk( $ids, 200 ) as $batch ) {
			$placeholders = implode( ',', array_fill( 0, count( $batch ), '%d' ) );
			$lock = self::is_sqlite_database() ? '' : ' FOR UPDATE';
			$wpdb->last_error = '';
			$rows = $wpdb->get_results( $wpdb->prepare( "SELECT p.id,p.status,c.cleanup_queue_json,c.cleanup_queue_digest,c.cleanup_due_at,c.cleanup_revision FROM " . self::table_names()['placements'] . " p JOIN " . self::table_names()['campaigns'] . " c ON c.public_id=p.campaign_id WHERE p.id IN ({$placeholders}) ORDER BY p.id ASC{$lock}", $batch ), ARRAY_A );
			if ( '' !== (string) $wpdb->last_error || ! is_array( $rows ) || count( $rows ) !== count( $batch ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_qtr_rows', 'Recovered quarantine rows are missing or duplicated before GC.', array( 'status' => 503 ) ); }
			foreach ( $rows as $index => $row ) {
				if ( (int) ( $row['id'] ?? 0 ) !== (int) $batch[ $index ] ) { return new WP_Error( 'complete99_campaign_public_quarantine_qtr_rows', 'Recovered quarantine row order is invalid.', array( 'status' => 503 ) ); }
				if ( hash_equals( (string) $manifest['proof']['qtnStatus'], (string) ( $row['status'] ?? '' ) ) ) { return false; }
				if ( ! hash_equals( self::public_quarantine_recovered_status( (string) $manifest['proof']['qtnStatus'] ), (string) ( $row['status'] ?? '' ) ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_qtr_status', 'Recovered quarantine row truth is malformed.', array( 'status' => 503 ) ); }
				$queue = self::decode_cleanup_queue( $row );
				if ( is_wp_error( $queue ) ) { return $queue; }
				if ( ! empty( $queue['obligations'] ) || null !== ( $row['cleanup_due_at'] ?? null ) ) { return false; }
			}
		}
		return true;
	}

	/**
	 * Resolve one final epoch without campaign fan-out. The immutable final
	 * absence receipt authorizes a bounded qtn -> qtr placement transition;
	 * owner state remains historical until a later ordinary owner mutation.
	 */
	private static function reconcile_public_quarantine_epoch_resolution( $epoch ) {
		global $wpdb;
		$started = self::begin_transaction( self::CAPACITY_ROLE_QUARANTINE );
		if ( is_wp_error( $started ) ) { return $started; }
		$clear = self::assert_public_quarantine_clear( true );
		if ( is_wp_error( $clear ) ) { self::rollback_transaction(); return $clear; }
		$manifest = self::public_quarantine_final_receipt_manifest( (int) $epoch, true );
		$valid = is_wp_error( $manifest ) ? $manifest : self::validate_public_quarantine_manifest_rows( $manifest, true );
		if ( is_wp_error( $valid ) ) { self::rollback_transaction(); return $valid; }
		$qtn_status = (string) $manifest['proof']['qtnStatus'];
		$qtr_status = self::public_quarantine_recovered_status( $qtn_status );
		$lock = self::is_sqlite_database() ? '' : ' FOR UPDATE';
		$wpdb->last_error = '';
		$rows = $wpdb->get_results( $wpdb->prepare( "SELECT id,placement_id,public_digest,status FROM " . self::table_names()['placements'] . " WHERE status=%s ORDER BY id ASC LIMIT " . ( self::RECONCILE_BATCH_SIZE + 1 ) . $lock, $qtn_status ), ARRAY_A );
		if ( '' !== (string) $wpdb->last_error || ! is_array( $rows ) || self::RECONCILE_BATCH_SIZE + 1 < count( $rows ) ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_public_quarantine_resolution_query', 'Aggregate quarantine resolution could not inspect its bounded row batch.', array( 'status' => 503 ) ); }
		if ( empty( $rows ) ) { self::rollback_transaction(); return array( 'done' => true, 'progress' => false, 'epoch' => (int) $epoch ); }
		$membership = array_flip( $manifest['ids'] );
		$batch = array_slice( $rows, 0, self::RECONCILE_BATCH_SIZE );
		$changed_at = current_time( 'mysql', true );
		foreach ( $batch as $row ) {
			$id = is_numeric( $row['id'] ?? null ) ? (int) $row['id'] : 0;
			$index = $membership[ $id ] ?? null;
			if ( ! is_int( $index ) || true === ( $manifest['orphan'][ $index ] ?? true ) || ! preg_match( '/\Aplc_[a-f0-9]{48}\z/', (string) ( $row['placement_id'] ?? '' ) ) || ! preg_match( '/\A[a-f0-9]{64}\z/', (string) ( $row['public_digest'] ?? '' ) ) || ! hash_equals( $qtn_status, (string) ( $row['status'] ?? '' ) ) ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_public_quarantine_resolution_membership', 'Aggregate quarantine resolution found a row outside its immutable final receipt.', array( 'status' => 503 ) ); }
			$wpdb->last_error = '';
			$updated = $wpdb->update( self::table_names()['placements'], array( 'status' => $qtr_status, 'stopped_at' => $changed_at, 'updated_at' => $changed_at ), array( 'id' => $id, 'placement_id' => (string) $row['placement_id'], 'public_digest' => (string) $row['public_digest'], 'status' => $qtn_status ) );
			if ( 1 !== (int) $updated || '' !== (string) $wpdb->last_error ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_public_quarantine_resolution_cas', 'Aggregate quarantine resolution row changed concurrently.', array( 'status' => 409 ) ); }
		}
		$ids = array_map( 'intval', array_column( $batch, 'id' ) );
		$placeholders = implode( ',', array_fill( 0, count( $ids ), '%d' ) );
		$wpdb->last_error = '';
		$readback = $wpdb->get_results( $wpdb->prepare( "SELECT id,status FROM " . self::table_names()['placements'] . " WHERE id IN ({$placeholders}) ORDER BY id ASC{$lock}", $ids ), ARRAY_A );
		if ( '' !== (string) $wpdb->last_error || ! is_array( $readback ) || count( $readback ) !== count( $ids ) ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_public_quarantine_resolution_readback', 'Aggregate quarantine resolution failed exact row readback.', array( 'status' => 503 ) ); }
		foreach ( $readback as $index => $row ) { if ( (int) ( $row['id'] ?? 0 ) !== $ids[ $index ] || ! hash_equals( $qtr_status, (string) ( $row['status'] ?? '' ) ) ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_public_quarantine_resolution_readback', 'Aggregate quarantine resolution failed exact row readback.', array( 'status' => 503 ) ); } }
		$commit = self::commit_transaction();
		if ( is_wp_error( $commit ) ) {
			$wpdb->last_error = '';
			$fresh = $wpdb->get_results( $wpdb->prepare( "SELECT id,status FROM " . self::table_names()['placements'] . " WHERE id IN ({$placeholders}) ORDER BY id ASC", $ids ), ARRAY_A );
			if ( '' !== (string) $wpdb->last_error || ! is_array( $fresh ) || count( $fresh ) !== count( $ids ) ) { return $commit; }
			foreach ( $fresh as $index => $row ) { if ( (int) ( $row['id'] ?? 0 ) !== $ids[ $index ] || ! hash_equals( $qtr_status, (string) ( $row['status'] ?? '' ) ) ) { return $commit; } }
		}
		return array( 'done' => count( $rows ) <= self::RECONCILE_BATCH_SIZE, 'progress' => true, 'epoch' => (int) $epoch, 'rowCount' => count( $batch ) );
	}

	/** Execute one immutable class GC transition or <=50-row deletion. */
	private static function reconcile_public_quarantine_terminal_gc_class( $epoch, $class ) {
		global $wpdb;
		$started = self::begin_transaction( self::CAPACITY_ROLE_QUARANTINE );
		if ( is_wp_error( $started ) ) { return $started; }
		$clear = self::assert_public_quarantine_clear( true );
		if ( is_wp_error( $clear ) ) { self::rollback_transaction(); return $clear; }
		$manifest = self::public_quarantine_final_receipt_manifest( (int) $epoch, true );
		if ( is_wp_error( $manifest ) ) { self::rollback_transaction(); return $manifest; }
		$class_count = 'qto' === $class ? (int) $manifest['proof']['qtoCount'] : (int) $manifest['proof']['qtnCount'];
		if ( 0 === $class_count ) { self::rollback_transaction(); return array( 'done' => true, 'progress' => false ); }
		$intent = self::public_quarantine_gc_intent( $manifest, $class, true );
		if ( is_wp_error( $intent ) && ! self::public_quarantine_gc_receipt_is_missing( $intent ) ) { self::rollback_transaction(); return $intent; }
		if ( is_wp_error( $intent ) ) {
			$valid = self::validate_public_quarantine_manifest_rows( $manifest, true );
			if ( is_wp_error( $valid ) ) { self::rollback_transaction(); return $valid; }
			if ( 'qtr' === $class ) {
				$ready = self::public_quarantine_qtr_gc_ready( $manifest );
				if ( is_wp_error( $ready ) ) { self::rollback_transaction(); return $ready; }
				if ( ! $ready ) { self::rollback_transaction(); return array( 'done' => false, 'progress' => false ); }
			}
			$payload = self::public_quarantine_build_gc_intent_locked( $manifest, $class, gmdate( 'Y-m-d\TH:i:s\Z' ) );
			if ( is_wp_error( $payload ) ) { self::rollback_transaction(); return $payload; }
			$stored = self::store_public_quarantine_gc_receipt_locked( $payload, 'gc_' . $class . '_intent' );
			if ( is_wp_error( $stored ) ) { self::rollback_transaction(); return $stored; }
			$commit = self::commit_transaction();
			if ( is_wp_error( $commit ) ) {
				$fresh = self::public_quarantine_gc_intent( self::public_quarantine_final_receipt_manifest( (int) $epoch, false ), $class, false );
				if ( is_wp_error( $fresh ) || ! hash_equals( self::canonical_json( $payload ), self::canonical_json( (array) ( $fresh['proof'] ?? array() ) ) ) ) { return $commit; }
			}
			return array( 'done' => false, 'progress' => true );
		}
		$completion = self::public_quarantine_gc_completion( $intent, $class, true );
		if ( ! is_wp_error( $completion ) ) { self::rollback_transaction(); return array( 'done' => true, 'progress' => false ); }
		if ( ! self::public_quarantine_gc_receipt_is_missing( $completion ) ) { self::rollback_transaction(); return $completion; }
		$batch_state = self::public_quarantine_gc_batch_state( $intent, $class, true );
		if ( is_wp_error( $batch_state ) ) { self::rollback_transaction(); return $batch_state; }
		$batch = $batch_state['nextBatch'];
		if ( null === $batch ) {
			$payload = self::public_quarantine_gc_completion_payload( $intent, $class, gmdate( 'Y-m-d\TH:i:s\Z' ) );
			if ( is_wp_error( $payload ) ) { self::rollback_transaction(); return $payload; }
			$stored = self::store_public_quarantine_gc_receipt_locked( $payload, 'gc_' . $class . '_complete' );
			if ( is_wp_error( $stored ) ) { self::rollback_transaction(); return $stored; }
			$commit = self::commit_transaction();
			if ( is_wp_error( $commit ) ) {
				$fresh = self::public_quarantine_gc_completion( $intent, $class, false );
				if ( is_wp_error( $fresh ) || ! hash_equals( self::canonical_json( $payload ), self::canonical_json( $fresh ) ) ) { return $commit; }
			}
			return array( 'done' => true, 'progress' => true );
		}
		$placeholders = implode( ',', array_fill( 0, count( $batch ), '%d' ) );
		$args = array_merge( array( (string) $intent['proof']['terminalStatus'] ), $batch );
		$wpdb->last_error = '';
		$deleted = $wpdb->query( $wpdb->prepare( "DELETE FROM " . self::table_names()['placements'] . " WHERE status=%s AND id IN ({$placeholders})", $args ) );
		if ( '' !== (string) $wpdb->last_error || (int) $deleted !== count( $batch ) ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_public_quarantine_gc_delete', 'Terminal GC chunk delete failed its exact CAS.', array( 'status' => 503 ) ); }
		$commit = self::commit_transaction();
		if ( is_wp_error( $commit ) ) {
			$fresh_manifest = self::public_quarantine_final_receipt_manifest( (int) $epoch, false );
			$fresh_intent = is_wp_error( $fresh_manifest ) ? $fresh_manifest : self::public_quarantine_gc_intent( $fresh_manifest, $class, false );
			$fresh_state = is_wp_error( $fresh_intent ) ? $fresh_intent : self::public_quarantine_gc_batch_state( $fresh_intent, $class, false );
			$survives = false;
			if ( ! is_wp_error( $fresh_state ) ) { foreach ( (array) ( $fresh_state['nextBatch'] ?? array() ) as $candidate ) { if ( in_array( $candidate, $batch, true ) ) { $survives = true; break; } } }
			if ( is_wp_error( $fresh_state ) || $survives ) { return $commit; }
		}
		return array( 'done' => false, 'progress' => true );
	}

	/** Fairly find an unfinished final epoch without requiring mutable cursor state. */
	private static function reconcile_public_quarantine_terminal_gc() {
		global $wpdb;
		$status = self::public_quarantine_status( false );
		if ( empty( $status['inspectable'] ) || ! empty( $status['active'] ) ) { return empty( $status['inspectable'] ) ? new WP_Error( 'complete99_campaign_public_quarantine_gc_status', 'Terminal GC cannot inspect the permanent sentinel.', array( 'status' => 503 ) ) : array( 'progress' => false ); }
		$table = self::table_names()['provider_receipts'];
		$wpdb->last_error = '';
		$rows = $wpdb->get_results( "SELECT campaign_version FROM {$table} WHERE campaign_id='" . self::PUBLIC_QUARANTINE_CAMPAIGN_ID . "' AND provider_key='complete99-public-quarantine' AND external_state='quarantine_clear' ORDER BY campaign_version ASC,id ASC LIMIT " . ( self::CAPACITY_MAX_ROWS + 1 ), ARRAY_A );
		if ( '' !== (string) $wpdb->last_error || ! is_array( $rows ) || self::CAPACITY_MAX_ROWS < count( $rows ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_gc_epochs', 'Terminal GC epoch receipts are unavailable or unbounded.', array( 'status' => 503 ) ); }
		$seen = array();
		foreach ( $rows as $row ) {
			$epoch = is_numeric( $row['campaign_version'] ?? null ) ? (int) $row['campaign_version'] : 0;
			if ( 1 > $epoch || isset( $seen[ $epoch ] ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_gc_epoch_duplicate', 'Terminal GC found an invalid or duplicated final epoch.', array( 'status' => 503 ) ); }
			$seen[ $epoch ] = true;
			$resolution = self::reconcile_public_quarantine_epoch_resolution( $epoch );
			if ( is_wp_error( $resolution ) ) { return $resolution; }
			if ( ! empty( $resolution['progress'] ) ) { return array( 'progress' => true, 'epoch' => $epoch, 'class' => 'resolution' ); }
			foreach ( array( 'qto', 'qtr' ) as $class ) {
				$result = self::reconcile_public_quarantine_terminal_gc_class( $epoch, $class );
				if ( is_wp_error( $result ) ) { return $result; }
				if ( ! empty( $result['progress'] ) ) { return array( 'progress' => true, 'epoch' => $epoch, 'class' => $class ); }
			}
		}
		return array( 'progress' => false );
	}

	/** Reject allocator regression below any immutable terminal-GC completion high-water. */
	private static function public_quarantine_gc_allocator_floor() {
		global $wpdb;
		$table = self::table_names()['provider_receipts'];
		$phase_by_state = array(
			'quarantine_clear' => 'closed',
			'quarantine_gc_qto_intent' => 'gc_qto_intent',
			'quarantine_gc_qto_done' => 'gc_qto_complete',
			'quarantine_gc_qtr_intent' => 'gc_qtr_intent',
			'quarantine_gc_qtr_done' => 'gc_qtr_complete',
		);
		$wpdb->last_error = '';
		$rows = $wpdb->get_results( "SELECT * FROM {$table} WHERE campaign_id='" . self::PUBLIC_QUARANTINE_CAMPAIGN_ID . "' AND provider_key='complete99-public-quarantine' AND external_state IN ('quarantine_clear','quarantine_gc_qto_intent','quarantine_gc_qto_done','quarantine_gc_qtr_intent','quarantine_gc_qtr_done') ORDER BY id ASC LIMIT " . ( self::CAPACITY_MAX_ROWS + 1 ), ARRAY_A );
		if ( '' !== (string) $wpdb->last_error || ! is_array( $rows ) || self::CAPACITY_MAX_ROWS < count( $rows ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_gc_allocator_unavailable', 'Terminal GC allocator history is unavailable or unbounded.', array( 'status' => 503 ) ); }
		$proofs = array();
		$events = array();
		$floor = 0;
		foreach ( $rows as $row ) {
			$json = (string) ( $row['proof_ref'] ?? '' );
			$proof = json_decode( $json, true );
			$phase = (string) ( $phase_by_state[ (string) ( $row['external_state'] ?? '' ) ] ?? '' );
			$epoch = is_array( $proof ) && is_int( $proof['epoch'] ?? null ) ? $proof['epoch'] : 0;
			$identity = is_array( $proof ) && '' !== $phase ? self::public_quarantine_receipt_identity( $proof, $phase ) : array();
			$key = $epoch . '|' . $phase;
			if ( ! is_array( $proof ) || 1 > $epoch || '' === $phase || 60000 < strlen( $json ) || ! hash_equals( $json, self::canonical_json( $proof ) )
				|| ! self::public_quarantine_provider_receipt_row_matches( $row, $proof, $phase, $identity ) || isset( $proofs[ $key ] ) || isset( $events[ (string) ( $identity['eventId'] ?? '' ) ] ) ) {
				return new WP_Error( 'complete99_campaign_public_quarantine_gc_allocator_corrupt', 'Terminal GC allocator history is malformed.', array( 'status' => 503 ) );
			}
			$proofs[ $key ] = $proof;
			$events[ $identity['eventId'] ] = $identity;
		}
		$ops = Complete99_Ops::table_names();
		$audit_table = $ops['audit_events'];
		$wpdb->last_error = '';
		$audits = $wpdb->get_results( "SELECT * FROM {$audit_table} WHERE subject_type='campaign_quarantine' AND action IN ('campaign.public_quarantine_closed','campaign.public_quarantine_gc_qto_intent','campaign.public_quarantine_gc_qto_complete','campaign.public_quarantine_gc_qtr_intent','campaign.public_quarantine_gc_qtr_complete') ORDER BY id ASC LIMIT " . ( self::CAPACITY_MAX_ROWS + 1 ), ARRAY_A );
		if ( '' !== (string) $wpdb->last_error || ! is_array( $audits ) || self::CAPACITY_MAX_ROWS < count( $audits ) || count( $audits ) !== count( $events ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_gc_allocator_audit', 'Terminal GC allocator audit history is unavailable or incomplete.', array( 'status' => 503 ) ); }
		$seen_events = array();
		foreach ( $audits as $audit ) {
			$event_id = (string) ( $audit['event_id'] ?? '' );
			if ( isset( $seen_events[ $event_id ] ) || ! isset( $events[ $event_id ] ) || ! self::public_quarantine_audit_row_matches( $audit, $events[ $event_id ] ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_gc_allocator_audit', 'Terminal GC allocator audit history is malformed.', array( 'status' => 503 ) ); }
			$seen_events[ $event_id ] = true;
		}
		$validated_completions = array();
		foreach ( $proofs as $key => $intent ) {
			if ( ! preg_match( '/\A([1-9][0-9]*)\|gc_(qto|qtr)_intent\z/', (string) $key, $matches ) ) { continue; }
			$epoch = (int) $matches[1];
			$class = (string) $matches[2];
			$completion_key = $epoch . '|gc_' . $class . '_complete';
			$completion = $proofs[ $completion_key ] ?? null;
			$closed = $proofs[ $epoch . '|closed' ] ?? null;
			$closed_ids = is_array( $closed ) ? base64_decode( (string) ( $closed['rowIdsBase64'] ?? '' ), true ) : false;
			$closed_bits = is_array( $closed ) ? base64_decode( (string) ( $closed['qtoBitsetBase64'] ?? '' ), true ) : false;
			$closed_count = is_array( $closed ) && is_int( $closed['rowCount'] ?? null ) ? $closed['rowCount'] : -1;
			$closed_shape = is_array( $closed ) && 'complete99-campaign-public-quarantine-final/v1' === (string) ( $closed['schemaVersion'] ?? '' ) && $epoch === (int) ( $closed['epoch'] ?? -1 )
				&& 0 <= $closed_count && self::PUBLIC_PLACEMENT_MAX_ROWS >= $closed_count && is_string( $closed_ids ) && strlen( $closed_ids ) === $closed_count * 8
				&& is_string( $closed_bits ) && strlen( $closed_bits ) === (int) ceil( $closed_count / 8 ) && hash_equals( (string) ( $closed['rowIdsBase64'] ?? '' ), base64_encode( $closed_ids ) ) && hash_equals( (string) ( $closed['qtoBitsetBase64'] ?? '' ), base64_encode( $closed_bits ) );
			$expected_ids = array();
			$prior_id = 0;
			$qto_count = 0;
			if ( $closed_shape ) {
				for ( $index = 0; $index < $closed_count; ++$index ) {
					$words = unpack( 'Nhigh/Nlow', substr( $closed_ids, $index * 8, 8 ) );
					$id = ( (int) $words['high'] * 4294967296 ) + (int) $words['low'];
					$is_qto = 0 !== ( ord( $closed_bits[ intdiv( $index, 8 ) ] ) & ( 1 << ( $index % 8 ) ) );
					if ( 1 > $id || $id <= $prior_id ) { $closed_shape = false; break; }
					if ( $is_qto ) { ++$qto_count; }
					if ( ( 'qto' === $class ) === $is_qto ) { $expected_ids[] = $id; }
					$prior_id = $id;
				}
			}
			$expected_packed = $closed_shape ? self::public_quarantine_pack_ids( $expected_ids ) : new WP_Error( 'complete99_campaign_public_quarantine_gc_allocator_manifest', 'Terminal GC final membership is malformed.', array( 'status' => 503 ) );
			$intent_ids = is_array( $intent ) ? base64_decode( (string) ( $intent['rowIdsBase64'] ?? '' ), true ) : false;
			$batch_digests = is_array( $intent ) ? base64_decode( (string) ( $intent['batchDigestsBase64'] ?? '' ), true ) : false;
			$intent_keys = array( 'batchDigestsBase64', 'batchSize', 'class', 'createdAt', 'epoch', 'finalReceiptDigest', 'maxId', 'rowCount', 'rowIdsBase64', 'rowsSha256', 'schemaVersion', 'terminalStatus' );
			$expected_count = 'qto' === $class ? (int) ( $closed['qtoCount'] ?? -1 ) : (int) ( $closed['qtnCount'] ?? -1 );
			$expected_rows_digest = (string) ( 'qto' === $class ? ( $closed['qtoRowsSha256'] ?? '' ) : ( $closed['qtnRowsSha256'] ?? '' ) );
			$expected_status = 'qto' === $class ? (string) ( $closed['qtoStatus'] ?? '' ) : self::public_quarantine_recovered_status( (string) ( $closed['qtnStatus'] ?? '' ) );
			try { $created_at = is_array( $intent ) ? self::iso_datetime( (string) ( $intent['createdAt'] ?? '' ) ) : ''; } catch ( \Throwable $error ) { $created_at = ''; }
			if ( ! $closed_shape || $qto_count !== (int) ( $closed['qtoCount'] ?? -1 ) || $closed_count - $qto_count !== (int) ( $closed['qtnCount'] ?? -1 ) || is_wp_error( $expected_packed )
				|| ! is_array( $intent ) || array_keys( $intent ) !== $intent_keys || 'complete99-campaign-public-quarantine-gc-intent/v1' !== (string) ( $intent['schemaVersion'] ?? '' ) || $epoch !== (int) ( $intent['epoch'] ?? -1 ) || ! hash_equals( $class, (string) ( $intent['class'] ?? '' ) )
				|| self::RECONCILE_BATCH_SIZE !== (int) ( $intent['batchSize'] ?? 0 ) || $expected_count !== (int) ( $intent['rowCount'] ?? -1 ) || ! hash_equals( (string) $expected_packed, (string) ( $intent['rowIdsBase64'] ?? '' ) )
				|| ! is_string( $intent_ids ) || strlen( $intent_ids ) !== $expected_count * 8 || ! is_string( $batch_digests ) || strlen( $batch_digests ) !== (int) ceil( $expected_count / self::RECONCILE_BATCH_SIZE ) * 32
				|| ( empty( $expected_ids ) ? 0 : $expected_ids[ count( $expected_ids ) - 1 ] ) !== (int) ( $intent['maxId'] ?? -1 ) || ! hash_equals( $expected_rows_digest, (string) ( $intent['rowsSha256'] ?? '' ) ) || ! hash_equals( $expected_status, (string) ( $intent['terminalStatus'] ?? '' ) )
				|| ! hash_equals( hash( 'sha256', self::canonical_json( $closed ) ), (string) ( $intent['finalReceiptDigest'] ?? '' ) ) || ! hash_equals( (string) ( $intent['createdAt'] ?? '' ), $created_at ) ) {
				return new WP_Error( 'complete99_campaign_public_quarantine_gc_allocator_binding', 'Terminal GC allocator intent is not bound to its exact final membership.', array( 'status' => 503 ) );
			}
			$floor = max( $floor, (int) $intent['maxId'] );
			if ( null !== $completion ) {
				$expected_completion = self::public_quarantine_gc_completion_payload( array( 'proof' => $intent ), $class, (string) ( $completion['completedAt'] ?? '' ) );
				if ( is_wp_error( $expected_completion ) || ! is_array( $expected_completion ) || ! hash_equals( self::canonical_json( $expected_completion ), self::canonical_json( $completion ) ) ) {
					return new WP_Error( 'complete99_campaign_public_quarantine_gc_allocator_binding', 'Terminal GC allocator completion is not bound to its exact intent and final membership.', array( 'status' => 503 ) );
				}
				$validated_completions[ $completion_key ] = true;
			}
		}
		foreach ( $proofs as $key => $proof ) {
			if ( preg_match( '/\A[1-9][0-9]*\|gc_(?:qto|qtr)_complete\z/', (string) $key ) && ! isset( $validated_completions[ $key ] ) ) {
				return new WP_Error( 'complete99_campaign_public_quarantine_gc_allocator_binding', 'Terminal GC allocator completion lacks its exact immutable intent.', array( 'status' => 503 ) );
			}
		}
		return $floor;
	}

	/** Add Campaign Studio beneath the private Complete99 OS menu. */
