	/** Load bilingual admin assets only on Campaign Studio. */
	public static function enqueue_admin_assets( $hook_suffix ) {
		if ( 'complete99-os_page_' . self::PAGE_SLUG !== (string) $hook_suffix
			|| ! is_user_logged_in()
			|| ! current_user_can( self::VIEW_CAPABILITY ) ) {
			return;
		}
		wp_enqueue_style(
			'complete99-campaigns',
			COMPLETE99_PLATFORM_URL . 'assets/css/campaigns.css',
			array(),
			COMPLETE99_PLATFORM_VERSION
		);
		wp_enqueue_script(
			'complete99-campaigns',
			COMPLETE99_PLATFORM_URL . 'assets/js/campaigns.js',
			array(),
			COMPLETE99_PLATFORM_VERSION,
			true
		);
		wp_localize_script(
			'complete99-campaigns',
			'Complete99CampaignStudio',
			array(
				'endpoint'  => esc_url_raw( rest_url( ltrim( self::REST_NAMESPACE . self::REST_ROUTE, '/' ) ) ),
				'nonce'     => wp_create_nonce( 'wp_rest' ),
				'canManage' => current_user_can( self::MANAGE_CAPABILITY ),
				'canApprove'=> current_user_can( self::APPROVE_CAPABILITY ),
				'canSchedule'=> current_user_can( self::SCHEDULE_CAPABILITY ),
				'canEvidence'=> current_user_can( self::EVIDENCE_CAPABILITY ),
				'canResults'=> current_user_can( self::RESULTS_CAPABILITY ),
				'canModerate'=> current_user_can( self::MODERATE_CAPABILITY ),
				'locale'    => is_rtl() ? 'he' : 'en',
				'messages'  => array(
					'loading'     => __( 'Loading private campaign records...', 'complete99-platform' ),
					'empty'       => __( 'No WordPress campaign records exist yet.', 'complete99-platform' ),
					'failed'      => __( 'Campaign Studio failed closed. No change was made.', 'complete99-platform' ),
					'saved'       => __( 'The campaign record was saved.', 'complete99-platform' ),
					'confirmation'=> __( 'This action records an internal workflow decision; it does not publish externally.', 'complete99-platform' ),
				),
			)
		);
	}

	/** Register all private Campaign Studio API routes. */
	public static function register_routes() {
		register_rest_route(
			self::REST_NAMESPACE,
			self::REST_ROUTE,
			array(
				array(
					'methods'             => WP_REST_Server::READABLE,
					'permission_callback' => array( __CLASS__, 'authorize_view' ),
					'callback'            => array( __CLASS__, 'rest_list' ),
				),
				array(
					'methods'             => WP_REST_Server::CREATABLE,
					'permission_callback' => array( __CLASS__, 'authorize_manage' ),
					'callback'            => array( __CLASS__, 'rest_create' ),
				),
			)
		);
		register_rest_route(
			self::REST_NAMESPACE,
			'/campaign-placement/(?P<token>[a-f0-9]{64})',
			array(
				'methods'             => WP_REST_Server::READABLE,
				'permission_callback' => '__return_true',
				'callback'            => array( __CLASS__, 'rest_public_readback' ),
			)
		);
		register_rest_route(
			self::REST_NAMESPACE,
			'/campaign-events/(?P<token>[a-f0-9]{64})',
			array(
				'methods'             => WP_REST_Server::CREATABLE,
				'permission_callback' => '__return_true',
				'callback'            => array( __CLASS__, 'rest_public_event' ),
				'args'                => array(
					'event' => array( 'required' => true, 'type' => 'string' ),
					'event_id' => array( 'required' => true, 'type' => 'string', 'pattern' => '^[A-Za-z0-9_-]{20,80}$' ),
				),
			)
		);
		register_rest_route(
			self::REST_NAMESPACE,
			self::REST_ROUTE . '/(?P<campaign_id>[a-z0-9_-]{8,64})/evidence',
			array(
				'methods'             => WP_REST_Server::READABLE,
				'permission_callback' => array( __CLASS__, 'authorize_evidence' ),
				'callback'            => array( __CLASS__, 'rest_evidence_inventory' ),
			)
		);
		register_rest_route(
			self::REST_NAMESPACE,
			self::REST_ROUTE . '/(?P<campaign_id>[a-z0-9_-]{8,64})/evidence-upload',
			array(
				'methods'             => WP_REST_Server::CREATABLE,
				'permission_callback' => array( __CLASS__, 'authorize_evidence' ),
				'callback'            => array( __CLASS__, 'rest_upload_evidence' ),
			)
		);
		register_rest_route(
			self::REST_NAMESPACE,
			self::REST_ROUTE . '/(?P<campaign_id>[a-z0-9_-]{8,64})/evidence/(?P<attachment_id>[1-9][0-9]*)/legal-hold',
			array(
				'methods'             => WP_REST_Server::CREATABLE,
				'permission_callback' => array( __CLASS__, 'authorize_evidence' ),
				'callback'            => array( __CLASS__, 'rest_evidence_legal_hold' ),
			)
		);
		register_rest_route(
			self::REST_NAMESPACE,
			self::REST_ROUTE . '/(?P<campaign_id>[a-z0-9_-]{8,64})/evidence/(?P<attachment_id>[1-9][0-9]*)/dispose',
			array(
				'methods'             => WP_REST_Server::CREATABLE,
				'permission_callback' => array( __CLASS__, 'authorize_evidence' ),
				'callback'            => array( __CLASS__, 'rest_dispose_evidence' ),
			)
		);
		register_rest_route(
			self::REST_NAMESPACE,
			self::REST_ROUTE . '/(?P<campaign_id>[a-z0-9_-]{8,64})',
			array(
				array(
					'methods'             => WP_REST_Server::READABLE,
					'permission_callback' => array( __CLASS__, 'authorize_view' ),
					'callback'            => array( __CLASS__, 'rest_get' ),
				),
				array(
					'methods'             => WP_REST_Server::EDITABLE,
					'permission_callback' => array( __CLASS__, 'authorize_manage' ),
					'callback'            => array( __CLASS__, 'rest_edit' ),
				),
			)
		);
		$actions = array(
			'submit'             => 'authorize_manage',
			'approve'            => 'authorize_approve',
			'schedule'           => 'authorize_schedule',
			'cancel'             => 'authorize_schedule',
			'prepare-package'    => 'authorize_schedule',
			'provider-receipts'  => 'authorize_evidence',
			'results'            => 'authorize_results',
			'moderation-issues'  => 'authorize_moderate',
		);
		foreach ( $actions as $action => $authorization ) {
			register_rest_route(
				self::REST_NAMESPACE,
				self::REST_ROUTE . '/(?P<campaign_id>[a-z0-9_-]{8,64})/' . $action,
				array(
					'methods'             => WP_REST_Server::CREATABLE,
					'permission_callback' => array( __CLASS__, $authorization ),
					'callback'            => array( __CLASS__, 'rest_' . str_replace( '-', '_', $action ) ),
				)
			);
		}
		foreach ( array( 'resolve', 'escalate', 'outcome' ) as $moderation_action ) {
			register_rest_route(
				self::REST_NAMESPACE,
				self::REST_ROUTE . '/(?P<campaign_id>[a-z0-9_-]{8,64})/moderation-issues/(?P<issue_id>issue_[a-f0-9]{48})/' . $moderation_action,
				array(
					'methods'             => WP_REST_Server::CREATABLE,
					'permission_callback' => array( __CLASS__, 'authorize_moderate' ),
					'callback'            => array( __CLASS__, 'rest_moderation_' . $moderation_action ),
				)
			);
		}
	}

	/** Require WordPress auth, view capability and REST nonce. */
	public static function authorize_view( WP_REST_Request $request ) {
		return self::authorize_request( $request, self::VIEW_CAPABILITY );
	}

	/** Require WordPress auth, manage capability and REST nonce. */
	public static function authorize_manage( WP_REST_Request $request ) {
		return self::authorize_request( $request, self::MANAGE_CAPABILITY );
	}

	public static function authorize_approve( WP_REST_Request $request ) {
		return self::authorize_request( $request, self::APPROVE_CAPABILITY );
	}

	public static function authorize_schedule( WP_REST_Request $request ) {
		return self::authorize_request( $request, self::SCHEDULE_CAPABILITY );
	}

	public static function authorize_evidence( WP_REST_Request $request ) {
		return self::authorize_request( $request, self::EVIDENCE_CAPABILITY );
	}

	public static function authorize_results( WP_REST_Request $request ) {
		return self::authorize_request( $request, self::RESULTS_CAPABILITY );
	}

	public static function authorize_moderate( WP_REST_Request $request ) {
		return self::authorize_request( $request, self::MODERATE_CAPABILITY );
	}

	private static function capabilities() {
		return array( self::VIEW_CAPABILITY, self::MANAGE_CAPABILITY, self::APPROVE_CAPABILITY, self::SCHEDULE_CAPABILITY, self::EVIDENCE_CAPABILITY, self::RESULTS_CAPABILITY, self::MODERATE_CAPABILITY );
	}

	private static function authorize_request( WP_REST_Request $request, $capability ) {
		if ( ! is_user_logged_in() ) {
			return new WP_Error( 'complete99_campaign_authentication_required', 'WordPress authentication is required.', array( 'status' => 401 ) );
		}
		if ( ! current_user_can( $capability ) ) {
			return new WP_Error( 'complete99_campaign_forbidden', 'This WordPress account cannot access Campaign Studio.', array( 'status' => 403 ) );
		}
		$nonce = trim( (string) $request->get_header( 'X-WP-Nonce' ) );
		if ( '' === $nonce || false === wp_verify_nonce( $nonce, 'wp_rest' ) ) {
			return new WP_Error( 'complete99_campaign_invalid_nonce', 'A valid WordPress REST nonce is required.', array( 'status' => 403 ) );
		}
		return true;
	}

	/** Enforce exact location membership and role for every row access. */
	private static function require_location_scope( $location_id, $operation ) {
		$location_id = absint( $location_id );
		$user_id     = get_current_user_id();
		$roles       = self::operation_roles( $operation );
		if ( 1 > $user_id || empty( $roles ) ) {
			return new WP_Error( 'complete99_campaign_scope_forbidden', 'Campaign location scope is unavailable.', array( 'status' => 403 ) );
		}
		if ( current_user_can( 'manage_options' ) ) {
			if ( 0 === $location_id || self::location_exists( $location_id ) ) {
				return true;
			}
			return new WP_Error( 'complete99_campaign_location_unknown', 'The requested Complete99 location does not exist.', array( 'status' => 404 ) );
		}
		if ( 0 === $location_id ) {
			return new WP_Error( 'complete99_campaign_global_scope_forbidden', 'Only a global WordPress owner can access business-wide campaigns.', array( 'status' => 403 ) );
		}
		global $wpdb;
		$tables = Complete99_Ops::table_names();
		$placeholders = implode( ',', array_fill( 0, count( $roles ), '%s' ) );
		$args = array_merge( array( $user_id, $location_id ), $roles );
		$sql = $wpdb->prepare(
			"SELECT COUNT(*) FROM {$tables['memberships']} m INNER JOIN {$tables['locations']} l ON l.id = m.location_id AND l.status = 'active' WHERE m.user_id = %d AND m.location_id = %d AND m.status = 'active' AND m.role_key IN ({$placeholders})",
			$args
		);
		$count = $wpdb->get_var( $sql );
		if ( 1 > (int) $count ) {
			return new WP_Error( 'complete99_campaign_location_forbidden', 'This account has no active campaign role for the requested location.', array( 'status' => 403 ) );
		}
		return true;
	}

	private static function operation_roles( $operation ) {
		$map = array(
			'view'     => array( 'owner', 'manager', 'marketing' ),
			'manage'   => array( 'owner', 'marketing' ),
			'approve'  => array( 'owner' ),
			'schedule' => array( 'owner', 'marketing' ),
			'evidence' => array( 'owner' ),
			'results'  => array( 'owner', 'manager', 'marketing' ),
			'moderate' => array( 'owner', 'marketing' ),
		);
		return $map[ $operation ] ?? array();
	}

	private static function location_exists( $location_id ) {
		global $wpdb;
		$tables = Complete99_Ops::table_names();
		$count = $wpdb->get_var( $wpdb->prepare( "SELECT COUNT(*) FROM {$tables['locations']} WHERE id = %d AND status = 'active'", absint( $location_id ) ) );
		return 1 <= (int) $count;
	}

	private static function scoped_location_ids( $operation ) {
		if ( current_user_can( 'manage_options' ) ) {
			return null;
		}
		global $wpdb;
		$roles = self::operation_roles( $operation );
		if ( empty( $roles ) ) {
			return array();
		}
		$tables = Complete99_Ops::table_names();
		$placeholders = implode( ',', array_fill( 0, count( $roles ), '%s' ) );
		$args = array_merge( array( get_current_user_id() ), $roles );
		$rows = $wpdb->get_col(
			$wpdb->prepare(
				"SELECT DISTINCT m.location_id FROM {$tables['memberships']} m INNER JOIN {$tables['locations']} l ON l.id = m.location_id AND l.status = 'active' WHERE m.user_id = %d AND m.status = 'active' AND m.location_id > 0 AND m.role_key IN ({$placeholders}) ORDER BY m.location_id ASC",
				$args
			)
		);
		return array_values( array_unique( array_map( 'absint', is_array( $rows ) ? $rows : array() ) ) );
	}

	private static function accountable_user_is_authorized( $user_id, $location_id, $capability, $operation ) {
		$fingerprint = self::accountable_user_authority_fingerprint( absint( $user_id ), absint( $location_id ), (string) $capability, (string) $operation );
		return ! is_wp_error( $fingerprint ) && ! empty( $fingerprint['authorized'] );
	}

	/** Lock and digest exact core-role plus Ops membership authority rows. */
	private static function accountable_user_authority_fingerprint( $user_id, $location_id, $capability, $operation ) {
		global $wpdb;
		$lock = self::$transaction_active && ! self::is_sqlite_database() ? ' FOR UPDATE' : '';
		$ops = Complete99_Ops::table_names();
		$roles = self::operation_roles( $operation );
		$placeholders = implode( ',', array_fill( 0, count( $roles ), '%s' ) );
		$membership_args = array_merge( array( (int) $user_id, (int) $location_id ), $roles );
		$cap_meta_prefix = $wpdb->get_blog_prefix( get_current_blog_id() );
		$role_option_key = $cap_meta_prefix . 'user_roles';
		$wpdb->last_error = '';
		$user = $wpdb->get_row( $wpdb->prepare( "SELECT ID,user_login,user_status FROM {$wpdb->users} WHERE ID=%d LIMIT 1{$lock}", (int) $user_id ), ARRAY_A );
		$capability_rows = $wpdb->get_results( $wpdb->prepare( "SELECT umeta_id,meta_key,meta_value FROM {$wpdb->usermeta} WHERE user_id=%d AND (meta_key=%s OR meta_key=%s) ORDER BY umeta_id ASC{$lock}", (int) $user_id, $cap_meta_prefix . 'capabilities', $cap_meta_prefix . 'user_level' ), ARRAY_A );
		$role_option = $wpdb->get_results( $wpdb->prepare( "SELECT option_id,option_value FROM {$wpdb->options} WHERE option_name=%s ORDER BY option_id ASC LIMIT 2{$lock}", $role_option_key ), ARRAY_A );
		$memberships = 0 === (int) $location_id ? array() : $wpdb->get_results( $wpdb->prepare( "SELECT id,user_id,location_id,role_key,status,version,created_at,updated_at FROM {$ops['memberships']} WHERE user_id=%d AND location_id=%d AND role_key IN ({$placeholders}) ORDER BY id ASC{$lock}", $membership_args ), ARRAY_A );
		$location = 0 === (int) $location_id ? array( 'id' => 0, 'status' => 'global' ) : $wpdb->get_row( $wpdb->prepare( "SELECT id,public_id,status,version,updated_at FROM {$ops['locations']} WHERE id=%d LIMIT 1{$lock}", (int) $location_id ), ARRAY_A );
		if ( '' !== (string) $wpdb->last_error || ! is_array( $user ) || ! is_array( $capability_rows ) || ! is_array( $role_option ) || 1 !== count( $role_option ) || ! is_array( $memberships ) || ! is_array( $location ) || 2 < count( $capability_rows ) ) {
			return new WP_Error( 'campaign_authority_projection_unavailable', 'Accountable user authority rows could not be locked and projected exactly.' );
		}
		$user_capabilities = null;
		foreach ( $capability_rows as $row ) { if ( hash_equals( $cap_meta_prefix . 'capabilities', (string) ( $row['meta_key'] ?? '' ) ) ) { if ( null !== $user_capabilities ) { return new WP_Error( 'campaign_authority_projection_unavailable', 'Accountable user capabilities are duplicated.' ); } $user_capabilities = maybe_unserialize( (string) ( $row['meta_value'] ?? '' ) ); } }
		$role_definitions = maybe_unserialize( (string) ( $role_option[0]['option_value'] ?? '' ) );
		if ( ! is_array( $user_capabilities ) || ! is_array( $role_definitions ) ) { return new WP_Error( 'campaign_authority_projection_unavailable', 'Accountable user role truth is malformed.' ); }
		$has_capability = static function ( $required ) use ( $user_capabilities, $role_definitions ) {
			if ( true === ( $user_capabilities[ $required ] ?? null ) ) { return true; }
			foreach ( $user_capabilities as $role_key => $enabled ) { if ( true === $enabled && true === ( $role_definitions[ $role_key ]['capabilities'][ $required ] ?? null ) ) { return true; } }
			return false;
		};
		$active_membership = false;
		foreach ( $memberships as $membership ) { if ( is_array( $membership ) && 'active' === (string) ( $membership['status'] ?? '' ) ) { $active_membership = true; break; } }
		$scope_authorized = 0 === (int) $location_id ? $has_capability( 'manage_options' ) : ( 'active' === (string) ( $location['status'] ?? '' ) && $active_membership );
		$authorized = 0 === (int) ( $user['user_status'] ?? -1 ) && $has_capability( (string) $capability ) && $scope_authorized;
		$projection = array( 'schemaVersion' => 'complete99-campaign-accountable-authority/v1', 'lockProtocol' => self::AUTHORITY_LOCK_PROTOCOL, 'lockOrder' => self::AUTHORITY_LOCK_ORDER, 'user' => $user, 'capabilityRows' => $capability_rows, 'roleOption' => $role_option[0], 'memberships' => $memberships, 'location' => $location, 'requiredCapability' => (string) $capability, 'operation' => (string) $operation, 'authorized' => $authorized );
		return array( 'revision' => hash( 'sha256', self::canonical_json( $projection ) ), 'projection' => $projection, 'authorized' => $authorized );
	}

	/** Return a bounded status for the parent private operations shell. */
	public static function operational_status() {
		$schema = self::schema_status();
		$cache_error = self::cache_retry_record();
		$cache_ready = null === $cache_error;
		$evidence_recovery = self::private_evidence_recovery_status();
		$evidence_ready = ! empty( $evidence_recovery['ready'] ) && ! empty( $evidence_recovery['inspectable'] );
		$capabilities_ready = false;
		try {
			self::assert_capabilities();
			$capabilities_ready = true;
		} catch ( \Throwable $error ) {
			$capabilities_ready = false;
		}
		$capacity = ! empty( $schema['ready'] ) ? self::capacity_status() : array(
			'ready'       => false,
			'inspectable' => false,
			'error'       => 'schema_not_ready',
		);
		$cron_heartbeat = ! empty( $schema['ready'] ) ? self::cron_heartbeat_status() : array( 'ready' => false, 'inspectable' => false, 'reason' => 'schema_not_ready' );
		$suppression_backlog = ! empty( $schema['ready'] ) ? self::public_suppression_backlog_status() : array( 'ready' => false, 'inspectable' => false, 'recoverablePending' => false, 'invalid' => false );
		return array(
			'ready'                  => ! empty( $schema['ready'] ) && ! empty( $capacity['ready'] ) && ! empty( $capacity['writeReady'] ) && ! empty( $cron_heartbeat['ready'] ) && ! empty( $suppression_backlog['ready'] ) && $capabilities_ready && $cache_ready && $evidence_ready,
			'schema_version'         => $schema['stored_version'],
