	/** Placement-backed projection for aggregates that still need bounded suppression finalization. */
	private static function public_suppression_backlog_status() {
		global $wpdb;
		$tables = self::table_names();
		$quarantine = self::public_quarantine_status( false );
		if ( empty( $quarantine['inspectable'] ) ) { return array( 'ready' => false, 'inspectable' => false, 'recoverablePending' => false, 'invalid' => true, 'reason' => 'sentinel_' . (string) ( $quarantine['reason'] ?? 'unavailable' ) ); }
		$closed_epoch = empty( $quarantine['active'] ) ? (int) ( $quarantine['payload']['epoch'] ?? 0 ) : 0;
		if ( 0 < $closed_epoch ) {
			$manifest = self::public_quarantine_final_receipt_manifest( $closed_epoch, false );
			if ( is_wp_error( $manifest ) ) { return array( 'ready' => false, 'inspectable' => false, 'recoverablePending' => true, 'invalid' => true, 'reason' => 'aggregate_cleanup_chain_' . $manifest->get_error_code() ); }
		}
		$wpdb->last_error = '';
		$row = $wpdb->get_row(
			"SELECT COALESCE(SUM(CASE WHEN p.status='suppressed_authority' AND c.id IS NOT NULL THEN 1 ELSE 0 END),0) AS recoverable_rows,COALESCE(SUM(CASE WHEN (p.status='suppressed_authority' OR LEFT(p.status,4)='qtn_') AND c.id IS NULL THEN 1 ELSE 0 END),0) AS invalid_rows,COALESCE(SUM(CASE WHEN LEFT(p.status,4)='qto_' THEN 1 ELSE 0 END),0) AS retained_warning_rows FROM {$tables['placements']} p LEFT JOIN {$tables['campaigns']} c ON c.public_id=p.campaign_id WHERE p.status='suppressed_authority' OR LEFT(p.status,4) IN ('qtn_','qto_')",
			ARRAY_A
		);
		if ( '' !== (string) $wpdb->last_error || ! is_array( $row ) || ! is_numeric( $row['recoverable_rows'] ?? null ) || ! is_numeric( $row['invalid_rows'] ?? null ) || ! is_numeric( $row['retained_warning_rows'] ?? null ) ) {
			return array( 'ready' => false, 'inspectable' => false, 'recoverablePending' => false, 'invalid' => true, 'reason' => 'query_failed' );
		}
		$recoverable = (int) $row['recoverable_rows'];
		$invalid = (int) $row['invalid_rows'];
		$warnings = (int) $row['retained_warning_rows'];
		return array( 'ready' => ! empty( $quarantine['ready'] ) && 0 === $recoverable && 0 === $invalid, 'inspectable' => true, 'recoverablePending' => 0 < $recoverable || ! empty( $quarantine['active'] ), 'invalid' => 0 < $invalid, 'recoverableRows' => $recoverable, 'invalidRows' => $invalid, 'retainedWarningRows' => $warnings, 'quarantine' => array( 'active' => ! empty( $quarantine['active'] ), 'epoch' => (int) ( $quarantine['payload']['epoch'] ?? 0 ), 'reason' => (string) ( $quarantine['reason'] ?? '' ) ) );
	}

	/** Plugin-owned campaign table names. */
	public static function table_names() {
		global $wpdb;
		return array(
			'campaigns'         => $wpdb->prefix . 'c99_campaigns',
			'revisions'         => $wpdb->prefix . 'c99_campaign_revisions',
			'prepared_packages' => $wpdb->prefix . 'c99_campaign_packages',
			'provider_receipts' => $wpdb->prefix . 'c99_campaign_provider_receipts',
			'results'           => $wpdb->prefix . 'c99_campaign_results',
			'placements'        => $wpdb->prefix . 'c99_campaign_placements',
			'event_aggregates'  => $wpdb->prefix . 'c99_campaign_event_aggregates',
		);
	}

