	/** Materialize missing page/cohort receipt rows from the exact current queue cohort. */
	private static function aggregate_cleanup_capacity_reservation( $scope, $generation, $binding_digest, $future = false ) {
		$scope = (string) $scope; $generation = (int) $generation; $binding_digest = (string) $binding_digest;
		$result = array( 'missingRows' => 0, 'campaignCanonicalBytes' => 0, 'operationsCanonicalBytes' => 0 );
		if ( ! in_array( $scope, array( 'quarantine', 'lifecycle' ), true ) || 1 > $generation || ! preg_match( '/\A[a-f0-9]{64}\z/', $binding_digest ) ) { return new WP_Error( 'complete99_campaign_aggregate_cleanup_reserve_scope', 'Aggregate cleanup reserve scope is invalid.', array( 'status' => 503 ) ); }
		$snapshot_scope = $future && 'quarantine' === $scope ? 'lifecycle' : $scope;
		$snapshot = self::aggregate_cleanup_snapshot( $snapshot_scope, $generation, $binding_digest, false );
		if ( is_wp_error( $snapshot ) ) { return $snapshot; }
		$snapshot['scope'] = $scope;
		$chain = hash( 'sha256', 'complete99-aggregate-cleanup-cohort/v1|' . $scope . '|' . $generation . '|' . $binding_digest );
		foreach ( $snapshot['queues'] as $queue_projection ) { $chain = hash( 'sha256', $chain . '|' . self::canonical_json( $queue_projection ) ); }
		$snapshot['cohortDigest'] = $chain;
		$inventory = self::aggregate_cleanup_receipt_inventory( 'aggregate_capacity', $snapshot, false );
		if ( is_wp_error( $inventory ) ) { return $inventory; }
		$stored_cohort = $inventory['cohort'];
		if ( is_array( $stored_cohort ) ) {
			if ( $future || ! hash_equals( $binding_digest, (string) ( $stored_cohort['bindingDigest'] ?? '' ) ) ) { return new WP_Error( 'complete99_campaign_aggregate_cleanup_reserve_collision', 'Aggregate cleanup reserve found divergent immutable cohort truth.', array( 'status' => 503 ) ); }
			$verified = self::verify_aggregate_cleanup_chain( $scope, $generation, hash( 'sha256', self::canonical_json( $stored_cohort ) ), false );
			return is_wp_error( $verified ) ? $verified : $result;
		}
		if ( $future && 0 < (int) $inventory['presentPrefix'] ) { return new WP_Error( 'complete99_campaign_aggregate_cleanup_reserve_collision', 'Future aggregate cleanup reserve identity is already occupied.', array( 'status' => 503 ) ); }
		$stamp = '9999-12-31T23:59:59Z'; $page_digests = '';
		foreach ( $snapshot['pages'] as $page_index => $obligations ) {
			$stored = $inventory['pages'][ $page_index ] ?? null;
			if ( is_array( $stored ) ) {
				$page_digests .= hex2bin( hash( 'sha256', self::canonical_json( $stored ) ) );
				continue;
			}
			$urls = array(); foreach ( $obligations as $obligation ) { $urls = array_merge( $urls, (array) $obligation['surfaceUrls'] ); } $urls = array_values( array_unique( $urls ) ); sort( $urls, SORT_STRING );
			$records = array(); foreach ( $urls as $url ) { $records[] = array( 'bodyBytes' => 1048576, 'bodySha256' => str_repeat( 'f', 64 ), 'code' => 200, 'markerAbsent' => true, 'type' => 'application/xhtml+xml', 'url' => $url, 'verifiedAt' => $stamp ); }
			$page = array( 'absenceRecords' => $records, 'bindingDigest' => $binding_digest, 'cohortDigest' => (string) $snapshot['cohortDigest'], 'generation' => $generation, 'obligations' => $obligations, 'pageIndex' => (int) $page_index, 'schemaVersion' => 'complete99-aggregate-cleanup-page/v1', 'scope' => $scope, 'verifiedAt' => $stamp );
			if ( ! self::aggregate_cleanup_payload_valid( $page, 'page' ) ) { return new WP_Error( 'complete99_campaign_aggregate_cleanup_reserve_page', 'Aggregate cleanup reserve page exceeds its canonical bound.', array( 'status' => 507 ) ); }
			$bytes = self::aggregate_cleanup_capacity_receipt_bytes( $page, 'page' ); ++$result['missingRows']; $result['campaignCanonicalBytes'] += $bytes['campaign']; $result['operationsCanonicalBytes'] += $bytes['operations'];
			$page_digests .= hex2bin( hash( 'sha256', self::canonical_json( $page ) ) );
		}
		$page_count = count( $snapshot['pages'] );
		$stored_page_digests = self::AGGREGATE_CLEANUP_DIGEST_VECTOR_MAX_PAGES < $page_count ? hex2bin( self::aggregate_cleanup_page_digest_chain( $scope, $generation, $page_digests ) ) : $page_digests;
		$cohort = array( 'bindingDigest' => $binding_digest, 'cohortDigest' => (string) $snapshot['cohortDigest'], 'completedAt' => $stamp, 'generation' => $generation, 'obligationCount' => count( $snapshot['obligations'] ), 'pageCount' => $page_count, 'pageDigestsBase64' => base64_encode( $stored_page_digests ), 'queueCount' => count( $snapshot['queues'] ), 'schemaVersion' => 'complete99-aggregate-cleanup-cohort/v1', 'scope' => $scope );
		if ( ! self::aggregate_cleanup_payload_valid( $cohort, 'cohort' ) ) { return new WP_Error( 'complete99_campaign_aggregate_cleanup_reserve_cohort', 'Aggregate cleanup reserve cohort exceeds its canonical bound.', array( 'status' => 507 ) ); }
		$bytes = self::aggregate_cleanup_capacity_receipt_bytes( $cohort, 'cohort' ); ++$result['missingRows']; $result['campaignCanonicalBytes'] += $bytes['campaign']; $result['operationsCanonicalBytes'] += $bytes['operations'];
		return $result;
	}

	/** Materialize the largest canonical receipt vector one lifecycle generation can still owe. */
	private static function lifecycle_capacity_budget( $generation, $lifecycle_digest, $started_at ) {
		if ( ! is_int( $generation ) || 1 > $generation || PHP_INT_MAX - 1 <= $generation || ! preg_match( '/\A[a-f0-9]{64}\z/', (string) $lifecycle_digest ) ) { return new WP_Error( 'complete99_campaign_lifecycle_reserve_generation', 'Lifecycle receipt reserve generation is invalid.', array( 'status' => 503 ) ); }
		$stamp = '9999-12-31T23:59:59Z';
		try { $started_at = self::iso_datetime( (string) $started_at ); } catch ( \Throwable $error ) { return new WP_Error( 'complete99_campaign_lifecycle_reserve_time', 'Lifecycle receipt reserve time is invalid.', array( 'status' => 503 ) ); }
		$opening = array( 'generation' => $generation, 'lifecycleDigest' => (string) $lifecycle_digest, 'phase' => 'suspending', 'schemaVersion' => 'complete99-campaign-lifecycle-suspending/v1', 'startedAt' => $started_at );
		$opening_digest = hash( 'sha256', self::canonical_json( $opening ) );
		$drained = array( 'aggregateCleanupReceiptDigest' => str_repeat( 'f', 64 ), 'cronEmpty' => true, 'generation' => $generation, 'lifecycleDigest' => (string) $lifecycle_digest, 'openingReceiptDigest' => $opening_digest, 'phase' => 'drained', 'schemaVersion' => 'complete99-campaign-lifecycle-drained/v1', 'verifiedAt' => $stamp );
		$surfaces = array();
		$hex = str_repeat( 'f', 64 );
		for ( $i = 0; $i < 4; ++$i ) { $prefix = 'https://lifecycle-capacity-' . $i . '.invalid/'; $url = $prefix . str_repeat( 'a', 512 - strlen( $prefix ) ); $surfaces[] = array( 'bodyBytes' => 1048576, 'bodySha256' => $hex, 'code' => 200, 'contentType' => 'application/xhtml+xml', 'markerAbsent' => true, 'url' => $url, 'verifiedAt' => $stamp ); }
		$absence = array( 'schemaVersion' => 'complete99-campaign-public-quarantine-absence/v1', 'sha256' => hash( 'sha256', self::canonical_json( $surfaces ) ), 'surfaces' => $surfaces );
		$inactive = array( 'absence' => $absence, 'aggregateCleanupReceiptDigest' => str_repeat( 'f', 64 ), 'completedAt' => $stamp, 'cronEmpty' => true, 'generation' => $generation, 'inactiveGeneration' => $generation + 1, 'lifecycleDigest' => (string) $lifecycle_digest, 'openingReceiptDigest' => $opening_digest, 'phase' => 'inactive', 'schemaVersion' => 'complete99-campaign-lifecycle-inactive/v1' );
		$payloads = array( 'suspending' => $opening, 'drained' => $drained, 'inactive' => $inactive );
		$bytes = array();
		foreach ( $payloads as $phase => $payload ) {
			if ( ! self::lifecycle_receipt_payload_valid( $payload, $phase ) || 60000 < strlen( self::canonical_json( $payload ) ) ) { return new WP_Error( 'complete99_campaign_lifecycle_reserve_payload', 'Lifecycle receipt reserve payload is invalid or unbounded.', array( 'status' => 507 ) ); }
			$bytes[ $phase ] = self::lifecycle_capacity_receipt_bytes( $payload, $phase );
		}
		return array( 'payloads' => $payloads, 'bytes' => $bytes );
	}

	/** Reserve only immutable lifecycle pairs still owed by the current/next generation. */
	private static function lifecycle_prior_inactive_receipt_requirement( $state, $generation ) {
		$state = (string) $state;
		$generation = is_int( $generation ) ? $generation : 0;
		if ( ! in_array( $state, array( 'active', 'inactive' ), true ) || 1 > $generation ) {
			return new WP_Error( 'complete99_campaign_lifecycle_prior_identity', 'Lifecycle prior-receipt identity is invalid.', array( 'status' => 503 ) );
		}
		if ( 'active' === $state && 1 === $generation ) { return null; }
		if ( 'active' === $state ) {
			if ( 3 > $generation ) { return new WP_Error( 'complete99_campaign_lifecycle_bootstrap_unproven', 'Active lifecycle bootstrap truth is missing its durable inactive transition.', array( 'status' => 503 ) ); }
			return array( 'receiptGeneration' => $generation - 2, 'inactiveGeneration' => $generation - 1 );
		}
		if ( 2 > $generation ) { return new WP_Error( 'complete99_campaign_lifecycle_bootstrap_unproven', 'Inactive lifecycle bootstrap truth is missing its durable suspension transition.', array( 'status' => 503 ) ); }
		return array( 'receiptGeneration' => $generation - 1, 'inactiveGeneration' => $generation );
	}

	private static function lifecycle_capacity_reservation() {
		global $wpdb;
		$status = self::lifecycle_reservation_status( false );
		if ( is_wp_error( $status ) ) { return $status; }
		$result = array( 'missingRows' => 0, 'campaignCanonicalBytes' => 0, 'operationsCanonicalBytes' => 0 );
		$state = (string) $status['state'];
		if ( in_array( $state, array( 'active', 'inactive' ), true ) ) {
			$requirement = self::lifecycle_prior_inactive_receipt_requirement( $state, (int) $status['generation'] );
			if ( is_wp_error( $requirement ) ) { return $requirement; }
			if ( is_array( $requirement ) ) {
				$prior = self::stored_lifecycle_receipt( (int) $requirement['receiptGeneration'], 'inactive', false );
				if ( is_wp_error( $prior ) || (int) ( $prior['inactiveGeneration'] ?? 0 ) !== (int) $requirement['inactiveGeneration'] ) { return is_wp_error( $prior ) ? $prior : new WP_Error( 'complete99_campaign_lifecycle_reserve_prior', 'Lifecycle capacity is not bound to the prior inactive cleanup chain.', array( 'status' => 503 ) ); }
			}
		}
		if ( 'inactive' === $state ) { return $result; }
		$generation = (int) $status['generation'] + ( 'active' === $state ? 1 : 0 );
		$started_at = 'active' === $state ? '9999-12-31T23:59:59Z' : (string) $status['changedAt'];
		$future = 'active' === $state ? self::lifecycle_reservation_payload( 'suspending', $generation, $started_at ) : null;
		if ( is_wp_error( $future ) ) { return $future; }
		$lifecycle_json = 'active' === $state ? self::canonical_json( $future ) : (string) $status['rawJson'];
		$budget = self::lifecycle_capacity_budget( $generation, hash( 'sha256', $lifecycle_json ), $started_at );
		if ( is_wp_error( $budget ) ) { return $budget; }
		$tables = self::table_names();
		$ops = Complete99_Ops::table_names();
		foreach ( array( 'suspending', 'drained', 'inactive' ) as $phase ) {
			$payload = $budget['payloads'][ $phase ];
			$identity = self::lifecycle_receipt_identity( $payload, $phase );
			$wpdb->last_error = '';
			$providers = $wpdb->get_results( $wpdb->prepare( "SELECT * FROM {$tables['provider_receipts']} WHERE receipt_id=%s OR (provider_key=%s AND external_id=%s) ORDER BY id ASC LIMIT 2", $identity['receiptId'], self::LIFECYCLE_RECEIPT_PROVIDER, $identity['externalId'] ), ARRAY_A );
			$provider_error = (string) $wpdb->last_error;
			$wpdb->last_error = '';
			$audits = $wpdb->get_results( $wpdb->prepare( "SELECT * FROM {$ops['audit_events']} WHERE event_id=%s ORDER BY id ASC LIMIT 2", $identity['eventId'] ), ARRAY_A );
			if ( '' !== $provider_error || '' !== (string) $wpdb->last_error || ! is_array( $providers ) || ! is_array( $audits ) || 1 < count( $providers ) || 1 < count( $audits ) || count( $providers ) !== count( $audits ) ) { return new WP_Error( 'complete99_campaign_lifecycle_reserve_truth', 'Lifecycle receipt reserve truth is unavailable, duplicated, or asymmetric.', array( 'status' => 503 ) ); }
			if ( 1 === count( $providers ) ) {
				$json = (string) ( $providers[0]['proof_ref'] ?? '' );
				$stored_payload = json_decode( $json, true );
				if ( 'active' === $state || ! is_array( $stored_payload ) || ! hash_equals( $json, self::canonical_json( $stored_payload ) ) || ! self::lifecycle_receipt_payload_valid( $stored_payload, $phase ) || $generation !== (int) ( $stored_payload['generation'] ?? 0 ) || ! hash_equals( hash( 'sha256', $lifecycle_json ), (string) ( $stored_payload['lifecycleDigest'] ?? '' ) ) || ( 'suspending' !== $phase && ! hash_equals( hash( 'sha256', self::canonical_json( $budget['payloads']['suspending'] ) ), (string) ( $stored_payload['openingReceiptDigest'] ?? '' ) ) ) || ! self::lifecycle_receipt_matches( $stored_payload, $phase, false ) ) { return new WP_Error( 'complete99_campaign_lifecycle_reserve_collision', 'Lifecycle receipt reserve identity is occupied by divergent truth.', array( 'status' => 503 ) ); }
				continue;
			}
			++$result['missingRows'];
			$result['campaignCanonicalBytes'] += (int) $budget['bytes'][ $phase ]['campaign'];
			$result['operationsCanonicalBytes'] += (int) $budget['bytes'][ $phase ]['operations'];
		}
		$aggregate = self::aggregate_cleanup_capacity_reservation( 'lifecycle', $generation, hash( 'sha256', $lifecycle_json ), 'active' === $state );
		if ( is_wp_error( $aggregate ) ) { return $aggregate; }
		$result['missingRows'] += (int) $aggregate['missingRows'];
		$result['campaignCanonicalBytes'] += (int) $aggregate['campaignCanonicalBytes'];
		$result['operationsCanonicalBytes'] += (int) $aggregate['operationsCanonicalBytes'];
		return $result;
	}

	/** Exact per-table reserve for incomplete immutable quarantine epochs. */
	private static function public_quarantine_capacity_reservation() {
		global $wpdb;
		$campaign = self::table_names();
		$ops = Complete99_Ops::table_names();
		$reserve = array( 'ready' => false, 'active' => false, 'missingReceiptRows' => 0, 'campaignRows' => array_fill_keys( array_keys( $campaign ), 0 ), 'operationsRows' => array_fill_keys( array_keys( $ops ), 0 ), 'campaignCanonicalBytes' => 0, 'operationsCanonicalBytes' => 0, 'recoveryCampaignRows' => array_fill_keys( array_keys( $campaign ), 0 ), 'recoveryOperationsRows' => array_fill_keys( array_keys( $ops ), 0 ), 'recoveryCampaignCanonicalBytes' => 0, 'recoveryOperationsCanonicalBytes' => 0 );
		$status = self::public_quarantine_status( false );
		if ( empty( $status['inspectable'] ) ) { return new WP_Error( 'complete99_campaign_quarantine_reserve_sentinel', 'Public quarantine reserve cannot inspect its permanent sentinel.', array( 'status' => 503 ) ); }
		$discovery = self::public_quarantine_phase_discovery();
		if ( is_wp_error( $discovery ) ) { return $discovery; }
		$phase_campaign_bytes = 0;
		$phase_operations_bytes = 0;
		/* Always reserve the next worst supported epoch; an anonymous fault can open the sentinel in O(1). */
		$wpdb->last_error = '';
		$zero_count = $wpdb->get_var( "SELECT COUNT(*) FROM {$campaign['campaigns']} c WHERE c.lifecycle_state IN ('schedule_requested','active')" );
		$terminal_count = $wpdb->get_var( $wpdb->prepare( "SELECT COUNT(*) FROM {$campaign['placements']} WHERE placement_id<>%s", self::public_quarantine_placement_id() ) );
		if ( '' !== (string) $wpdb->last_error || ! is_numeric( $zero_count ) || ! is_numeric( $terminal_count ) || self::CAMPAIGN_MAX_ROWS < (int) $zero_count || self::PUBLIC_PLACEMENT_MAX_ROWS < (int) $terminal_count ) { return new WP_Error( 'complete99_campaign_quarantine_reserve_projection', 'Public quarantine reserve projection is invalid.', array( 'status' => 503 ) ); }
		$budget = self::public_quarantine_epoch_capacity_budget( (int) $zero_count, (int) $terminal_count );
		if ( is_wp_error( $budget ) ) { return $budget; }
		$reserve['active'] = ! empty( $status['active'] );
		$sentinel_epoch = (int) ( $status['payload']['epoch'] ?? 0 );
		foreach ( array_keys( (array) $discovery['epochs'] ) as $discovered_epoch ) { if ( (int) $discovered_epoch > $sentinel_epoch ) { return new WP_Error( 'complete99_campaign_quarantine_reserve_future_epoch', 'Quarantine receipt inventory contains a future epoch.', array( 'status' => 503 ) ); } }
		$aggregate_epoch = $reserve['active'] ? $sentinel_epoch : $sentinel_epoch + 1;
		$epochs = array_values( array_unique( array_merge( array_map( 'intval', array_keys( (array) $discovery['epochs'] ) ), array( $aggregate_epoch ) ) ) ); sort( $epochs, SORT_NUMERIC );
		$inventories = self::public_quarantine_epoch_phase_inventories( 'quarantine_capacity', $epochs, (array) $discovery['epochs'], false );
		if ( is_wp_error( $inventories ) ) { return $inventories; }
		$add_pair = static function ( $bytes ) use ( &$reserve, &$phase_campaign_bytes, &$phase_operations_bytes ) { ++$reserve['missingReceiptRows']; $phase_campaign_bytes += (int) $bytes['campaign']; $phase_operations_bytes += (int) $bytes['operations']; };
		foreach ( $inventories as $candidate_epoch => $inventory ) {
			$phases = (array) $inventory['phases']; $closed = $inventory['closed']; $is_target = (int) $candidate_epoch === $aggregate_epoch;
			if ( ! $is_target && empty( $inventory['complete'] ) ) {
				if ( ! is_array( $closed ) ) { return new WP_Error( 'complete99_campaign_quarantine_reserve_historical_phase', 'A historical quarantine epoch is incomplete before its final GC-only phase.', array( 'status' => 503 ) ); }
				$historical_budget = self::public_quarantine_epoch_capacity_budget( 0, (int) $closed['rowCount'] );
				if ( is_wp_error( $historical_budget ) ) { return $historical_budget; }
				foreach ( array( 'qto' => (int) $closed['qtoCount'], 'qtr' => (int) $closed['qtnCount'] ) as $class => $count ) {
					if ( 1 > $count ) { continue; }
					if ( null === ( $phases[ 'gc_' . $class . '_intent' ] ?? null ) ) { $add_pair( $historical_budget['gc_intent'] ); }
					if ( null === ( $phases[ 'gc_' . $class . '_complete' ] ?? null ) ) { $add_pair( $historical_budget['gc_complete'] ); }
				}
				continue;
			}
			if ( ! $is_target || ! empty( $inventory['complete'] ) ) { continue; }
			$target_zero_count = is_array( $phases['zero'] ?? null ) ? (int) $phases['zero']['campaignCount'] : (int) $zero_count;
			$target_terminal_count = is_array( $closed ) ? (int) $closed['rowCount'] : (int) $terminal_count;
			$target_budget = self::public_quarantine_epoch_capacity_budget( $target_zero_count, $target_terminal_count );
			if ( is_wp_error( $target_budget ) ) { return $target_budget; }
			foreach ( array( 'opened' => $target_budget['opened'], 'zero' => $target_budget['zero'], 'closed' => $target_budget['closed'] ) as $phase => $bytes ) { if ( null === ( $phases[ $phase ] ?? null ) ) { $add_pair( $bytes ); } }
			$page_count = is_array( $phases['zero'] ?? null ) ? (int) $inventory['zeroPageCount'] : count( $target_budget['zero_page'] );
			for ( $page = 0; $page < $page_count; ++$page ) { $phase = self::public_quarantine_zero_page_phase( $page ); if ( null === ( $phases[ $phase ] ?? null ) ) { $add_pair( $target_budget['zero_page'][ $page ] ); } }
			if ( ! is_array( $closed ) ) { foreach ( array( 'qto', 'qtr' ) as $class ) { if ( null === ( $phases[ 'gc_' . $class . '_intent' ] ?? null ) ) { $add_pair( $target_budget['gc_intent'] ); } if ( null === ( $phases[ 'gc_' . $class . '_complete' ] ?? null ) ) { $add_pair( $target_budget['gc_complete'] ); } } }
			else { foreach ( array( 'qto' => (int) $closed['qtoCount'], 'qtr' => (int) $closed['qtnCount'] ) as $class => $count ) { if ( 0 < $count && null === ( $phases[ 'gc_' . $class . '_intent' ] ?? null ) ) { $add_pair( $target_budget['gc_intent'] ); } if ( 0 < $count && null === ( $phases[ 'gc_' . $class . '_complete' ] ?? null ) ) { $add_pair( $target_budget['gc_complete'] ); } } }
		}
		$aggregate_binding = $reserve['active'] ? hash( 'sha256', self::canonical_json( (array) $status['payload'] ) ) : str_repeat( 'f', 64 );
		if ( ! is_array( $inventories[ $aggregate_epoch ]['closed'] ?? null ) ) { $aggregate = self::aggregate_cleanup_capacity_reservation( 'quarantine', $aggregate_epoch, $aggregate_binding, ! $reserve['active'] ); if ( is_wp_error( $aggregate ) ) { return $aggregate; } $reserve['missingReceiptRows'] += (int) $aggregate['missingRows']; $phase_campaign_bytes += (int) $aggregate['campaignCanonicalBytes']; $phase_operations_bytes += (int) $aggregate['operationsCanonicalBytes']; }
		$lifecycle = self::lifecycle_capacity_reservation();
		if ( is_wp_error( $lifecycle ) ) { return $lifecycle; }
		$reserve['lifecycleMissingReceiptRows'] = (int) $lifecycle['missingRows'];
		$reserve['missingReceiptRows'] += (int) $lifecycle['missingRows'];
		$phase_campaign_bytes += (int) $lifecycle['campaignCanonicalBytes'];
		$phase_operations_bytes += (int) $lifecycle['operationsCanonicalBytes'];
		$reserve['campaignRows']['provider_receipts'] = $reserve['missingReceiptRows'];
		$reserve['operationsRows']['audit_events'] = $reserve['missingReceiptRows'];
		$reserve['campaignCanonicalBytes'] = $phase_campaign_bytes;
		$reserve['operationsCanonicalBytes'] = $phase_operations_bytes;
		/* Aggregate epoch/lifecycle work writes no per-owner revisions, commands, or cleanup receipts. */
		$reserve['ready'] = true;
		return $reserve;
	}

	/**
	 * Return exact, bounded rollback-capacity projections for Campaign and Ops.
	 *
	 * Rows and JSON bytes are measured with the same table order, id order and
	 * canonical JSON flags used by the deployment bridge. Fetching one row past
	 * the supported boundary makes over-capacity state detectable without an
	 * unbounded read.
	 */
	public static function capacity_status() {
		$status = array(
			'schemaVersion'      => 'complete99-campaign-capacity/v3',
			'ready'              => false,
			'writeReady'         => false,
			'inspectable'        => false,
			'maxRowsPerTable'    => self::CAPACITY_MAX_ROWS,
			'maxCampaignRows'    => self::CAMPAIGN_MAX_ROWS,
			'maxCanonicalBytes'  => self::CAPACITY_MAX_BYTES,
			'writeReserveRowsPerTable'   => self::CAPACITY_WRITE_RESERVE_ROWS,
			'writeReserveCanonicalBytes' => self::CAPACITY_WRITE_RESERVE_BYTES,
			'publicEventTableMaxRows'    => self::PUBLIC_EVENT_TABLE_MAX_ROWS,
			'publicEventTableMaxBytes'   => self::PUBLIC_EVENT_TABLE_MAX_BYTES,
			'cohorts'            => array(),
		);
		try {
			$status['cohorts']['operations'] = self::capacity_cohort_status( Complete99_Ops::table_names() );
			$status['cohorts']['campaign']   = self::capacity_cohort_status( self::table_names() );
			$reserve = self::public_quarantine_capacity_reservation();
			if ( is_wp_error( $reserve ) ) { throw new \RuntimeException( $reserve->get_error_code() ); }
			$status['quarantineReserve'] = $reserve;
			$status['ready'] = ! empty( $status['cohorts']['operations']['ready'] ) && ! empty( $status['cohorts']['campaign']['ready'] );
			$campaign_rows = (int) ( $status['cohorts']['campaign']['tables']['campaigns']['rowCount'] ?? PHP_INT_MAX );
			$status['campaignRows'] = $campaign_rows;
			$status['campaignRowHeadroom'] = max( 0, self::CAMPAIGN_MAX_ROWS - $campaign_rows );
			$status['campaignRowLimitReady'] = $campaign_rows <= self::CAMPAIGN_MAX_ROWS;
			if ( ! $status['campaignRowLimitReady'] ) { $status['ready'] = false; }
			$campaign_headroom = (int) ( $status['cohorts']['campaign']['canonicalByteHeadroom'] ?? 0 );
			$operations_headroom = (int) ( $status['cohorts']['operations']['canonicalByteHeadroom'] ?? 0 );
			$quarantine_rows_ready = true;
			$recovery_rows_ready = true;
			foreach ( array( 'campaign', 'operations' ) as $cohort_key ) {
				$core_rows = (array) $reserve[ $cohort_key . 'Rows' ];
				$recovery_rows = (array) $reserve[ 'recovery' . ucfirst( $cohort_key ) . 'Rows' ];
				foreach ( $status['cohorts'][ $cohort_key ]['tables'] as $table_key => $table_status ) {
					$headroom = (int) ( $table_status['rowHeadroom'] ?? 0 );
					$core = (int) ( $core_rows[ $table_key ] ?? 0 );
					$extra = (int) ( $recovery_rows[ $table_key ] ?? 0 );
					if ( $headroom < $core ) { $quarantine_rows_ready = false; }
					if ( $headroom < $core + $extra ) { $recovery_rows_ready = false; }
				}
			}
			$status['quarantineReady'] = $status['ready'] && $quarantine_rows_ready
				&& $campaign_headroom >= (int) $reserve['campaignCanonicalBytes']
				&& $operations_headroom >= (int) $reserve['operationsCanonicalBytes'];
			$status['recoveryReady'] = $status['quarantineReady'] && $recovery_rows_ready
				&& $campaign_headroom >= (int) $reserve['campaignCanonicalBytes'] + (int) $reserve['recoveryCampaignCanonicalBytes']
				&& $operations_headroom >= (int) $reserve['operationsCanonicalBytes'] + (int) $reserve['recoveryOperationsCanonicalBytes'];
			$event_table = $status['cohorts']['campaign']['tables']['event_aggregates'] ?? array();
			$campaign_non_event_bytes = (int) ( $status['cohorts']['campaign']['totalCanonicalBytes'] ?? PHP_INT_MAX ) - (int) ( $event_table['canonicalBytes'] ?? 0 );
			$status['publicEventAllocationReady'] = is_array( $event_table )
				&& (int) ( $event_table['rowCount'] ?? PHP_INT_MAX ) <= self::PUBLIC_EVENT_TABLE_MAX_ROWS
				&& (int) ( $event_table['canonicalBytes'] ?? PHP_INT_MAX ) <= self::PUBLIC_EVENT_TABLE_MAX_BYTES
				&& $campaign_non_event_bytes + self::PUBLIC_EVENT_TABLE_MAX_BYTES + (int) $reserve['campaignCanonicalBytes'] + (int) $reserve['recoveryCampaignCanonicalBytes'] <= self::CAPACITY_MAX_BYTES - self::CAPACITY_WRITE_RESERVE_BYTES;
			$status['inspectable'] = true;
			$status['writeReady'] = $status['recoveryReady']
				&& $campaign_headroom >= self::CAPACITY_WRITE_RESERVE_BYTES + (int) $reserve['campaignCanonicalBytes'] + (int) $reserve['recoveryCampaignCanonicalBytes']
				&& $operations_headroom >= self::CAPACITY_WRITE_RESERVE_BYTES + (int) $reserve['operationsCanonicalBytes'] + (int) $reserve['recoveryOperationsCanonicalBytes'];
			foreach ( array( 'campaign', 'operations' ) as $cohort_key ) {
				$core_rows = (array) $reserve[ $cohort_key . 'Rows' ];
				$recovery_rows = (array) $reserve[ 'recovery' . ucfirst( $cohort_key ) . 'Rows' ];
				foreach ( $status['cohorts'][ $cohort_key ]['tables'] as $table_key => $table_status ) {
					if ( (int) ( $table_status['rowHeadroom'] ?? 0 ) < self::CAPACITY_WRITE_RESERVE_ROWS + (int) ( $core_rows[ $table_key ] ?? 0 ) + (int) ( $recovery_rows[ $table_key ] ?? 0 ) ) { $status['writeReady'] = false; }
				}
			}
			if ( empty( $status['publicEventAllocationReady'] ) ) { $status['writeReady'] = false; }
			if ( empty( $status['campaignRowLimitReady'] ) ) { $status['writeReady'] = false; }
			$status['cacheReady'] = null === self::cache_retry_record();
			if ( ! $status['cacheReady'] ) { $status['writeReady'] = false; }
		} catch ( \Throwable $error ) {
			$status['error'] = 'capacity_inspection_failed';
		}
		return $status;
	}

	/** Lock the bounded Campaign ID range so concurrent creates cannot exceed revision headroom. */
	private static function campaign_row_capacity( $for_update = false ) {
		global $wpdb;
		$table = self::table_names()['campaigns'];
		$lock = $for_update && ! self::is_sqlite_database() ? ' FOR UPDATE' : '';
		$wpdb->last_error = '';
		$rows = $wpdb->get_col( 'SELECT id FROM ' . self::quote_identifier( $table ) . ' ORDER BY id ASC LIMIT ' . ( self::CAMPAIGN_MAX_ROWS + 1 ) . $lock );
		if ( '' !== (string) $wpdb->last_error || ! is_array( $rows ) || self::CAMPAIGN_MAX_ROWS + 1 < count( $rows ) ) { return new WP_Error( 'complete99_campaign_row_capacity_unavailable', 'Campaign row capacity could not be inspected exactly.', array( 'status' => 503 ) ); }
		foreach ( $rows as $index => $id ) { if ( ! is_numeric( $id ) || 1 > (int) $id || ( 0 < $index && (int) $id <= (int) $rows[ $index - 1 ] ) ) { return new WP_Error( 'complete99_campaign_row_capacity_corrupt', 'Campaign row capacity contains malformed identity truth.', array( 'status' => 503 ) ); } }
		return array( 'rowCount' => count( $rows ), 'ready' => count( $rows ) <= self::CAMPAIGN_MAX_ROWS, 'createReady' => count( $rows ) < self::CAMPAIGN_MAX_ROWS );
	}

	/** Measure one exact seven-table cohort using bridge-compatible encoding. */
	private static function capacity_cohort_status( $tables ) {
		global $wpdb;
		$cohort = array(
			'ready'                 => false,
			'writeReady'            => false,
			'totalCanonicalBytes'   => 0,
			'canonicalByteHeadroom' => 0,
			'tables'                => array(),
		);
		$total = 0;
		foreach ( $tables as $key => $table ) {
			$wpdb->last_error = '';
			$rows = $wpdb->get_results(
				'SELECT * FROM ' . self::quote_identifier( $table ) . ' ORDER BY id ASC LIMIT ' . ( self::CAPACITY_MAX_ROWS + 1 ),
				ARRAY_A
			);
			self::throw_on_database_error();
			if ( ! is_array( $rows ) ) { throw new \RuntimeException( 'Rollback capacity rows could not be inspected.' ); }
			$count = count( $rows );
			$bytes = strlen( self::canonical_json( $rows ) );
			$total += $bytes;
			$cohort['tables'][ $key ] = array(
				'rowCount'       => $count,
				'rowHeadroom'    => max( 0, self::CAPACITY_MAX_ROWS - $count ),
				'canonicalBytes' => $bytes,
				'withinLimit'    => $count <= self::CAPACITY_MAX_ROWS,
			);
		}
		$cohort['totalCanonicalBytes'] = $total;
		$cohort['canonicalByteHeadroom'] = max( 0, self::CAPACITY_MAX_BYTES - $total );
		$cohort['ready'] = $total <= self::CAPACITY_MAX_BYTES;
		foreach ( $cohort['tables'] as $table_status ) {
			if ( empty( $table_status['withinLimit'] ) ) { $cohort['ready'] = false; break; }
		}
		$cohort['writeReady'] = $cohort['ready'] && $total <= self::CAPACITY_MAX_BYTES - self::CAPACITY_WRITE_RESERVE_BYTES;
		foreach ( $cohort['tables'] as $table_status ) {
			if ( (int) $table_status['rowHeadroom'] < self::CAPACITY_WRITE_RESERVE_ROWS ) { $cohort['writeReady'] = false; break; }
		}
		return $cohort;
	}

	/** Exact bounded bridge-compatible projection of the public event table only. */
	private static function public_event_capacity_status() {
		global $wpdb;
		$table = self::table_names()['event_aggregates'];
		$wpdb->last_error = '';
		$rows = $wpdb->get_results( 'SELECT * FROM ' . self::quote_identifier( $table ) . ' ORDER BY id ASC LIMIT ' . ( self::PUBLIC_EVENT_TABLE_MAX_ROWS + 1 ), ARRAY_A );
		if ( '' !== (string) $wpdb->last_error || ! is_array( $rows ) ) {
			return new WP_Error( 'complete99_campaign_event_capacity_unavailable', 'Anonymous event capacity could not be inspected.', array( 'status' => 503 ) );
		}
		$count = count( $rows );
		$bytes = strlen( self::canonical_json( $rows ) );
		return array( 'rowCount' => $count, 'canonicalBytes' => $bytes, 'withinLimit' => $count <= self::PUBLIC_EVENT_TABLE_MAX_ROWS && $bytes <= self::PUBLIC_EVENT_TABLE_MAX_BYTES );
	}

	/** Prove that an actual bounded worker completed recently, independent of public traffic. */
	private static function cron_heartbeat_status() {
		global $wpdb;
		$table = self::table_names()['event_aggregates'];
		$lock = self::$transaction_active && ! self::is_sqlite_database() ? ' FOR UPDATE' : '';
		$wpdb->last_error = '';
		$rows = $wpdb->get_results(
			$wpdb->prepare(
				"SELECT * FROM {$table} WHERE placement_id=%s AND event_date=%s AND event_key=%s ORDER BY id ASC LIMIT 2{$lock}",
				self::CRON_HEARTBEAT_PLACEMENT_ID,
				self::CRON_HEARTBEAT_EVENT_DATE,
				self::CRON_HEARTBEAT_EVENT_KEY
			),
			ARRAY_A
		);
		if ( '' !== (string) $wpdb->last_error || ! is_array( $rows ) ) {
			return array( 'ready' => false, 'inspectable' => false, 'reason' => 'query_failed' );
		}
		if ( 1 !== count( $rows ) ) {
			return array( 'ready' => false, 'inspectable' => true, 'reason' => empty( $rows ) ? 'missing' : 'duplicated' );
		}
		$row = $rows[0];
		$last_at = strtotime( (string) ( $row['last_at'] ?? '' ) . ' UTC' );
		$shape_ready = hash_equals( self::CRON_HEARTBEAT_CAMPAIGN_ID, (string) ( $row['campaign_id'] ?? '' ) )
			&& hash_equals( self::CRON_HEARTBEAT_PLACEMENT_ID, (string) ( $row['placement_id'] ?? '' ) )
			&& hash_equals( self::CRON_HEARTBEAT_EVENT_DATE, (string) ( $row['event_date'] ?? '' ) )
			&& hash_equals( '', (string) ( $row['event_hour'] ?? '' ) )
			&& hash_equals( self::CRON_HEARTBEAT_EVENT_KEY, (string) ( $row['event_key'] ?? '' ) )
			&& hash_equals( 'system_cron_heartbeat', (string) ( $row['provenance_key'] ?? '' ) )
			&& hash_equals( hash( 'sha256', 'complete99-campaign-system-cron-heartbeat/v1' ), (string) ( $row['claim_digest'] ?? '' ) )
			&& is_numeric( $row['event_count'] ?? null ) && 0 < (int) $row['event_count']
			&& false !== $last_at && $last_at <= time() + 300;
		$age = false === $last_at ? null : max( 0, time() - $last_at );
		return array(
			'ready'       => $shape_ready && null !== $age && $age <= self::CRON_HEARTBEAT_MAX_AGE,
			'inspectable' => true,
			'lastAt'      => false === $last_at ? null : gmdate( 'Y-m-d\TH:i:s\Z', $last_at ),
			'ageSeconds'  => $age,
			'maxAgeSeconds' => self::CRON_HEARTBEAT_MAX_AGE,
			'reason'      => $shape_ready ? ( $age <= self::CRON_HEARTBEAT_MAX_AGE ? null : 'stale' ) : 'invalid',
		);
	}

	/** Stable digest of the watchdog truth; elapsed seconds are deliberately excluded. */
	private static function cron_heartbeat_digest( $status ) {
		$status = is_array( $status ) ? $status : array();
		return hash(
			'sha256',
			self::canonical_json(
				array(
					'schemaVersion' => 'complete99-campaign-cron-heartbeat-status/v1',
					'ready'         => ! empty( $status['ready'] ),
					'inspectable'   => ! empty( $status['inspectable'] ),
					'lastAt'        => is_string( $status['lastAt'] ?? null ) ? $status['lastAt'] : null,
					'maxAgeSeconds' => self::CRON_HEARTBEAT_MAX_AGE,
					'reason'        => is_string( $status['reason'] ?? null ) ? $status['reason'] : 'unavailable',
				)
			)
		);
	}

	/** Update the single protected heartbeat only after retention succeeded in this transaction. */
	private static function store_cron_heartbeat() {
		global $wpdb;
		if ( ! self::$transaction_active ) { return new WP_Error( 'complete99_campaign_cron_heartbeat_outside_transaction', 'Cron heartbeat requires the protected transaction.', array( 'status' => 503 ) ); }
		$table = self::table_names()['event_aggregates'];
		$now = current_time( 'mysql', true );
		$digest = hash( 'sha256', 'complete99-campaign-system-cron-heartbeat/v1' );
		$wpdb->last_error = '';
		$lock = self::is_sqlite_database() ? '' : ' FOR UPDATE';
		$existing = $wpdb->get_results( $wpdb->prepare( "SELECT id,event_count,first_at FROM {$table} WHERE placement_id=%s AND event_date=%s AND event_key=%s ORDER BY id ASC LIMIT 2{$lock}", self::CRON_HEARTBEAT_PLACEMENT_ID, self::CRON_HEARTBEAT_EVENT_DATE, self::CRON_HEARTBEAT_EVENT_KEY ), ARRAY_A );
		if ( '' !== (string) $wpdb->last_error || ! is_array( $existing ) || 1 < count( $existing ) ) { return new WP_Error( 'complete99_campaign_cron_heartbeat_read_failed', 'Cron heartbeat truth is unavailable.', array( 'status' => 503 ) ); }
		if ( empty( $existing ) ) {
			$stored = $wpdb->insert( $table, array( 'campaign_id' => self::CRON_HEARTBEAT_CAMPAIGN_ID, 'placement_id' => self::CRON_HEARTBEAT_PLACEMENT_ID, 'event_date' => self::CRON_HEARTBEAT_EVENT_DATE, 'event_hour' => '', 'event_key' => self::CRON_HEARTBEAT_EVENT_KEY, 'provenance_key' => 'system_cron_heartbeat', 'claim_digest' => $digest, 'event_count' => 1, 'first_at' => $now, 'last_at' => $now ) );
		} else {
			$count = is_numeric( $existing[0]['event_count'] ?? null ) ? (int) $existing[0]['event_count'] : -1;
			if ( 0 > $count || PHP_INT_MAX === $count ) { return new WP_Error( 'complete99_campaign_cron_heartbeat_invalid', 'Cron heartbeat counter is invalid.', array( 'status' => 503 ) ); }
			$stored = $wpdb->update( $table, array( 'campaign_id' => self::CRON_HEARTBEAT_CAMPAIGN_ID, 'provenance_key' => 'system_cron_heartbeat', 'claim_digest' => $digest, 'event_count' => $count + 1, 'last_at' => $now ), array( 'id' => (int) $existing[0]['id'], 'event_count' => $count ) );
		}
		if ( 1 !== $stored || '' !== (string) $wpdb->last_error ) { return new WP_Error( 'complete99_campaign_cron_heartbeat_store_failed', 'Cron heartbeat could not be stored exactly.', array( 'status' => 503 ) ); }
		$wpdb->last_error = '';
		$row = $wpdb->get_row( $wpdb->prepare( "SELECT campaign_id,placement_id,event_date,event_hour,event_key,provenance_key,claim_digest,event_count,last_at FROM {$table} WHERE placement_id=%s AND event_date=%s AND event_key=%s LIMIT 1{$lock}", self::CRON_HEARTBEAT_PLACEMENT_ID, self::CRON_HEARTBEAT_EVENT_DATE, self::CRON_HEARTBEAT_EVENT_KEY ), ARRAY_A );
		if ( '' !== (string) $wpdb->last_error || ! is_array( $row ) || ! hash_equals( self::CRON_HEARTBEAT_CAMPAIGN_ID, (string) ( $row['campaign_id'] ?? '' ) ) || ! hash_equals( 'system_cron_heartbeat', (string) ( $row['provenance_key'] ?? '' ) ) || ! hash_equals( $digest, (string) ( $row['claim_digest'] ?? '' ) ) || ! hash_equals( $now, (string) ( $row['last_at'] ?? '' ) ) || ! is_numeric( $row['event_count'] ?? null ) || 1 > (int) $row['event_count'] ) {
			return new WP_Error( 'complete99_campaign_cron_heartbeat_readback_failed', 'Cron heartbeat failed exact locked readback.', array( 'status' => 503 ) );
		}
		return true;
	}

	private static function public_quarantine_placement_id() {
		return 'plc_' . substr( hash( 'sha256', 'complete99-public-quarantine-placement/v1' ), 0, 48 );
	}

	private static function public_quarantine_token() {
		/* Reserved singleton identity, never exposed or accepted as a public bearer. */
		return hash( 'sha256', 'complete99-public-quarantine-token/v1' );
	}

	private static function public_quarantine_package_digest() {
		return hash( 'sha256', 'complete99-public-quarantine-package/v1' );
	}

	/** A compact generation-bound terminal status that fits the protected varchar(24). */
	private static function public_quarantine_terminal_status( $payload, $orphan = false ) {
		$prefix = $orphan ? 'qto_' : 'qtn_';
		$epoch = $payload['epoch'] ?? null;
		if ( ! is_int( $epoch ) || 1 > $epoch || PHP_INT_MAX <= $epoch ) { return ''; }
		return $prefix . str_pad( dechex( $epoch ), 16, '0', STR_PAD_LEFT );
	}

	/** Preserve the quarantine epoch on historical rows after an explicit owner recovery. */
	private static function public_quarantine_recovered_status( $terminal_status ) {
		return preg_match( '/\Aqtn_[a-f0-9]{16}\z/', (string) $terminal_status )
			? 'qtr_' . substr( (string) $terminal_status, 4 )
			: '';
	}

	private static function public_quarantine_terminal_projection( $row, $orphan ) {
		return array(
			'id' => (int) ( $row['id'] ?? 0 ),
			'placementId' => (string) ( $row['placement_id'] ?? '' ),
			'campaignId' => (string) ( $row['campaign_id'] ?? '' ),
			'campaignVersion' => (int) ( $row['campaign_version'] ?? 0 ),
			'packageDigest' => (string) ( $row['package_digest'] ?? '' ),
			'slotKey' => (string) ( $row['slot_key'] ?? '' ),
			'locale' => (string) ( $row['locale'] ?? '' ),
			'publicDigest' => (string) ( $row['public_digest'] ?? '' ),
			'readbackTokenDigest' => hash( 'sha256', (string) ( $row['readback_token'] ?? '' ) ),
			'startsAt' => (string) ( $row['starts_at'] ?? '' ),
			'expiresAt' => (string) ( $row['expires_at'] ?? '' ),
			'activatedAt' => (string) ( $row['activated_at'] ?? '' ),
			'createdAt' => (string) ( $row['created_at'] ?? '' ),
			'terminalClass' => $orphan ? 'orphan' : 'campaign',
		);
	}

	private static function public_quarantine_payload( $state, $epoch, $reason_code, $campaign_id, $schedule_digest, $slot, $changed_at, $next_attempt_at, $public_origins = array() ) {
		return array(
			'schemaVersion' => 'complete99-campaign-public-quarantine/v1',
			'state' => (string) $state,
			'epoch' => (int) $epoch,
			'reasonCode' => (string) $reason_code,
			'initiatingCampaignId' => (string) $campaign_id,
			'scheduleDigest' => (string) $schedule_digest,
			'slotKey' => (string) $slot,
			'changedAt' => (string) $changed_at,
			'nextAttemptAt' => (string) $next_attempt_at,
			'publicOrigins' => array_values( (array) $public_origins ),
		);
	}

	private static function public_quarantine_url_is_safe( $url ) {
		if ( ! is_string( $url ) || '' === $url || 512 < strlen( $url ) || preg_match( '/[^\x20-\x7e]/', $url ) ) { return false; }
		$parts = wp_parse_url( $url );
		$query_safe = ! is_array( $parts ) || ! isset( $parts['query'] );
		if ( is_array( $parts ) && isset( $parts['query'] ) ) {
			$path = (string) ( $parts['path'] ?? '/' );
			$query = (string) $parts['query'];
			$query_safe = ( '' === $path || '/' === $path ) && 1 === preg_match( '/\Apage_id=([1-9][0-9]*)\z/', $query, $matches )
				&& (string) (int) $matches[1] === $matches[1] && 0 < (int) $matches[1];
		}
		if ( ! is_array( $parts ) || 'https' !== strtolower( (string) ( $parts['scheme'] ?? '' ) ) || '' === (string) ( $parts['host'] ?? '' )
			|| isset( $parts['user'] ) || isset( $parts['pass'] ) || ! $query_safe || isset( $parts['fragment'] ) || ( isset( $parts['port'] ) && 443 !== (int) $parts['port'] )
			|| preg_match( '/[^A-Za-z0-9.-]/', (string) $parts['host'] ) || preg_match( '/[\\\\\x00-\x1f\x7f]/', (string) ( $parts['path'] ?? '/' ) ) ) { return false; }
		return true;
	}

	/** Validate an immutable owned event endpoint after its original WordPress origin may have changed. */
	private static function historical_owned_event_endpoint_is_safe( $endpoint, $proof_url, $token ) {
		if ( ! self::public_quarantine_url_is_safe( $proof_url ) || ! is_string( $endpoint ) || '' === $endpoint || 1024 < strlen( $endpoint )
			|| ! preg_match( '/\A[a-f0-9]{64}\z/', (string) $token ) || preg_match( '/[^\x20-\x7e]/', $endpoint ) ) { return false; }
		$event = wp_parse_url( $endpoint );
		$proof = wp_parse_url( $proof_url );
		if ( ! is_array( $event ) || ! is_array( $proof ) || 'https' !== strtolower( (string) ( $event['scheme'] ?? '' ) )
			|| isset( $event['user'] ) || isset( $event['pass'] ) || isset( $event['fragment'] )
			|| ! hash_equals( strtolower( (string) ( $proof['host'] ?? '' ) ), strtolower( (string) ( $event['host'] ?? '' ) ) )
			|| (int) ( $proof['port'] ?? 443 ) !== (int) ( $event['port'] ?? 443 )
			|| preg_match( '/[\\\\\x00-\x1f\x7f]/', (string) ( $event['path'] ?? '/' ) ) ) { return false; }
		$route = '/' . trim( self::REST_NAMESPACE, '/' ) . '/campaign-events/' . $token;
		if ( ! isset( $event['query'] ) ) {
			$path = (string) ( $event['path'] ?? '' );
			return strlen( $path ) >= strlen( $route ) && hash_equals( $route, substr( $path, -strlen( $route ) ) );
		}
		$query = (string) $event['query'];
		if ( '' === $query || false !== strpos( $query, '&' ) || false !== strpos( $query, ';' ) || false === strpos( $query, '=' ) ) { return false; }
		list( $raw_key, $raw_value ) = explode( '=', $query, 2 );
		return hash_equals( 'rest_route', rawurldecode( $raw_key ) ) && hash_equals( $route, rawurldecode( $raw_value ) );
	}

	private static function public_quarantine_current_origins( $required_slot = '' ) {
		$urls = array();
		foreach ( array( 'home_banner', 'store_banner' ) as $slot ) {
			$url = self::placement_public_url( $slot );
			if ( is_wp_error( $url ) || ! self::public_quarantine_url_is_safe( $url ) ) {
				if ( hash_equals( (string) $required_slot, $slot ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_origin_invalid', 'The initiating public quarantine surface URL is invalid.', array( 'status' => 503 ) ); }
				continue;
			}
			$urls[] = $url;
		}
		$urls = array_values( array_unique( $urls ) );
		sort( $urls, SORT_STRING );
		return empty( $urls ) ? new WP_Error( 'complete99_campaign_public_quarantine_origin_invalid', 'No public quarantine surface URL is safely resolvable.', array( 'status' => 503 ) ) : $urls;
	}

	private static function public_quarantine_row_values( $payload ) {
		$changed_mysql = self::mysql_datetime_or_null( (string) ( $payload['changedAt'] ?? '' ) );
		$changed_mysql = is_string( $changed_mysql ) ? $changed_mysql : '';
		$json = self::canonical_json( $payload );
		$active = 'active' === (string) ( $payload['state'] ?? '' );
		return array(
			'placement_id' => self::public_quarantine_placement_id(),
			'campaign_id' => self::PUBLIC_QUARANTINE_CAMPAIGN_ID,
			'campaign_version' => (int) ( $payload['epoch'] ?? -1 ),
			'package_digest' => self::public_quarantine_package_digest(),
			'slot_key' => self::PUBLIC_QUARANTINE_SLOT,
			'locale' => 'system',
			'public_json' => $json,
			'public_digest' => hash( 'sha256', $json ),
			'readback_token' => self::public_quarantine_token(),
			'status' => $active ? self::PUBLIC_QUARANTINE_STATUS_ACTIVE : self::PUBLIC_QUARANTINE_STATUS_CLEAR,
			'starts_at' => '1970-01-01 00:00:00',
			'expires_at' => '9999-12-31 23:59:59',
			'activated_at' => $active ? $changed_mysql : null,
			'stopped_at' => $active ? null : $changed_mysql,
			'created_at' => '1970-01-01 00:00:00',
			'updated_at' => $changed_mysql,
		);
	}

	/** Exact singleton status; every public and scheduling path fails closed unless it is clear. */
	private static function public_quarantine_status( $for_update = false ) {
		global $wpdb;
		$table = self::table_names()['placements'];
		$lock = $for_update && ! self::is_sqlite_database() ? ' FOR UPDATE' : '';
		$wpdb->last_error = '';
		$rows = $wpdb->get_results(
			$wpdb->prepare(
				"SELECT * FROM {$table} WHERE placement_id=%s OR readback_token=%s OR campaign_id=%s OR slot_key=%s ORDER BY id ASC LIMIT 3{$lock}",
				self::public_quarantine_placement_id(), self::public_quarantine_token(), self::PUBLIC_QUARANTINE_CAMPAIGN_ID, self::PUBLIC_QUARANTINE_SLOT
			),
			ARRAY_A
		);
		if ( '' !== (string) $wpdb->last_error || ! is_array( $rows ) ) { return array( 'ready' => false, 'active' => false, 'inspectable' => false, 'reason' => 'query_failed' ); }
		if ( 1 !== count( $rows ) ) { return array( 'ready' => false, 'active' => false, 'inspectable' => false, 'reason' => empty( $rows ) ? 'missing' : 'duplicate' ); }
		$row = $rows[0];
		$payload = json_decode( (string) ( $row['public_json'] ?? '' ), true );
		/* json_decode preserves the exact key order emitted by canonical_json(). */
		$keys = array( 'changedAt', 'epoch', 'initiatingCampaignId', 'nextAttemptAt', 'publicOrigins', 'reasonCode', 'scheduleDigest', 'schemaVersion', 'slotKey', 'state' );
		$shape = is_array( $payload ) && array_keys( $payload ) === $keys && 'complete99-campaign-public-quarantine/v1' === (string) ( $payload['schemaVersion'] ?? '' )
			&& in_array( (string) ( $payload['state'] ?? '' ), array( 'clear', 'active' ), true ) && is_int( $payload['epoch'] ?? null ) && 0 <= (int) $payload['epoch'] && PHP_INT_MAX > (int) $payload['epoch']
			&& hash_equals( (string) ( $row['public_json'] ?? '' ), self::canonical_json( $payload ) );
		try {
			$shape = $shape && hash_equals( (string) $payload['changedAt'], self::iso_datetime( (string) $payload['changedAt'] ) );
		} catch ( \Throwable $error ) { $shape = false; }
		if ( $shape && 'clear' === (string) $payload['state'] ) {
			$shape = '' === (string) $payload['reasonCode'] && '' === (string) $payload['initiatingCampaignId'] && '' === (string) $payload['scheduleDigest'] && '' === (string) $payload['slotKey'] && '' === (string) $payload['nextAttemptAt'] && is_array( $payload['publicOrigins'] ) && empty( $payload['publicOrigins'] );
		} elseif ( $shape ) {
			$shape = preg_match( '/\A[a-z0-9_:-]{3,96}\z/', (string) $payload['reasonCode'] )
				&& preg_match( '/\A[a-z0-9_-]{8,64}\z/', (string) $payload['initiatingCampaignId'] )
				&& preg_match( '/\A[a-f0-9]{64}\z/', (string) $payload['scheduleDigest'] )
				&& in_array( (string) $payload['slotKey'], array( 'home_banner', 'store_banner' ), true );
			try {
				$shape = $shape && hash_equals( (string) $payload['nextAttemptAt'], self::iso_datetime( (string) $payload['nextAttemptAt'] ) );
			} catch ( \Throwable $error ) { $shape = false; }
			$origins = $payload['publicOrigins'] ?? null;
			$shape = $shape && is_array( $origins ) && 1 <= count( $origins ) && 4 >= count( $origins ) && array_values( array_unique( $origins ) ) === $origins;
			$sorted = is_array( $origins ) ? $origins : array(); sort( $sorted, SORT_STRING );
			$shape = $shape && $sorted === $origins && count( $origins ) === count( array_filter( $origins, array( __CLASS__, 'public_quarantine_url_is_safe' ) ) );
		}
		$expected = $shape ? self::public_quarantine_row_values( $payload ) : array();
		foreach ( $expected as $key => $value ) {
			if ( is_int( $value ) ? (int) ( $row[ $key ] ?? -1 ) !== $value : ! hash_equals( (string) $value, (string) ( $row[ $key ] ?? '' ) ) ) { $shape = false; break; }
		}
		if ( ! $shape ) { return array( 'ready' => false, 'active' => false, 'inspectable' => false, 'reason' => 'invalid' ); }
		$active = 'active' === (string) $payload['state'];
		return array( 'ready' => ! $active, 'active' => $active, 'inspectable' => true, 'reason' => $active ? 'active' : null, 'row' => $row, 'payload' => $payload );
	}

	private static function ensure_public_quarantine_sentinel() {
		global $wpdb;
		$status = self::public_quarantine_status( false );
		if ( ! empty( $status['inspectable'] ) ) { return true; }
		if ( 'missing' !== (string) ( $status['reason'] ?? '' ) ) { throw new \RuntimeException( 'The public quarantine singleton is malformed.' ); }
		$payload = self::public_quarantine_payload( 'clear', 0, '', '', '', '', '1970-01-01T00:00:00Z', '' );
		$wpdb->last_error = '';
		if ( 1 !== $wpdb->insert( self::table_names()['placements'], self::public_quarantine_row_values( $payload ) ) || '' !== (string) $wpdb->last_error ) {
			throw new \RuntimeException( 'The public quarantine singleton could not be seeded.' );
		}
		$status = self::public_quarantine_status( false );
		if ( empty( $status['inspectable'] ) || empty( $status['ready'] ) ) { throw new \RuntimeException( 'The public quarantine singleton failed exact readback.' ); }
		return true;
	}

	private static function assert_public_quarantine_clear( $for_update = false ) {
		$status = self::public_quarantine_status( $for_update );
		if ( empty( $status['inspectable'] ) || empty( $status['ready'] ) ) {
			return new WP_Error( 'complete99_campaign_public_quarantine', 'Campaign public and scheduling operations are paused for reconciliation.', array( 'status' => 503, 'reason' => (string) ( $status['reason'] ?? 'unavailable' ) ) );
		}
		return true;
	}

	private static function public_quarantine_receipt_identity( $payload, $phase ) {
		$phase = (string) $phase;
		$digest = hash( 'sha256', self::canonical_json( $payload ) );
		$epoch = (int) ( $payload['epoch'] ?? -1 );
		$occurred_at = self::mysql_datetime_or_null( (string) ( $payload['completedAt'] ?? $payload['createdAt'] ?? $payload['recordedAt'] ?? $payload['changedAt'] ?? '' ) );
		$fixed = self::public_quarantine_receipt_fixed_identity( $epoch, $phase );
		return array(
			'eventId' => $fixed['eventId'],
			'receiptId' => $fixed['receiptId'],
			'action' => 'campaign.public_quarantine_' . $phase,
			'subjectId' => self::public_quarantine_receipt_subject_id( $epoch, $phase ),
			'externalId' => $fixed['externalId'],
			'payloadDigest' => $digest,
			'materialDigest' => 'opened' === $phase ? $digest : (string) ( $payload['finalReceiptDigest'] ?? $payload['zeroReceiptDigest'] ?? $payload['openingPayloadDigest'] ?? '' ),
			'proofRef' => self::canonical_json( $payload ),
			'occurredAt' => $occurred_at,
		);
	}

	private static function public_quarantine_receipt_external_state( $phase ) {
		if ( preg_match( '/\Azero_page_[0-9]{4}\z/', (string) $phase ) ) { return 'quarantine_zero_page'; }
		$states = array(
			'opened' => 'quarantine_active',
			'zero' => 'quarantine_zero_overlay',
			'closed' => 'quarantine_clear',
			'gc_qto_intent' => 'quarantine_gc_qto_intent',
			'gc_qto_complete' => 'quarantine_gc_qto_done',
			'gc_qtr_intent' => 'quarantine_gc_qtr_intent',
			'gc_qtr_complete' => 'quarantine_gc_qtr_done',
		);
		return (string) ( $states[ (string) $phase ] ?? '' );
	}

	private static function public_quarantine_receipt_fixed_identity( $epoch, $phase ) {
		$seed = self::public_quarantine_placement_id() . '|' . (int) $epoch . '|' . (string) $phase;
		return array( 'eventId' => 'evt_' . substr( hash( 'sha256', $seed ), 0, 60 ), 'receiptId' => 'qrc_' . substr( hash( 'sha256', $seed ), 0, 60 ), 'externalId' => 'quarantine:' . (int) $epoch . ':' . (string) $phase );
	}

	/** Discover every quarantine phase identity without trusting phase counts. */
	private static function public_quarantine_phase_discovery() {
		global $wpdb;
		$table = self::table_names()['provider_receipts']; $ops = Complete99_Ops::table_names();
		$wpdb->last_error = '';
		$rows = $wpdb->get_results( "SELECT receipt_id,campaign_version,external_state,external_id FROM {$table} WHERE campaign_id='" . self::PUBLIC_QUARANTINE_CAMPAIGN_ID . "' AND provider_key='complete99-public-quarantine' ORDER BY campaign_version ASC,id ASC LIMIT " . ( self::CAPACITY_MAX_ROWS + 1 ), ARRAY_A );
		if ( '' !== (string) $wpdb->last_error || ! is_array( $rows ) || self::CAPACITY_MAX_ROWS < count( $rows ) ) { return new WP_Error( 'complete99_campaign_quarantine_inventory_discovery', 'Quarantine phase identities are unavailable or unbounded.', array( 'status' => 503 ) ); }
		$wpdb->last_error = '';
		$audit_count = $wpdb->get_var( "SELECT COUNT(*) FROM {$ops['audit_events']} WHERE subject_type='campaign_quarantine' AND action LIKE 'campaign.public_quarantine_%'" );
		if ( '' !== (string) $wpdb->last_error || ! is_numeric( $audit_count ) || (int) $audit_count !== count( $rows ) || self::CAPACITY_MAX_ROWS < (int) $audit_count ) { return new WP_Error( 'complete99_campaign_quarantine_inventory_audit_count', 'Quarantine phase provider and audit inventories are asymmetric or unbounded.', array( 'status' => 503 ) ); }
