			} elseif ( null !== $phases['gc_qto_intent'] || null !== $phases['gc_qto_complete'] || null !== $phases['gc_qtr_intent'] || null !== $phases['gc_qtr_complete'] ) { return new WP_Error( 'complete99_campaign_quarantine_inventory_gc_without_final', 'Quarantine GC phase exists without its immutable final receipt.', array( 'status' => 503 ) ); }
			$inventories[ $epoch ] = array( 'phases' => $phases, 'zeroPageCount' => $page_counts[ $epoch ], 'closed' => $closed, 'complete' => is_array( $closed ) && true === $qto_complete && true === $qtr_complete );
		}
		return $inventories;
	}

	private static function public_quarantine_receipt_subject_id( $epoch, $phase ) {
		return 'qtn_' . substr( hash( 'sha256', self::public_quarantine_placement_id() . '|' . (int) $epoch . '|' . (string) $phase ), 0, 60 );
	}

	private static function public_quarantine_provider_receipt_row_matches( $receipt, $payload, $phase, $identity = null ) {
		if ( ! is_array( $receipt ) || ! is_array( $payload ) ) { return false; }
		$identity = is_array( $identity ) ? $identity : self::public_quarantine_receipt_identity( $payload, $phase );
		return hash_equals( (string) $identity['receiptId'], (string) ( $receipt['receipt_id'] ?? '' ) )
			&& self::PUBLIC_QUARANTINE_CAMPAIGN_ID === (string) ( $receipt['campaign_id'] ?? '' ) && (int) ( $payload['epoch'] ?? -1 ) === (int) ( $receipt['campaign_version'] ?? -2 )
			&& 'website' === (string) ( $receipt['channel'] ?? '' ) && 'complete99-public-quarantine' === (string) ( $receipt['provider_key'] ?? '' )
			&& 'complete99-wordpress' === (string) ( $receipt['provider_account_ref'] ?? '' ) && 'confirmed' === (string) ( $receipt['receipt_status'] ?? '' )
			&& 'system_verified' === (string) ( $receipt['proof_level'] ?? '' ) && '' !== self::public_quarantine_receipt_external_state( $phase ) && hash_equals( self::public_quarantine_receipt_external_state( $phase ), (string) ( $receipt['external_state'] ?? '' ) )
			&& hash_equals( (string) $identity['externalId'], (string) ( $receipt['external_id'] ?? '' ) ) && hash_equals( (string) $identity['proofRef'], (string) ( $receipt['proof_ref'] ?? '' ) )
			&& hash_equals( (string) $identity['materialDigest'], (string) ( $receipt['material_digest'] ?? '' ) ) && hash_equals( (string) $identity['payloadDigest'], (string) ( $receipt['payload_digest'] ?? '' ) )
			&& hash_equals( (string) $identity['occurredAt'], (string) ( $receipt['occurred_at'] ?? '' ) ) && 0 === (int) ( $receipt['created_by'] ?? -1 )
			&& hash_equals( (string) $identity['occurredAt'], (string) ( $receipt['created_at'] ?? '' ) );
	}

	private static function public_quarantine_audit_row_matches( $row, $identity ) {
		return is_array( $row ) && is_array( $identity )
			&& hash_equals( (string) $identity['eventId'], (string) ( $row['event_id'] ?? '' ) ) && 0 === (int) ( $row['actor_user_id'] ?? -1 )
			&& hash_equals( (string) $identity['action'], (string) ( $row['action'] ?? '' ) ) && 'campaign_quarantine' === (string) ( $row['subject_type'] ?? '' )
			&& hash_equals( (string) $identity['subjectId'], (string) ( $row['subject_id'] ?? '' ) ) && '' === (string) ( $row['command_id'] ?? '' )
			&& hash_equals( (string) $identity['payloadDigest'], (string) ( $row['payload_digest'] ?? '' ) ) && hash_equals( (string) $identity['occurredAt'], (string) ( $row['occurred_at'] ?? '' ) );
	}

	private static function public_quarantine_receipt_matches( $payload, $phase, $for_update = false ) {
		global $wpdb;
		$identity = self::public_quarantine_receipt_identity( $payload, $phase );
		$ops = Complete99_Ops::table_names();
		$tables = self::table_names();
		$lock = $for_update && ! self::is_sqlite_database() ? ' FOR UPDATE' : '';
		$wpdb->last_error = '';
		$receipts = $wpdb->get_results( $wpdb->prepare( "SELECT * FROM {$tables['provider_receipts']} WHERE receipt_id=%s OR (provider_key='complete99-public-quarantine' AND external_id=%s) ORDER BY id ASC LIMIT 2{$lock}", $identity['receiptId'], $identity['externalId'] ), ARRAY_A );
		if ( '' !== (string) $wpdb->last_error || ! is_array( $receipts ) || 1 !== count( $receipts ) ) { return false; }
		if ( ! self::public_quarantine_provider_receipt_row_matches( $receipts[0], $payload, $phase, $identity ) ) { return false; }
		$wpdb->last_error = '';
		$rows = $wpdb->get_results( $wpdb->prepare( "SELECT * FROM {$ops['audit_events']} WHERE event_id=%s ORDER BY id ASC LIMIT 2{$lock}", $identity['eventId'] ), ARRAY_A );
		return '' === (string) $wpdb->last_error && is_array( $rows ) && 1 === count( $rows ) && self::public_quarantine_audit_row_matches( $rows[0], $identity );
	}

	/** Store an immutable opening/final receipt while the active singleton stays locked. */
	private static function store_public_quarantine_receipt( $active_payload, $target_payload, $phase ) {
		$started = self::begin_transaction( self::CAPACITY_ROLE_QUARANTINE );
		if ( is_wp_error( $started ) ) { return $started; }
		$stored = self::store_public_quarantine_receipt_locked( $active_payload, $target_payload, $phase );
		if ( is_wp_error( $stored ) ) { self::rollback_transaction(); return $stored; }
		$commit = self::commit_transaction();
		if ( is_wp_error( $commit ) && ! self::public_quarantine_receipt_matches( $target_payload, $phase, false ) ) { return $commit; }
		return true;
	}

	/** Inner receipt writer: it never owns or closes the caller's protected transaction. */
	private static function store_public_quarantine_receipt_locked( $active_payload, $target_payload, $phase ) {
		global $wpdb;
		if ( ! self::$transaction_active ) { return new WP_Error( 'complete99_campaign_public_quarantine_receipt_unlocked', 'Public quarantine receipt storage requires the protected writer transaction.', array( 'status' => 503 ) ); }
		$status = self::public_quarantine_status( true );
		if ( empty( $status['inspectable'] ) || empty( $status['active'] ) || ! hash_equals( self::canonical_json( $active_payload ), self::canonical_json( (array) ( $status['payload'] ?? array() ) ) ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_receipt_state', 'Public quarantine receipt state is stale.', array( 'status' => 409 ) ); }
		$identity = self::public_quarantine_receipt_identity( $target_payload, $phase );
		if ( ! preg_match( '/\A[a-f0-9]{64}\z/', $identity['materialDigest'] ) || ! is_string( $identity['occurredAt'] ) || '' === $identity['occurredAt'] || strlen( $identity['proofRef'] ) > 60000 ) { return new WP_Error( 'complete99_campaign_public_quarantine_receipt_payload', 'Public quarantine receipt payload is invalid.', array( 'status' => 503 ) ); }
		if ( ! self::public_quarantine_receipt_matches( $target_payload, $phase, true ) ) {
			$tables = self::table_names();
			$lock = self::is_sqlite_database() ? '' : ' FOR UPDATE';
			$wpdb->last_error = '';
			$existing = $wpdb->get_results( $wpdb->prepare( "SELECT * FROM {$tables['provider_receipts']} WHERE receipt_id=%s OR (provider_key='complete99-public-quarantine' AND external_id=%s) ORDER BY id ASC LIMIT 2{$lock}", $identity['receiptId'], $identity['externalId'] ), ARRAY_A );
			if ( '' !== (string) $wpdb->last_error || ! is_array( $existing ) || ! empty( $existing ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_receipt_collision', 'Public quarantine receipt identity is already occupied by divergent truth.', array( 'status' => 503 ) ); }
			$stored = $wpdb->insert( $tables['provider_receipts'], array( 'receipt_id' => $identity['receiptId'], 'campaign_id' => self::PUBLIC_QUARANTINE_CAMPAIGN_ID, 'campaign_version' => (int) $target_payload['epoch'], 'channel' => 'website', 'provider_key' => 'complete99-public-quarantine', 'provider_account_ref' => 'complete99-wordpress', 'receipt_status' => 'confirmed', 'proof_level' => 'system_verified', 'external_state' => self::public_quarantine_receipt_external_state( $phase ), 'external_id' => $identity['externalId'], 'proof_ref' => $identity['proofRef'], 'material_digest' => $identity['materialDigest'], 'payload_digest' => $identity['payloadDigest'], 'occurred_at' => $identity['occurredAt'], 'created_by' => 0, 'created_at' => $identity['occurredAt'] ) );
			if ( 1 !== $stored || '' !== (string) $wpdb->last_error ) { return new WP_Error( 'complete99_campaign_public_quarantine_receipt_store', 'Public quarantine proof receipt could not be stored.', array( 'status' => 503 ) ); }
			self::invalidate_receipt_phase_inventory_cache();
			$ops = Complete99_Ops::table_names();
			$wpdb->last_error = '';
			$stored = $wpdb->insert( $ops['audit_events'], array( 'event_id' => $identity['eventId'], 'actor_user_id' => 0, 'action' => $identity['action'], 'subject_type' => 'campaign_quarantine', 'subject_id' => $identity['subjectId'], 'command_id' => null, 'payload_digest' => $identity['payloadDigest'], 'occurred_at' => $identity['occurredAt'] ) );
			if ( 1 !== $stored || '' !== (string) $wpdb->last_error || ! self::public_quarantine_receipt_matches( $target_payload, $phase, true ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_receipt_store', 'Public quarantine receipt could not be stored exactly.', array( 'status' => 503 ) ); }
			self::invalidate_receipt_phase_inventory_cache();
		}
		return true;
	}

	/** Load a fixed logical receipt and require its full canonical provider+audit binding. */
	private static function public_quarantine_stored_receipt_payload( $epoch, $phase, $for_update = false ) {
		global $wpdb;
		if ( ! is_int( $epoch ) || 1 > $epoch || ! in_array( $phase, array( 'opened', 'closed', 'zero' ), true ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_receipt_identity_invalid', 'Public quarantine receipt identity is invalid.', array( 'status' => 503 ) ); }
		$fixed = self::public_quarantine_receipt_fixed_identity( $epoch, $phase );
		$table = self::table_names()['provider_receipts'];
		$lock = $for_update && ! self::is_sqlite_database() ? ' FOR UPDATE' : '';
		$wpdb->last_error = '';
		$rows = $wpdb->get_results( $wpdb->prepare( "SELECT * FROM {$table} WHERE receipt_id=%s OR (provider_key='complete99-public-quarantine' AND external_id=%s) ORDER BY id ASC LIMIT 2{$lock}", $fixed['receiptId'], $fixed['externalId'] ), ARRAY_A );
		if ( '' !== (string) $wpdb->last_error || ! is_array( $rows ) || 1 !== count( $rows ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_receipt_unavailable', 'Public quarantine receipt is missing or duplicated.', array( 'status' => 503 ) ); }
		$proof_json = (string) ( $rows[0]['proof_ref'] ?? '' );
		$proof = json_decode( $proof_json, true );
		if ( ! is_array( $proof ) || ! hash_equals( $proof_json, self::canonical_json( $proof ) ) || 60000 < strlen( $proof_json ) || (int) ( $proof['epoch'] ?? -1 ) !== $epoch || ! self::public_quarantine_receipt_matches( $proof, $phase, $for_update ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_receipt_corrupt', 'Public quarantine receipt failed its full canonical binding.', array( 'status' => 503 ) ); }
		return $proof;
	}

	/** Load one immutable terminal-GC receipt without scanning historical proof payloads. */
	private static function public_quarantine_gc_receipt_payload( $epoch, $phase, $for_update = false ) {
		global $wpdb;
		$allowed = array( 'gc_qto_intent', 'gc_qto_complete', 'gc_qtr_intent', 'gc_qtr_complete' );
		if ( ! is_int( $epoch ) || 1 > $epoch || ! in_array( $phase, $allowed, true ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_gc_identity', 'Public quarantine GC receipt identity is invalid.', array( 'status' => 503 ) ); }
		$fixed = self::public_quarantine_receipt_fixed_identity( $epoch, $phase );
		$lock = $for_update && ! self::is_sqlite_database() ? ' FOR UPDATE' : '';
		$table = self::table_names()['provider_receipts'];
		$wpdb->last_error = '';
		$rows = $wpdb->get_results( $wpdb->prepare( "SELECT * FROM {$table} WHERE receipt_id=%s OR (provider_key='complete99-public-quarantine' AND external_id=%s) ORDER BY id ASC LIMIT 2{$lock}", $fixed['receiptId'], $fixed['externalId'] ), ARRAY_A );
		if ( '' !== (string) $wpdb->last_error || ! is_array( $rows ) || 1 !== count( $rows ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_gc_receipt_unavailable', 'Public quarantine GC receipt is missing or duplicated.', array( 'status' => 503, 'missing' => is_array( $rows ) && empty( $rows ) ) ); }
		$json = (string) ( $rows[0]['proof_ref'] ?? '' );
		$proof = json_decode( $json, true );
		if ( ! is_array( $proof ) || 60000 < strlen( $json ) || ! hash_equals( $json, self::canonical_json( $proof ) ) || (int) ( $proof['epoch'] ?? -1 ) !== $epoch || ! self::public_quarantine_receipt_matches( $proof, $phase, $for_update ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_gc_receipt_corrupt', 'Public quarantine GC receipt failed exact canonical binding.', array( 'status' => 503 ) ); }
		return $proof;
	}

	/** Store one terminal-GC proof while a clear sentinel and final receipt are locked. */
	private static function store_public_quarantine_gc_receipt_locked( $payload, $phase ) {
		global $wpdb;
		if ( ! self::$transaction_active ) { return new WP_Error( 'complete99_campaign_public_quarantine_gc_unlocked', 'Public quarantine GC receipt storage requires a protected transaction.', array( 'status' => 503 ) ); }
		$status = self::public_quarantine_status( true );
		$epoch = $payload['epoch'] ?? null;
		if ( empty( $status['inspectable'] ) || empty( $status['ready'] ) || ! is_int( $epoch ) || 1 > $epoch || (int) ( $status['payload']['epoch'] ?? 0 ) < $epoch ) { return new WP_Error( 'complete99_campaign_public_quarantine_gc_state', 'Public quarantine GC requires clear, non-regressed sentinel truth.', array( 'status' => 503 ) ); }
		$final = self::public_quarantine_stored_receipt_payload( $epoch, 'closed', true );
		$final_digest = is_wp_error( $final ) ? '' : hash( 'sha256', self::canonical_json( $final ) );
		if ( is_wp_error( $final ) || ! hash_equals( $final_digest, (string) ( $payload['finalReceiptDigest'] ?? '' ) ) ) { return is_wp_error( $final ) ? $final : new WP_Error( 'complete99_campaign_public_quarantine_gc_final_binding', 'Public quarantine GC is not bound to the immutable final receipt.', array( 'status' => 503 ) ); }
		$identity = self::public_quarantine_receipt_identity( $payload, $phase );
		if ( '' === self::public_quarantine_receipt_external_state( $phase ) || ! preg_match( '/\A[a-f0-9]{64}\z/', (string) $identity['materialDigest'] ) || '' === (string) $identity['occurredAt'] || 60000 < strlen( $identity['proofRef'] ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_gc_payload', 'Public quarantine GC receipt payload is invalid.', array( 'status' => 503 ) ); }
		if ( self::public_quarantine_receipt_matches( $payload, $phase, true ) ) { return true; }
		$tables = self::table_names();
		$lock = self::is_sqlite_database() ? '' : ' FOR UPDATE';
		$wpdb->last_error = '';
		$existing = $wpdb->get_results( $wpdb->prepare( "SELECT id FROM {$tables['provider_receipts']} WHERE receipt_id=%s OR (provider_key='complete99-public-quarantine' AND external_id=%s) ORDER BY id ASC LIMIT 2{$lock}", $identity['receiptId'], $identity['externalId'] ), ARRAY_A );
		if ( '' !== (string) $wpdb->last_error || ! is_array( $existing ) || ! empty( $existing ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_gc_collision', 'Public quarantine GC receipt identity is occupied by divergent truth.', array( 'status' => 503 ) ); }
		$stored = $wpdb->insert( $tables['provider_receipts'], array( 'receipt_id' => $identity['receiptId'], 'campaign_id' => self::PUBLIC_QUARANTINE_CAMPAIGN_ID, 'campaign_version' => $epoch, 'channel' => 'website', 'provider_key' => 'complete99-public-quarantine', 'provider_account_ref' => 'complete99-wordpress', 'receipt_status' => 'confirmed', 'proof_level' => 'system_verified', 'external_state' => self::public_quarantine_receipt_external_state( $phase ), 'external_id' => $identity['externalId'], 'proof_ref' => $identity['proofRef'], 'material_digest' => $identity['materialDigest'], 'payload_digest' => $identity['payloadDigest'], 'occurred_at' => $identity['occurredAt'], 'created_by' => 0, 'created_at' => $identity['occurredAt'] ) );
		if ( 1 !== $stored || '' !== (string) $wpdb->last_error ) { return new WP_Error( 'complete99_campaign_public_quarantine_gc_store', 'Public quarantine GC provider receipt could not be stored.', array( 'status' => 503 ) ); }
		self::invalidate_receipt_phase_inventory_cache();
		$ops = Complete99_Ops::table_names();
		$stored = $wpdb->insert( $ops['audit_events'], array( 'event_id' => $identity['eventId'], 'actor_user_id' => 0, 'action' => $identity['action'], 'subject_type' => 'campaign_quarantine', 'subject_id' => $identity['subjectId'], 'command_id' => null, 'payload_digest' => $identity['payloadDigest'], 'occurred_at' => $identity['occurredAt'] ) );
		if ( 1 === $stored && '' === (string) $wpdb->last_error ) { self::invalidate_receipt_phase_inventory_cache(); }
		return 1 === $stored && '' === (string) $wpdb->last_error && self::public_quarantine_receipt_matches( $payload, $phase, true ) ? true : new WP_Error( 'complete99_campaign_public_quarantine_gc_store', 'Public quarantine GC receipt failed exact provider and audit readback.', array( 'status' => 503 ) );
	}

	/** Build one compact exact overlay for every campaign governed by this quarantine generation. */
	private static function public_quarantine_zero_membership_cohort( $opening, $for_update = false, &$member_digests = null ) {
		global $wpdb;
		if ( ! is_array( $opening ) || 'active' !== (string) ( $opening['state'] ?? '' ) || ! is_int( $opening['epoch'] ?? null ) || 1 > $opening['epoch'] ) { return new WP_Error( 'complete99_campaign_public_quarantine_zero_opening', 'Zero-placement quarantine opening truth is invalid.', array( 'status' => 503 ) ); }
		$tables = self::table_names();
		$lock = $for_update && ! self::is_sqlite_database() ? ' FOR UPDATE' : '';
		$cursor = 0;
		$count = 0;
		$first = 0;
		$last = 0;
		$id_bytes = '';
		$opening_digest = hash( 'sha256', self::canonical_json( $opening ) );
		$chain = hash( 'sha256', 'complete99-campaign-public-quarantine-zero/v1|' . (int) $opening['epoch'] . '|' . $opening_digest );
		$member_digests = array();
		do {
			$wpdb->last_error = '';
			$rows = $wpdb->get_results( $wpdb->prepare( "SELECT c.* FROM {$tables['campaigns']} c WHERE c.id>%d AND (c.lifecycle_state IN ('schedule_requested','active') OR c.public_id=%s) ORDER BY c.id ASC LIMIT 201{$lock}", $cursor, (string) $opening['initiatingCampaignId'] ), ARRAY_A );
			if ( '' !== (string) $wpdb->last_error || ! is_array( $rows ) || 201 < count( $rows ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_zero_query', 'Aggregate quarantine campaign cohort is unavailable.', array( 'status' => 503 ) ); }
			foreach ( array_slice( $rows, 0, 200 ) as $row ) {
				$id = is_numeric( $row['id'] ?? null ) ? (int) $row['id'] : 0;
				$loaded = self::decode_campaign_row( $row );
				$projection = is_wp_error( $loaded ) ? $loaded : self::public_quarantine_zero_projection_from_loaded( $loaded );
				if ( $id <= $cursor || 1 > $id || self::CAMPAIGN_MAX_ROWS < ++$count || is_wp_error( $projection ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_zero_corrupt', 'Zero-placement campaign cohort contains malformed truth.', array( 'status' => 503 ) ); }
				$chain = hash( 'sha256', $chain . '|' . self::canonical_json( $projection ) );
				$member_digests[] = hash( 'sha256', self::canonical_json( $projection ) );
				$high = (int) floor( $id / 4294967296 );
				$low = (int) ( $id - ( $high * 4294967296 ) );
				$id_bytes .= pack( 'NN', $high, $low );
				if ( 0 === $first ) { $first = $id; }
				$last = $id;
				$cursor = $id;
			}
		} while ( 200 < count( $rows ) );
		return array( 'schemaVersion' => 'complete99-campaign-public-quarantine-zero/v1', 'epoch' => (int) $opening['epoch'], 'openingPayloadDigest' => $opening_digest, 'problemClass' => 'quarantine_generation_member', 'campaignCount' => $count, 'firstId' => $first, 'lastId' => $last, 'campaignIdsBase64' => base64_encode( $id_bytes ), 'rowsSha256' => $chain, 'recordedAt' => (string) $opening['changedAt'] );
	}

	/** Stable per-member projection used to reject ID reuse or row substitution on recovery. */
	private static function public_quarantine_zero_projection_from_loaded( $loaded ) {
		if ( is_wp_error( $loaded ) || ! is_array( $loaded['row'] ?? null ) || ! is_array( $loaded['state'] ?? null ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_zero_member_unavailable', 'Zero-placement campaign truth is unavailable.', array( 'status' => 503 ) ); }
		$row = $loaded['row'];
		$state = $loaded['state'];
		$projection = array(
			'id' => (int) ( $row['id'] ?? 0 ),
			'publicId' => (string) ( $row['public_id'] ?? '' ),
			'version' => (int) ( $row['version'] ?? 0 ),
			'stateDigest' => (string) ( $row['state_digest'] ?? '' ),
			'lifecycleState' => (string) ( $row['lifecycle_state'] ?? '' ),
			'externalState' => (string) ( $row['external_state'] ?? '' ),
			'jobState' => (string) ( $row['job_state'] ?? '' ),
			'scheduledVersion' => (int) ( $state['runtime']['scheduledVersion'] ?? 0 ),
			'scheduleDigest' => (string) ( $state['runtime']['scheduleDigest'] ?? '' ),
			'slotKey' => (string) ( $row['slot_key'] ?? '' ),
			'activationAt' => (string) ( $row['activation_at'] ?? '' ),
			'expiryAt' => (string) ( $row['expiry_at'] ?? '' ),
			'problemClass' => 'quarantine_generation_member',
		);
		$allowed_external = array( 'unverified', 'owned_pending', 'owned_active', 'suppressed' );
		$job = $projection['jobState'];
		if ( 'suspended' === $job ) { $job = (string) ( $state['runtime']['suspendedFromJobState'] ?? '' ); }
		$pair_valid = ( 'schedule_requested' === $projection['lifecycleState'] && 'unverified' === $projection['externalState'] && in_array( $job, array( 'reconcile_pending', 'scheduled', 'readback_pending', 'retry_pending', 'expiry_retry_pending' ), true ) )
			|| ( 'schedule_requested' === $projection['lifecycleState'] && 'owned_pending' === $projection['externalState'] && in_array( $job, array( 'readback_pending', 'retry_pending', 'expiry_retry_pending' ), true ) )
			|| ( 'active' === $projection['lifecycleState'] && 'owned_active' === $projection['externalState'] && in_array( $job, array( 'readback_verified', 'retry_pending', 'expiry_retry_pending' ), true ) )
			|| ( 'suppressed' === $projection['externalState'] && in_array( $job, array( 'authority_retry_pending', 'operator_attention' ), true ) );
		if ( 1 > $projection['id'] || ! hash_equals( $projection['publicId'], (string) ( $state['campaignId'] ?? '' ) ) || 1 > $projection['version'] || ! preg_match( '/\A[a-f0-9]{64}\z/', $projection['stateDigest'] ) || ! in_array( $projection['lifecycleState'], array( 'schedule_requested', 'active' ), true ) || ! in_array( $projection['externalState'], $allowed_external, true ) || ! $pair_valid || 1 > $projection['scheduledVersion'] || ! preg_match( '/\A[a-f0-9]{64}\z/', $projection['scheduleDigest'] ) || ! in_array( $projection['slotKey'], array( 'home_banner', 'store_banner' ), true ) || false === strtotime( $projection['activationAt'] . ' UTC' ) || false === strtotime( $projection['expiryAt'] . ' UTC' ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_zero_member_corrupt', 'Aggregate quarantine campaign truth no longer matches its captured problem class.', array( 'status' => 503 ) ); }
		return $projection;
	}

	private static function public_quarantine_zero_page_phase( $page_index ) {
		return sprintf( 'zero_page_%04d', (int) $page_index );
	}

	private static function public_quarantine_zero_page_payload( $zero_proof, $page_index, $digests ) {
		$page_index = (int) $page_index;
		$first = $page_index * self::PUBLIC_QUARANTINE_ZERO_PAGE_SIZE;
		$expected = min( self::PUBLIC_QUARANTINE_ZERO_PAGE_SIZE, max( 0, (int) ( $zero_proof['campaignCount'] ?? 0 ) - $first ) );
		if ( 0 > $page_index || 1 > $expected || count( (array) $digests ) !== $expected ) { return new WP_Error( 'complete99_campaign_public_quarantine_zero_page_shape', 'Zero-placement member page is invalid.', array( 'status' => 503 ) ); }
		$bytes = '';
		foreach ( $digests as $digest ) {
			if ( ! is_string( $digest ) || ! preg_match( '/\A[a-f0-9]{64}\z/', $digest ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_zero_page_digest', 'Zero-placement member digest is invalid.', array( 'status' => 503 ) ); }
			$bytes .= hex2bin( $digest );
		}
		return array( 'schemaVersion' => 'complete99-campaign-public-quarantine-zero-page/v1', 'epoch' => (int) $zero_proof['epoch'], 'pageIndex' => $page_index, 'firstMemberIndex' => $first, 'memberCount' => $expected, 'memberDigestsBase64' => base64_encode( $bytes ), 'zeroReceiptDigest' => hash( 'sha256', self::canonical_json( $zero_proof ) ), 'recordedAt' => (string) $zero_proof['recordedAt'] );
	}

	/** Load one fixed zero-member page and bind it to the immutable zero receipt. */
	private static function public_quarantine_zero_page_receipt( $zero_proof, $page_index, $for_update = false ) {
		global $wpdb;
		$page_index = (int) $page_index;
		$phase = self::public_quarantine_zero_page_phase( $page_index );
		$fixed = self::public_quarantine_receipt_fixed_identity( (int) ( $zero_proof['epoch'] ?? 0 ), $phase );
		$lock = $for_update && ! self::is_sqlite_database() ? ' FOR UPDATE' : '';
		$table = self::table_names()['provider_receipts'];
		$wpdb->last_error = '';
		$rows = $wpdb->get_results( $wpdb->prepare( "SELECT * FROM {$table} WHERE receipt_id=%s OR (provider_key='complete99-public-quarantine' AND external_id=%s) ORDER BY id ASC LIMIT 2{$lock}", $fixed['receiptId'], $fixed['externalId'] ), ARRAY_A );
		if ( '' !== (string) $wpdb->last_error || ! is_array( $rows ) || 1 !== count( $rows ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_zero_page_unavailable', 'A zero-placement member page is missing or duplicated.', array( 'status' => 503 ) ); }
		$json = (string) ( $rows[0]['proof_ref'] ?? '' );
		$proof = json_decode( $json, true );
		$keys = array( 'epoch', 'firstMemberIndex', 'memberCount', 'memberDigestsBase64', 'pageIndex', 'recordedAt', 'schemaVersion', 'zeroReceiptDigest' );
		$first = $page_index * self::PUBLIC_QUARANTINE_ZERO_PAGE_SIZE;
		$expected = min( self::PUBLIC_QUARANTINE_ZERO_PAGE_SIZE, max( 0, (int) ( $zero_proof['campaignCount'] ?? 0 ) - $first ) );
		$raw = is_array( $proof ) ? base64_decode( (string) ( $proof['memberDigestsBase64'] ?? '' ), true ) : false;
		if ( ! is_array( $proof ) || array_keys( $proof ) !== $keys || 60000 < strlen( $json ) || ! hash_equals( $json, self::canonical_json( $proof ) ) || 'complete99-campaign-public-quarantine-zero-page/v1' !== (string) ( $proof['schemaVersion'] ?? '' ) || (int) ( $zero_proof['epoch'] ?? -1 ) !== (int) ( $proof['epoch'] ?? -2 ) || $page_index !== (int) ( $proof['pageIndex'] ?? -1 ) || $first !== (int) ( $proof['firstMemberIndex'] ?? -1 ) || $expected !== (int) ( $proof['memberCount'] ?? -1 ) || ! hash_equals( hash( 'sha256', self::canonical_json( $zero_proof ) ), (string) ( $proof['zeroReceiptDigest'] ?? '' ) ) || ! hash_equals( (string) ( $zero_proof['recordedAt'] ?? '' ), (string) ( $proof['recordedAt'] ?? '' ) ) || ! is_string( $raw ) || strlen( $raw ) !== $expected * 32 || ! hash_equals( (string) $proof['memberDigestsBase64'], base64_encode( $raw ) ) || ! self::public_quarantine_receipt_matches( $proof, $phase, $for_update ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_zero_page_corrupt', 'A zero-placement member page failed exact receipt binding.', array( 'status' => 503 ) ); }
		$digests = array();
		for ( $offset = 0; $offset < strlen( $raw ); $offset += 32 ) { $digests[] = bin2hex( substr( $raw, $offset, 32 ) ); }
		return array( 'proof' => $proof, 'digests' => $digests );
	}

	/** Load and exactly validate the immutable zero-placement overlay receipt. */
	private static function public_quarantine_zero_membership_receipt( $epoch, $for_update = false ) {
		$cache_key = (string) (int) $epoch;
		if ( ! $for_update && isset( self::$public_quarantine_zero_cache[ $cache_key ] ) ) { return self::$public_quarantine_zero_cache[ $cache_key ]; }
		$proof = self::public_quarantine_stored_receipt_payload( (int) $epoch, 'zero', $for_update );
		$keys = array( 'campaignCount', 'campaignIdsBase64', 'epoch', 'firstId', 'lastId', 'openingPayloadDigest', 'problemClass', 'recordedAt', 'rowsSha256', 'schemaVersion' );
		if ( is_wp_error( $proof ) || array_keys( (array) $proof ) !== $keys || 'complete99-campaign-public-quarantine-zero/v1' !== (string) ( $proof['schemaVersion'] ?? '' )
			|| (int) $epoch !== (int) ( $proof['epoch'] ?? -1 ) || ! is_int( $proof['campaignCount'] ?? null ) || 0 > $proof['campaignCount'] || self::CAMPAIGN_MAX_ROWS < $proof['campaignCount']
			|| ! is_int( $proof['firstId'] ?? null ) || ! is_int( $proof['lastId'] ?? null ) || ! preg_match( '/\A[a-f0-9]{64}\z/', (string) ( $proof['openingPayloadDigest'] ?? '' ) ) || ! preg_match( '/\A[a-f0-9]{64}\z/', (string) ( $proof['rowsSha256'] ?? '' ) )
			|| 'quarantine_generation_member' !== (string) ( $proof['problemClass'] ?? '' ) ) { return is_wp_error( $proof ) ? $proof : new WP_Error( 'complete99_campaign_public_quarantine_zero_receipt_shape', 'Aggregate quarantine overlay receipt is malformed.', array( 'status' => 503 ) ); }
		try { $recorded = self::iso_datetime( (string) $proof['recordedAt'] ); } catch ( \Throwable $error ) { $recorded = ''; }
		$raw = base64_decode( (string) $proof['campaignIdsBase64'], true );
		if ( ! hash_equals( (string) $proof['recordedAt'], $recorded ) || ! is_string( $raw ) || ! hash_equals( (string) $proof['campaignIdsBase64'], base64_encode( $raw ) ) || strlen( $raw ) !== $proof['campaignCount'] * 8 ) { return new WP_Error( 'complete99_campaign_public_quarantine_zero_receipt_encoding', 'Zero-placement overlay receipt encoding is malformed.', array( 'status' => 503 ) ); }
		$ids = array();
		for ( $index = 0; $index < $proof['campaignCount']; ++$index ) {
			$words = unpack( 'Nhigh/Nlow', substr( $raw, $index * 8, 8 ) );
			$id = ( (int) $words['high'] * 4294967296 ) + (int) $words['low'];
			if ( 1 > $id || ( 0 < $index && $id <= $ids[ $index - 1 ] ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_zero_receipt_ids', 'Zero-placement overlay IDs are malformed.', array( 'status' => 503 ) ); }
			$ids[] = $id;
		}
		if ( empty( $ids ) ? ( 0 !== $proof['firstId'] || 0 !== $proof['lastId'] ) : ( $ids[0] !== $proof['firstId'] || $ids[ count( $ids ) - 1 ] !== $proof['lastId'] ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_zero_receipt_counts', 'Zero-placement overlay counts are inconsistent.', array( 'status' => 503 ) ); }
		$opening = self::public_quarantine_stored_receipt_payload( (int) $epoch, 'opened', $for_update );
		if ( is_wp_error( $opening ) || ! hash_equals( (string) $proof['openingPayloadDigest'], hash( 'sha256', self::canonical_json( $opening ) ) ) ) { return is_wp_error( $opening ) ? $opening : new WP_Error( 'complete99_campaign_public_quarantine_zero_receipt_opening', 'Zero-placement overlay is not bound to its opening receipt.', array( 'status' => 503 ) ); }
		$member_digests = array();
		$page_count = (int) ceil( $proof['campaignCount'] / self::PUBLIC_QUARANTINE_ZERO_PAGE_SIZE );
		for ( $page_index = 0; $page_index < $page_count; ++$page_index ) {
			$page = self::public_quarantine_zero_page_receipt( $proof, $page_index, $for_update );
			if ( is_wp_error( $page ) ) { return $page; }
			foreach ( $page['digests'] as $digest ) {
				$member_index = count( $member_digests );
				if ( ! isset( $ids[ $member_index ] ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_zero_page_overflow', 'Zero-placement member pages exceed captured membership.', array( 'status' => 503 ) ); }
				$member_digests[ $ids[ $member_index ] ] = $digest;
			}
		}
		if ( count( $member_digests ) !== $proof['campaignCount'] ) { return new WP_Error( 'complete99_campaign_public_quarantine_zero_page_count', 'Zero-placement member pages do not cover exact membership.', array( 'status' => 503 ) ); }
		$result = array( 'proof' => $proof, 'ids' => $ids, 'membership' => array_fill_keys( $ids, true ), 'memberDigests' => $member_digests, 'opening' => $opening );
		if ( ! $for_update ) { self::$public_quarantine_zero_cache[ $cache_key ] = $result; }
		return $result;
	}

	private static function public_quarantine_zero_member_matches( $loaded, $zero ) {
		$id = is_wp_error( $loaded ) ? 0 : (int) ( $loaded['row']['id'] ?? 0 );
		$expected = is_array( $zero ) ? (string) ( $zero['memberDigests'][ $id ] ?? '' ) : '';
		$projection = self::public_quarantine_zero_projection_from_loaded( $loaded );
		if ( ! preg_match( '/\A[a-f0-9]{64}\z/', $expected ) || is_wp_error( $projection ) || ! hash_equals( $expected, hash( 'sha256', self::canonical_json( $projection ) ) ) ) { return is_wp_error( $projection ) ? $projection : new WP_Error( 'complete99_campaign_public_quarantine_zero_member_changed', 'Zero-placement campaign membership no longer matches its captured stable projection.', array( 'status' => 503 ) ); }
		return true;
	}

	/** Point-load the current immutable zero-placement overlay used by every scheduler projection. */
	private static function public_quarantine_zero_membership_for_scheduler() {
		$status = self::public_quarantine_status( false );
		if ( empty( $status['inspectable'] ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_zero_status', 'Campaign scheduling cannot inspect zero-placement overlay truth.', array( 'status' => 503 ) ); }
		if ( ! empty( $status['active'] ) ) { return new WP_Error( 'complete99_campaign_public_quarantine', 'Campaign scheduling is paused by the active public quarantine.', array( 'status' => 503 ) ); }
		$epoch = (int) ( $status['payload']['epoch'] ?? -1 );
		if ( 0 === $epoch ) { return array( 'membership' => array(), 'proof' => null ); }
		if ( 1 > $epoch ) { return new WP_Error( 'complete99_campaign_public_quarantine_zero_epoch', 'Campaign scheduling found an invalid quarantine epoch.', array( 'status' => 503 ) ); }
		$manifest = self::public_quarantine_final_receipt_manifest( $epoch, false );
		return is_wp_error( $manifest ) ? $manifest : (array) $manifest['zero'];
	}

	/** Classify a signed owner-resolution marker against the latest aggregate epoch. */
	private static function aggregate_quarantine_resolution_state( $loaded, $zero, $current_epoch ) {
		if ( is_wp_error( $loaded ) || ! is_array( $loaded['state'] ?? null ) || ! is_array( $loaded['row'] ?? null ) ) { return new WP_Error( 'complete99_campaign_quarantine_resolution_unavailable', 'Campaign quarantine resolution truth is unavailable.', array( 'status' => 503 ) ); }
		$marker = $loaded['state']['runtime']['publicQuarantineOverlay'] ?? array();
		if ( empty( $marker ) ) { return 'none'; }
		$keys = array( 'epoch', 'memberDigest', 'resolvedVersion', 'schemaVersion' );
		if ( ! is_array( $marker ) || array_keys( $marker ) !== $keys || 'complete99-campaign-quarantine-resolution/v1' !== (string) ( $marker['schemaVersion'] ?? '' ) || ! is_int( $marker['epoch'] ?? null ) || 1 > $marker['epoch'] || ! is_int( $marker['resolvedVersion'] ?? null ) || 1 > $marker['resolvedVersion'] || ! preg_match( '/\A[a-f0-9]{64}\z/', (string) ( $marker['memberDigest'] ?? '' ) ) ) { return new WP_Error( 'complete99_campaign_quarantine_resolution_corrupt', 'Campaign quarantine resolution marker is malformed.', array( 'status' => 503 ) ); }
		$current_epoch = (int) $current_epoch;
		if ( (int) $marker['epoch'] > $current_epoch ) { return new WP_Error( 'complete99_campaign_quarantine_resolution_future', 'Campaign quarantine resolution marker refers to a future aggregate epoch.', array( 'status' => 503 ) ); }
		/* Historical markers only classify relation. Full historical manifest
		 * verification is reserved for explicit owner/audit mutation paths. */
		if ( (int) $marker['epoch'] < $current_epoch ) { return 'old'; }
		$receipt = $zero;
		$id = (int) ( $loaded['row']['id'] ?? 0 );
		if ( ! is_array( $receipt ) || ! isset( $receipt['membership'][ $id ] ) || (int) ( $loaded['row']['version'] ?? 0 ) < (int) $marker['resolvedVersion'] || ! hash_equals( (string) ( $receipt['memberDigests'][ $id ] ?? '' ), (string) $marker['memberDigest'] ) ) { return is_wp_error( $receipt ) ? $receipt : new WP_Error( 'complete99_campaign_quarantine_resolution_corrupt', 'Campaign quarantine resolution marker is not bound to its immutable aggregate member.', array( 'status' => 503 ) ); }
		return 'current';
	}

	/** An aggregate receipt overlays only exact actionable raw campaign truth. */
	private static function campaign_projection_has_aggregate_overlay( $row, $zero, $kind ) {
		$id = is_numeric( $row['id'] ?? null ) ? (int) $row['id'] : 0;
		$membership = is_array( $zero ) ? (array) ( $zero['membership'] ?? array() ) : array();
		$cleanup = in_array( (string) $kind, array( 'cleanup_due', 'cleanup_future' ), true );
		$current_qtr = $row['aggregate_current_qtr'] ?? null;
		if ( ! in_array( (string) $kind, array( 'cleanup_due', 'cleanup_future', 'schedule_due', 'schedule_future' ), true ) || ! in_array( $current_qtr, array( 0, 1, '0', '1' ), true ) ) { return new WP_Error( 'complete99_campaign_scheduler_overlay_projection', 'Campaign aggregate overlay projection is malformed.', array( 'status' => 503 ) ); }
		if ( 1 > $id || ! in_array( (string) ( $row['lifecycle_state'] ?? '' ), array( 'schedule_requested', 'active' ), true ) ) { return false; }
		$loaded = self::decode_campaign_row( $row );
		if ( is_wp_error( $loaded ) ) { return $loaded; }
		$current_epoch = is_array( $zero['proof'] ?? null ) ? (int) ( $zero['proof']['epoch'] ?? 0 ) : 0;
		if ( ! isset( $membership[ $id ] ) ) { return false; }
		$resolution = self::aggregate_quarantine_resolution_state( $loaded, $zero, $current_epoch );
		if ( is_wp_error( $resolution ) ) { return $resolution; }
		/* Current qtr truth or the exact current owner-resolution marker admits
		 * post-recovery cleanup; unresolved/old zero members remain overlaid. */
		if ( $cleanup && ( 1 === (int) $current_qtr || 'current' === $resolution ) ) { return false; }
		if ( 'current' === $resolution ) { return false; }
		$matches = self::public_quarantine_zero_member_matches( $loaded, $zero );
		return is_wp_error( $matches ) ? $matches : true;
	}

	/**
	 * Keyset-scan at most the protected campaign bound and omit receipt-backed
	 * zero-placement overlays without allowing low IDs to starve later work.
	 */
	private static function bounded_actionable_campaign_rows( $kind, $now, $wanted ) {
		global $wpdb;
		$allowed = array( 'cleanup_due', 'cleanup_future', 'schedule_due', 'schedule_future' );
		$wanted = (int) $wanted;
		if ( ! in_array( $kind, $allowed, true ) || 1 > $wanted || self::CAMPAIGN_MAX_ROWS < $wanted ) { return new WP_Error( 'complete99_campaign_scheduler_projection_invalid', 'Campaign scheduler projection request is invalid.', array( 'status' => 503 ) ); }
		$zero = self::public_quarantine_zero_membership_for_scheduler();
		if ( is_wp_error( $zero ) ) { return $zero; }
		$table = self::table_names()['campaigns'];
		$placements = self::table_names()['placements'];
		$current_epoch = is_array( $zero['proof'] ?? null ) ? (int) ( $zero['proof']['epoch'] ?? 0 ) : 0;
		$current_qtr = 0 < $current_epoch ? self::public_quarantine_recovered_status( self::public_quarantine_terminal_status( array( 'epoch' => $current_epoch ), false ) ) : 'qtr_0000000000000000';
		if ( ! preg_match( '/\Aqtr_[a-f0-9]{16}\z/', $current_qtr ) ) { return new WP_Error( 'complete99_campaign_scheduler_overlay_epoch', 'Campaign aggregate cleanup epoch is invalid.', array( 'status' => 503 ) ); }
		$cursor_id = 0;
		$cursor_revision = -1;
		$cursor_time = '';
		$scanned = 0;
		$found = array();
		do {
			$wpdb->last_error = '';
			$projection = $wpdb->prepare( "SELECT c.*,CASE WHEN EXISTS (SELECT 1 FROM {$placements} qr WHERE qr.campaign_id=c.public_id AND qr.status=%s) THEN 1 ELSE 0 END AS aggregate_current_qtr FROM {$table} c ", $current_qtr );
			$qtn_guard = " AND NOT EXISTS (SELECT 1 FROM {$placements} qp WHERE qp.campaign_id=c.public_id AND LEFT(qp.status,4)='qtn_')";
			if ( 'cleanup_due' === $kind ) {
				$sql = $wpdb->prepare( $projection . "WHERE (c.cleanup_revision>%d OR (c.cleanup_revision=%d AND c.id>%d)) AND c.cleanup_due_at IS NOT NULL AND c.cleanup_due_at<=%s{$qtn_guard} ORDER BY c.cleanup_revision ASC,c.id ASC LIMIT 101", $cursor_revision, $cursor_revision, $cursor_id, $now );
			} elseif ( 'cleanup_future' === $kind ) {
				$sql = '' === $cursor_time
					? $wpdb->prepare( $projection . "WHERE c.cleanup_due_at>%s{$qtn_guard} ORDER BY c.cleanup_due_at ASC,c.id ASC LIMIT 101", $now )
					: $wpdb->prepare( $projection . "WHERE c.cleanup_due_at>%s AND (c.cleanup_due_at>%s OR (c.cleanup_due_at=%s AND c.id>%d)){$qtn_guard} ORDER BY c.cleanup_due_at ASC,c.id ASC LIMIT 101", $now, $cursor_time, $cursor_time, $cursor_id );
			} elseif ( 'schedule_due' === $kind ) {
				$sql = $wpdb->prepare( $projection . "WHERE c.id>%d AND c.cleanup_due_at IS NULL AND c.lifecycle_state IN ('schedule_requested','active'){$qtn_guard} AND (c.job_state IN ('reconcile_pending','suspended') OR (c.job_state IN ('scheduled','readback_pending','readback_verified','retry_pending','authority_retry_pending','expiry_retry_pending') AND (c.next_attempt_at IS NULL OR c.next_attempt_at<=%s))) ORDER BY c.id ASC LIMIT 101", $cursor_id, $now );
			} else {
				$sql = '' === $cursor_time
					? $wpdb->prepare( $projection . "WHERE c.cleanup_due_at IS NULL AND c.lifecycle_state IN ('schedule_requested','active') AND c.job_state IN ('scheduled','readback_pending','readback_verified','retry_pending','authority_retry_pending','expiry_retry_pending') AND c.next_attempt_at>%s{$qtn_guard} ORDER BY c.next_attempt_at ASC,c.id ASC LIMIT 101", $now )
					: $wpdb->prepare( $projection . "WHERE c.cleanup_due_at IS NULL AND c.lifecycle_state IN ('schedule_requested','active') AND c.job_state IN ('scheduled','readback_pending','readback_verified','retry_pending','authority_retry_pending','expiry_retry_pending') AND c.next_attempt_at>%s AND (c.next_attempt_at>%s OR (c.next_attempt_at=%s AND c.id>%d)){$qtn_guard} ORDER BY c.next_attempt_at ASC,c.id ASC LIMIT 101", $now, $cursor_time, $cursor_time, $cursor_id );
			}
			$rows = $wpdb->get_results( $sql, ARRAY_A );
			if ( '' !== (string) $wpdb->last_error || ! is_array( $rows ) || 101 < count( $rows ) ) { return new WP_Error( 'complete99_campaign_scheduler_projection_query', 'Campaign scheduler projection could not be inspected.', array( 'status' => 503 ) ); }
			$page = array_slice( $rows, 0, 100 );
			foreach ( $page as $row ) {
				$id = is_numeric( $row['id'] ?? null ) ? (int) $row['id'] : 0;
				if ( $id <= $cursor_id && ! in_array( $kind, array( 'cleanup_due', 'cleanup_future', 'schedule_future' ), true ) ) { return new WP_Error( 'complete99_campaign_scheduler_projection_order', 'Campaign scheduler keyset order is invalid.', array( 'status' => 503 ) ); }
				if ( 1 > $id || ! is_numeric( $row['cleanup_revision'] ?? null ) || 0 > (int) $row['cleanup_revision'] || '' === (string) ( $row['public_id'] ?? '' ) || self::CAMPAIGN_MAX_ROWS < ++$scanned ) { return new WP_Error( 'complete99_campaign_scheduler_projection_row', 'Campaign scheduler projection contains malformed or unbounded truth.', array( 'status' => 503 ) ); }
				$cursor_id = $id;
				$cursor_revision = (int) $row['cleanup_revision'];
				if ( in_array( $kind, array( 'cleanup_future', 'schedule_future' ), true ) ) {
					$cursor_time = (string) ( 'cleanup_future' === $kind ? $row['cleanup_due_at'] : $row['next_attempt_at'] );
					if ( false === strtotime( $cursor_time . ' UTC' ) ) { return new WP_Error( 'complete99_campaign_scheduler_projection_time', 'Campaign scheduler projection contains an invalid time.', array( 'status' => 503 ) ); }
				}
				$zero_overlay = self::campaign_projection_has_aggregate_overlay( $row, $zero, $kind );
				if ( is_wp_error( $zero_overlay ) ) { return $zero_overlay; }
				if ( ! $zero_overlay ) { $found[] = $row; }
				if ( count( $found ) >= $wanted ) { return $found; }
			}
			if ( self::CAMPAIGN_MAX_ROWS <= $scanned && 100 < count( $rows ) ) { return new WP_Error( 'complete99_campaign_scheduler_projection_capacity', 'Campaign scheduler projection exceeds its protected bound.', array( 'status' => 503 ) ); }
		} while ( 100 < count( $rows ) );
		return $found;
	}

	/** Store the one immutable zero-placement cohort receipt for an active epoch. */
	private static function ensure_public_quarantine_zero_membership_receipt( $opening ) {
		$started = self::begin_transaction( self::CAPACITY_ROLE_QUARANTINE );
		if ( is_wp_error( $started ) ) { return $started; }
		$status = self::public_quarantine_status( true );
		if ( empty( $status['active'] ) || ! hash_equals( self::canonical_json( $opening ), self::canonical_json( (array) ( $status['payload'] ?? array() ) ) ) ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_public_quarantine_zero_stale', 'Zero-placement overlay opening changed.', array( 'status' => 409 ) ); }
		$member_digests = array();
		$cohort = self::public_quarantine_zero_membership_cohort( $opening, true, $member_digests );
		if ( is_wp_error( $cohort ) ) { self::rollback_transaction(); return $cohort; }
		$already = self::public_quarantine_receipt_matches( $cohort, 'zero', true );
		$stored = self::store_public_quarantine_receipt_locked( $opening, $cohort, 'zero' );
		if ( is_wp_error( $stored ) || ! self::public_quarantine_receipt_matches( $cohort, 'zero', true ) ) { self::rollback_transaction(); return is_wp_error( $stored ) ? $stored : new WP_Error( 'complete99_campaign_public_quarantine_zero_receipt_readback', 'Zero-placement overlay receipt failed exact readback.', array( 'status' => 503 ) ); }
		foreach ( array_chunk( $member_digests, self::PUBLIC_QUARANTINE_ZERO_PAGE_SIZE ) as $page_index => $page_digests ) {
