			|| ! is_int( $proof['rowCount'] ) || 0 > $proof['rowCount'] || self::PUBLIC_PLACEMENT_MAX_ROWS < $proof['rowCount'] || ! is_int( $proof['qtnCount'] ) || 0 > $proof['qtnCount'] || ! is_int( $proof['qtoCount'] ) || 0 > $proof['qtoCount'] || $proof['rowCount'] !== $proof['qtnCount'] + $proof['qtoCount']
