		$ids_raw = base64_decode( (string) $proof['rowIdsBase64'], true );
		$bits_raw = base64_decode( (string) $proof['qtoBitsetBase64'], true );
		if ( ! is_string( $ids_raw ) || ! is_string( $bits_raw ) || ! hash_equals( (string) $proof['rowIdsBase64'], base64_encode( $ids_raw ) ) || ! hash_equals( (string) $proof['qtoBitsetBase64'], base64_encode( $bits_raw ) ) || strlen( $ids_raw ) !== $proof['rowCount'] * 8 || strlen( $bits_raw ) !== (int) ceil( $proof['rowCount'] / 8 ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_manifest_encoding', 'Public quarantine final manifest encoding is invalid.', array( 'status' => 503 ) ); }
		$ids = array();
		$orphan = array();
		$qto_count = 0;
		$initiator_member_count = 0;
		for ( $index = 0; $index < $proof['rowCount']; ++$index ) {
			$words = unpack( 'Nhigh/Nlow', substr( $ids_raw, $index * 8, 8 ) );
			$id = ( (int) $words['high'] * 4294967296 ) + (int) $words['low'];
			if ( ! is_int( $id ) || 1 > $id || ( 0 < $index && $id <= $ids[ $index - 1 ] ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_manifest_ids', 'Public quarantine final manifest IDs are invalid.', array( 'status' => 503 ) ); }
