		if ( is_wp_error( $opening ) || array_keys( (array) $opening ) !== $opening_keys || 'complete99-campaign-public-quarantine/v1' !== (string) ( $opening['schemaVersion'] ?? '' ) || 'active' !== (string) ( $opening['state'] ?? '' ) || $epoch !== (int) ( $opening['epoch'] ?? -1 ) || ! hash_equals( (string) $proof['openingPayloadDigest'], hash( 'sha256', self::canonical_json( $opening ) ) ) || ! is_array( $opening['publicOrigins'] ?? null ) || empty( $opening['publicOrigins'] ) || 4 < count( $opening['publicOrigins'] ) || count( $opening['publicOrigins'] ) !== count( array_filter( $opening['publicOrigins'], array( __CLASS__, 'public_quarantine_url_is_safe' ) ) ) ) { return is_wp_error( $opening ) ? $opening : new WP_Error( 'complete99_campaign_public_quarantine_manifest_opening', 'Public quarantine final manifest is not bound to its opening receipt.', array( 'status' => 503 ) ); }
		try { $completed = self::iso_datetime( (string) $proof['completedAt'] ); } catch ( \Throwable $error ) { $completed = ''; }
