		$expected_clear = self::public_quarantine_payload( 'clear', $epoch, '', '', '', '', (string) $proof['completedAt'], '' );
		$absence = $proof['publicAbsence'] ?? null;
		if ( ! is_array( $absence ) || array_keys( $absence ) !== array( 'schemaVersion', 'sha256', 'surfaces' ) || 'complete99-campaign-public-quarantine-absence/v1' !== (string) ( $absence['schemaVersion'] ?? '' ) || ! is_array( $absence['surfaces'] ?? null ) || empty( $absence['surfaces'] ) || 4 < count( $absence['surfaces'] ) || ! hash_equals( (string) ( $absence['sha256'] ?? '' ), hash( 'sha256', self::canonical_json( $absence['surfaces'] ) ) ) || ! hash_equals( self::canonical_json( $expected_clear ), self::canonical_json( (array) ( $proof['clearPayload'] ?? array() ) ) ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_manifest_absence', 'Public quarantine final absence proof is invalid.', array( 'status' => 503 ) ); }
		foreach ( $absence['surfaces'] as $surface ) {
