		}
		$zero = self::public_quarantine_zero_membership_receipt( $epoch, $for_update );
		if ( is_wp_error( $zero ) || ! hash_equals( (string) $proof['zeroCampaignReceiptDigest'], hash( 'sha256', self::canonical_json( (array) ( $zero['proof'] ?? array() ) ) ) ) ) { return is_wp_error( $zero ) ? $zero : new WP_Error( 'complete99_campaign_public_quarantine_manifest_zero_receipt', 'Public quarantine final manifest is not bound to its zero-placement overlay.', array( 'status' => 503 ) ); }
		$aggregate_cleanup = self::verify_aggregate_cleanup_chain( 'quarantine', $epoch, (string) $proof['aggregateCleanupReceiptDigest'], (bool) $for_update );
		if ( is_wp_error( $aggregate_cleanup ) ) { return $aggregate_cleanup; }
		return array( 'proof' => $proof, 'ids' => $ids, 'orphan' => $orphan, 'opening' => $opening, 'zero' => $zero, 'aggregateCleanup' => $aggregate_cleanup['cohort'], 'aggregateCleanupPages' => $aggregate_cleanup['pages'] );
	}

	private static function public_quarantine_pack_ids( $ids ) {
		$bytes = '';
		$prior = 0;
		foreach ( (array) $ids as $id ) {
			$id = is_int( $id ) ? $id : ( is_numeric( $id ) ? (int) $id : 0 );
			if ( 1 > $id || $id <= $prior ) { return new WP_Error( 'complete99_campaign_public_quarantine_gc_ids', 'Public quarantine GC IDs are invalid.', array( 'status' => 503 ) ); }
			$high = (int) floor( $id / 4294967296 );
			$low = (int) ( $id - ( $high * 4294967296 ) );
			$bytes .= pack( 'NN', $high, $low );
			$prior = $id;
		}
		return base64_encode( $bytes );
	}

	/** Deterministic class-specific GC intent bound to the full immutable final receipt. */
	private static function public_quarantine_gc_intent_from_manifest( $manifest, $class, $created_at, $batch_digests_base64 ) {
		if ( ! in_array( $class, array( 'qto', 'qtr' ), true ) || ! is_array( $manifest['proof'] ?? null ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_gc_manifest', 'Public quarantine GC manifest input is invalid.', array( 'status' => 503 ) ); }
		try { $created_at = self::iso_datetime( (string) $created_at ); } catch ( \Throwable $error ) { return new WP_Error( 'complete99_campaign_public_quarantine_gc_time', 'Public quarantine GC time is invalid.', array( 'status' => 503 ) ); }
		$ids = array();
		foreach ( $manifest['ids'] as $index => $id ) {
			if ( ( 'qto' === $class ) === ( true === ( $manifest['orphan'][ $index ] ?? null ) ) ) { $ids[] = (int) $id; }
		}
		$packed = self::public_quarantine_pack_ids( $ids );
		if ( is_wp_error( $packed ) ) { return $packed; }
		$proof = $manifest['proof'];
		return array(
			'schemaVersion' => 'complete99-campaign-public-quarantine-gc-intent/v1',
			'epoch' => (int) $proof['epoch'],
			'class' => $class,
			'batchSize' => self::RECONCILE_BATCH_SIZE,
			'batchDigestsBase64' => (string) $batch_digests_base64,
			'finalReceiptDigest' => hash( 'sha256', self::canonical_json( $proof ) ),
			'terminalStatus' => 'qto' === $class ? (string) $proof['qtoStatus'] : self::public_quarantine_recovered_status( (string) $proof['qtnStatus'] ),
			'rowCount' => count( $ids ),
			'rowIdsBase64' => $packed,
			'rowsSha256' => (string) ( 'qto' === $class ? $proof['qtoRowsSha256'] : $proof['qtnRowsSha256'] ),
			'maxId' => empty( $ids ) ? 0 : (int) $ids[ count( $ids ) - 1 ],
			'createdAt' => $created_at,
		);
	}

	/** Build <=50-row class digests while every source row is locked and still present. */
	private static function public_quarantine_build_gc_intent_locked( $manifest, $class, $created_at ) {
		global $wpdb;
		if ( ! self::$transaction_active ) { return new WP_Error( 'complete99_campaign_public_quarantine_gc_intent_unlocked', 'Public quarantine GC intent requires a protected transaction.', array( 'status' => 503 ) ); }
		$ids = array();
		foreach ( $manifest['ids'] as $index => $id ) { if ( ( 'qto' === $class ) === ( true === ( $manifest['orphan'][ $index ] ?? null ) ) ) { $ids[] = (int) $id; } }
		$expected_status = 'qto' === $class ? (string) $manifest['proof']['qtoStatus'] : self::public_quarantine_recovered_status( (string) $manifest['proof']['qtnStatus'] );
		$class_rows_digest = (string) ( 'qto' === $class ? $manifest['proof']['qtoRowsSha256'] : $manifest['proof']['qtnRowsSha256'] );
		$digests = '';
		foreach ( array_chunk( $ids, self::RECONCILE_BATCH_SIZE ) as $batch_index => $batch ) {
			$placeholders = implode( ',', array_fill( 0, count( $batch ), '%d' ) );
			$lock = self::is_sqlite_database() ? '' : ' FOR UPDATE';
			$wpdb->last_error = '';
			$rows = $wpdb->get_results( $wpdb->prepare( "SELECT id,placement_id,campaign_id,campaign_version,package_digest,slot_key,locale,public_json,public_digest,readback_token,starts_at,expires_at,activated_at,created_at,status FROM " . self::table_names()['placements'] . " WHERE id IN ({$placeholders}) ORDER BY id ASC{$lock}", $batch ), ARRAY_A );
			if ( '' !== (string) $wpdb->last_error || ! is_array( $rows ) || count( $rows ) !== count( $batch ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_gc_batch_missing', 'A terminal GC batch is missing or duplicated before intent storage.', array( 'status' => 503 ) ); }
			$digest = hash( 'sha256', 'complete99-campaign-public-quarantine-gc-batch/v1|' . (int) $manifest['proof']['epoch'] . '|' . $class . '|' . (int) $batch_index . '|' . $class_rows_digest );
			foreach ( $rows as $index => $row ) {
				if ( (int) ( $row['id'] ?? 0 ) !== (int) $batch[ $index ] || ! hash_equals( $expected_status, (string) ( $row['status'] ?? '' ) ) || ! hash_equals( (string) ( $row['public_digest'] ?? '' ), hash( 'sha256', (string) ( $row['public_json'] ?? '' ) ) ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_gc_batch_changed', 'A terminal GC batch changed before intent storage.', array( 'status' => 503 ) ); }
				$digest = hash( 'sha256', $digest . '|' . self::canonical_json( self::public_quarantine_terminal_projection( $row, 'qto' === $class ) ) );
			}
			$digests .= hex2bin( $digest );
		}
		return self::public_quarantine_gc_intent_from_manifest( $manifest, $class, $created_at, base64_encode( $digests ) );
	}

	/** Load and fully bind one GC intent to the class membership in the final receipt. */
	private static function public_quarantine_gc_intent( $manifest, $class, $for_update = false ) {
		$phase = 'gc_' . $class . '_intent';
		$proof = self::public_quarantine_gc_receipt_payload( (int) $manifest['proof']['epoch'], $phase, $for_update );
		if ( is_wp_error( $proof ) ) { return $proof; }
		$expected = self::public_quarantine_gc_intent_from_manifest( $manifest, $class, (string) ( $proof['createdAt'] ?? '' ), (string) ( $proof['batchDigestsBase64'] ?? '' ) );
		if ( is_wp_error( $expected ) || ! hash_equals( self::canonical_json( (array) $expected ), self::canonical_json( (array) $proof ) ) ) { return is_wp_error( $expected ) ? $expected : new WP_Error( 'complete99_campaign_public_quarantine_gc_intent_corrupt', 'Public quarantine GC intent is not bound to exact final membership.', array( 'status' => 503 ) ); }
