		$batch_raw = base64_decode( (string) ( $proof['batchDigestsBase64'] ?? '' ), true );
		$ids = array();
		if ( ! is_string( $raw ) || ! is_string( $batch_raw ) || self::RECONCILE_BATCH_SIZE !== (int) ( $proof['batchSize'] ?? 0 ) || strlen( $raw ) !== (int) $proof['rowCount'] * 8 || strlen( $batch_raw ) !== (int) ceil( (int) $proof['rowCount'] / self::RECONCILE_BATCH_SIZE ) * 32 || ! hash_equals( (string) $proof['rowIdsBase64'], base64_encode( $raw ) ) || ! hash_equals( (string) $proof['batchDigestsBase64'], base64_encode( $batch_raw ) ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_gc_intent_encoding', 'Public quarantine GC intent encoding is invalid.', array( 'status' => 503 ) ); }
		$prior = 0;
		for ( $offset = 0; $offset < strlen( $raw ); $offset += 8 ) { $words = unpack( 'Nhigh/Nlow', substr( $raw, $offset, 8 ) ); $id = ( (int) $words['high'] * 4294967296 ) + (int) $words['low']; if ( 1 > $id || $id <= $prior ) { return new WP_Error( 'complete99_campaign_public_quarantine_gc_intent_ids', 'Public quarantine GC intent IDs are invalid.', array( 'status' => 503 ) ); } $ids[] = $id; $prior = $id; }
		if ( ( empty( $ids ) ? 0 : $ids[ count( $ids ) - 1 ] ) !== (int) ( $proof['maxId'] ?? -1 ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_gc_intent_max', 'Public quarantine GC maximum ID is inconsistent.', array( 'status' => 503 ) ); }
		$batch_digests = array();
		for ( $offset = 0; $offset < strlen( $batch_raw ); $offset += 32 ) { $batch_digests[] = bin2hex( substr( $batch_raw, $offset, 32 ) ); }
		return array( 'proof' => $proof, 'ids' => $ids, 'membership' => array_fill_keys( $ids, true ), 'batchDigests' => $batch_digests );
	}

	private static function public_quarantine_gc_completion( $intent, $class, $for_update = false ) {
		$phase = 'gc_' . $class . '_complete';
		$proof = self::public_quarantine_gc_receipt_payload( (int) $intent['proof']['epoch'], $phase, $for_update );
		if ( is_wp_error( $proof ) ) { return $proof; }
		$keys = array( 'class', 'completedAt', 'epoch', 'finalReceiptDigest', 'intentPayloadDigest', 'maxId', 'rowCount', 'schemaVersion' );
		try { $completed = self::iso_datetime( (string) ( $proof['completedAt'] ?? '' ) ); } catch ( \Throwable $error ) { $completed = ''; }
		if ( array_keys( $proof ) !== $keys || 'complete99-campaign-public-quarantine-gc-complete/v1' !== (string) ( $proof['schemaVersion'] ?? '' ) || ! hash_equals( $class, (string) ( $proof['class'] ?? '' ) ) || (int) $intent['proof']['epoch'] !== (int) ( $proof['epoch'] ?? -1 ) || (int) $intent['proof']['rowCount'] !== (int) ( $proof['rowCount'] ?? -1 ) || (int) $intent['proof']['maxId'] !== (int) ( $proof['maxId'] ?? -1 ) || ! hash_equals( (string) $intent['proof']['finalReceiptDigest'], (string) ( $proof['finalReceiptDigest'] ?? '' ) ) || ! hash_equals( hash( 'sha256', self::canonical_json( $intent['proof'] ) ), (string) ( $proof['intentPayloadDigest'] ?? '' ) ) || ! hash_equals( (string) ( $proof['completedAt'] ?? '' ), $completed ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_gc_completion_corrupt', 'Public quarantine GC completion receipt is malformed.', array( 'status' => 503 ) ); }
