	private static function public_quarantine_gc_receipt_is_missing( $error ) {
		$data = is_wp_error( $error ) ? $error->get_error_data() : null;
		return is_wp_error( $error ) && 'complete99_campaign_public_quarantine_gc_receipt_unavailable' === $error->get_error_code() && is_array( $data ) && ! empty( $data['missing'] );
	}

	/** Validate every all-present/all-absent <=50-row GC chunk; partial chunks are corruption. */
	private static function public_quarantine_gc_batch_state( $intent, $class, $for_update = false ) {
		global $wpdb;
		if ( ! in_array( $class, array( 'qto', 'qtr' ), true ) || ! is_array( $intent['ids'] ?? null ) || ! is_array( $intent['batchDigests'] ?? null ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_gc_batch_input', 'Terminal GC batch input is invalid.', array( 'status' => 503 ) ); }
		$next = null;
		$survivors = 0;
		foreach ( array_chunk( $intent['ids'], self::RECONCILE_BATCH_SIZE ) as $batch_index => $batch ) {
			$placeholders = implode( ',', array_fill( 0, count( $batch ), '%d' ) );
			$lock = $for_update && ! self::is_sqlite_database() ? ' FOR UPDATE' : '';
			$wpdb->last_error = '';
			$rows = $wpdb->get_results( $wpdb->prepare( "SELECT id,placement_id,campaign_id,campaign_version,package_digest,slot_key,locale,public_json,public_digest,readback_token,starts_at,expires_at,activated_at,created_at,status FROM " . self::table_names()['placements'] . " WHERE id IN ({$placeholders}) ORDER BY id ASC{$lock}", $batch ), ARRAY_A );
			if ( '' !== (string) $wpdb->last_error || ! is_array( $rows ) || ( ! empty( $rows ) && count( $rows ) !== count( $batch ) ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_gc_batch_partial', 'A terminal GC chunk is partially missing or unavailable.', array( 'status' => 503 ) ); }
			if ( empty( $rows ) ) { continue; }
			$survivors += count( $rows );
			$digest = hash( 'sha256', 'complete99-campaign-public-quarantine-gc-batch/v1|' . (int) $intent['proof']['epoch'] . '|' . $class . '|' . (int) $batch_index . '|' . (string) $intent['proof']['rowsSha256'] );
			foreach ( $rows as $index => $row ) {
				if ( (int) ( $row['id'] ?? 0 ) !== (int) $batch[ $index ] || ! hash_equals( (string) $intent['proof']['terminalStatus'], (string) ( $row['status'] ?? '' ) ) || ! hash_equals( (string) ( $row['public_digest'] ?? '' ), hash( 'sha256', (string) ( $row['public_json'] ?? '' ) ) ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_gc_batch_reused', 'A terminal GC ID was reused or its immutable row changed.', array( 'status' => 503 ) ); }
				$digest = hash( 'sha256', $digest . '|' . self::canonical_json( self::public_quarantine_terminal_projection( $row, 'qto' === $class ) ) );
			}
			if ( ! hash_equals( (string) ( $intent['batchDigests'][ $batch_index ] ?? '' ), $digest ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_gc_batch_digest', 'A terminal GC chunk failed its immutable digest.', array( 'status' => 503 ) ); }
			if ( null === $next ) { $next = $batch; }
		}
		return array( 'nextBatch' => $next, 'survivorCount' => $survivors );
	}

	/** Recompute the final immutable-row chain; qtr is the only permitted qtn successor. */
	private static function validate_public_quarantine_manifest_rows( $manifest, $for_update = false ) {
		global $wpdb;
		if ( is_wp_error( $manifest ) || ! is_array( $manifest['proof'] ?? null ) || ! is_array( $manifest['ids'] ?? null ) || ! is_array( $manifest['orphan'] ?? null ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_manifest_invalid', 'Public quarantine manifest validation input is invalid.', array( 'status' => 503 ) ); }
		$proof = $manifest['proof'];
		$ids = $manifest['ids'];
		$orphan = $manifest['orphan'];
		$lock = $for_update && ! self::is_sqlite_database() ? ' FOR UPDATE' : '';
		$chain = hash( 'sha256', 'complete99-campaign-public-quarantine-cohort/v1|' . (int) $proof['epoch'] . '|' . (string) $proof['openingPayloadDigest'] . '|' . (string) $proof['qtnStatus'] . '|' . (string) $proof['qtoStatus'] );
		$qtn_chain = hash( 'sha256', 'complete99-campaign-public-quarantine-qtn/v1|' . (int) $proof['epoch'] . '|' . (string) $proof['openingPayloadDigest'] . '|' . (string) $proof['qtnStatus'] );
		$qto_chain = hash( 'sha256', 'complete99-campaign-public-quarantine-qto/v1|' . (int) $proof['epoch'] . '|' . (string) $proof['openingPayloadDigest'] . '|' . (string) $proof['qtoStatus'] );
		$intents = array();
		$completions = array();
		foreach ( array( 'qto', 'qtr' ) as $class ) {
			$intent = self::public_quarantine_gc_intent( $manifest, $class, $for_update );
			if ( is_wp_error( $intent ) && ! self::public_quarantine_gc_receipt_is_missing( $intent ) ) { return $intent; }
			$intents[ $class ] = is_wp_error( $intent ) ? null : $intent;
			if ( null !== $intents[ $class ] ) {
				$completion = self::public_quarantine_gc_completion( $intents[ $class ], $class, $for_update );
				if ( is_wp_error( $completion ) && ! self::public_quarantine_gc_receipt_is_missing( $completion ) ) { return $completion; }
				$completions[ $class ] = is_wp_error( $completion ) ? null : $completion;
			} else { $completions[ $class ] = null; }
		}
		foreach ( array( 'qto', 'qtr' ) as $class ) {
			if ( null === $intents[ $class ] ) { continue; }
			$batch_state = self::public_quarantine_gc_batch_state( $intents[ $class ], $class, $for_update );
			if ( is_wp_error( $batch_state ) || ( null !== $completions[ $class ] && 0 !== (int) ( $batch_state['survivorCount'] ?? -1 ) ) ) { return is_wp_error( $batch_state ) ? $batch_state : new WP_Error( 'complete99_campaign_public_quarantine_manifest_gc_survivor', 'A terminal row survives its exact GC completion receipt.', array( 'status' => 503 ) ); }
		}
		$seen = 0;
		$present_qtn = 0;
		$present_qto = 0;
		for ( $offset = 0; $offset < count( $ids ); $offset += 200 ) {
			$batch = array_slice( $ids, $offset, 200 );
			$placeholders = implode( ',', array_fill( 0, count( $batch ), '%d' ) );
			$wpdb->last_error = '';
			$rows = empty( $batch ) ? array() : $wpdb->get_results( $wpdb->prepare( "SELECT id,placement_id,campaign_id,campaign_version,package_digest,slot_key,locale,public_json,public_digest,readback_token,starts_at,expires_at,activated_at,created_at,status FROM " . self::table_names()['placements'] . " WHERE id IN ({$placeholders}) ORDER BY id ASC{$lock}", $batch ), ARRAY_A );
			if ( '' !== (string) $wpdb->last_error || ! is_array( $rows ) || count( $rows ) > count( $batch ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_manifest_row_query', 'Public quarantine manifest rows are duplicated or unavailable.', array( 'status' => 503 ) ); }
			$by_id = array();
			foreach ( $rows as $row ) { $row_id = (int) ( $row['id'] ?? 0 ); if ( isset( $by_id[ $row_id ] ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_manifest_row_query', 'Public quarantine manifest rows are duplicated.', array( 'status' => 503 ) ); } $by_id[ $row_id ] = $row; }
			foreach ( $batch as $id ) {
				$is_orphan = true === ( $orphan[ $seen ] ?? null );
				$class = $is_orphan ? 'qto' : 'qtr';
				if ( ! isset( $by_id[ $id ] ) ) {
					if ( null === $intents[ $class ] || empty( $intents[ $class ]['membership'][ $id ] ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_manifest_row_missing', 'A public quarantine row vanished without a class-bound GC intent.', array( 'status' => 503 ) ); }
					++$seen;
					continue;
				}
				if ( null !== $completions[ $class ] ) { return new WP_Error( 'complete99_campaign_public_quarantine_manifest_gc_survivor', 'A terminal row survives its exact GC completion receipt.', array( 'status' => 503 ) ); }
				$row = $by_id[ $id ];
				$expected_status = $is_orphan ? (string) $proof['qtoStatus'] : (string) $proof['qtnStatus'];
				$allowed_statuses = $is_orphan ? array( $expected_status ) : array( $expected_status, self::public_quarantine_recovered_status( $expected_status ) );
				if ( null !== $intents[ $class ] ) { $allowed_statuses = array( (string) $intents[ $class ]['proof']['terminalStatus'] ); }
				if ( ! in_array( (string) ( $row['status'] ?? '' ), $allowed_statuses, true ) || ! hash_equals( (string) ( $row['public_digest'] ?? '' ), hash( 'sha256', (string) ( $row['public_json'] ?? '' ) ) ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_manifest_row_changed', 'A public quarantine manifest row changed after closure.', array( 'status' => 503 ) ); }
				$projection = self::public_quarantine_terminal_projection( $row, $is_orphan );
				$chain = hash( 'sha256', $chain . '|' . self::canonical_json( $projection ) );
				if ( $is_orphan ) { $qto_chain = hash( 'sha256', $qto_chain . '|' . self::canonical_json( $projection ) ); ++$present_qto; } else { $qtn_chain = hash( 'sha256', $qtn_chain . '|' . self::canonical_json( $projection ) ); ++$present_qtn; }
				++$seen;
			}
		}
		if ( $seen !== count( $ids ) || ( null === $intents['qto'] && ! hash_equals( (string) $proof['qtoRowsSha256'], $qto_chain ) ) || ( null === $intents['qtr'] && ! hash_equals( (string) $proof['qtnRowsSha256'], $qtn_chain ) ) || ( null === $intents['qto'] && null === $intents['qtr'] && ! hash_equals( (string) $proof['rowsSha256'], $chain ) ) || ( null !== $completions['qto'] && 0 !== $present_qto ) || ( null !== $completions['qtr'] && 0 !== $present_qtn ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_manifest_digest', 'Public quarantine manifest row or GC digest is inconsistent.', array( 'status' => 503 ) ); }
		return true;
	}

	private static function install_schema_tables() {
		global $wpdb;
		if ( ! function_exists( 'dbDelta' ) ) {
			require_once ABSPATH . 'wp-admin/includes/upgrade.php';
		}
		if ( ! function_exists( 'dbDelta' ) ) {
			throw new \RuntimeException( 'The WordPress schema migration utility is unavailable.' );
		}
		$tables          = self::table_names();
		$charset_collate = trim( (string) $wpdb->get_charset_collate() );
		$engine          = self::is_sqlite_database() ? '' : ' ENGINE=InnoDB';
		$suffix          = $engine . ( '' !== $charset_collate ? ' ' . $charset_collate : '' );
		$definitions     = array(
			"CREATE TABLE {$tables['campaigns']} (
				id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
				public_id varchar(64) NOT NULL,
				location_id bigint(20) unsigned NOT NULL DEFAULT 0,
				name varchar(191) NOT NULL,
				primary_channel varchar(32) NOT NULL,
				scenario varchar(32) NOT NULL DEFAULT '',
				lifecycle_state varchar(32) NOT NULL DEFAULT 'draft',
				external_state varchar(32) NOT NULL DEFAULT 'unverified',
				job_state varchar(32) NOT NULL DEFAULT 'not_scheduled',
				next_attempt_at datetime NULL,
				slot_key varchar(32) NOT NULL DEFAULT '',
				activation_at datetime NULL,
				expiry_at datetime NULL,
				cleanup_queue_json longtext NOT NULL,
				cleanup_queue_digest char(64) NOT NULL,
				cleanup_due_at datetime NULL,
				cleanup_revision bigint(20) unsigned NOT NULL DEFAULT 0,
				state_json longtext NOT NULL,
				state_digest char(64) NOT NULL,
				approved_material_digest char(64) NULL,
				approved_by bigint(20) unsigned NOT NULL DEFAULT 0,
				approved_at datetime NULL,
				version bigint(20) unsigned NOT NULL DEFAULT 1,
				created_by bigint(20) unsigned NOT NULL,
				updated_by bigint(20) unsigned NOT NULL,
				created_at datetime NOT NULL,
				updated_at datetime NOT NULL,
				PRIMARY KEY  (id),
				UNIQUE KEY public_id (public_id),
				KEY location_state (location_id,lifecycle_state),
				KEY channel_state (primary_channel,lifecycle_state),
				KEY campaign_job_state (lifecycle_state,job_state,next_attempt_at),
				KEY campaign_slot_window (slot_key,lifecycle_state,activation_at,expiry_at),
				KEY campaign_cleanup_due (cleanup_due_at,id),
				KEY updated_at (updated_at)
			){$suffix};",
			"CREATE TABLE {$tables['revisions']} (
				id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
				revision_id varchar(64) NOT NULL,
				campaign_id varchar(64) NOT NULL,
				version bigint(20) unsigned NOT NULL,
				reason varchar(48) NOT NULL,
				snapshot_json longtext NOT NULL,
				snapshot_digest char(64) NOT NULL,
				created_by bigint(20) unsigned NOT NULL,
				created_at datetime NOT NULL,
				PRIMARY KEY  (id),
				UNIQUE KEY revision_id (revision_id),
				UNIQUE KEY campaign_version (campaign_id,version),
				KEY campaign_created (campaign_id,created_at)
			){$suffix};",
			"CREATE TABLE {$tables['prepared_packages']} (
				id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
				package_id varchar(64) NOT NULL,
				campaign_id varchar(64) NOT NULL,
				campaign_version bigint(20) unsigned NOT NULL,
				channel varchar(32) NOT NULL,
				status varchar(24) NOT NULL,
				package_json longtext NOT NULL,
				package_digest char(64) NOT NULL,
				approval_snapshot_digest char(64) NOT NULL,
				created_by bigint(20) unsigned NOT NULL,
				created_at datetime NOT NULL,
				PRIMARY KEY  (id),
				UNIQUE KEY package_id (package_id),
				KEY campaign_channel (campaign_id,channel),
				KEY campaign_version (campaign_id,campaign_version)
			){$suffix};",
			"CREATE TABLE {$tables['provider_receipts']} (
				id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
				receipt_id varchar(64) NOT NULL,
				campaign_id varchar(64) NOT NULL,
				campaign_version bigint(20) unsigned NOT NULL,
				channel varchar(32) NOT NULL,
				provider_key varchar(64) NOT NULL,
				provider_account_ref varchar(191) NOT NULL,
				receipt_status varchar(24) NOT NULL,
				proof_level varchar(32) NOT NULL,
				external_state varchar(24) NOT NULL,
				external_id varchar(191) NULL,
				proof_ref text NULL,
				material_digest char(64) NOT NULL,
				payload_digest char(64) NOT NULL,
				occurred_at datetime NOT NULL,
				created_by bigint(20) unsigned NOT NULL,
				created_at datetime NOT NULL,
				PRIMARY KEY  (id),
				UNIQUE KEY receipt_id (receipt_id),
				KEY campaign_created (campaign_id,created_at),
				KEY provider_external (provider_key,external_id)
			){$suffix};",
			"CREATE TABLE {$tables['results']} (
				id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
				result_id varchar(64) NOT NULL,
				campaign_id varchar(64) NOT NULL,
				campaign_version bigint(20) unsigned NOT NULL,
				metric_key varchar(96) NOT NULL,
				value_decimal decimal(20,6) NOT NULL,
				unit varchar(32) NOT NULL,
				observation_type varchar(24) NOT NULL,
				evidence_level varchar(32) NOT NULL,
				source_ref text NOT NULL,
				provider_receipt_id varchar(64) NULL,
				observed_at datetime NOT NULL,
				created_by bigint(20) unsigned NOT NULL,
				created_at datetime NOT NULL,
				PRIMARY KEY  (id),
				UNIQUE KEY result_id (result_id),
				KEY campaign_metric (campaign_id,metric_key),
				KEY campaign_created (campaign_id,created_at)
			){$suffix};",
			"CREATE TABLE {$tables['placements']} (
				id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
				placement_id varchar(64) NOT NULL,
				campaign_id varchar(64) NOT NULL,
				campaign_version bigint(20) unsigned NOT NULL,
				package_digest char(64) NOT NULL,
				slot_key varchar(32) NOT NULL,
				locale varchar(8) NOT NULL,
				public_json longtext NOT NULL,
				public_digest char(64) NOT NULL,
				readback_token char(64) NOT NULL,
				status varchar(24) NOT NULL,
				starts_at datetime NOT NULL,
				expires_at datetime NOT NULL,
				activated_at datetime NULL,
				stopped_at datetime NULL,
				created_at datetime NOT NULL,
				updated_at datetime NOT NULL,
				PRIMARY KEY  (id),
				UNIQUE KEY placement_id (placement_id),
				UNIQUE KEY readback_token (readback_token),
				KEY slot_status (slot_key,status),
				KEY campaign_status (campaign_id,status),
				KEY expires_at (expires_at)
			){$suffix};",
			"CREATE TABLE {$tables['event_aggregates']} (
				id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
				campaign_id varchar(64) NOT NULL,
				placement_id varchar(64) NOT NULL,
				event_date date NOT NULL,
				event_hour char(10) NOT NULL DEFAULT '',
				event_key varchar(80) NOT NULL,
				provenance_key varchar(48) NOT NULL DEFAULT 'anonymous_unverified_web',
				claim_digest char(64) NOT NULL DEFAULT '',
				event_count bigint(20) unsigned NOT NULL DEFAULT 0,
				first_at datetime NOT NULL,
				last_at datetime NOT NULL,
				PRIMARY KEY  (id),
				UNIQUE KEY placement_date_event (placement_id,event_date,event_key),
				KEY campaign_event (campaign_id,event_key),
				KEY event_date (event_date)
			){$suffix};",
		);
		foreach ( $definitions as $definition ) {
			dbDelta( $definition );
		}
		self::ensure_public_quarantine_sentinel();
	}

	private static function assert_schema_tables() {
		$status = self::schema_status();
		if ( ! empty( $status['inspection_failed'] )
			|| ! empty( $status['missing_tables'] )
			|| ! empty( $status['invalid_tables'] )
			|| ! empty( $status['invalid_columns'] )
			|| ! empty( $status['invalid_collations'] )
			|| ! empty( $status['invalid_engines'] )
			|| ! empty( $status['invalid_indexes'] ) ) {
			throw new \RuntimeException( 'The Complete99 campaign tables are incomplete.' );
		}
	}

	private static function assert_capabilities() {
		global $wpdb;
		$role_key = $wpdb->get_blog_prefix( get_current_blog_id() ) . 'user_roles';
		$wpdb->last_error = '';
		$raw = $wpdb->get_var(
			$wpdb->prepare( "SELECT option_value FROM {$wpdb->options} WHERE option_name = %s LIMIT 1", $role_key )
		);
		if ( '' !== (string) $wpdb->last_error || null === $raw ) {
			throw new \RuntimeException( 'The durable WordPress roles option is unavailable.' );
		}
		$roles = maybe_unserialize( $raw );
		foreach ( self::capabilities() as $capability ) {
			if ( true !== ( $roles['administrator']['capabilities'][ $capability ] ?? null ) ) {
				throw new \RuntimeException( 'A Campaign Studio capability is not durable.' );
			}
		}
	}

	/** Inspect schema metadata and bounded counts without returning row content. */
	public static function schema_status() {
		global $wpdb;
		$contract = self::schema_contract();
		$tables   = self::table_names();
		$status   = array(
			'ready'                => false,
			'stored_version'       => self::persisted_schema_version(),
			'required_table_count' => count( $contract ),
			'present_table_count'  => 0,
			'missing_tables'       => array(),
			'invalid_tables'       => array(),
			'invalid_engines'      => array(),
			'invalid_indexes'      => array(),
			'invalid_columns'      => array(),
			'invalid_collations'   => array(),
			'invalid_core_engines' => array(),
			'record_counts'        => array(),
			'inspection_failed'    => false,
		);
		try {
			$sqlite = self::is_sqlite_database();
			foreach ( $contract as $key => $requirements ) {
				$metadata = self::table_metadata( $tables[ $key ], $sqlite );
				if ( empty( $metadata['exists'] ) ) {
					$status['missing_tables'][] = $key;
					continue;
				}
				++$status['present_table_count'];
				if ( array_diff( $requirements['columns'], $metadata['columns'] ) ) {
					$status['invalid_tables'][] = $key;
				}
				foreach ( (array) ( $requirements['critical_columns'] ?? array() ) as $column => $expected ) {
					if ( ! self::column_spec_matches( $metadata['column_specs'][ $column ] ?? array(), $expected, $sqlite ) ) { $status['invalid_columns'][ $key ][] = $column; }
				}
				if ( ! $sqlite && ! in_array( strtolower( $metadata['engine'] ), array( 'innodb', 'xtradb' ), true ) ) {
					$status['invalid_engines'][ $key ] = $metadata['engine'];
				}
				if ( ! $sqlite && '' !== (string) $wpdb->collate && ! hash_equals( strtolower( (string) $wpdb->collate ), strtolower( (string) $metadata['collation'] ) ) ) { $status['invalid_collations'][ $key ] = $metadata['collation']; }
				$missing = self::missing_unique_indexes( $requirements['unique_indexes'], $metadata['unique_indexes'], $sqlite );
				if ( $missing ) {
					$status['invalid_indexes'][ $key ] = $missing;
				}
				$wpdb->last_error = '';
				$count = $wpdb->get_var( 'SELECT COUNT(*) FROM ' . self::quote_identifier( $tables[ $key ] ) );
				self::throw_on_database_error();
				if ( ! is_numeric( $count ) ) {
					throw new \RuntimeException( 'Campaign record count could not be verified.' );
				}
				$status['record_counts'][ $key ] = max( 0, (int) $count );
			}
			if ( ! $sqlite ) {
				foreach ( array( 'posts' => $wpdb->posts, 'postmeta' => $wpdb->postmeta ) as $core_key => $core_table ) {
					$core_metadata = self::table_metadata( $core_table, false );
					if ( empty( $core_metadata['exists'] ) || ! in_array( strtolower( (string) $core_metadata['engine'] ), array( 'innodb', 'xtradb' ), true ) ) {
						$status['invalid_core_engines'][ $core_key ] = (string) ( $core_metadata['engine'] ?? '' );
					}
				}
			}
			$status['ready'] = hash_equals( self::SCHEMA_VERSION, (string) $status['stored_version'] )
				&& empty( $status['missing_tables'] )
				&& empty( $status['invalid_tables'] )
				&& empty( $status['invalid_columns'] )
				&& empty( $status['invalid_collations'] )
				&& empty( $status['invalid_engines'] )
				&& empty( $status['invalid_core_engines'] )
				&& empty( $status['invalid_indexes'] );
		} catch ( \Throwable $error ) {
			$status['ready']             = false;
			$status['inspection_failed'] = true;
		}
		return $status;
	}

	private static function schema_contract() {
		return array(
			'campaigns' => array(
				'columns'        => array( 'id', 'public_id', 'location_id', 'name', 'primary_channel', 'scenario', 'lifecycle_state', 'external_state', 'job_state', 'next_attempt_at', 'slot_key', 'activation_at', 'expiry_at', 'cleanup_queue_json', 'cleanup_queue_digest', 'cleanup_due_at', 'cleanup_revision', 'state_json', 'state_digest', 'approved_material_digest', 'approved_by', 'approved_at', 'version', 'created_by', 'updated_by', 'created_at', 'updated_at' ),
				'critical_columns'=> array(
					'public_id'                => array( 'type' => 'varchar(64)', 'nullable' => false ),
					'location_id'              => array( 'type' => 'bigint(20) unsigned', 'nullable' => false, 'default' => '0' ),
					'primary_channel'          => array( 'type' => 'varchar(32)', 'nullable' => false ),
					'lifecycle_state'          => array( 'type' => 'varchar(32)', 'nullable' => false, 'default' => 'draft' ),
					'external_state'           => array( 'type' => 'varchar(32)', 'nullable' => false, 'default' => 'unverified' ),
					'job_state'                => array( 'type' => 'varchar(32)', 'nullable' => false, 'default' => 'not_scheduled' ),
					'next_attempt_at'          => array( 'type' => 'datetime', 'nullable' => true ),
					'activation_at'            => array( 'type' => 'datetime', 'nullable' => true ),
					'expiry_at'                => array( 'type' => 'datetime', 'nullable' => true ),
					'cleanup_queue_json'        => array( 'type' => 'longtext', 'nullable' => false ),
					'cleanup_queue_digest'      => array( 'type' => 'char(64)', 'nullable' => false ),
					'cleanup_due_at'            => array( 'type' => 'datetime', 'nullable' => true ),
					'cleanup_revision'          => array( 'type' => 'bigint(20) unsigned', 'nullable' => false, 'default' => '0' ),
					'state_json'               => array( 'type' => 'longtext', 'nullable' => false ),
					'state_digest'             => array( 'type' => 'char(64)', 'nullable' => false ),
					'approved_material_digest' => array( 'type' => 'char(64)', 'nullable' => true ),
					'version'                  => array( 'type' => 'bigint(20) unsigned', 'nullable' => false, 'default' => '1' ),
					'created_at'               => array( 'type' => 'datetime', 'nullable' => false ),
					'updated_at'               => array( 'type' => 'datetime', 'nullable' => false ),
				),
				'unique_indexes' => array( 'primary' => array( 'id' ), 'public_id' => array( 'public_id' ) ),
			),
			'revisions' => array(
				'columns'        => array( 'id', 'revision_id', 'campaign_id', 'version', 'reason', 'snapshot_json', 'snapshot_digest', 'created_by', 'created_at' ),
				'critical_columns'=> array(
					'revision_id'    => array( 'type' => 'varchar(64)', 'nullable' => false ),
					'campaign_id'    => array( 'type' => 'varchar(64)', 'nullable' => false ),
					'version'        => array( 'type' => 'bigint(20) unsigned', 'nullable' => false ),
					'reason'         => array( 'type' => 'varchar(48)', 'nullable' => false ),
					'snapshot_json'  => array( 'type' => 'longtext', 'nullable' => false ),
					'snapshot_digest'=> array( 'type' => 'char(64)', 'nullable' => false ),
					'created_by'     => array( 'type' => 'bigint(20) unsigned', 'nullable' => false ),
					'created_at'     => array( 'type' => 'datetime', 'nullable' => false ),
				),
				'unique_indexes' => array( 'primary' => array( 'id' ), 'revision_id' => array( 'revision_id' ), 'campaign_version' => array( 'campaign_id', 'version' ) ),
			),
			'prepared_packages' => array(
				'columns'        => array( 'id', 'package_id', 'campaign_id', 'campaign_version', 'channel', 'status', 'package_json', 'package_digest', 'approval_snapshot_digest', 'created_by', 'created_at' ),
				'critical_columns'=> array(
					'package_id'              => array( 'type' => 'varchar(64)', 'nullable' => false ),
					'campaign_id'             => array( 'type' => 'varchar(64)', 'nullable' => false ),
					'campaign_version'        => array( 'type' => 'bigint(20) unsigned', 'nullable' => false ),
