	private static function table_metadata( $table, $sqlite ) {
		global $wpdb;
		$metadata = array( 'exists' => false, 'engine' => $sqlite ? 'sqlite' : '', 'collation' => '', 'columns' => array(), 'column_specs' => array(), 'unique_indexes' => array() );
		if ( $sqlite ) {
			$wpdb->last_error = '';
			$found = $wpdb->get_var( $wpdb->prepare( "SELECT name FROM sqlite_master WHERE type = 'table' AND name = %s", $table ) );
			self::throw_on_database_error();
			if ( ! is_string( $found ) || ! hash_equals( $table, $found ) ) {
				return $metadata;
			}
			$metadata['exists'] = true;
			$columns = $wpdb->get_results( 'PRAGMA table_info(' . self::quote_identifier( $table ) . ')', ARRAY_A );
			$primary = array();
			foreach ( is_array( $columns ) ? $columns : array() as $row ) {
				$name = isset( $row['name'] ) ? (string) $row['name'] : '';
				if ( '' !== $name ) {
					$metadata['columns'][] = $name;
					$metadata['column_specs'][ $name ] = array( 'type' => strtolower( (string) ( $row['type'] ?? '' ) ), 'nullable' => empty( $row['notnull'] ), 'default' => null === ( $row['dflt_value'] ?? null ) ? null : trim( (string) $row['dflt_value'], "'\"" ) );
				}
				if ( ! empty( $row['pk'] ) ) {
					$primary[ (int) $row['pk'] ] = $name;
				}
			}
			if ( $primary ) {
				ksort( $primary, SORT_NUMERIC );
				$metadata['unique_indexes']['primary'] = array_values( $primary );
			}
			$indexes = $wpdb->get_results( 'PRAGMA index_list(' . self::quote_identifier( $table ) . ')', ARRAY_A );
			foreach ( is_array( $indexes ) ? $indexes : array() as $index ) {
				if ( empty( $index['unique'] ) || empty( $index['name'] ) ) {
					continue;
				}
				$name  = (string) $index['name'];
				$parts = $wpdb->get_results( 'PRAGMA index_info(' . self::quote_identifier( $name ) . ')', ARRAY_A );
				$cols  = array();
				foreach ( is_array( $parts ) ? $parts : array() as $part ) {
					$cols[ (int) ( $part['seqno'] ?? count( $cols ) ) ] = (string) ( $part['name'] ?? '' );
				}
				ksort( $cols, SORT_NUMERIC );
				$metadata['unique_indexes'][ strtolower( $name ) ] = array_values( $cols );
			}
			self::throw_on_database_error();
			return $metadata;
		}
		$like = method_exists( $wpdb, 'esc_like' ) ? $wpdb->esc_like( $table ) : addcslashes( $table, '_%\\' );
		$found = $wpdb->get_var( $wpdb->prepare( 'SHOW TABLES LIKE %s', $like ) );
		self::throw_on_database_error();
		if ( ! is_string( $found ) || ! hash_equals( $table, $found ) ) {
			return $metadata;
		}
		$metadata['exists'] = true;
		$row = $wpdb->get_row( $wpdb->prepare( 'SHOW TABLE STATUS LIKE %s', $like ), ARRAY_A );
		$metadata['engine'] = is_array( $row ) ? (string) ( $row['Engine'] ?? '' ) : '';
		$metadata['collation'] = is_array( $row ) ? (string) ( $row['Collation'] ?? '' ) : '';
		$full_columns = $wpdb->get_results( 'SHOW FULL COLUMNS FROM ' . self::quote_identifier( $table ), ARRAY_A );
		foreach ( is_array( $full_columns ) ? $full_columns : array() as $column ) {
			$name = (string) ( $column['Field'] ?? '' );
			if ( '' === $name ) { continue; }
			$metadata['columns'][] = $name;
			$metadata['column_specs'][ $name ] = array( 'type' => strtolower( (string) ( $column['Type'] ?? '' ) ), 'nullable' => 'YES' === strtoupper( (string) ( $column['Null'] ?? '' ) ), 'default' => $column['Default'] ?? null, 'collation' => (string) ( $column['Collation'] ?? '' ) );
		}
		$rows = $wpdb->get_results( 'SHOW INDEX FROM ' . self::quote_identifier( $table ), ARRAY_A );
		$indexes = array();
		foreach ( is_array( $rows ) ? $rows : array() as $index ) {
			if ( 0 !== (int) ( $index['Non_unique'] ?? 1 ) || empty( $index['Key_name'] ) || empty( $index['Column_name'] ) ) {
				continue;
			}
			$name = strtolower( (string) $index['Key_name'] );
			$indexes[ $name ][ (int) ( $index['Seq_in_index'] ?? 1 ) ] = (string) $index['Column_name'];
		}
		foreach ( $indexes as $name => $columns ) {
			ksort( $columns, SORT_NUMERIC );
			$metadata['unique_indexes'][ $name ] = array_values( $columns );
		}
		self::throw_on_database_error();
		return $metadata;
	}

	private static function column_spec_matches( $actual, $expected, $sqlite ) {
		if ( ! is_array( $actual ) || ! is_array( $expected ) ) { return false; }
		$actual_type = strtolower( preg_replace( '/\s+/', ' ', trim( (string) ( $actual['type'] ?? '' ) ) ) );
		$expected_type = strtolower( (string) ( $expected['type'] ?? '' ) );
		if ( $sqlite ) {
			$affinity = 0 === strpos( $expected_type, 'varchar' ) || 0 === strpos( $expected_type, 'char' ) || 'longtext' === $expected_type ? 'text' : ( 0 === strpos( $expected_type, 'bigint' ) ? 'integer' : $expected_type );
			if ( false === strpos( $actual_type, $affinity ) ) { return false; }
		} elseif ( ! hash_equals( $expected_type, $actual_type ) ) { return false; }
		if ( isset( $expected['nullable'] ) && (bool) $expected['nullable'] !== (bool) ( $actual['nullable'] ?? true ) ) { return false; }
		if ( array_key_exists( 'default', $expected ) && (string) $expected['default'] !== (string) ( $actual['default'] ?? '' ) ) { return false; }
		return true;
	}

	private static function missing_unique_indexes( $required, $actual, $sqlite ) {
		$missing = array();
		foreach ( $required as $name => $columns ) {
			$name = strtolower( $name );
			if ( isset( $actual[ $name ] ) && array_values( $actual[ $name ] ) === $columns ) {
				continue;
			}
			$by_columns = false;
			if ( $sqlite ) {
				foreach ( $actual as $actual_columns ) {
					if ( array_values( $actual_columns ) === $columns ) {
						$by_columns = true;
						break;
					}
				}
			}
			if ( ! $by_columns ) {
				$missing[] = $name;
			}
		}
		return $missing;
	}

	private static function persisted_schema_version() {
		global $wpdb;
		$wpdb->last_error = '';
		$raw = $wpdb->get_var( $wpdb->prepare( "SELECT option_value FROM {$wpdb->options} WHERE option_name = %s LIMIT 1", self::OPTION_SCHEMA_VERSION ) );
		if ( '' !== (string) $wpdb->last_error || null === $raw ) {
			return '';
		}
		$value = maybe_unserialize( $raw );
		return is_string( $value ) ? $value : '';
	}

	private static function throw_on_database_error() {
		global $wpdb;
		if ( '' !== (string) $wpdb->last_error ) {
			throw new \RuntimeException( 'Campaign Studio database inspection failed.' );
		}
	}

	/** Repair the indexed job projection from digest-verified canonical state. */
	private static function repair_job_state_projection() {
		global $wpdb;
		$tables = self::table_names();
		$cursor = 0;
		$repaired = 0;
		do {
			$wpdb->last_error = '';
			$rows = $wpdb->get_results( $wpdb->prepare( "SELECT id,job_state,next_attempt_at,slot_key,activation_at,expiry_at,cleanup_queue_json,cleanup_queue_digest,cleanup_due_at,cleanup_revision,state_json,state_digest FROM {$tables['campaigns']} WHERE id > %d ORDER BY id ASC LIMIT 200", $cursor ), ARRAY_A );
			self::throw_on_database_error();
			foreach ( is_array( $rows ) ? $rows : array() as $row ) {
				if ( self::CAMPAIGN_MAX_ROWS < ++$repaired ) { throw new \RuntimeException( 'Campaign migration exceeds the protected owner-action row boundary.' ); }
				$cursor = (int) $row['id'];
				$state = json_decode( (string) $row['state_json'], true );
				if ( ! is_array( $state ) || ! hash_equals( (string) $row['state_digest'], hash( 'sha256', self::canonical_json( $state ) ) ) ) {
					throw new \RuntimeException( 'A campaign job projection cannot be repaired from corrupt state.' );
				}
				$job = (string) ( $state['runtime']['jobState'] ?? '' );
				$next_attempt = self::mysql_datetime_or_null( $state['runtime']['nextAttemptAt'] ?? '' );
				$slot = 'website' === ( $state['primaryChannel'] ?? '' ) ? (string) ( $state['governance']['slotKey'] ?? '' ) : '';
				$activation = self::state_activation_datetime( $state );
				$expiry = self::state_expiry_datetime( $state );
				$cleanup_json = (string) ( $row['cleanup_queue_json'] ?? '' );
				$cleanup_digest = (string) ( $row['cleanup_queue_digest'] ?? '' );
				$cleanup_revision = (int) ( $row['cleanup_revision'] ?? 0 );
				if ( '' === $cleanup_json && '' === $cleanup_digest && 0 === $cleanup_revision ) {
					$cleanup_json = self::canonical_json( self::empty_cleanup_queue() );
					$cleanup_digest = hash( 'sha256', $cleanup_json );
					if ( 1 !== $wpdb->update( $tables['campaigns'], array( 'cleanup_queue_json' => $cleanup_json, 'cleanup_queue_digest' => $cleanup_digest, 'cleanup_due_at' => null, 'cleanup_revision' => 0 ), array( 'id' => $cursor ) ) ) { throw new \RuntimeException( 'A campaign cleanup queue could not be initialized.' ); }
					$row['cleanup_queue_json'] = $cleanup_json; $row['cleanup_queue_digest'] = $cleanup_digest; $row['cleanup_due_at'] = null; $row['cleanup_revision'] = 0;
				} elseif ( is_wp_error( self::decode_cleanup_queue( $row ) ) ) {
					throw new \RuntimeException( 'A campaign cleanup queue cannot be repaired from corrupt truth.' );
				}
				$projection_current = hash_equals( (string) $row['job_state'], $job )
					&& (string) ( $row['next_attempt_at'] ?? '' ) === (string) ( $next_attempt ?? '' )
					&& (string) ( $row['slot_key'] ?? '' ) === $slot
					&& (string) ( $row['activation_at'] ?? '' ) === (string) ( $activation ?? '' )
					&& (string) ( $row['expiry_at'] ?? '' ) === (string) ( $expiry ?? '' );
				if ( '' === $job || ( ! $projection_current && 1 !== $wpdb->update( $tables['campaigns'], array( 'job_state' => $job, 'next_attempt_at' => $next_attempt, 'slot_key' => $slot, 'activation_at' => $activation, 'expiry_at' => $expiry ), array( 'id' => $cursor ) ) ) ) {
					throw new \RuntimeException( 'A campaign job projection could not be repaired.' );
				}
			}
		} while ( is_array( $rows ) && 200 === count( $rows ) );
	}

	private static function quote_identifier( $identifier ) {
		return '`' . str_replace( '`', '``', (string) $identifier ) . '`';
	}

	private static function is_sqlite_database() {
		global $wpdb;
		$engine = defined( 'DB_ENGINE' ) ? strtolower( (string) DB_ENGINE ) : '';
		$type   = defined( 'DATABASE_TYPE' ) ? strtolower( (string) DATABASE_TYPE ) : '';
		return 'sqlite' === $engine || 'sqlite' === $type || false !== strpos( strtolower( get_class( $wpdb ) ), 'sqlite' );
	}

