	}

	private static function prove_public_quarantine_absence( $urls, $verified_at ) {
		$urls = array_values( array_unique( (array) $urls ) ); sort( $urls, SORT_STRING );
		if ( empty( $urls ) || 4 < count( $urls ) || count( $urls ) !== count( array_filter( $urls, array( __CLASS__, 'public_quarantine_url_is_safe' ) ) ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_absence_urls', 'Public quarantine absence URLs are invalid.', array( 'status' => 503 ) ); }
		$purged = self::purge_public_placement_caches( 'public_quarantine_clear' );
		if ( is_wp_error( $purged ) ) { return $purged; }
		$records = array();
		foreach ( $urls as $url ) {
			try { do_action( 'litespeed_purge_url', $url ); } catch ( \Throwable $error ) { return new WP_Error( 'complete99_campaign_public_quarantine_origin_purge', 'A historical public surface could not be purged.', array( 'status' => 503 ) ); }
