			$body = is_wp_error( $response ) ? '' : (string) wp_remote_retrieve_body( $response );
			$type_header = is_wp_error( $response ) ? '' : strtolower( trim( (string) wp_remote_retrieve_header( $response, 'content-type' ) ) );
			$type = trim( explode( ';', $type_header, 2 )[0] );
