			$type_valid = $terminal_absence ? in_array( $type, array( '', 'text/html', 'application/xhtml+xml' ), true ) : in_array( $type, array( 'text/html', 'application/xhtml+xml' ), true );
			if ( ( 200 !== $code && ! $terminal_absence ) || 1048576 < strlen( $body ) || ! $type_valid || self::public_html_contains_campaign_marker( $body ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_absence_failed', 'A public surface still exposes campaign placement truth.', array( 'status' => 503 ) ); }
