			$records[] = array( 'url' => $url, 'code' => $code, 'contentType' => $terminal_absence ? '' : $type, 'bodyBytes' => strlen( $body ), 'bodySha256' => hash( 'sha256', $body ), 'markerAbsent' => true, 'verifiedAt' => $verified_at );
		}
		return array( 'schemaVersion' => 'complete99-campaign-public-quarantine-absence/v1', 'surfaces' => $records, 'sha256' => hash( 'sha256', self::canonical_json( $records ) ) );
	}

	/** Remove every Campaign lifecycle hook and prove the raw cron option contains none. */
	private static function clear_public_quarantine_campaign_events_locked() {
		global $wpdb;
		if ( ! self::$transaction_active ) { return new WP_Error( 'complete99_campaign_public_quarantine_cron_unlocked', 'Public quarantine cron proof requires the protected transaction.', array( 'status' => 503 ) ); }
		foreach ( array( 'complete99_campaign_activate', 'complete99_campaign_expire', 'complete99_campaign_verify_readback' ) as $hook ) {
			$removed = wp_unschedule_hook( $hook, true );
			if ( is_wp_error( $removed ) || false === $removed ) { return new WP_Error( 'complete99_campaign_public_quarantine_cron_remove', 'Public quarantine could not remove every Campaign lifecycle hook.', array( 'status' => 503 ) ); }
		}
		$lock = self::is_sqlite_database() ? '' : ' FOR UPDATE';
		$wpdb->last_error = '';
		$rows = $wpdb->get_results( $wpdb->prepare( "SELECT option_value FROM {$wpdb->options} WHERE option_name=%s ORDER BY option_id ASC LIMIT 2{$lock}", 'cron' ), ARRAY_A );
		if ( '' !== (string) $wpdb->last_error || ! is_array( $rows ) || 1 < count( $rows ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_cron_readback', 'Public quarantine cron truth could not be read back exactly.', array( 'status' => 503 ) ); }
		if ( empty( $rows ) ) { return true; }
		$cron = maybe_unserialize( (string) $rows[0]['option_value'] );
		if ( ! is_array( $cron ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_cron_corrupt', 'Public quarantine found malformed cron truth.', array( 'status' => 503 ) ); }
		foreach ( $cron as $timestamp => $events ) {
			if ( 'version' === (string) $timestamp ) { continue; }
			if ( ! is_array( $events ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_cron_corrupt', 'Public quarantine found malformed cron truth.', array( 'status' => 503 ) ); }
			foreach ( array( 'complete99_campaign_activate', 'complete99_campaign_expire', 'complete99_campaign_verify_readback' ) as $hook ) {
				if ( array_key_exists( $hook, $events ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_cron_survivor', 'A Campaign lifecycle hook survived public quarantine cleanup.', array( 'status' => 503 ) ); }
			}
		}
		return true;
	}

