	/** Reconcile one permanent-quarantine slice before ordinary campaign jobs. */
	private static function reconcile_public_quarantine() {
		$status = self::public_quarantine_status( false );
		if ( empty( $status['inspectable'] ) ) { return new WP_Error( 'complete99_campaign_public_quarantine_invalid', 'Public quarantine singleton is unavailable.', array( 'status' => 503 ) ); }
		if ( empty( $status['active'] ) ) { return array( 'active' => false, 'progress' => false ); }
		$payload = (array) $status['payload'];
		$receipt = self::store_public_quarantine_receipt( $payload, $payload, 'opened' );
		if ( is_wp_error( $receipt ) ) { return $receipt; }
		$retry_at = 0;
		foreach ( array( 'reconcile_public_quarantine_placements', 'reconcile_public_quarantine_orphans', 'reconcile_public_quarantine_campaigns' ) as $method ) {
			$result = self::$method( $payload );
			if ( is_wp_error( $result ) ) { return $result; }
			if ( ! empty( $result['progress'] ) ) { $result['active'] = true; return $result; }
			$retry_at = max( $retry_at, (int) ( $result['retryAt'] ?? 0 ) );
		}
		$zero = self::ensure_public_quarantine_zero_membership_receipt( $payload );
		if ( is_wp_error( $zero ) ) { return $zero; }
		if ( ! empty( $zero['progress'] ) ) { return array( 'active' => true, 'progress' => true, 'kind' => 'zero_membership', 'count' => (int) ( $zero['cohort']['campaignCount'] ?? 0 ) ); }
		$aggregate_cleanup = self::reconcile_aggregate_cleanup( 'quarantine', (int) $payload['epoch'] );
		if ( is_wp_error( $aggregate_cleanup ) ) { return $aggregate_cleanup; }
		if ( empty( $aggregate_cleanup['done'] ) ) { return array( 'active' => true, 'progress' => ! empty( $aggregate_cleanup['progress'] ), 'kind' => 'aggregate_cleanup', 'retryAt' => $retry_at ); }
		$cleared = self::maybe_clear_public_quarantine( $payload );
		return is_wp_error( $cleared ) ? $cleared : array( 'active' => empty( $cleared['cleared'] ), 'progress' => ! empty( $cleared['cleared'] ), 'kind' => 'clear', 'retryAt' => $retry_at );
	}

	/** Hold the bridge-shared fence for the complete zero-traffic worker invocation. */
	public static function reconcile_schedules() {
		return self::run_lifecycle_worker_operation( 'reconcile', static function () { return self::reconcile_schedules_fenced(); } );
	}

	/** Process at most 100 due jobs or five seconds; retry timing is durable and indexed. */
	private static function reconcile_schedules_fenced() {
		global $wpdb;
		$tables = self::table_names();
		$started_at = microtime( true );
		$failures = array();
		$quiescence = self::worker_quiescence_status();
		if ( is_wp_error( $quiescence ) ) { return $quiescence; }
		/* Install an independent successor before retention, DB reads or recovery can fail. */
		$system_successor = self::enqueue_reconcile_trigger( time() + self::SYSTEM_CRON_INTERVAL_SECONDS );
		if ( is_wp_error( $system_successor ) ) { return $system_successor; }
		$retention = self::reconcile_public_event_retention();
		if ( is_wp_error( $retention ) ) {
			$failures[] = 'public_event_retention';
			$retention_retry = self::enqueue_reconcile_trigger( time() + 60 );
			if ( is_wp_error( $retention_retry ) ) { $failures[] = 'public_event_retention_retry'; }
		}
		$quarantine = self::reconcile_public_quarantine();
		if ( is_wp_error( $quarantine ) ) {
			self::enqueue_reconcile_trigger( time() + 60 );
			return $quarantine;
		}
		$quarantine_active = ! empty( $quarantine['active'] );
		$quarantine_retry_at = (int) ( $quarantine['retryAt'] ?? 0 );
		if ( $quarantine_active && ! empty( $quarantine['progress'] ) ) {
			$queued = self::enqueue_reconcile_trigger( time() + 1 );
			return is_wp_error( $queued ) ? $queued : true;
		}
		if ( ! $quarantine_active ) {
			$terminal_gc = self::reconcile_public_quarantine_terminal_gc();
			if ( is_wp_error( $terminal_gc ) ) { return $terminal_gc; }
			if ( ! empty( $terminal_gc['progress'] ) ) {
				$queued = self::enqueue_reconcile_trigger( time() + 1 );
				return is_wp_error( $queued ) ? $queued : true;
			}
		}
		$now = current_time( 'mysql', true );
		$cleanup_limit = self::RECONCILE_BATCH_SIZE * self::RECONCILE_MAX_BATCHES;
		$cleanup_rows = self::bounded_actionable_campaign_rows( 'cleanup_due', $now, $cleanup_limit );
		if ( is_wp_error( $cleanup_rows ) ) { return $cleanup_rows; }
		$seen_cleanup_rows = array();
		foreach ( $cleanup_rows as $row ) {
			if ( ( microtime( true ) - $started_at ) >= self::RECONCILE_TIME_BUDGET ) { break; }
			$id = is_numeric( $row['id'] ?? null ) ? (int) $row['id'] : 0;
			if ( 1 > $id || isset( $seen_cleanup_rows[ $id ] ) || ! is_numeric( $row['cleanup_revision'] ?? null ) || '' === (string) ( $row['public_id'] ?? '' ) ) { return new WP_Error( 'complete99_campaign_cleanup_reconcile_row_invalid', 'Campaign worker found an invalid cleanup snapshot row.', array( 'status' => 503 ) ); }
			$seen_cleanup_rows[ $id ] = true;
			$cleanup_result = self::reconcile_campaign_cleanup( (string) $row['public_id'] );
			if ( is_wp_error( $cleanup_result ) ) {
				$deferred = self::defer_failed_cleanup_row( (string) $row['public_id'], $cleanup_result->get_error_code() );
				$failures[] = is_wp_error( $deferred ) ? 'cleanup-deferral:' . (string) $row['public_id'] : 'cleanup:' . (string) $row['public_id'];
			}
		}
		$cleanup_batches = min( self::RECONCILE_MAX_BATCHES, (int) ceil( count( $cleanup_rows ) / self::RECONCILE_BATCH_SIZE ) );
		// Secure a later-ID/future cleanup slice before any schedule, evidence, or cache work can fail or exhaust the request budget.
		$campaign_continuation = self::schedule_next_reconcile_trigger( false );
		if ( is_wp_error( $campaign_continuation ) ) { return $campaign_continuation; }
		$schedule_batch_limit = $quarantine_active ? 0 : max( 0, self::RECONCILE_MAX_BATCHES - $cleanup_batches );
		$schedule_rows = 0 < $schedule_batch_limit ? self::bounded_actionable_campaign_rows( 'schedule_due', current_time( 'mysql', true ), $schedule_batch_limit * self::RECONCILE_BATCH_SIZE ) : array();
		if ( is_wp_error( $schedule_rows ) ) { return $schedule_rows; }
		foreach ( array_chunk( $schedule_rows, self::RECONCILE_BATCH_SIZE ) as $rows ) {
			if ( ( microtime( true ) - $started_at ) >= self::RECONCILE_TIME_BUDGET ) { break; }
			foreach ( $rows as $row ) {
				$result = self::reconcile_campaign_schedule( (string) $row['public_id'] );
				if ( is_wp_error( $result ) ) {
					$error_data = $result->get_error_data();
					if ( is_array( $error_data ) && ! empty( $error_data['retryStored'] ) ) { continue; }
					$loaded = self::load_campaign( (string) $row['public_id'] );
					$retry_state = 'complete99_campaign_authority_retry' === $result->get_error_code() ? 'authority_retry_pending' : 'retry_pending';
					$retry = is_wp_error( $loaded ) ? $loaded : self::mark_schedule_retry( $loaded, $result->get_error_code(), $retry_state, $loaded );
					if ( is_wp_error( $retry ) ) { $failures[] = (string) $row['public_id']; }
				}
			}
		}
		$campaign_continuation = self::schedule_next_reconcile_trigger( false );
		if ( is_wp_error( $campaign_continuation ) ) { return $campaign_continuation; }
		if ( ( microtime( true ) - $started_at ) < self::RECONCILE_TIME_BUDGET ) {
			$cache_reconciled = self::reconcile_cache_retry();
			if ( is_wp_error( $cache_reconciled ) ) { $failures[] = 'public_cache'; }
		}
		if ( $quarantine_active && ( microtime( true ) - $started_at ) < self::RECONCILE_TIME_BUDGET ) {
			$quarantine_after_cleanup = self::reconcile_public_quarantine();
			if ( is_wp_error( $quarantine_after_cleanup ) ) { $failures[] = 'public_quarantine'; }
			$quarantine_active = is_wp_error( $quarantine_after_cleanup ) || ! empty( $quarantine_after_cleanup['active'] );
			$quarantine_retry_at = is_wp_error( $quarantine_after_cleanup ) ? time() + 60 : (int) ( $quarantine_after_cleanup['retryAt'] ?? 0 );
		}
		if ( ( microtime( true ) - $started_at ) < self::RECONCILE_TIME_BUDGET ) {
			$evidence_reconciled = self::reconcile_private_evidence_dispositions();
			if ( is_wp_error( $evidence_reconciled ) ) { $failures[] = 'private_evidence'; }
		}
		$now = current_time( 'mysql', true );
		$due_cleanup = self::bounded_actionable_campaign_rows( 'cleanup_due', $now, 1 );
		$due_schedule = self::bounded_actionable_campaign_rows( 'schedule_due', $now, 1 );
		if ( is_wp_error( $due_cleanup ) || is_wp_error( $due_schedule ) ) { return is_wp_error( $due_cleanup ) ? $due_cleanup : $due_schedule; }
		$due = ! empty( $due_cleanup ) || ! empty( $due_schedule ) ? 1 : 0;
		$continuation = self::schedule_next_reconcile_trigger( false );
		if ( is_wp_error( $continuation ) ) { return $continuation; }
		if ( $quarantine_active ) {
			$next_quarantine = ! empty( $failures ) ? time() + 60 : ( (int) $due > 0 ? time() + 1 : ( 0 < $quarantine_retry_at ? $quarantine_retry_at : time() + 60 ) );
			$quarantine_retry = self::enqueue_reconcile_trigger( max( time() + 1, $next_quarantine ) );
			if ( is_wp_error( $quarantine_retry ) ) { return $quarantine_retry; }
		}
		return empty( $failures ) ? true : new WP_Error( 'complete99_campaign_reconcile_write_failed', 'One or more campaign retry states could not be stored.' );
	}

	private static function reconcile_campaign_schedule( $campaign_id ) {
		$loaded = self::load_campaign( $campaign_id );
		if ( is_wp_error( $loaded ) ) { return $loaded; }
		$effective = self::effective_campaign_state( $loaded );
		if ( is_wp_error( $effective ) ) { return $effective; }
		if ( is_array( $effective['overlay'] ?? null ) ) { return true; }
		$state = $loaded['state'];
		$lifecycle = (string) ( $state['runtime']['lifecycleState'] ?? '' );
		if ( ! in_array( $lifecycle, array( 'schedule_requested', 'active' ), true ) ) { return true; }
		if ( 'suspended' === ( $state['runtime']['jobState'] ?? '' ) ) {
			$resume_job = (string) ( $state['runtime']['suspendedFromJobState'] ?? '' );
			$resumable = 'active' === $lifecycle
				? array( 'readback_verified', 'retry_pending', 'authority_retry_pending', 'expiry_retry_pending' )
				: array( 'scheduled', 'reconcile_pending', 'readback_pending', 'retry_pending', 'authority_retry_pending', 'expiry_retry_pending' );
			if ( ! in_array( $resume_job, $resumable, true ) ) {
				return new WP_Error( 'complete99_campaign_suspended_state_invalid', 'Campaign suspension lacks an exact resumable job state.' );
			}
			$state['runtime']['jobState'] = $resume_job;
			$state['runtime']['suspendedFromJobState'] = '';
			$restored = self::save_campaign( $loaded, $state, 'schedule_resume_state_restored', 0, self::CAPACITY_ROLE_RECOVERY );
			if ( is_wp_error( $restored ) ) { return $restored; }
			$loaded = $restored;
			$state = $loaded['state'];
		}
		if ( 'active' === $lifecycle && 'readback_verified' === (string) ( $state['runtime']['jobState'] ?? '' ) ) {
			global $wpdb;
			$tables = self::table_names();
			$public_transaction = self::begin_public_read_transaction();
			if ( is_wp_error( $public_transaction ) ) { return $public_transaction; }
			$lock = self::is_sqlite_database() ? '' : ' FOR UPDATE';
			$wpdb->last_error = '';
			$active_rows = $wpdb->get_results( $wpdb->prepare( "SELECT * FROM {$tables['placements']} WHERE campaign_id=%s AND campaign_version=%d AND package_digest=%s AND status='active' ORDER BY id ASC LIMIT 2{$lock}", (string) $state['campaignId'], (int) ( $state['runtime']['scheduledVersion'] ?? 0 ), (string) ( $state['runtime']['scheduledPackageDigest'] ?? '' ) ), ARRAY_A );
			$active_rows_error = (string) $wpdb->last_error;
			if ( '' !== $active_rows_error || ! is_array( $active_rows ) || 1 !== count( $active_rows ) ) {
				self::rollback_transaction();
				$code = '' !== $active_rows_error || ! is_array( $active_rows )
					? 'campaign_public_active_placement_query_failed'
					: ( empty( $active_rows ) ? 'campaign_public_active_placement_missing' : 'campaign_public_active_placement_duplicated' );
				$suppressed = self::suppress_active_campaign_coherence( $loaded, $code );
				return is_wp_error( $suppressed ) ? $suppressed : true;
			}
			$public_context = self::locked_public_placement_context( (string) $active_rows[0]['readback_token'], array( 'active' ) );
			if ( is_wp_error( $public_context ) ) {
				self::rollback_transaction();
				return self::suppress_public_context_error( $public_context ) ? true : $public_context;
			}
			$public_commit = self::commit_public_read_transaction();
			if ( is_wp_error( $public_commit ) ) { return $public_commit; }
		}
		$authority = self::authority_snapshot_is_current( $state );
		$heartbeat = self::cron_heartbeat_status();
		$safety_error = is_wp_error( $authority ) ? $authority->get_error_code() : ( empty( $heartbeat['ready'] ) ? 'campaign_cron_watchdog_stale' : '' );
		if ( '' !== $safety_error ) {
			if ( 'active' === $lifecycle ) {
				$suppressed = self::suppress_active_campaign_coherence( $loaded, $safety_error );
				if ( is_wp_error( $suppressed ) ) {
					return new WP_Error( 'complete99_campaign_authority_suppression_failed', 'Active campaign safety truth changed and durable suppression could not be proven.' );
				}
				return true;
			}
			return new WP_Error( 'complete99_campaign_authority_retry', is_wp_error( $authority ) ? $authority->get_error_message() : 'The protected cron watchdog is stale; website activation remains paused.' );
		}
		if ( 'authority_retry_pending' === ( $state['runtime']['jobState'] ?? '' ) ) {
			$restored = self::advance_suppressed_activation_generation( $loaded );
			if ( is_wp_error( $restored ) ) { return self::activation_supersession_retry_error( $restored ); }
			$loaded = $restored;
			$state = $loaded['state'];
			$lifecycle = 'schedule_requested';
		}
		$cron_fence = self::begin_campaign_cron_mutation_fence();
		if ( is_wp_error( $cron_fence ) ) { return $cron_fence; }
		$result = null;
		$released = false;
		try {
			$result = self::reconcile_campaign_schedule_under_cron_fence( $loaded, $campaign_id );
		} catch ( \Throwable $error ) {
			$result = new WP_Error( 'complete99_campaign_schedule_reconcile_exception', 'Campaign schedule reconciliation stopped before mutating stale truth.', array( 'status' => 503 ) );
		} finally {
			$released = self::end_campaign_cron_mutation_fence( $cron_fence );
		}
		if ( ! $released ) { return new WP_Error( 'complete99_campaign_schedule_cron_lock_release_unknown', 'Campaign schedule cron-fence ownership became uncertain.', array( 'status' => 503 ) ); }
		if ( is_array( $result ) && 'expire' === (string) ( $result['_cronAction'] ?? '' ) ) { $expired = self::cron_expire_fenced( $result['args'][0], $result['args'][1], $result['args'][2] ); return is_wp_error( $expired ) ? $expired : true; }
		if ( is_array( $result ) && 'activate' === (string) ( $result['_cronAction'] ?? '' ) ) { $activated = self::cron_activate_fenced( $result['args'][0], $result['args'][1], $result['args'][2] ); return is_wp_error( $activated ) ? $activated : true; }
		if ( is_array( $result ) && 'save' === (string) ( $result['_cronAction'] ?? '' ) ) { return self::save_campaign( $result['loaded'], $result['state'], (string) $result['reason'], 0, self::CAPACITY_ROLE_RECOVERY ); }
		return $result;
	}

	private static function campaign_schedule_snapshot_matches( $expected, $current ) {
		if ( is_wp_error( $expected ) || is_wp_error( $current ) || ! is_array( $expected['row'] ?? null ) || ! is_array( $current['row'] ?? null ) ) { return false; }
		foreach ( array( 'id', 'version', 'cleanup_revision' ) as $key ) { if ( (int) ( $expected['row'][ $key ] ?? -1 ) !== (int) ( $current['row'][ $key ] ?? -2 ) ) { return false; } }
		foreach ( array( 'public_id', 'state_digest', 'cleanup_queue_digest', 'cleanup_due_at' ) as $key ) { if ( ! hash_equals( (string) ( $expected['row'][ $key ] ?? '' ), (string) ( $current['row'][ $key ] ?? '' ) ) ) { return false; } }
		return true;
	}

	/** Reconcile cron and its durable campaign projection under one retained slot fence. */
	private static function reconcile_campaign_schedule_under_cron_fence( $expected, $campaign_id ) {
		$loaded = self::load_campaign( (string) $campaign_id );
		if ( is_wp_error( $loaded ) ) { return $loaded; }
		if ( ! self::campaign_schedule_snapshot_matches( $expected, $loaded ) ) { return true; }
		$effective = self::effective_campaign_state( $loaded );
		if ( is_wp_error( $effective ) ) { return $effective; }
		if ( is_array( $effective['overlay'] ?? null ) ) { return true; }
		$state = $loaded['state'];
		$lifecycle = (string) ( $state['runtime']['lifecycleState'] ?? '' );
		if ( ! in_array( $lifecycle, array( 'schedule_requested', 'active' ), true ) || 'suspended' === (string) ( $state['runtime']['jobState'] ?? '' ) ) { return true; }
		$starts = (int) ( $state['runtime']['activationTimestamp'] ?? 0 );
		$expires = (int) ( $state['runtime']['expiryTimestamp'] ?? 0 );
		$args = array( (string) $state['campaignId'], (int) ( $state['runtime']['scheduledVersion'] ?? 0 ), (string) ( $state['runtime']['scheduleDigest'] ?? '' ) );
		if ( 1 > $starts || $expires <= $starts || $expires <= time() ) { return array( '_cronAction' => 'expire', 'args' => $args ); }
		$activation_next = wp_next_scheduled( 'complete99_campaign_activate', $args );
		$expiry_next = wp_next_scheduled( 'complete99_campaign_expire', $args );
		if ( false !== $activation_next && (int) $activation_next !== $starts ) {
			$removed = wp_unschedule_event( (int) $activation_next, 'complete99_campaign_activate', $args, true );
			if ( is_wp_error( $removed ) || false === $removed || false !== wp_next_scheduled( 'complete99_campaign_activate', $args ) ) { return new WP_Error( 'complete99_campaign_activation_event_drift', 'A drifted activation trigger could not be removed exactly.' ); }
			$activation_next = false;
		}
		if ( false !== $expiry_next && (int) $expiry_next !== $expires ) {
			$removed = wp_unschedule_event( (int) $expiry_next, 'complete99_campaign_expire', $args, true );
			if ( is_wp_error( $removed ) || false === $removed || false !== wp_next_scheduled( 'complete99_campaign_expire', $args ) ) { return new WP_Error( 'complete99_campaign_expiry_event_drift', 'A drifted expiry trigger could not be removed exactly.' ); }
			$expiry_next = false;
		}
		$activation_created = false;
		if ( 'active' !== $lifecycle && $starts > time() && false === $activation_next ) {
			$result = wp_schedule_single_event( $starts, 'complete99_campaign_activate', $args, true );
			if ( is_wp_error( $result ) || false === $result ) { return new WP_Error( 'complete99_campaign_activation_reconcile_failed', 'Activation trigger could not be reconciled.' ); }
			$activation_created = true;
		}
		if ( false === $expiry_next ) {
			$result = wp_schedule_single_event( $expires, 'complete99_campaign_expire', $args, true );
			if ( is_wp_error( $result ) || false === $result ) {
				if ( $activation_created ) {
					$removed = wp_unschedule_event( $starts, 'complete99_campaign_activate', $args, true );
					if ( is_wp_error( $removed ) || false === $removed || false !== wp_next_scheduled( 'complete99_campaign_activate', $args ) ) { return new WP_Error( 'complete99_campaign_activation_compensation_failed', 'Activation compensation failed after expiry scheduling failure.' ); }
				}
				return new WP_Error( 'complete99_campaign_expiry_reconcile_failed', 'Expiry trigger could not be reconciled.' );
			}
		}
		if ( 'active' !== $lifecycle && $starts > time() && (int) wp_next_scheduled( 'complete99_campaign_activate', $args ) !== $starts ) { return new WP_Error( 'complete99_campaign_activation_readback_failed', 'Activation trigger exact timestamp readback failed.' ); }
		if ( (int) wp_next_scheduled( 'complete99_campaign_expire', $args ) !== $expires ) { return new WP_Error( 'complete99_campaign_expiry_readback_failed', 'Expiry trigger exact timestamp readback failed.' ); }
		if ( 'active' !== $lifecycle && $starts <= time() ) {
			return array( '_cronAction' => 'activate', 'args' => $args );
		}
		if ( 'active' !== $lifecycle ) {
			$current = self::load_campaign( $campaign_id );
			if ( is_wp_error( $current ) || ! self::campaign_schedule_snapshot_matches( $loaded, $current ) ) { return is_wp_error( $current ) ? $current : true; }
			$next = $current['state'];
			$next['runtime']['jobState'] = 'scheduled';
			$next['runtime']['nextAttemptAt'] = gmdate( 'Y-m-d\TH:i:s\Z', $starts );
			$next['runtime']['lastErrorCode'] = '';
			return array( '_cronAction' => 'save', 'loaded' => $current, 'state' => $next, 'reason' => 'cron_reconciled' );
		}
		$watchdog = gmdate( 'Y-m-d\TH:i:s\Z', min( $expires, time() + self::AUTHORITY_WATCHDOG_SECONDS ) );
		if ( in_array( (string) ( $state['runtime']['jobState'] ?? '' ), array( 'retry_pending', 'expiry_retry_pending' ), true )
			|| ( 'readback_verified' === ( $state['runtime']['jobState'] ?? '' ) && ! hash_equals( (string) ( $state['runtime']['nextAttemptAt'] ?? '' ), $watchdog ) ) ) {
			$state['runtime']['jobState'] = 'readback_verified';
			$state['runtime']['nextAttemptAt'] = $watchdog;
			$state['runtime']['lastErrorCode'] = '';
			return array( '_cronAction' => 'save', 'loaded' => $loaded, 'state' => $state, 'reason' => 'active_schedule_resumed' );
		}
		return true;
	}

	/** Persist an unrecoverable historical-placement fault without allowing an outer retry to overwrite it. */
	private static function store_activation_supersession_fault( $current, $code, $message ) {
		$pre = $current;
		$state = $current['state'];
		$state['runtime']['externalState'] = 'suppressed';
		$state['runtime']['jobState'] = 'operator_attention';
		$state['runtime']['lastErrorCode'] = sanitize_key( (string) $code );
		$state['runtime']['nextAttemptAt'] = '';
		$saved = self::save_campaign( $current, $state, 'activation_supersession_operator_attention', 0, self::CAPACITY_ROLE_RECOVERY );
		if ( is_wp_error( $saved ) ) { self::rollback_transaction(); return $saved; }
		$commit = self::commit_transaction();
		if ( is_wp_error( $commit ) ) {
			$stored = self::classify_campaign_commit( (string) $state['campaignId'], $pre, $saved );
			return new WP_Error( 'complete99_campaign_activation_supersession_fault_outcome_unknown', 'Activation supersession fault storage has an unknown commit outcome.', array( 'status' => 503, 'retryStored' => true, 'stored' => $stored, 'cause' => $commit->get_error_code() ) );
		}
		return new WP_Error( sanitize_key( (string) $code ), (string) $message, array( 'status' => 503, 'retryStored' => true ) );
	}

	/** Classify immutable historical receipt truth before a generation can advance. */
	private static function activation_supersession_receipt_fault( $was_verified, $receipt_rows, $row, $package, $proof_url ) {
		if ( ! is_array( $receipt_rows ) ) { return array( 'code' => 'activation_supersession_receipt_query_invalid', 'message' => 'Historical system receipt truth is unavailable.' ); }
		if ( $was_verified ) {
			if ( 1 !== count( $receipt_rows ) ) {
				return array(
					'code' => empty( $receipt_rows ) ? 'activation_supersession_receipt_missing' : 'activation_supersession_receipt_duplicated',
					'message' => 'Historical verified system receipt truth is missing or duplicated.',
				);
			}
			if ( ! self::verified_readback_receipt_matches( $receipt_rows[0], $row, $package, $proof_url, true ) ) {
				return array( 'code' => 'activation_supersession_receipt_corrupt', 'message' => 'Historical verified system receipt truth is corrupt.' );
			}
			return null;
		}
		return empty( $receipt_rows ) ? null : array( 'code' => 'activation_supersession_pending_receipt_invalid', 'message' => 'A suppressed unverified placement unexpectedly has system-verified evidence.' );
	}

	/** Produce the exact next-generation durable runtime only after historical truth is proven. */
	private static function activation_generation_advance_state( $state, $generation ) {
		$current = is_array( $state ) ? ( $state['runtime']['activationGeneration'] ?? null ) : null;
		if ( ! is_int( $generation ) || ! is_int( $current ) || $current !== $generation || 0 > $generation || self::ACTIVATION_GENERATION_MAX <= $generation ) {
			return new WP_Error( 'complete99_campaign_activation_generation_transition_invalid', 'Activation generation transition input is stale or exhausted.', array( 'status' => 503 ) );
		}
		$state['runtime']['lifecycleState'] = 'schedule_requested';
		$state['runtime']['externalState'] = 'unverified';
		$state['runtime']['jobState'] = 'reconcile_pending';
		$state['runtime']['activationGeneration'] = $generation + 1;
		$state['runtime']['attempts'] = 0;
		$state['runtime']['nextAttemptAt'] = '';
		$state['runtime']['lastErrorCode'] = '';
		$state['runtime']['authoritySuppression'] = array();
		return $state;
	}

	/** Add retryStored without losing the exact underlying generation fault. */
	private static function activation_supersession_retry_error( $error, $stored = 'pre' ) {
		if ( ! is_wp_error( $error ) ) { return $error; }
		$data = $error->get_error_data();
		$data = is_array( $data ) ? $data : array( 'status' => 503 );
		$data['retryStored'] = true;
		if ( ! isset( $data['stored'] ) ) { $data['stored'] = in_array( $stored, array( 'pre', 'post', 'mixed' ), true ) ? $stored : 'mixed'; }
		return new WP_Error( $error->get_error_code(), $error->get_error_message(), $data );
	}

	private static function database_row_matches_snapshot( $expected, $fresh ) {
		if ( null === $expected || null === $fresh ) { return null === $expected && null === $fresh; }
		if ( ! is_array( $expected ) || ! is_array( $fresh ) ) { return false; }
		try { return hash_equals( self::canonical_json( $expected ), self::canonical_json( $fresh ) ); } catch ( \Throwable $error ) { return false; }
	}

	/** Classify only an exact all-pre or all-post durable vector; every alias or mix is unsafe. */
	private static function classify_commit_match_vector( $all_pre, $all_post ) {
		if ( true === $all_pre && true !== $all_post ) { return 'pre'; }
		if ( true === $all_post && true !== $all_pre ) { return 'post'; }
		return 'mixed';
	}

	/** Point-read an exact campaign-only mutation after an unacknowledged COMMIT. */
	private static function classify_campaign_commit( $campaign_id, $pre_campaign, $post_campaign ) {
		$fresh = self::load_campaign( (string) $campaign_id );
		if ( is_wp_error( $fresh ) ) { return 'mixed'; }
		$pre = self::campaign_schedule_snapshot_matches( $pre_campaign, $fresh );
		$post = self::campaign_schedule_snapshot_matches( $post_campaign, $fresh );
		return self::classify_commit_match_vector( $pre, $post );
	}

	/** Point-read atomic pre/post vectors after an unacknowledged COMMIT. */
	private static function classify_campaign_placement_commit( $campaign_id, $pre_campaign, $post_campaign, $placement_id, $pre_placement, $post_placement ) {
		global $wpdb;
		$fresh_campaign = self::load_campaign( (string) $campaign_id );
		if ( is_wp_error( $fresh_campaign ) ) { return 'mixed'; }
		$fresh_placement = null;
		if ( '' !== (string) $placement_id ) {
			$wpdb->last_error = '';
			$rows = $wpdb->get_results( $wpdb->prepare( 'SELECT * FROM ' . self::table_names()['placements'] . ' WHERE placement_id=%s ORDER BY id ASC LIMIT 2', (string) $placement_id ), ARRAY_A );
			if ( '' !== (string) $wpdb->last_error || ! is_array( $rows ) || 1 < count( $rows ) ) { return 'mixed'; }
			$fresh_placement = 1 === count( $rows ) ? $rows[0] : null;
		}
		$all_pre = self::campaign_schedule_snapshot_matches( $pre_campaign, $fresh_campaign ) && self::database_row_matches_snapshot( $pre_placement, $fresh_placement );
		$all_post = self::campaign_schedule_snapshot_matches( $post_campaign, $fresh_campaign ) && self::database_row_matches_snapshot( $post_placement, $fresh_placement );
		return self::classify_commit_match_vector( $all_pre, $all_post );
	}

	private static function activation_supersession_commit_outcome_error( $commit, $stored ) {
		self::enqueue_reconcile_trigger( time() + 1 );
		return new WP_Error( 'complete99_campaign_activation_supersession_commit_outcome_unknown', 'Activation generation supersession commit acknowledgement was ambiguous.', array( 'status' => 503, 'stored' => in_array( $stored, array( 'pre', 'post' ), true ) ? $stored : 'mixed', 'retryStored' => true, 'cause' => $commit->get_error_code() ) );
	}

	/** Preserve the specialized retry state whenever a generation transition commit is ambiguous. */
	private static function activation_supersession_commit_error( $commit, $campaign_id, $pre_campaign, $post_campaign, $placement_id = '', $pre_placement = null, $post_placement = null ) {
		if ( ! is_wp_error( $commit ) ) { return $commit; }
		$stored = self::classify_campaign_placement_commit( $campaign_id, $pre_campaign, $post_campaign, $placement_id, $pre_placement, $post_placement );
		return self::activation_supersession_commit_outcome_error( $commit, $stored );
	}

	/**
	 * Terminalize the exact suppressed generation before deriving a new public identity.
	 * Historical system evidence is immutable and remains bound only to the superseded row.
	 */
	private static function advance_suppressed_activation_generation( $expected ) {
		$result = self::advance_suppressed_activation_generation_internal( $expected );
		return is_wp_error( $result ) ? self::activation_supersession_retry_error( $result ) : $result;
	}

	/** Keep every pre-state failure inside the specialized authority-retry contract. */
	private static function advance_suppressed_activation_generation_internal( $expected ) {
		global $wpdb;
		$transaction = self::begin_transaction( self::CAPACITY_ROLE_RECOVERY );
		if ( is_wp_error( $transaction ) ) { return $transaction; }
		$quarantine = self::assert_public_quarantine_clear( true );
		if ( is_wp_error( $quarantine ) ) { self::rollback_transaction(); return $quarantine; }
		$campaign_id = (string) ( $expected['state']['campaignId'] ?? '' );
		$current = self::load_campaign( $campaign_id, true );
		if ( is_wp_error( $current ) ) { self::rollback_transaction(); return $current; }
		$state = $current['state'];
		if ( 'authority_retry_pending' !== (string) ( $state['runtime']['jobState'] ?? '' ) ) {
			self::rollback_transaction();
			return $current;
		}
		if ( ! in_array( (string) ( $state['runtime']['externalState'] ?? '' ), array( 'unverified', 'suppressed' ), true ) ) {
			return self::store_activation_supersession_fault( $current, 'activation_retry_external_state_invalid', 'Authority retry state is not bound to a recoverable public state.' );
		}
		if ( (int) ( $current['row']['version'] ?? 0 ) !== (int) ( $expected['row']['version'] ?? -1 )
			|| ! hash_equals( (string) ( $state['runtime']['scheduleDigest'] ?? '' ), (string) ( $expected['state']['runtime']['scheduleDigest'] ?? '' ) )
			|| null !== ( $current['row']['cleanup_due_at'] ?? null )
				|| ! empty( $current['cleanupQueue']['obligations'] ?? array() ) ) {
			self::rollback_transaction();
			return new WP_Error( 'complete99_campaign_activation_supersession_stale', 'Suppressed activation truth changed or cleanup is still pending.', array( 'status' => 409, 'retryStored' => true ) );
		}
		$generation = $state['runtime']['activationGeneration'] ?? null;
		if ( ! is_int( $generation ) || 0 > $generation || self::ACTIVATION_GENERATION_MAX <= $generation ) {
			return self::store_activation_supersession_fault( $current, 'activation_supersession_generation_exhausted', 'Campaign activation generation cannot be advanced safely.' );
		}
		if ( is_wp_error( self::authority_snapshot_is_current( $state ) ) || empty( self::cron_heartbeat_status()['ready'] ) ) {
			self::rollback_transaction();
			return new WP_Error( 'complete99_campaign_activation_supersession_authority_stale', 'Suppressed activation authority is not yet current.', array( 'status' => 503, 'retryStored' => true ) );
		}
		$tables = self::table_names();
		$lock = self::is_sqlite_database() ? '' : ' FOR UPDATE';
		$package_id = (string) ( $state['runtime']['scheduledPackageId'] ?? '' );
		$scheduled_version = (int) ( $state['runtime']['scheduledVersion'] ?? 0 );
		$package_digest = (string) ( $state['runtime']['scheduledPackageDigest'] ?? '' );
		$approval_digest = (string) ( $state['runtime']['scheduledApprovalDigest'] ?? '' );
		$slot = (string) ( $state['governance']['slotKey'] ?? '' );
		$expected_placement_id = self::owned_placement_id( $campaign_id, (string) ( $state['runtime']['scheduleDigest'] ?? '' ), $generation );
		$wpdb->last_error = '';
		$package_rows = $wpdb->get_results( $wpdb->prepare( "SELECT * FROM {$tables['prepared_packages']} WHERE package_id=%s AND campaign_id=%s AND campaign_version=%d AND package_digest=%s AND approval_snapshot_digest=%s AND channel='website' AND status='prepared' ORDER BY id ASC LIMIT 2{$lock}", $package_id, $campaign_id, $scheduled_version, $package_digest, $approval_digest ), ARRAY_A );
		if ( '' !== (string) $wpdb->last_error || ! is_array( $package_rows ) ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_activation_supersession_package_query_failed', 'Suppressed package truth could not be inspected.', array( 'status' => 503, 'retryStored' => true ) ); }
		if ( 1 !== count( $package_rows ) ) { return self::store_activation_supersession_fault( $current, empty( $package_rows ) ? 'activation_supersession_package_missing' : 'activation_supersession_package_duplicated', 'Suppressed package truth is missing or duplicated.' ); }
		$package = $package_rows[0];
		$wpdb->last_error = '';
		$placement_rows = $wpdb->get_results( $wpdb->prepare( "SELECT * FROM {$tables['placements']} WHERE placement_id=%s ORDER BY id ASC LIMIT 2{$lock}", $expected_placement_id ), ARRAY_A );
		$placement_error = (string) $wpdb->last_error;
		$wpdb->last_error = '';
		$current_conflicts = $wpdb->get_results(
			$wpdb->prepare(
				"SELECT id,placement_id,status FROM {$tables['placements']} WHERE placement_id<>%s AND campaign_id=%s AND campaign_version=%d AND package_digest=%s AND slot_key=%s AND status IN ('scheduled','pending_readback','active','suppressed_authority','suppressed_readback') ORDER BY id ASC LIMIT 2{$lock}",
				$expected_placement_id,
				$campaign_id,
				$scheduled_version,
				$package_digest,
				$slot
			),
			ARRAY_A
		);
		if ( '' !== $placement_error || '' !== (string) $wpdb->last_error || ! is_array( $placement_rows ) || ! is_array( $current_conflicts ) ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_activation_supersession_placement_query_failed', 'Suppressed placement truth could not be inspected.', array( 'status' => 503, 'retryStored' => true ) ); }
		if ( ! empty( $current_conflicts ) ) { return self::store_activation_supersession_fault( $current, 'activation_supersession_placement_duplicated', 'Suppressed placement truth has another current-generation row.' ); }
		$receipt_rows = self::system_readback_receipts( array( 'placement_id' => $expected_placement_id ), true );
		if ( is_wp_error( $receipt_rows ) ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_activation_supersession_receipt_query_failed', 'Historical system receipt truth could not be inspected.', array( 'status' => 503, 'retryStored' => true ) ); }
		if ( empty( $placement_rows ) ) {
			$preplacement = 'schedule_requested' === (string) ( $state['runtime']['lifecycleState'] ?? '' )
				&& 'unverified' === (string) ( $state['runtime']['externalState'] ?? '' )
				&& empty( $state['runtime']['authoritySuppression'] ?? array() )
				&& empty( $receipt_rows );
			if ( ! $preplacement ) { return self::store_activation_supersession_fault( $current, ! empty( $receipt_rows ) ? 'activation_preplacement_receipt_invalid' : 'activation_supersession_placement_missing', 'Pre-placement authority retry truth is missing, mixed, or already claims system evidence.' ); }
			$state['runtime']['jobState'] = 'reconcile_pending';
			$state['runtime']['attempts'] = 0;
			$state['runtime']['nextAttemptAt'] = '';
			$state['runtime']['lastErrorCode'] = '';
			$resumed = self::save_campaign( $current, $state, 'authority_retry_preplacement_resumed', 0, self::CAPACITY_ROLE_RECOVERY );
			if ( is_wp_error( $resumed ) ) { self::rollback_transaction(); return $resumed; }
			$commit = self::commit_transaction();
			return is_wp_error( $commit ) ? self::activation_supersession_commit_error( $commit, $campaign_id, $current, $resumed ) : $resumed;
		}
		if ( 1 !== count( $placement_rows ) ) { return self::store_activation_supersession_fault( $current, 'activation_supersession_placement_duplicated', 'Suppressed placement truth is duplicated.' ); }
		$row = $placement_rows[0];
		$suppressed_status = (string) ( $row['status'] ?? '' );
		$quarantine_recovered = false;
		if ( preg_match( '/\Aqtr_([a-f0-9]{16})\z/', $suppressed_status, $qtr_match ) ) {
			$qtr_epoch = hexdec( $qtr_match[1] );
			$qtr_manifest = is_int( $qtr_epoch ) && 0 < $qtr_epoch ? self::public_quarantine_final_receipt_manifest( $qtr_epoch, true ) : new WP_Error( 'complete99_campaign_activation_qtr_epoch', 'Recovered quarantine epoch is invalid.', array( 'status' => 503 ) );
			$qtr_valid = is_wp_error( $qtr_manifest ) ? $qtr_manifest : self::validate_public_quarantine_manifest_rows( $qtr_manifest, true );
			$qtr_index = is_wp_error( $qtr_manifest ) ? false : array_search( (int) ( $row['id'] ?? 0 ), $qtr_manifest['ids'], true );
			if ( is_wp_error( $qtr_valid ) || false === $qtr_index || true === ( $qtr_manifest['orphan'][ $qtr_index ] ?? true ) || ! hash_equals( $campaign_id, (string) ( $row['campaign_id'] ?? '' ) ) || ! hash_equals( self::public_quarantine_recovered_status( (string) $qtr_manifest['proof']['qtnStatus'] ), $suppressed_status ) ) { return self::store_activation_supersession_fault( $current, 'activation_supersession_qtr_corrupt', 'Recovered quarantine placement is not bound to its immutable final receipt.' ); }
			$quarantine_recovered = true;
		}
		$historical_token = (string) ( $row['readback_token'] ?? '' );
		$historical_public_json = (string) ( $row['public_json'] ?? '' );
		$historical_public = json_decode( $historical_public_json, true );
		$historical_public_exact = is_array( $historical_public ) && hash_equals( $historical_public_json, self::canonical_json( $historical_public ) )
			&& hash_equals( (string) ( $row['public_digest'] ?? '' ), hash( 'sha256', $historical_public_json ) )
			&& self::historical_owned_event_endpoint_is_safe( (string) ( $historical_public['eventEndpoint'] ?? '' ), (string) ( $historical_public['proofUrl'] ?? '' ), $historical_token );
		$placement_exact = ( 'suppressed_authority' === $suppressed_status || $quarantine_recovered )
			&& hash_equals( $expected_placement_id, (string) ( $row['placement_id'] ?? '' ) )
			&& $historical_public_exact
			&& hash_equals( $campaign_id, (string) ( $row['campaign_id'] ?? '' ) )
			&& $scheduled_version === (int) ( $row['campaign_version'] ?? -1 )
			&& hash_equals( $package_digest, (string) ( $row['package_digest'] ?? '' ) )
			&& hash_equals( $slot, (string) ( $row['slot_key'] ?? '' ) )
			&& strtotime( (string) ( $row['starts_at'] ?? '' ) . ' UTC' ) === (int) ( $state['runtime']['activationTimestamp'] ?? 0 )
			&& strtotime( (string) ( $row['expires_at'] ?? '' ) . ' UTC' ) === (int) ( $state['runtime']['expiryTimestamp'] ?? 0 );
		if ( ! $placement_exact ) { return self::store_activation_supersession_fault( $current, 'activation_supersession_placement_corrupt', 'Suppressed placement truth is not exactly bound to its generation.' ); }
		if ( 'suppressed' !== (string) ( $state['runtime']['externalState'] ?? '' ) ) { return self::store_activation_supersession_fault( $current, 'activation_supersession_external_state_invalid', 'Suppressed placement is not bound to suppressed campaign truth.' ); }
		$was_verified = 'active' === (string) ( $state['runtime']['lifecycleState'] ?? '' );
		$proof_url = is_array( $historical_public ) ? (string) ( $historical_public['proofUrl'] ?? '' ) : '';
		$receipt_fault = self::activation_supersession_receipt_fault( $was_verified, $receipt_rows, $row, $package, $proof_url );
		if ( is_array( $receipt_fault ) ) { return self::store_activation_supersession_fault( $current, (string) $receipt_fault['code'], (string) $receipt_fault['message'] ); }
		$receipt_digest = $was_verified ? hash( 'sha256', self::canonical_json( $receipt_rows[0] ) ) : '';
		$now = current_time( 'mysql', true );
		$historical_target_status = $quarantine_recovered ? $suppressed_status : 'superseded';
		$updated = $wpdb->update(
			$tables['placements'],
			array( 'status' => $historical_target_status, 'updated_at' => $now ),
			array( 'id' => (int) $row['id'], 'placement_id' => $expected_placement_id, 'campaign_id' => $campaign_id, 'campaign_version' => $scheduled_version, 'package_digest' => $package_digest, 'public_digest' => (string) $row['public_digest'], 'readback_token' => $historical_token, 'status' => $suppressed_status )
		);
		if ( 1 !== $updated ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_activation_supersession_store_failed', 'Suppressed placement changed concurrently.', array( 'status' => 409, 'retryStored' => true ) ); }
		$state = self::activation_generation_advance_state( $state, $generation );
		if ( is_wp_error( $state ) ) { self::rollback_transaction(); return $state; }
		$saved = self::save_campaign( $current, $state, 'authority_restored_generation_advanced', 0, self::CAPACITY_ROLE_RECOVERY );
		if ( is_wp_error( $saved ) ) { self::rollback_transaction(); return $saved; }
		$wpdb->last_error = '';
		$stored_row = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$tables['placements']} WHERE id=%d LIMIT 1{$lock}", (int) $row['id'] ), ARRAY_A );
		$stored_row_error = (string) $wpdb->last_error;
		$stored_receipts = self::system_readback_receipts( $row, true );
		if ( '' !== $stored_row_error || ! is_array( $stored_row ) || ! hash_equals( $historical_target_status, (string) ( $stored_row['status'] ?? '' ) )
			|| ! hash_equals( $expected_placement_id, (string) ( $stored_row['placement_id'] ?? '' ) ) || is_wp_error( $stored_receipts )
			|| ( $was_verified && ( 1 !== count( $stored_receipts ) || ! hash_equals( $receipt_digest, hash( 'sha256', self::canonical_json( $stored_receipts[0] ) ) ) ) )
			|| ( ! $was_verified && ! empty( $stored_receipts ) ) ) {
			self::rollback_transaction();
			return new WP_Error( 'complete99_campaign_activation_supersession_readback_failed', 'Activation generation supersession failed exact placement, state, or historical receipt readback.', array( 'status' => 503, 'retryStored' => true ) );
		}
		$commit = self::commit_transaction();
		if ( is_wp_error( $commit ) ) { return self::activation_supersession_commit_error( $commit, $campaign_id, $current, $saved, $expected_placement_id, $row, $stored_row ); }
		return $saved;
	}

	private static function finish_deactivation_suspension_ownership( $token ) {
		if ( '' === self::$deactivation_suspension_token || ! is_string( $token ) || ! hash_equals( self::$deactivation_suspension_token, $token ) ) { return false; }
		self::$lifecycle_entrant_permit = null;
		$worker_released = true; $lifecycle_released = true;
		if ( self::$deactivation_suspension_adopted_worker ) { self::$worker_execution_fence_owned = false; }
		elseif ( self::$worker_execution_fence_owned ) { $worker_released = self::end_worker_execution_fence(); }
		if ( self::$deactivation_suspension_adopted_lifecycle ) { self::$lifecycle_role_lock_owned = false; }
		elseif ( self::$lifecycle_role_lock_owned ) { $lifecycle_released = self::end_lifecycle_role_fence(); }
		self::$deactivation_suspension_token = '';
		self::$deactivation_suspension_adopted_lifecycle = false;
		self::$deactivation_suspension_adopted_worker = false;
		self::$deactivation_suspension_deployment_owner = false;
		return $worker_released && $lifecycle_released;
	}

	/** Retain lifecycle+worker ownership until core persists active_plugins and fires deactivated_plugin. */
	public static function begin_deactivation_suspension() {
		if ( '' !== self::$deactivation_suspension_token || self::$activation_recovery_mode || self::$lifecycle_role_lock_owned || self::$worker_execution_fence_owned || self::$transaction_active || 0 < self::$authority_write_depth ) { return new WP_Error( 'complete99_campaign_deactivation_nested', 'Campaign deactivation suspension cannot be entered safely.', array( 'status' => 503 ) ); }
		$deploy = self::active_deploy_lock( false );
		if ( is_wp_error( $deploy ) ) { return $deploy; }
		$adopted = false;
		if ( $deploy ) {
			$owner = self::activation_recovery_deployment_owner();
			$fresh_owner = is_wp_error( $owner ) ? $owner : self::activation_recovery_deployment_owner();
			if ( is_wp_error( $owner ) || is_wp_error( $fresh_owner ) || ! hash_equals( self::canonical_json( $owner ), self::canonical_json( $fresh_owner ) ) ) { return is_wp_error( $owner ) ? $owner : ( is_wp_error( $fresh_owner ) ? $fresh_owner : new WP_Error( 'complete99_campaign_deactivation_deploy_owner_changed', 'Deactivation deployment ownership changed during adoption.', array( 'status' => 503 ) ) ); }
			self::$lifecycle_role_lock_owned = true; self::$worker_execution_fence_owned = true;
			self::$deactivation_suspension_adopted_lifecycle = true; self::$deactivation_suspension_adopted_worker = true; self::$deactivation_suspension_deployment_owner = true; $adopted = true;
		} else {
			$lifecycle = self::begin_lifecycle_role_fence( array( 'active', 'suspending' ) );
			if ( is_wp_error( $lifecycle ) ) { return $lifecycle; }
			$worker = self::begin_worker_execution_fence( false, true );
			if ( is_wp_error( $worker ) ) { self::end_lifecycle_role_fence(); return $worker; }
		}
		try { $token = bin2hex( random_bytes( 32 ) ); } catch ( \Throwable $error ) { $token = ''; }
		if ( ! preg_match( '/\A[a-f0-9]{64}\z/', $token ) ) { self::$deactivation_suspension_token = str_repeat( '0', 64 ); self::finish_deactivation_suspension_ownership( self::$deactivation_suspension_token ); return new WP_Error( 'complete99_campaign_deactivation_token', 'Campaign deactivation token could not be created.', array( 'status' => 503 ) ); }
		self::$deactivation_suspension_token = $token;
		$current = self::lifecycle_reservation_status( false );
		if ( ! self::create_lifecycle_entrant_permit( 'deactivation_suspension', $current, 'deactivation', $token ) ) { self::finish_deactivation_suspension_ownership( $token ); return new WP_Error( 'complete99_campaign_deactivation_entrant_permit', 'Campaign deactivation entrant ownership could not be authenticated.', array( 'status' => 503 ) ); }
		if ( ! is_wp_error( $current ) && hash_equals( 'active', (string) ( $current['state'] ?? '' ) ) ) {
			$current = self::transition_lifecycle_reservation_locked( $current, 'suspending' );
			if ( ! is_wp_error( $current ) && ! self::rebind_lifecycle_entrant_permit( $current ) ) { $current = new WP_Error( 'complete99_campaign_deactivation_entrant_rebind', 'Campaign deactivation could not bind the exact suspending lifecycle truth.', array( 'status' => 503 ) ); }
		}
		$result = is_wp_error( $current ) ? $current : ( hash_equals( 'suspending', (string) ( $current['state'] ?? '' ) ) ? self::suspend_schedules_fenced( $current, false ) : new WP_Error( 'complete99_campaign_deactivation_state', 'Campaign lifecycle is not eligible for deactivation.', array( 'status' => 423 ) ) );
		if ( is_wp_error( $result ) ) { self::finish_deactivation_suspension_ownership( $token ); return $result; }
		return array( 'token' => $token, 'generation' => (int) $result['generation'], 'deploymentOwner' => self::$deactivation_suspension_deployment_owner, 'adopted' => $adopted );
	}

	public static function complete_deactivation_suspension( $token ) {
		if ( '' === self::$deactivation_suspension_token || ! is_string( $token ) || ! hash_equals( self::$deactivation_suspension_token, $token ) || ! self::$lifecycle_role_lock_owned || ! self::$worker_execution_fence_owned ) { return new WP_Error( 'complete99_campaign_deactivation_owner', 'Campaign deactivation ownership is invalid.', array( 'status' => 503 ) ); }
		$current = self::lifecycle_reservation_status( false );
		if ( ! self::rebind_lifecycle_entrant_permit( $current ) ) {
			$released = self::finish_deactivation_suspension_ownership( $token );
			return new WP_Error( 'complete99_campaign_deactivation_entrant_rebind', 'Campaign deactivation finalization could not bind exact lifecycle truth.', array( 'status' => 503, 'released' => $released ) );
		}
		$result = is_wp_error( $current ) ? $current : self::suspend_schedules_fenced( $current, true );
		$final = is_wp_error( $result ) ? $result : self::lifecycle_reservation_status( false );
		$exact = ! is_wp_error( $final ) && hash_equals( 'inactive', (string) ( $final['state'] ?? '' ) );
		$released = self::finish_deactivation_suspension_ownership( $token );
		if ( is_wp_error( $result ) ) { return $result; }
		return $exact && $released ? true : new WP_Error( 'complete99_campaign_deactivation_complete', 'Campaign deactivation did not prove inactive truth and exact fence disposition.', array( 'status' => 503 ) );
	}

	public static function abort_deactivation_suspension( $token ) {
		return self::finish_deactivation_suspension_ownership( (string) $token ) ? true : new WP_Error( 'complete99_campaign_deactivation_abort', 'Campaign deactivation fence disposition could not be proven.', array( 'status' => 503 ) );
	}

	/** Enter a crash-safe aggregate lifecycle transition before plugin deactivation completes. */
	public static function suspend_schedules( $finalize = true ) {
		$finalize = true === $finalize;
		$lifecycle = self::begin_lifecycle_role_fence( array( 'active', 'suspending', 'inactive' ) );
		if ( is_wp_error( $lifecycle ) ) { throw new \RuntimeException( $lifecycle->get_error_message() ); }
		$current = $lifecycle;
		$failure = null;
		$worker_owned = false;
		$worker_released = false;
		$role_released = false;
		try {
			/* The worker fence must drain before active can become suspending. */
			$worker = self::begin_worker_execution_fence( false, true );
			if ( is_wp_error( $worker ) ) { throw new \RuntimeException( $worker->get_error_message() ); }
			$worker_owned = true;
			if ( ! self::create_lifecycle_entrant_permit( 'deactivation_suspension', $current, 'deactivation' ) ) { throw new \RuntimeException( 'Campaign deactivation entrant ownership could not be authenticated.' ); }
			if ( hash_equals( 'active', (string) $current['state'] ) ) {
				$current = self::transition_lifecycle_reservation_locked( $current, 'suspending' );
				if ( is_wp_error( $current ) ) { throw new \RuntimeException( $current->get_error_message() ); }
				if ( ! self::rebind_lifecycle_entrant_permit( $current ) ) { throw new \RuntimeException( 'Campaign deactivation entrant could not bind suspending truth.' ); }
			}
			if ( hash_equals( 'suspending', (string) $current['state'] ) ) { $current = self::suspend_schedules_fenced( $current, $finalize ); }
			$expected_state = $finalize ? 'inactive' : 'suspending';
			if ( is_wp_error( $current ) || ! hash_equals( $expected_state, (string) ( $current['state'] ?? '' ) ) ) { throw new \RuntimeException( is_wp_error( $current ) ? $current->get_error_message() : 'Campaign lifecycle did not reach exact deactivation phase truth.' ); }
		} catch ( \Throwable $error ) {
			$failure = $error;
		} finally {
			self::$lifecycle_entrant_permit = null;
			$worker_released = ! $worker_owned || self::end_worker_execution_fence();
			$role_released = self::end_lifecycle_role_fence();
		}
		if ( ! $worker_released || ! $role_released ) { throw new \RuntimeException( 'Campaign suspension fence release could not be proven.' ); }
		if ( $failure ) { throw $failure; }
		return true;
	}

	private static function suspend_schedules_fenced( $current, $finalize = true ) {
		if ( ! self::$worker_execution_fence_owned || ! self::$lifecycle_role_lock_owned || ! is_array( $current ) || ! hash_equals( 'suspending', (string) ( $current['state'] ?? '' ) ) ) { return new WP_Error( 'complete99_campaign_lifecycle_suspend_order', 'Campaign suspension requires exact suspending lifecycle and worker ownership.', array( 'status' => 503 ) ); }
		$context = self::begin_lifecycle_cleanup_drain_context( $current );
		if ( is_wp_error( $context ) ) { return $context; }
		try { return self::suspend_schedules_fenced_body( $current, $finalize ); }
		finally { self::$lifecycle_cleanup_drain_context = null; }
	}

	private static function suspend_schedules_fenced_body( $current, $finalize = true ) {
		$generation = (int) $current['generation'];
		$lifecycle_digest = hash( 'sha256', (string) $current['rawJson'] );
		$opening = array( 'generation' => $generation, 'lifecycleDigest' => $lifecycle_digest, 'phase' => 'suspending', 'schemaVersion' => 'complete99-campaign-lifecycle-suspending/v1', 'startedAt' => (string) $current['changedAt'] );
		$stored = self::store_lifecycle_receipt( $opening, 'suspending' );
		if ( is_wp_error( $stored ) ) { return $stored; }
		$opening_digest = hash( 'sha256', self::canonical_json( $opening ) );
		$limit = (int) ceil( ( self::CAMPAIGN_MAX_ROWS * 3 + 1 ) / self::RECONCILE_BATCH_SIZE ) + 2;
		$done = false;
		for ( $batch_index = 0; $batch_index < $limit; ++$batch_index ) {
			$batch = self::suspend_campaign_cron_batch();
			if ( is_wp_error( $batch ) ) { return $batch; }
			if ( ! empty( $batch['done'] ) ) { $done = true; break; }
		}
		if ( ! $done ) { return new WP_Error( 'complete99_campaign_lifecycle_cron_bound', 'Campaign lifecycle cron drain exceeded its protected bound.', array( 'status' => 503 ) ); }
		$cleanup_done = false;
		/* Aggregate pages and <=50-row queue CAS batches resume from immutable receipts. */
		$cleanup_limit = self::CAMPAIGN_MAX_ROWS + 2;
		for ( $cleanup_index = 0; $cleanup_index < $cleanup_limit; ++$cleanup_index ) {
			$cleanup_batch = self::suspend_cleanup_batch( $generation );
			if ( is_wp_error( $cleanup_batch ) ) { return $cleanup_batch; }
			if ( ! empty( $cleanup_batch['done'] ) ) { $cleanup_done = true; break; }
		}
		if ( ! $cleanup_done ) { return new WP_Error( 'complete99_campaign_lifecycle_cleanup_bound', 'Campaign lifecycle cleanup exceeded its protected bound.', array( 'status' => 503 ) ); }
		$aggregate_cleanup = self::aggregate_cleanup_stored_payload( 'lifecycle', $generation, 'cohort', -1, false );
		$aggregate_cleanup_digest = is_wp_error( $aggregate_cleanup ) ? '' : hash( 'sha256', self::canonical_json( $aggregate_cleanup ) );
		$aggregate_cleanup_chain = is_wp_error( $aggregate_cleanup ) ? $aggregate_cleanup : self::verify_aggregate_cleanup_chain( 'lifecycle', $generation, $aggregate_cleanup_digest, false );
		$cron_empty = self::lifecycle_cron_empty();
		$cleanup_empty = self::lifecycle_cleanup_empty();
		if ( is_wp_error( $aggregate_cleanup_chain ) || is_wp_error( $cron_empty ) || is_wp_error( $cleanup_empty ) || true !== $cron_empty || true !== $cleanup_empty ) { return is_wp_error( $aggregate_cleanup_chain ) ? $aggregate_cleanup_chain : ( is_wp_error( $cron_empty ) ? $cron_empty : ( is_wp_error( $cleanup_empty ) ? $cleanup_empty : new WP_Error( 'complete99_campaign_lifecycle_drain_rescan', 'Lifecycle drain final rescan found surviving cron or cleanup truth.', array( 'status' => 503 ) ) ) ); }
		$drained = self::stored_lifecycle_receipt( $generation, 'drained', false );
		if ( is_wp_error( $drained ) ) {
			$drained = array( 'aggregateCleanupReceiptDigest' => $aggregate_cleanup_digest, 'cronEmpty' => true, 'generation' => $generation, 'lifecycleDigest' => $lifecycle_digest, 'openingReceiptDigest' => $opening_digest, 'phase' => 'drained', 'schemaVersion' => 'complete99-campaign-lifecycle-drained/v1', 'verifiedAt' => gmdate( 'Y-m-d\TH:i:s\Z' ) );
			$stored = self::store_lifecycle_receipt( $drained, 'drained' );
			if ( is_wp_error( $stored ) ) { return $stored; }
		}
		if ( ! hash_equals( $lifecycle_digest, (string) ( $drained['lifecycleDigest'] ?? '' ) ) || ! hash_equals( $opening_digest, (string) ( $drained['openingReceiptDigest'] ?? '' ) ) || ! hash_equals( $aggregate_cleanup_digest, (string) ( $drained['aggregateCleanupReceiptDigest'] ?? '' ) ) ) { return new WP_Error( 'complete99_campaign_lifecycle_drain_receipt_stale', 'Lifecycle cron-drain receipt is not bound to the suspending generation and aggregate cleanup.', array( 'status' => 503 ) ); }
		$final = self::stored_lifecycle_receipt( $generation, 'inactive', false );
		if ( is_wp_error( $final ) ) {
			$urls = self::lifecycle_public_absence_urls();
			if ( is_wp_error( $urls ) ) { return $urls; }
			$completed_at = gmdate( 'Y-m-d\TH:i:s\Z' );
			$fenced = self::begin_worker_external_effect_fence( 'lifecycle_drain' );
			if ( is_wp_error( $fenced ) ) { return $fenced; }
			$absence = self::prove_public_quarantine_absence( $urls, $completed_at );
			if ( is_wp_error( $absence ) ) { return $absence; }
			$final = array( 'absence' => $absence, 'aggregateCleanupReceiptDigest' => $aggregate_cleanup_digest, 'completedAt' => $completed_at, 'cronEmpty' => true, 'generation' => $generation, 'inactiveGeneration' => $generation + 1, 'lifecycleDigest' => $lifecycle_digest, 'openingReceiptDigest' => $opening_digest, 'phase' => 'inactive', 'schemaVersion' => 'complete99-campaign-lifecycle-inactive/v1' );
			$stored = self::store_lifecycle_receipt( $final, 'inactive' );
			if ( is_wp_error( $stored ) ) { return $stored; }
		}
		if ( ! self::lifecycle_receipt_payload_valid( $final, 'inactive' ) || (int) $final['inactiveGeneration'] !== $generation + 1 || ! hash_equals( $lifecycle_digest, (string) $final['lifecycleDigest'] ) || ! hash_equals( $opening_digest, (string) $final['openingReceiptDigest'] ) || ! hash_equals( $aggregate_cleanup_digest, (string) $final['aggregateCleanupReceiptDigest'] ) ) { return new WP_Error( 'complete99_campaign_lifecycle_final_receipt_stale', 'Lifecycle inactive receipt is not bound to the suspending generation and aggregate cleanup.', array( 'status' => 503 ) ); }
		/* Core persists active_plugins after the deactivation callback returns. */
		if ( true !== $finalize ) { return $current; }
		$inactive = self::transition_lifecycle_reservation_locked( $current, 'inactive' );
		return is_wp_error( $inactive ) ? $inactive : ( (int) $inactive['generation'] === (int) $final['inactiveGeneration'] ? $inactive : new WP_Error( 'complete99_campaign_lifecycle_inactive_generation', 'Lifecycle inactive generation failed exact final-receipt binding.', array( 'status' => 503 ) ) );
	}

	public static function resume_schedules() {
		if ( self::$activation_recovery_mode && self::$lifecycle_role_lock_owned && self::$worker_execution_fence_owned ) {
			$current = self::lifecycle_reservation_status( false );
			$result = is_wp_error( $current ) ? $current : self::resume_schedules_fenced( $current );
			if ( is_wp_error( $result ) ) { throw new \RuntimeException( $result->get_error_message() ); }
			return true;
		}
		$lifecycle = self::begin_lifecycle_role_fence( array( 'active', 'suspending', 'inactive' ) );
		if ( is_wp_error( $lifecycle ) ) { throw new \RuntimeException( $lifecycle->get_error_message() ); }
		$current = $lifecycle;
		$failure = null;
		$worker_owned = false;
		$worker_released = false;
		$role_released = false;
		try {
			$worker = self::begin_worker_execution_fence( false, true );
			if ( is_wp_error( $worker ) ) { throw new \RuntimeException( $worker->get_error_message() ); }
			$worker_owned = true;
			if ( ! self::create_lifecycle_entrant_permit( 'activation_recovery', $current, 'activation' ) ) { throw new \RuntimeException( 'Campaign activation entrant ownership could not be authenticated.' ); }
			$current = self::resume_schedules_fenced( $current );
			if ( is_wp_error( $current ) ) { throw new \RuntimeException( $current->get_error_message() ); }
		} catch ( \Throwable $error ) {
			$failure = $error;
		} finally {
			self::$lifecycle_entrant_permit = null;
			$worker_released = ! $worker_owned || self::end_worker_execution_fence();
			$role_released = self::end_lifecycle_role_fence();
		}
		if ( ! $worker_released || ! $role_released ) { throw new \RuntimeException( 'Campaign resume fence release could not be proven.' ); }
		if ( $failure ) { throw $failure; }
		return true;
	}

	private static function resume_schedules_fenced( $current ) {
		if ( ! self::$worker_execution_fence_owned || ! self::$lifecycle_role_lock_owned || ! is_array( $current ) ) { return new WP_Error( 'complete99_campaign_lifecycle_resume_order', 'Campaign resume requires exact lifecycle and worker ownership.', array( 'status' => 503 ) ); }
		if ( hash_equals( 'suspending', (string) $current['state'] ) ) {
			$current = self::suspend_schedules_fenced( $current );
			if ( is_wp_error( $current ) ) { return $current; }
		}
		if ( hash_equals( 'active', (string) ( $current['state'] ?? '' ) ) ) { return $current; }
		if ( ! hash_equals( 'inactive', (string) ( $current['state'] ?? '' ) ) ) { return new WP_Error( 'complete99_campaign_lifecycle_resume_state', 'Campaign lifecycle cannot resume from malformed state.', array( 'status' => 503 ) ); }
		$requirement = self::lifecycle_prior_inactive_receipt_requirement( 'inactive', (int) $current['generation'] );
		if ( is_wp_error( $requirement ) ) { return $requirement; }
		$final = self::stored_lifecycle_receipt( (int) $requirement['receiptGeneration'], 'inactive', false );
		if ( is_wp_error( $final ) ) { return $final; }
		if ( (int) ( $final['inactiveGeneration'] ?? 0 ) !== (int) $requirement['inactiveGeneration'] ) { return new WP_Error( 'complete99_campaign_lifecycle_resume_receipt_stale', 'Campaign lifecycle inactive receipt is stale.', array( 'status' => 503 ) ); }
		$urls = self::lifecycle_public_absence_urls();
		$verified_at = gmdate( 'Y-m-d\TH:i:s\Z' );
		$absence = is_wp_error( $urls ) ? $urls : self::prove_public_quarantine_absence( $urls, $verified_at );
		if ( is_wp_error( $absence ) ) { return $absence; }
		$queued = self::enqueue_reconcile_trigger( time() + self::SYSTEM_CRON_INTERVAL_SECONDS );
		if ( is_wp_error( $queued ) ) { return $queued; }
		$current = self::transition_lifecycle_reservation_locked( $current, 'active' );
		return is_wp_error( $current ) ? $current : $current;
	}

	/** Prevent public slot HTML from becoming a durable full-page cache artifact. */
	public static function enforce_public_slot_no_cache() {
		if ( is_admin() || ( ! is_front_page() && ! ( function_exists( 'is_shop' ) && is_shop() ) ) ) { return; }
		if ( ! defined( 'DONOTCACHEPAGE' ) ) { define( 'DONOTCACHEPAGE', true ); }
		nocache_headers();
		if ( ! headers_sent() ) {
			header( 'Cache-Control: no-store, no-cache, must-revalidate, max-age=0', true );
			header( 'X-LiteSpeed-Cache-Control: no-cache', true );
		}
		do_action( 'litespeed_control_set_nocache', 'Complete99 campaign slot' );
	}

	private static function purge_public_placement_caches_with_retry( $reason, $campaign_id = '' ) {
		$first = self::purge_public_placement_caches( $reason );
		$result = is_wp_error( $first ) ? self::purge_public_placement_caches( $reason ) : $first;
		if ( is_wp_error( $result ) ) {
			$stored = self::store_cache_retry( $reason, $campaign_id );
			return is_wp_error( $stored ) ? $stored : new WP_Error( 'complete99_campaign_cache_purge_failed', 'Campaign public cache invalidation failed and is queued for durable retry.', array( 'status' => 503, 'stored' => true, 'owner' => 'Complete99_Campaigns' ) );
		}
		$cleared = self::clear_cache_retry_record();
		return is_wp_error( $cleared ) ? $cleared : true;
	}

	/** Purge every known page/object cache boundary used by the owned home/store slots. */
	private static function purge_public_placement_caches( $reason ) {
		$urls = array( home_url( '/' ) );
		$page_ids = array( (int) get_option( 'page_on_front', 0 ) );
		if ( function_exists( 'wc_get_page_id' ) ) {
			$shop_id = (int) wc_get_page_id( 'shop' );
			if ( 0 < $shop_id ) {
				$page_ids[] = $shop_id;
				$shop_url = get_permalink( $shop_id );
				if ( is_string( $shop_url ) && '' !== $shop_url ) { $urls[] = $shop_url; }
			}
		}
		try {
			foreach ( array_unique( array_filter( $page_ids ) ) as $page_id ) { clean_post_cache( (int) $page_id ); }
			foreach ( array_unique( $urls ) as $url ) { do_action( 'litespeed_purge_url', $url ); }
			return true;
		} catch ( \Throwable $error ) {
			return new WP_Error( 'complete99_campaign_cache_purge_failed', 'Campaign public cache invalidation failed.', array( 'status' => 503 ) );
		}
	}

	private static function cache_retry_record() {
		$value = get_option( self::OPTION_CACHE_ERROR, false );
		if ( false === $value || null === $value || '' === $value ) { return null; }
		$valid = is_array( $value )
			&& 'complete99-campaign-cache-retry/v2' === ( $value['schemaVersion'] ?? '' )
			&& 'Complete99_Campaigns' === ( $value['owner'] ?? '' )
			&& preg_match( '/\A[a-z0-9_-]{1,64}\z/', (string) ( $value['reason'] ?? '' ) )
			&& ( '' === (string) ( $value['campaignId'] ?? '' ) || preg_match( '/\A[a-z0-9_-]{8,64}\z/', (string) $value['campaignId'] ) )
			&& array( 'home_banner', 'store_banner' ) === array_values( (array) ( $value['surfaces'] ?? array() ) )
			&& is_int( $value['attempts'] ?? null ) && 0 < $value['attempts'] && self::CACHE_RETRY_MAX_ATTEMPTS >= $value['attempts']
			&& false !== strtotime( (string) ( $value['recordedAt'] ?? '' ) )
			&& false !== strtotime( (string) ( $value['nextAttemptAt'] ?? '' ) );
		if ( ! $valid ) {
			return array( 'schemaVersion' => 'complete99-campaign-cache-retry/corrupt', 'owner' => 'Complete99_Campaigns', 'reason' => 'cache_retry_record_corrupt', 'campaignId' => '', 'surfaces' => array( 'home_banner', 'store_banner' ), 'attempts' => self::CACHE_RETRY_MAX_ATTEMPTS, 'recordedAt' => '', 'nextAttemptAt' => gmdate( 'Y-m-d\TH:i:s\Z' ) );
		}
		return $value;
	}

	private static function public_cache_retry_status( $record ) {
		return array( 'owner' => 'Complete99_Campaigns', 'reason' => sanitize_key( (string) ( $record['reason'] ?? 'cache_retry_record_corrupt' ) ), 'campaignId' => (string) ( $record['campaignId'] ?? '' ), 'surfaces' => array( 'home_banner', 'store_banner' ), 'attempts' => (int) ( $record['attempts'] ?? 0 ), 'nextAttemptAt' => (string) ( $record['nextAttemptAt'] ?? '' ) );
	}

	private static function store_cache_retry( $reason, $campaign_id ) {
		$prior = self::cache_retry_record();
		$attempts = min( self::CACHE_RETRY_MAX_ATTEMPTS, (int) ( is_array( $prior ) ? ( $prior['attempts'] ?? 0 ) : 0 ) + 1 );
		$record = array(
			'schemaVersion' => 'complete99-campaign-cache-retry/v2',
			'owner' => 'Complete99_Campaigns',
			'reason' => sanitize_key( (string) $reason ),
			'campaignId' => preg_match( '/\A[a-z0-9_-]{8,64}\z/', (string) $campaign_id ) ? (string) $campaign_id : '',
			'surfaces' => array( 'home_banner', 'store_banner' ),
			'attempts' => $attempts,
			'recordedAt' => gmdate( 'Y-m-d\TH:i:s\Z' ),
			'nextAttemptAt' => gmdate( 'Y-m-d\TH:i:s\Z', time() + min( 3600, 30 * ( 2 ** min( 6, $attempts ) ) ) ),
		);
		update_option( self::OPTION_CACHE_ERROR, $record, false );
		$readback = self::cache_retry_record();
		if ( ! is_array( $readback ) || ! hash_equals( hash( 'sha256', self::canonical_json( $record ) ), hash( 'sha256', self::canonical_json( $readback ) ) ) ) {
			return new WP_Error( 'complete99_campaign_cache_retry_store_failed', 'Campaign cache retry truth could not be stored exactly.', array( 'status' => 503 ) );
		}
		$queued = self::enqueue_reconcile_trigger( strtotime( $record['nextAttemptAt'] ) );
		return is_wp_error( $queued ) ? $queued : true;
	}

	private static function clear_cache_retry_record() {
		$value = get_option( self::OPTION_CACHE_ERROR, false );
		if ( false !== $value ) { delete_option( self::OPTION_CACHE_ERROR ); }
		return false === get_option( self::OPTION_CACHE_ERROR, false )
			? true
			: new WP_Error( 'complete99_campaign_cache_retry_clear_failed', 'Resolved campaign cache retry truth could not be cleared.', array( 'status' => 503 ) );
	}

	private static function reconcile_cache_retry() {
		$record = self::cache_retry_record();
		if ( null === $record ) { return true; }
		$due = strtotime( (string) ( $record['nextAttemptAt'] ?? '' ) );
		if ( false !== $due && $due > time() ) { return true; }
		return self::purge_public_placement_caches_with_retry( (string) ( $record['reason'] ?? 'cache_retry' ), (string) ( $record['campaignId'] ?? '' ) );
	}

	public static function enqueue_public_assets() {
		if ( is_admin() || ( ! is_front_page() && ! ( function_exists( 'is_shop' ) && is_shop() ) ) ) { return; }
		wp_enqueue_style( 'complete99-campaign-placement', COMPLETE99_PLATFORM_URL . 'assets/css/campaign-placement.css', array(), COMPLETE99_PLATFORM_VERSION );
		wp_enqueue_script( 'complete99-campaign-placement', COMPLETE99_PLATFORM_URL . 'assets/js/campaign-placement.js', array(), COMPLETE99_PLATFORM_VERSION, true );
	}

