	/** Cron activation is a stale-safe derived trigger; database truth remains authoritative. */
	private static function owned_placement_id( $campaign_id, $schedule_digest, $activation_generation ) {
		if ( ! is_int( $activation_generation ) || 0 > $activation_generation || self::ACTIVATION_GENERATION_MAX < $activation_generation ) { return ''; }
		return 'plc_' . substr( hash( 'sha256', (string) $campaign_id . '|' . (string) $schedule_digest . '|generation:' . $activation_generation ), 0, 48 );
	}

	private static function owned_placement_token( $placement_id, $package_digest, $schedule_digest, $activation_generation ) {
		if ( ! preg_match( '/\Aplc_[a-f0-9]{48}\z/', (string) $placement_id ) || ! is_int( $activation_generation ) || 0 > $activation_generation || self::ACTIVATION_GENERATION_MAX < $activation_generation ) { return ''; }
		return hash_hmac( 'sha256', (string) $placement_id . '|' . (string) $package_digest . '|' . (string) $schedule_digest . '|generation:' . $activation_generation, wp_salt( 'auth' ) );
	}

	/** One stale-safe eligibility contract shared by every lifecycle callback. */
	private static function campaign_callback_eligible( $kind, $loaded, $campaign_id, $scheduled_version, $schedule_digest ) {
		if ( ! in_array( (string) $kind, array( 'activate', 'verify', 'expire' ), true ) || ! is_array( $loaded['state'] ?? null ) ) { return false; }
		$state = $loaded['state'];
		$runtime = (array) ( $state['runtime'] ?? array() );
		if ( ! hash_equals( (string) $campaign_id, (string) ( $state['campaignId'] ?? '' ) ) || (int) $scheduled_version !== (int) ( $runtime['scheduledVersion'] ?? 0 ) || ! preg_match( '/\A[a-f0-9]{64}\z/', (string) $schedule_digest ) || ! hash_equals( (string) $schedule_digest, (string) ( $runtime['scheduleDigest'] ?? '' ) ) ) { return false; }
		$lifecycle = (string) ( $runtime['lifecycleState'] ?? '' );
		$job = (string) ( $runtime['jobState'] ?? '' );
		$external = (string) ( $runtime['externalState'] ?? '' );
		$authority_clear = empty( $runtime['authoritySuppression'] ?? array() );
		if ( 'activate' === $kind ) {
			return 'schedule_requested' === $lifecycle && 'unverified' === $external && $authority_clear && in_array( $job, array( 'reconcile_pending', 'scheduled', 'retry_pending' ), true );
		}
		if ( 'verify' === $kind ) {
			return 'schedule_requested' === $lifecycle && 'unverified' === $external && $authority_clear && in_array( $job, array( 'readback_pending', 'retry_pending' ), true );
		}
		$jobs = 'schedule_requested' === $lifecycle ? array( 'reconcile_pending', 'scheduled', 'readback_pending', 'retry_pending', 'expiry_retry_pending' ) : ( 'active' === $lifecycle ? array( 'readback_verified', 'retry_pending', 'expiry_retry_pending' ) : array() );
		return $authority_clear && in_array( $external, array( 'unverified', 'owned_pending', 'owned_active' ), true ) && in_array( $job, $jobs, true );
	}

	public static function cron_activate( $campaign_id, $scheduled_version, $schedule_digest ) {
		return self::run_lifecycle_worker_operation( 'activate', static function () use ( $campaign_id, $scheduled_version, $schedule_digest ) { return self::cron_activate_fenced( $campaign_id, $scheduled_version, $schedule_digest ); } );
	}

	private static function cron_activate_fenced( $campaign_id, $scheduled_version, $schedule_digest ) {
		$quarantine_preflight = self::assert_public_quarantine_clear( false );
		if ( is_wp_error( $quarantine_preflight ) ) { self::enqueue_reconcile_trigger( time() + 1 ); return $quarantine_preflight; }
		$loaded = self::load_campaign( (string) $campaign_id );
		if ( is_wp_error( $loaded ) ) {
			return $loaded;
		}
		$effective = self::effective_campaign_state( $loaded );
		if ( is_wp_error( $effective ) ) { return $effective; }
		if ( is_array( $effective['overlay'] ?? null ) ) { return true; }
		$state = $loaded['state'];
		if ( ! self::campaign_callback_eligible( 'activate', $loaded, $campaign_id, $scheduled_version, $schedule_digest ) ) { return true; }
		$args = array( (string) $campaign_id, (int) $scheduled_version, (string) $schedule_digest );
		$activation_at = (int) ( $state['runtime']['activationTimestamp'] ?? 0 );
		if ( $activation_at > time() ) {
			$fence = self::begin_campaign_cron_mutation_fence();
			if ( is_wp_error( $fence ) ) { return self::activation_fault( $loaded, $fence->get_error_code(), $fence->get_error_message() ); }
			$requeued = true;
			$released = false;
			try {
				$current = self::load_campaign( (string) $campaign_id );
				$current_effective = is_wp_error( $current ) ? $current : self::effective_campaign_state( $current );
				$current_state = is_wp_error( $current_effective ) ? array() : $current['state'];
				if ( is_wp_error( $current ) || is_wp_error( $current_effective ) ) { $requeued = is_wp_error( $current ) ? $current : $current_effective; }
				elseif ( is_array( $current_effective['overlay'] ?? null ) || ! self::campaign_schedule_snapshot_matches( $loaded, $current )
					|| ! self::campaign_callback_eligible( 'activate', $current, $campaign_id, $scheduled_version, $schedule_digest )
					|| (int) ( $current_state['runtime']['activationTimestamp'] ?? 0 ) <= time() ) { $requeued = true; }
				else { $requeued = self::ensure_exact_campaign_event_locked( 'complete99_campaign_activate', (int) $current_state['runtime']['activationTimestamp'], $args, 'activation_early' ); }
			} finally {
				$released = self::end_campaign_cron_mutation_fence( $fence );
			}
			if ( ! $released ) { return new WP_Error( 'complete99_campaign_activation_early_lock_release_unknown', 'Campaign activation early-event fence ownership became uncertain.', array( 'status' => 503, 'retryStored' => true, 'stored' => 'pre' ) ); }
			if ( is_wp_error( $requeued ) ) { return self::activation_fault( $loaded, $requeued->get_error_code(), $requeued->get_error_message() ); }
			return true;
		}
		$authority = self::authority_snapshot_is_current( $state );
		$heartbeat = self::cron_heartbeat_status();
		if ( empty( $heartbeat['ready'] ) ) {
			return self::activation_fault( $loaded, 'campaign_cron_watchdog_stale', 'Campaign activation requires a recently completed protected cron retention pass.', 'authority_retry_pending' );
		}
		if ( 0 !== (int) ( $state['locationId'] ?? -1 ) || ! user_can( (int) ( $state['runtime']['approvedBy'] ?? 0 ), 'manage_options' ) || is_wp_error( $authority ) ) {
			return self::activation_fault( $loaded, is_wp_error( $authority ) ? $authority->get_error_code() : 'global_website_owner_revoked', 'Campaign activation authority is unavailable.', 'authority_retry_pending' );
		}
		if ( (int) ( $state['runtime']['expiryTimestamp'] ?? 0 ) <= time() ) { self::cron_expire_fenced( $campaign_id, $scheduled_version, $schedule_digest ); return true; }
		global $wpdb;
		$tables = self::table_names();
		$wpdb->last_error = '';
		$package = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$tables['prepared_packages']} WHERE package_id=%s AND campaign_id=%s AND campaign_version=%d AND channel='website' AND package_digest=%s AND approval_snapshot_digest=%s AND status='prepared' LIMIT 1", $state['runtime']['scheduledPackageId'], $campaign_id, (int) $scheduled_version, $state['runtime']['scheduledPackageDigest'], $state['runtime']['scheduledApprovalDigest'] ), ARRAY_A );
		if ( '' !== (string) $wpdb->last_error ) { return self::activation_fault( $loaded, 'activation_package_query_failed', 'The prepared package could not be read.' ); }
		if ( ! is_array( $package ) || ! hash_equals( $schedule_digest, hash( 'sha256', $state['runtime']['scheduledApprovalDigest'] . '|' . $package['package_id'] . '|' . $package['package_digest'] ) ) ) {
			return self::activation_fault( $loaded, 'activation_package_binding_invalid', 'The scheduled prepared package is missing or no longer matches durable schedule truth.' );
		}
		$decoded = json_decode( (string) $package['package_json'], true );
		$unsigned = is_array( $decoded ) ? $decoded : array();
		unset( $unsigned['sha256'] );
		if ( ! is_array( $decoded ) || ! hash_equals( (string) $package['package_digest'], (string) ( $decoded['sha256'] ?? '' ) )
			|| ! hash_equals( (string) $package['package_digest'], hash( 'sha256', self::canonical_json( $unsigned ) ) )
			|| (int) ( $package['campaign_version'] ?? 0 ) !== (int) $scheduled_version
			|| (int) ( $decoded['approvalSnapshot']['campaignVersion'] ?? 0 ) !== (int) $scheduled_version
			|| ! hash_equals( (string) $state['runtime']['scheduledApprovalDigest'], (string) ( $decoded['approvalSnapshot']['sha256'] ?? '' ) ) ) {
			return self::activation_fault( $loaded, 'activation_package_corrupt', 'The scheduled prepared package failed exact JSON, hash, or approval verification.' );
		}
		$activation_generation = $state['runtime']['activationGeneration'] ?? null;
		$placement_id = self::owned_placement_id( $campaign_id, $schedule_digest, $activation_generation );
		$token = self::owned_placement_token( $placement_id, (string) $package['package_digest'], $schedule_digest, $activation_generation );
		if ( '' === $placement_id || '' === $token ) { return self::activation_fault( $loaded, 'activation_generation_invalid', 'The activation generation is missing or invalid.' ); }
		$event_endpoint = rest_url( self::REST_NAMESPACE . '/campaign-events/' . $token );
		if ( ! self::is_first_party_url( $event_endpoint ) ) { return self::activation_fault( $loaded, 'placement_event_endpoint_invalid', 'The owned event endpoint is not on the exact WordPress origin.' ); }
		$proof_url = self::placement_public_url( (string) $state['governance']['slotKey'] );
		if ( is_wp_error( $proof_url ) ) { return self::activation_fault( $loaded, 'placement_proof_url_invalid', 'The owned proof URL is unavailable.' ); }
		$public = $decoded['payload'];
		$public['eventEndpoint'] = $event_endpoint;
		$public['proofUrl'] = $proof_url;
		$public_json = self::canonical_json( $public );
		$public_digest = hash( 'sha256', $public_json );
		$transaction = self::begin_transaction( self::CAPACITY_ROLE_ORDINARY );
		if ( is_wp_error( $transaction ) ) { return self::activation_fault( $loaded, 'activation_transaction_failed', $transaction->get_error_message() ); }
		$quarantine = self::assert_public_quarantine_clear( true );
		if ( is_wp_error( $quarantine ) ) { self::rollback_transaction(); return self::activation_fault( $loaded, 'activation_public_quarantine', $quarantine->get_error_message(), 'authority_retry_pending' ); }
		$current = self::load_campaign( (string) $campaign_id, true );
		$locked_state = is_wp_error( $current ) ? array() : $current['state'];
		$locked_authority = is_wp_error( $current ) ? $current : self::authority_snapshot_is_current( $locked_state );
		$locked_heartbeat = self::cron_heartbeat_status();
		if ( is_wp_error( $current )
			|| ! self::campaign_callback_eligible( 'activate', $current, $campaign_id, $scheduled_version, $schedule_digest )
			|| (int) ( $locked_state['runtime']['activationGeneration'] ?? -1 ) !== (int) $activation_generation
			|| ! hash_equals( (string) ( $locked_state['runtime']['scheduledPackageId'] ?? '' ), (string) $package['package_id'] )
			|| ! hash_equals( (string) ( $locked_state['runtime']['scheduledPackageDigest'] ?? '' ), (string) $package['package_digest'] )
			|| ! hash_equals( (string) ( $locked_state['runtime']['scheduledApprovalDigest'] ?? '' ), (string) $package['approval_snapshot_digest'] )
			|| ! hash_equals( (string) $schedule_digest, hash( 'sha256', (string) ( $locked_state['runtime']['scheduledApprovalDigest'] ?? '' ) . '|' . $package['package_id'] . '|' . $package['package_digest'] ) )
			|| 0 !== (int) ( $locked_state['locationId'] ?? -1 )
			|| ! user_can( (int) ( $locked_state['runtime']['approvedBy'] ?? 0 ), 'manage_options' )
			|| is_wp_error( $locked_authority )
			|| empty( $locked_heartbeat['ready'] )
			|| (int) ( $locked_state['runtime']['activationTimestamp'] ?? 0 ) > time()
			|| (int) ( $locked_state['runtime']['expiryTimestamp'] ?? 0 ) <= time() ) {
			self::rollback_transaction();
			if ( is_wp_error( $current ) ) {
				return self::activation_fault( $loaded, 'activation_locked_campaign_unavailable', 'Locked campaign truth could not be reloaded during activation.' );
			}
			if ( ! self::campaign_callback_eligible( 'activate', $current, $campaign_id, $scheduled_version, $schedule_digest ) ) {
				return true;
			}
			if ( empty( $locked_heartbeat['ready'] ) ) {
				return self::activation_fault( $current, 'campaign_cron_watchdog_stale', 'Locked campaign activation found a stale protected cron watchdog.', 'authority_retry_pending' );
			}
			return self::activation_fault( $current, 'activation_locked_binding_drift', 'Locked campaign, package, authority, or schedule truth changed during activation.' );
		}
		$loaded = $current;
		$state = $locked_state;
		$cleanup_inputs = self::capture_cleanup_inputs( $current );
		if ( is_wp_error( $cleanup_inputs ) ) { self::rollback_transaction(); return self::activation_fault( $loaded, $cleanup_inputs->get_error_code(), $cleanup_inputs->get_error_message() ); }
		$cleanup_inputs['cronActions'] = array_values( array_filter( $cleanup_inputs['cronActions'], static function ( $cron ) { return 'complete99_campaign_verify_readback' === (string) ( $cron['hook'] ?? '' ); } ) );
		$slot_lock = self::lock_owned_slot_window( $campaign_id, (string) $state['governance']['slotKey'], (int) $state['runtime']['activationTimestamp'], (int) $state['runtime']['expiryTimestamp'] );
		if ( is_wp_error( $slot_lock ) ) { self::rollback_transaction(); return self::activation_fault( $loaded, $slot_lock->get_error_code(), $slot_lock->get_error_message() ); }
		$superseded = self::supersede_owned_slot_placements( $campaign_id, (string) $state['governance']['slotKey'], (string) $schedule_digest );
		if ( is_wp_error( $superseded ) ) { self::rollback_transaction(); return self::activation_fault( $loaded, $superseded->get_error_code(), $superseded->get_error_message() ); }
		$existing = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$tables['placements']} WHERE placement_id = %s LIMIT 1", $placement_id ), ARRAY_A );
		if ( ! is_array( $existing ) ) {
			$allocator_floor = self::public_quarantine_gc_allocator_floor();
			if ( is_wp_error( $allocator_floor ) ) { self::rollback_transaction(); return self::activation_fault( $loaded, $allocator_floor->get_error_code(), $allocator_floor->get_error_message() ); }
			if ( 1 !== $wpdb->insert( $tables['placements'], array( 'placement_id' => $placement_id, 'campaign_id' => $campaign_id, 'campaign_version' => $scheduled_version, 'package_digest' => $package['package_digest'], 'slot_key' => $state['governance']['slotKey'], 'locale' => 'bilingual', 'public_json' => $public_json, 'public_digest' => $public_digest, 'readback_token' => $token, 'status' => 'pending_readback', 'starts_at' => gmdate( 'Y-m-d H:i:s', (int) $state['runtime']['activationTimestamp'] ), 'expires_at' => gmdate( 'Y-m-d H:i:s', (int) $state['runtime']['expiryTimestamp'] ), 'activated_at' => null, 'stopped_at' => null, 'created_at' => current_time( 'mysql', true ), 'updated_at' => current_time( 'mysql', true ) ) ) ) {
				self::rollback_transaction(); return self::activation_fault( $loaded, 'placement_insert_failed', 'The owned placement row could not be created.' );
			}
			$inserted_id = (int) $wpdb->insert_id;
			if ( $inserted_id <= (int) $allocator_floor ) { self::rollback_transaction(); return self::activation_fault( $loaded, 'placement_allocator_regressed', 'The owned placement allocator reused an immutable terminal row identity.' ); }
		} elseif ( ! hash_equals( (string) $existing['package_digest'], (string) $package['package_digest'] )
			|| ! hash_equals( (string) $existing['public_digest'], $public_digest )
			|| ! hash_equals( (string) $existing['readback_token'], $token ) ) {
			self::rollback_transaction(); return self::activation_fault( $loaded, 'placement_identity_mismatch', 'An existing placement identity conflicts with the scheduled package.' );
		} elseif ( 'stopped' === (string) $existing['status']
			&& 1 !== $wpdb->update( $tables['placements'], array( 'status' => 'pending_readback', 'stopped_at' => null, 'updated_at' => current_time( 'mysql', true ) ), array( 'id' => (int) $existing['id'], 'status' => (string) $existing['status'] ) ) ) {
			self::rollback_transaction(); return self::activation_fault( $loaded, 'placement_restore_failed', 'The owned placement could not be restored.' );
		} elseif ( 'suppressed_authority' === (string) $existing['status'] ) {
			self::rollback_transaction(); return true;
		} elseif ( ! in_array( (string) $existing['status'], array( 'pending_readback', 'active', 'stopped' ), true ) ) {
			self::rollback_transaction(); return self::activation_fault( $loaded, 'placement_state_invalid', 'The owned placement state is invalid.' );
		}
		$next = $current['state'];
		$next['runtime']['jobState'] = 'readback_pending';
		$next['runtime']['nextAttemptAt'] = gmdate( 'Y-m-d\TH:i:s\Z', time() + 30 );
		$next['runtime']['lastErrorCode'] = '';
		$saved = self::save_campaign( $current, $next, 'owned_placement_pending_readback', 0 );
		if ( is_wp_error( $saved ) ) { self::rollback_transaction(); return self::activation_fault( $loaded, 'activation_state_failed', 'Activation state could not be stored.' ); }
		$verify_at = time() + 1;
		$verify_args = array( (string) $campaign_id, (int) $scheduled_version, (string) $schedule_digest );
		$public_url = self::placement_public_url( (string) $state['governance']['slotKey'] );
		if ( is_wp_error( $public_url ) ) { self::rollback_transaction(); return self::activation_fault( $saved, $public_url->get_error_code(), $public_url->get_error_message() ); }
		$cleanup_inputs['surfaces'][] = array( 'slot' => (string) $state['governance']['slotKey'], 'url' => $public_url, 'placementId' => $placement_id, 'publicDigest' => $public_digest );
		$cleanup = self::append_cleanup_obligation( $saved, 'activation', (string) $schedule_digest . '|generation:' . (int) $activation_generation, $cleanup_inputs, 'absent', array( array( 'hook' => 'complete99_campaign_verify_readback', 'args' => $verify_args, 'timestamp' => $verify_at, 'action' => 'ensure' ) ) );
		if ( is_wp_error( $cleanup ) ) { self::rollback_transaction(); return self::activation_fault( $saved, $cleanup->get_error_code(), $cleanup->get_error_message() ); }
		$wpdb->last_error = '';
		$post_placement = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$tables['placements']} WHERE placement_id=%s LIMIT 1", $placement_id ), ARRAY_A );
		if ( '' !== (string) $wpdb->last_error || ! is_array( $post_placement ) ) { self::rollback_transaction(); return self::activation_fault( $saved, 'activation_postcondition_failed', 'Activation placement postcondition could not be read exactly.' ); }
		$commit = self::commit_transaction();
		self::enqueue_reconcile_trigger( time() + 1 );
		if ( is_wp_error( $commit ) ) { return self::activation_commit_error( $commit, $campaign_id, $current, $cleanup, $placement_id, $existing, $post_placement ); }
		return true;
	}

	/** Retain the shared lifecycle fence across a WordPress cron option mutation. */
	private static function begin_campaign_cron_mutation_fence() {
		if ( self::$transaction_active ) {
			$clear = self::assert_public_quarantine_clear( true );
			return is_wp_error( $clear ) ? $clear : array( 'owns' => false );
		}
		$started = self::begin_public_read_transaction();
		if ( is_wp_error( $started ) ) { return $started; }
		$clear = self::assert_public_quarantine_clear( true );
		if ( is_wp_error( $clear ) ) { self::rollback_transaction(); return $clear; }
		$committed = self::commit_public_read_transaction( true );
		return is_wp_error( $committed ) ? $committed : array( 'owns' => true );
	}

	private static function end_campaign_cron_mutation_fence( $fence ) {
		return empty( $fence['owns'] ) || self::release_advisory_locks();
	}

	/** Repair one exact three-argument campaign event and prove its persisted timestamp. */
	private static function ensure_exact_campaign_event( $hook, $timestamp, $args, $error_prefix ) {
		$timestamp = (int) $timestamp;
		if ( $timestamp <= time() || 3 !== count( $args ) ) {
			return new WP_Error( 'complete99_campaign_' . sanitize_key( $error_prefix ) . '_invalid', 'Campaign event identity or timestamp is invalid.' );
		}
		$fence = self::begin_campaign_cron_mutation_fence();
		if ( is_wp_error( $fence ) ) { return $fence; }
		$result = self::ensure_exact_campaign_event_locked( $hook, $timestamp, $args, $error_prefix );
		$released = self::end_campaign_cron_mutation_fence( $fence );
		return $released ? $result : new WP_Error( 'complete99_campaign_' . sanitize_key( $error_prefix ) . '_lock_release_unknown', 'Campaign event fence ownership became uncertain.', array( 'status' => 503 ) );
	}

	private static function ensure_exact_campaign_event_locked( $hook, $timestamp, $args, $error_prefix ) {
		$next = wp_next_scheduled( $hook, $args );
		if ( false !== $next && (int) $next !== $timestamp ) {
			$removed = wp_unschedule_event( (int) $next, $hook, $args, true );
			if ( is_wp_error( $removed ) || false === $removed || false !== wp_next_scheduled( $hook, $args ) ) {
				return new WP_Error( 'complete99_campaign_' . sanitize_key( $error_prefix ) . '_drift', 'A drifted campaign event could not be removed exactly.' );
			}
			$next = false;
		}
		if ( false === $next ) {
			$scheduled = wp_schedule_single_event( $timestamp, $hook, $args, true );
			if ( is_wp_error( $scheduled ) || false === $scheduled ) {
				return new WP_Error( 'complete99_campaign_' . sanitize_key( $error_prefix ) . '_enqueue', 'Campaign event could not be queued at its durable timestamp.' );
			}
		}
		if ( (int) wp_next_scheduled( $hook, $args ) !== $timestamp ) {
			return new WP_Error( 'complete99_campaign_' . sanitize_key( $error_prefix ) . '_readback', 'Campaign event timestamp readback did not match durable state.' );
		}
		return true;
	}

	private static function mark_schedule_retry( $loaded, $error_code, $job_state = 'retry_pending', $expected = null ) {
		if ( null === $expected || ! self::campaign_schedule_snapshot_matches( $expected, $loaded ) ) {
			return new WP_Error( 'complete99_campaign_retry_snapshot_required', 'A byte-exact campaign retry snapshot is required.', array( 'status' => 409, 'retryStored' => true, 'stored' => 'pre' ) );
		}
		$campaign_id = (string) ( $loaded['state']['campaignId'] ?? '' );
		$transaction = self::begin_transaction( self::CAPACITY_ROLE_RECOVERY );
		if ( is_wp_error( $transaction ) ) { return new WP_Error( $transaction->get_error_code(), $transaction->get_error_message(), array( 'status' => 503, 'retryStored' => true, 'stored' => 'pre' ) ); }
		$quarantine = self::assert_public_quarantine_clear( true );
		if ( is_wp_error( $quarantine ) ) {
			self::rollback_transaction();
			self::enqueue_reconcile_trigger( time() + 1 );
			return new WP_Error( $quarantine->get_error_code(), $quarantine->get_error_message(), array( 'status' => 503, 'retryStored' => true, 'stored' => 'pre' ) );
		}
		$current = self::load_campaign( $campaign_id, true );
		if ( is_wp_error( $current ) ) { self::rollback_transaction(); return new WP_Error( $current->get_error_code(), $current->get_error_message(), array( 'status' => 503, 'retryStored' => true, 'stored' => 'pre' ) ); }
		if ( ! self::campaign_schedule_snapshot_matches( $expected, $current ) || ! in_array( (string) ( $current['state']['runtime']['lifecycleState'] ?? '' ), array( 'schedule_requested', 'active' ), true ) ) { self::rollback_transaction(); return true; }
		$current_job = (string) ( $current['state']['runtime']['jobState'] ?? '' );
		$current_external = (string) ( $current['state']['runtime']['externalState'] ?? '' );
		$desired_job = in_array( $job_state, array( 'retry_pending', 'authority_retry_pending', 'expiry_retry_pending' ), true ) ? $job_state : 'retry_pending';
		if ( in_array( $current_job, array( 'operator_attention', 'expired', 'cancelled', 'readback_verified' ), true )
			|| ( 'authority_retry_pending' === $current_job && 'authority_retry_pending' !== $desired_job )
			|| ( 'suppressed' === $current_external && 'authority_retry_pending' !== $desired_job ) ) { self::rollback_transaction(); return true; }
		$next_attempts = min( self::SCHEDULE_MAX_ATTEMPTS, (int) ( $current['state']['runtime']['attempts'] ?? 0 ) + 1 );
		if ( self::SCHEDULE_MAX_ATTEMPTS <= $next_attempts ) {
			global $wpdb;
			$tables = self::table_names();
			$cleanup_inputs = self::capture_cleanup_inputs( $current );
			if ( is_wp_error( $cleanup_inputs ) ) { self::rollback_transaction(); return $cleanup_inputs; }
			$cleanup_inputs['cronActions'] = array_values( array_filter( $cleanup_inputs['cronActions'], static function ( $cron ) { return 'complete99_campaign_expire' !== (string) ( $cron['hook'] ?? '' ); } ) );
			$updated = $wpdb->query( $wpdb->prepare( "UPDATE {$tables['placements']} SET status='suppressed_readback',stopped_at=%s,updated_at=%s WHERE campaign_id=%s AND status='pending_readback'", current_time( 'mysql', true ), current_time( 'mysql', true ), (string) $current['state']['campaignId'] ) );
			$remaining = $wpdb->get_var( $wpdb->prepare( "SELECT COUNT(*) FROM {$tables['placements']} WHERE campaign_id=%s AND status='pending_readback'", (string) $current['state']['campaignId'] ) );
			if ( false === $updated || ! is_numeric( $remaining ) || 0 !== (int) $remaining ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_readback_suppression_failed', 'Terminal readback failure could not suppress every pending placement.', array( 'status' => 503 ) ); }
			$state = $current['state'];
			$state['runtime']['lastErrorCode'] = sanitize_key( $error_code );
			$state['runtime']['attempts'] = self::SCHEDULE_MAX_ATTEMPTS;
			$state['runtime']['jobState'] = 'operator_attention';
			$state['runtime']['externalState'] = 'suppressed';
			$state['runtime']['nextAttemptAt'] = '';
			$saved = self::save_campaign( $current, $state, 'owned_readback_terminal_suppressed', 0, self::CAPACITY_ROLE_RECOVERY );
			if ( is_wp_error( $saved ) ) { self::rollback_transaction(); return $saved; }
			$cleanup = self::append_cleanup_obligation( $saved, 'readback_terminal_suppression', (string) ( $state['runtime']['scheduleDigest'] ?? '' ) . '|generation:' . (int) ( $state['runtime']['activationGeneration'] ?? 0 ) . '|readback-terminal', $cleanup_inputs, 'absent' );
			if ( is_wp_error( $cleanup ) ) { self::rollback_transaction(); return $cleanup; }
			$commit = self::commit_transaction();
			self::enqueue_reconcile_trigger( time() + 1 );
			if ( is_wp_error( $commit ) ) {
				$stored = self::classify_campaign_commit( $campaign_id, $current, $cleanup );
				return new WP_Error( 'complete99_campaign_readback_suppression_outcome_unknown', 'Terminal readback suppression commit acknowledgement was ambiguous.', array( 'status' => 503, 'stored' => $stored, 'retryStored' => true, 'cause' => $commit->get_error_code() ) );
			}
			return true;
		}
		$state = $current['state'];
		$state['runtime']['lastErrorCode'] = sanitize_key( $error_code );
		$state['runtime']['attempts'] = $next_attempts;
		$state['runtime']['jobState'] = $desired_job;
		$state['runtime']['nextAttemptAt'] = gmdate( 'Y-m-d\TH:i:s\Z', time() + min( 3600, 30 * ( 2 ** min( 6, $state['runtime']['attempts'] ) ) ) );
		$saved = self::save_campaign( $current, $state, 'owned_readback_retry', 0, self::CAPACITY_ROLE_RECOVERY );
		if ( is_wp_error( $saved ) ) { self::rollback_transaction(); return $saved; }
		$commit = self::commit_transaction();
		if ( is_wp_error( $commit ) ) {
			$stored = self::classify_campaign_commit( $campaign_id, $current, $saved );
			return new WP_Error( 'complete99_campaign_retry_commit_outcome_unknown', 'Campaign retry commit acknowledgement was ambiguous.', array( 'status' => 503, 'stored' => $stored, 'retryStored' => true, 'cause' => $commit->get_error_code() ) );
		}
		$queued = self::enqueue_reconcile_trigger( strtotime( $state['runtime']['nextAttemptAt'] ) );
		if ( is_wp_error( $queued ) ) { return new WP_Error( $queued->get_error_code(), $queued->get_error_message(), array( 'status' => 503, 'stored' => 'post', 'retryStored' => true ) ); }
		return $saved;
	}

	private static function activation_fault( $loaded, $error_code, $message, $job_state = 'retry_pending' ) {
		$stored = self::mark_schedule_retry( $loaded, $error_code, $job_state, $loaded );
		if ( is_wp_error( $stored ) ) {
			$data = $stored->get_error_data();
			$data = is_array( $data ) ? $data : array( 'status' => 503 );
			$data['retryStored'] = true;
			$data['stored'] = in_array( (string) ( $data['stored'] ?? '' ), array( 'pre', 'post', 'mixed' ), true ) ? (string) $data['stored'] : 'pre';
			$data['desiredRetryState'] = in_array( $job_state, array( 'retry_pending', 'authority_retry_pending', 'expiry_retry_pending' ), true ) ? $job_state : 'retry_pending';
			self::enqueue_reconcile_trigger( time() + 1 );
			return new WP_Error( $stored->get_error_code(), $stored->get_error_message(), $data );
		}
		return new WP_Error( sanitize_key( $error_code ), (string) $message, array( 'retryStored' => true, 'status' => 503 ) );
	}

	private static function activation_commit_error( $commit, $campaign_id, $pre_campaign, $post_campaign, $placement_id, $pre_placement, $post_placement ) {
		$stored = self::classify_campaign_placement_commit( $campaign_id, $pre_campaign, $post_campaign, $placement_id, $pre_placement, $post_placement );
		self::enqueue_reconcile_trigger( time() + 1 );
		return new WP_Error( 'complete99_campaign_activation_commit_outcome_unknown', 'Activation commit acknowledgement was ambiguous; exact pre/post reconciliation was queued.', array( 'status' => 503, 'stored' => $stored, 'retryStored' => true, 'cause' => is_wp_error( $commit ) ? $commit->get_error_code() : 'commit_unknown' ) );
	}

	/**
	 * Reselect and lock the exact public placement, campaign and package binding.
	 * Caller must hold the shared public-read or writer transaction boundary.
	 */
	private static function locked_public_placement_context( $token, $allowed_statuses ) {
		global $wpdb;
		if ( ! self::$transaction_active ) { return new WP_Error( 'complete99_campaign_public_context_unlocked', 'Public placement truth requires a transaction.' ); }
		$quarantine = self::assert_public_quarantine_clear( true );
		if ( is_wp_error( $quarantine ) ) { return $quarantine; }
		$tables = self::table_names();
		$lock = self::is_sqlite_database() ? '' : ' FOR UPDATE';
		$wpdb->last_error = '';
		$row = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$tables['placements']} WHERE readback_token=%s LIMIT 1{$lock}", (string) $token ), ARRAY_A );
		$row_error = (string) $wpdb->last_error;
		/* A historical/superseded token is unavailable, never an instruction to suppress current truth. */
		if ( '' !== $row_error || ! is_array( $row ) || ! in_array( (string) ( $row['status'] ?? '' ), (array) $allowed_statuses, true ) ) {
			return new WP_Error( 'complete99_campaign_public_context_missing', 'Placement is unavailable.' );
		}
		$current = is_array( $row ) ? self::load_campaign( (string) $row['campaign_id'], true ) : new WP_Error( 'complete99_campaign_public_context_missing', 'Placement is unavailable.' );
		$state = is_wp_error( $current ) ? array() : $current['state'];
		$wpdb->last_error = '';
		$current_rows = ! is_wp_error( $current ) ? $wpdb->get_results(
			$wpdb->prepare(
				"SELECT id,placement_id,status FROM {$tables['placements']} WHERE campaign_id=%s AND campaign_version=%d AND package_digest=%s AND slot_key=%s AND status IN ('pending_readback','active') ORDER BY id ASC LIMIT 2{$lock}",
				(string) ( $state['campaignId'] ?? '' ),
				(int) ( $state['runtime']['scheduledVersion'] ?? 0 ),
				(string) ( $state['runtime']['scheduledPackageDigest'] ?? '' ),
				(string) ( $state['governance']['slotKey'] ?? '' )
			),
			ARRAY_A
		) : null;
		$current_rows_error = (string) $wpdb->last_error;
		$current_row_exact = '' === $current_rows_error && is_array( $current_rows ) && 1 === count( $current_rows ) && is_array( $row )
			&& (int) ( $current_rows[0]['id'] ?? 0 ) === (int) ( $row['id'] ?? -1 )
			&& hash_equals( (string) ( $current_rows[0]['placement_id'] ?? '' ), (string) ( $row['placement_id'] ?? '' ) )
			&& hash_equals( (string) ( $current_rows[0]['status'] ?? '' ), (string) ( $row['status'] ?? '' ) );
		$now_mysql = current_time( 'mysql', true );
		$wpdb->last_error = '';
		$slot_rows = ! is_wp_error( $current ) ? $wpdb->get_results(
			$wpdb->prepare(
				"SELECT id,placement_id,status FROM {$tables['placements']} WHERE slot_key=%s AND status IN ('pending_readback','active') AND starts_at<=%s AND expires_at>%s ORDER BY id ASC LIMIT 2{$lock}",
				(string) ( $state['governance']['slotKey'] ?? '' ),
				$now_mysql,
				$now_mysql
			),
			ARRAY_A
		) : null;
		$slot_rows_error = (string) $wpdb->last_error;
		$slot_row_exact = '' === $slot_rows_error && is_array( $slot_rows ) && 1 === count( $slot_rows ) && is_array( $row )
			&& (int) ( $slot_rows[0]['id'] ?? 0 ) === (int) ( $row['id'] ?? -1 )
			&& hash_equals( (string) ( $slot_rows[0]['placement_id'] ?? '' ), (string) ( $row['placement_id'] ?? '' ) )
			&& hash_equals( (string) ( $slot_rows[0]['status'] ?? '' ), (string) ( $row['status'] ?? '' ) );
		$wpdb->last_error = '';
		$package_rows = ! is_wp_error( $current ) ? $wpdb->get_results(
			$wpdb->prepare(
				"SELECT * FROM {$tables['prepared_packages']} WHERE package_id=%s AND campaign_id=%s AND campaign_version=%d AND channel='website' AND status='prepared' ORDER BY id ASC LIMIT 2{$lock}",
				(string) ( $state['runtime']['scheduledPackageId'] ?? '' ),
				(string) ( $state['campaignId'] ?? '' ),
				(int) ( $state['runtime']['scheduledVersion'] ?? 0 )
			),
			ARRAY_A
		) : null;
		$package_error = (string) $wpdb->last_error;
		$package = is_array( $package_rows ) && 1 === count( $package_rows ) ? $package_rows[0] : null;
		$starts_at = is_array( $row ) ? strtotime( (string) $row['starts_at'] . ' UTC' ) : false;
		$expires_at = is_array( $row ) ? strtotime( (string) $row['expires_at'] . ' UTC' ) : false;
		$public = is_array( $row ) ? json_decode( (string) $row['public_json'], true ) : null;
		$event_endpoint = is_array( $row ) ? rest_url( self::REST_NAMESPACE . '/campaign-events/' . (string) $row['readback_token'] ) : '';
		$schedule_digest = is_array( $package ) ? hash( 'sha256', (string) $package['approval_snapshot_digest'] . '|' . (string) $package['package_id'] . '|' . (string) $package['package_digest'] ) : '';
		$decoded_package = is_array( $package ) ? json_decode( (string) ( $package['package_json'] ?? '' ), true ) : null;
		$unsigned_package = is_array( $decoded_package ) ? $decoded_package : array();
		unset( $unsigned_package['sha256'] );
		$expected_public = is_array( $decoded_package['payload'] ?? null ) ? $decoded_package['payload'] : null;
		$proof_url = is_array( $row ) ? self::placement_public_url( (string) ( $row['slot_key'] ?? '' ) ) : new WP_Error( 'complete99_campaign_public_context_stale', 'Placement is unavailable.' );
		if ( is_array( $expected_public ) ) { $expected_public['eventEndpoint'] = $event_endpoint; $expected_public['proofUrl'] = is_wp_error( $proof_url ) ? '' : $proof_url; }
		$activation_generation = $state['runtime']['activationGeneration'] ?? null;
		$expected_placement_id = ! is_wp_error( $current ) ? self::owned_placement_id( (string) $state['campaignId'], $schedule_digest, $activation_generation ) : '';
		$expected_token = is_array( $package ) ? self::owned_placement_token( $expected_placement_id, (string) $package['package_digest'], $schedule_digest, $activation_generation ) : '';
		$status_state_coherent = is_array( $row ) && ( 'pending_readback' === (string) ( $row['status'] ?? '' )
			? 'schedule_requested' === (string) ( $state['runtime']['lifecycleState'] ?? '' )
				&& in_array( (string) ( $state['runtime']['jobState'] ?? '' ), array( 'readback_pending', 'retry_pending' ), true )
				&& 'unverified' === (string) ( $state['runtime']['externalState'] ?? '' )
			: 'active' === (string) ( $row['status'] ?? '' )
				&& 'active' === (string) ( $state['runtime']['lifecycleState'] ?? '' )
				&& 'readback_verified' === (string) ( $state['runtime']['jobState'] ?? '' )
				&& 'owned_active' === (string) ( $state['runtime']['externalState'] ?? '' ) );
		$coherent = '' === $row_error && $current_row_exact && $slot_row_exact && '' === $package_error && is_array( $row ) && ! is_wp_error( $current ) && is_array( $package ) && is_array( $public ) && is_array( $decoded_package ) && is_array( $expected_public )
			&& in_array( (string) $row['status'], (array) $allowed_statuses, true ) && $status_state_coherent;
		$coherent = $coherent && false !== $starts_at && false !== $expires_at && $starts_at <= time() && $expires_at > time()
			&& $starts_at === (int) ( $state['runtime']['activationTimestamp'] ?? 0 ) && $expires_at === (int) ( $state['runtime']['expiryTimestamp'] ?? 0 )
			&& in_array( (string) ( $state['runtime']['lifecycleState'] ?? '' ), array( 'schedule_requested', 'active' ), true ) && 'suspended' !== (string) ( $state['runtime']['jobState'] ?? '' )
			&& hash_equals( (string) $row['campaign_id'], (string) ( $state['campaignId'] ?? '' ) ) && (int) $row['campaign_version'] === (int) ( $state['runtime']['scheduledVersion'] ?? 0 )
			&& hash_equals( (string) $row['slot_key'], (string) ( $state['governance']['slotKey'] ?? '' ) ) && hash_equals( $expected_placement_id, (string) $row['placement_id'] ) && hash_equals( $expected_token, (string) $row['readback_token'] )
			&& hash_equals( (string) $row['package_digest'], (string) ( $state['runtime']['scheduledPackageDigest'] ?? '' ) ) && hash_equals( (string) $package['package_id'], (string) ( $state['runtime']['scheduledPackageId'] ?? '' ) )
			&& hash_equals( (string) $package['package_digest'], (string) $row['package_digest'] ) && hash_equals( (string) $package['approval_snapshot_digest'], (string) ( $state['runtime']['scheduledApprovalDigest'] ?? '' ) )
			&& hash_equals( $schedule_digest, (string) ( $state['runtime']['scheduleDigest'] ?? '' ) ) && hash_equals( (string) $package['package_json'], self::canonical_json( $decoded_package ) )
			&& hash_equals( (string) $package['package_digest'], (string) ( $decoded_package['sha256'] ?? '' ) ) && hash_equals( (string) $package['package_digest'], hash( 'sha256', self::canonical_json( $unsigned_package ) ) )
			&& hash_equals( (string) $package['package_id'], (string) ( $decoded_package['packageId'] ?? '' ) ) && hash_equals( (string) $state['campaignId'], (string) ( $decoded_package['campaignId'] ?? '' ) )
			&& 'website' === (string) ( $decoded_package['channel'] ?? '' ) && 'prepared' === (string) ( $decoded_package['status'] ?? '' ) && is_array( $decoded_package['blockers'] ?? null ) && empty( $decoded_package['blockers'] )
			&& array_key_exists( 'publicationClaim', $decoded_package ) && false === $decoded_package['publicationClaim'] && 'not_attempted' === (string) ( $decoded_package['providerAction'] ?? '' )
			&& (int) ( $decoded_package['approvalSnapshot']['campaignVersion'] ?? 0 ) === (int) ( $state['runtime']['scheduledVersion'] ?? 0 ) && hash_equals( (string) $package['approval_snapshot_digest'], (string) ( $decoded_package['approvalSnapshot']['sha256'] ?? '' ) )
			&& hash_equals( (string) $row['public_json'], self::canonical_json( $public ) ) && hash_equals( self::canonical_json( $expected_public ), (string) $row['public_json'] )
			&& hash_equals( (string) $row['public_digest'], hash( 'sha256', (string) $row['public_json'] ) ) && self::WEBSITE_CONSENT_BASIS === (string) ( $public['consentBasis'] ?? '' )
			&& self::WEBSITE_MEASUREMENT_MODE === (string) ( $public['measurementMode'] ?? '' ) && self::WEBSITE_MEASUREMENT_PURPOSE === (string) ( $public['measurementPurpose'] ?? '' )
			&& is_string( $public['eventEndpoint'] ?? null ) && hash_equals( $event_endpoint, (string) $public['eventEndpoint'] ) && self::is_first_party_url( $event_endpoint )
			&& ! is_wp_error( $proof_url ) && is_string( $public['proofUrl'] ?? null ) && hash_equals( $proof_url, (string) $public['proofUrl'] )
			&& is_string( $public['privacyUrl'] ?? null ) && self::is_first_party_url( $public['privacyUrl'] );
		if ( ! $coherent ) {
			return is_array( $row ) && ! is_wp_error( $current )
				? new WP_Error( 'complete99_campaign_public_coherence_stale', 'Placement package or public payload coherence is stale.', array( 'row' => $row, 'campaign' => $current, 'authorityCode' => 'campaign_public_coherence_stale', 'placementStatus' => (string) ( $row['status'] ?? '' ) ) )
				: new WP_Error( 'complete99_campaign_public_context_stale', 'Placement is unavailable.' );
		}
		$receipt_rows = self::system_readback_receipts( $row, true );
		$receipt_error = is_wp_error( $receipt_rows ) ? $receipt_rows->get_error_code() : '';
		$receipt = is_array( $receipt_rows ) && 1 === count( $receipt_rows ) ? $receipt_rows[0] : null;
		$receipt_coherent = 'active' === (string) $row['status']
			? '' === $receipt_error && is_array( $receipt_rows ) && 1 === count( $receipt_rows ) && ! is_wp_error( $proof_url ) && self::verified_readback_receipt_matches( $receipt, $row, $package, $proof_url )
			: '' === $receipt_error && is_array( $receipt_rows ) && empty( $receipt_rows );
		if ( ! $receipt_coherent ) { return new WP_Error( 'complete99_campaign_public_receipt_stale', 'Placement system receipt coherence is stale.', array( 'row' => $row, 'campaign' => $current, 'authorityCode' => 'campaign_public_receipt_stale', 'placementStatus' => (string) $row['status'] ) ); }
		$authority = self::authority_snapshot_is_current( $state );
		$heartbeat = self::cron_heartbeat_status();
		if ( is_wp_error( $authority ) ) {
			return new WP_Error( 'complete99_campaign_public_authority_stale', 'Placement authority is stale.', array( 'row' => $row, 'campaign' => $current, 'authorityCode' => $authority->get_error_code(), 'placementStatus' => (string) $row['status'] ) );
		}
		if ( empty( $heartbeat['ready'] ) ) {
			return new WP_Error( 'complete99_campaign_public_watchdog_stale', 'Placement watchdog truth is stale.', array( 'row' => $row, 'campaign' => $current, 'authorityCode' => 'campaign_cron_watchdog_stale', 'placementStatus' => (string) $row['status'] ) );
		}
		return array( 'row' => $row, 'campaign' => $current, 'package' => $package, 'receipt' => $receipt, 'public' => $public );
	}

	/** Convert an internal stale-authority context into durable public suppression. */
	private static function suppress_public_context_error( $error ) {
		if ( ! is_wp_error( $error ) || ! in_array( $error->get_error_code(), array( 'complete99_campaign_public_authority_stale', 'complete99_campaign_public_watchdog_stale', 'complete99_campaign_public_coherence_stale', 'complete99_campaign_public_receipt_stale' ), true ) ) { return false; }
		$data = $error->get_error_data();
		if ( ! is_array( $data ) || ! is_array( $data['row'] ?? null ) || ! is_array( $data['campaign'] ?? null ) ) { return false; }
		return ! is_wp_error( self::suppress_active_campaign_coherence( $data['campaign'], (string) ( $data['authorityCode'] ?? 'campaign_public_coherence_stale' ) ) );
	}

	public static function rest_public_readback( WP_REST_Request $request ) {
		$transaction = self::begin_public_read_transaction();
		if ( is_wp_error( $transaction ) ) { return new WP_Error( 'complete99_campaign_placement_unavailable', 'Campaign placement is temporarily unavailable.', array( 'status' => 503 ) ); }
		$context = self::locked_public_placement_context( (string) $request['token'], array( 'pending_readback', 'active' ) );
		if ( is_wp_error( $context ) ) { self::rollback_transaction(); self::suppress_public_context_error( $context ); return new WP_Error( 'complete99_campaign_placement_unavailable', 'Campaign placement is unavailable.', array( 'status' => 404 ) ); }
		$row = $context['row'];
		$public = $context['public'];
		$verified = 'active' === (string) $row['status'] && is_array( $context['receipt'] ?? null );
		$committed = self::commit_public_read_transaction();
		if ( is_wp_error( $committed ) ) { return new WP_Error( 'complete99_campaign_placement_unavailable', 'Campaign placement is temporarily unavailable.', array( 'status' => 503 ) ); }
		return rest_ensure_response( array( 'schemaVersion' => 'complete99-public-campaign-placement/v1', 'verified' => $verified, 'verificationSource' => $verified ? 'independent_public_html_readback' : 'pending_independent_readback', 'placement' => $public ) );
	}

	private static function placement_public_url( $slot ) {
		if ( 'home_banner' === $slot ) { return home_url( '/' ); }
		if ( 'store_banner' === $slot && function_exists( 'wc_get_page_id' ) ) {
			$page_id = (int) wc_get_page_id( 'shop' );
			$url = 0 < $page_id ? get_permalink( $page_id ) : '';
			if ( is_string( $url ) && self::is_first_party_url( $url ) ) { return $url; }
		}
		return new WP_Error( 'complete99_campaign_public_slot_url_missing', 'The owned placement has no exact first-party public page.' );
	}

	private static function rendered_copy_digest( $public, $locale ) {
		$copy = (array) ( $public['copy'][ $locale ] ?? array() );
		return hash( 'sha256', self::canonical_json( array( 'locale' => $locale, 'headline' => (string) ( $copy['headline'] ?? '' ), 'body' => (string) ( $copy['body'] ?? '' ), 'cta' => (string) ( $copy['cta'] ?? '' ), 'landingUrl' => (string) ( $public['landingUrl'] ?? '' ), 'assetSha256' => (string) ( $public['asset']['sha256'] ?? '' ) ) ) );
	}

	private static function system_readback_receipt_id( $placement_id ) {
		return preg_match( '/\Aplc_[a-f0-9]{48}\z/', (string) $placement_id )
			? 'rcp_' . substr( hash( 'sha256', (string) $placement_id . '|system-readback' ), 0, 48 )
			: '';
	}

	/** Lock every row that can claim the logical system readback identity. */
	private static function system_readback_receipts( $row, $for_update = false ) {
		global $wpdb;
		if ( ! is_array( $row ) || '' === self::system_readback_receipt_id( (string) ( $row['placement_id'] ?? '' ) ) ) {
			return new WP_Error( 'complete99_campaign_system_receipt_identity_invalid', 'System readback receipt identity is invalid.', array( 'status' => 503 ) );
		}
		$tables = self::table_names();
		$lock = $for_update && ! self::is_sqlite_database() ? ' FOR UPDATE' : '';
		$receipt_id = self::system_readback_receipt_id( (string) $row['placement_id'] );
		$wpdb->last_error = '';
		$rows = $wpdb->get_results(
			$wpdb->prepare(
				"SELECT * FROM {$tables['provider_receipts']} WHERE receipt_id=%s OR (provider_key='wordpress-owned' AND external_id=%s) ORDER BY id ASC LIMIT 2{$lock}",
				$receipt_id,
				(string) $row['placement_id']
			),
			ARRAY_A
		);
		return '' === (string) $wpdb->last_error && is_array( $rows )
			? $rows
			: new WP_Error( 'complete99_campaign_system_receipt_query_failed', 'System readback receipt truth could not be inspected.', array( 'status' => 503 ) );
	}

	private static function verified_readback_receipt_matches( $receipt, $row, $package, $proof_url, $historical = false ) {
		$expected_receipt_id = self::system_readback_receipt_id( (string) ( $row['placement_id'] ?? '' ) );
		$public_json = is_array( $row ) ? (string) ( $row['public_json'] ?? '' ) : '';
		$public = '' !== $public_json ? json_decode( $public_json, true ) : null;
		$token = (string) ( $row['readback_token'] ?? '' );
		$stored_proof_url = is_array( $public ) ? (string) ( $public['proofUrl'] ?? '' ) : '';
		$stored_event_endpoint = is_array( $public ) ? (string) ( $public['eventEndpoint'] ?? '' ) : '';
		$current_event_endpoint = is_array( $row ) ? rest_url( self::REST_NAMESPACE . '/campaign-events/' . $token ) : '';
		$event_endpoint = $historical ? $stored_event_endpoint : $current_event_endpoint;
		$historical_urls_exact = ! $historical || self::historical_owned_event_endpoint_is_safe( $stored_event_endpoint, $stored_proof_url, $token );
		return is_array( $receipt ) && is_array( $row ) && is_array( $package ) && is_string( $proof_url )
			&& is_array( $public ) && hash_equals( $public_json, self::canonical_json( $public ) ) && $historical_urls_exact
			&& ( $historical || self::is_first_party_url( $event_endpoint ) )
			&& hash_equals( $event_endpoint, $stored_event_endpoint ) && hash_equals( (string) $proof_url, $stored_proof_url )
			&& hash_equals( (string) $row['public_digest'], hash( 'sha256', $public_json ) )
			&& hash_equals( $expected_receipt_id, (string) ( $receipt['receipt_id'] ?? '' ) )
			&& hash_equals( (string) $row['campaign_id'], (string) ( $receipt['campaign_id'] ?? '' ) )
			&& (int) $row['campaign_version'] === (int) ( $receipt['campaign_version'] ?? -1 )
			&& 'website' === (string) ( $receipt['channel'] ?? '' )
			&& 'wordpress-owned' === (string) ( $receipt['provider_key'] ?? '' )
			&& 'complete99-wordpress' === (string) ( $receipt['provider_account_ref'] ?? '' )
			&& 'confirmed' === (string) ( $receipt['receipt_status'] ?? '' )
			&& 'system_verified' === (string) ( $receipt['proof_level'] ?? '' )
			&& 'owned_active' === (string) ( $receipt['external_state'] ?? '' )
			&& hash_equals( (string) $row['placement_id'], (string) ( $receipt['external_id'] ?? '' ) )
			&& hash_equals( (string) $proof_url, (string) ( $receipt['proof_ref'] ?? '' ) )
			&& hash_equals( (string) ( $package['approval_snapshot_digest'] ?? '' ), (string) ( $receipt['material_digest'] ?? '' ) )
			&& hash_equals( (string) $row['public_digest'], (string) ( $receipt['payload_digest'] ?? '' ) )
			&& 0 === (int) ( $receipt['created_by'] ?? -1 )
			&& false !== strtotime( (string) ( $receipt['occurred_at'] ?? '' ) . ' UTC' )
			&& false !== strtotime( (string) ( $receipt['created_at'] ?? '' ) . ' UTC' );
	}

	/** Independent worker verifies the actual rendered public page before creating system evidence. */
	public static function cron_verify_readback( $campaign_id, $scheduled_version, $schedule_digest ) {
		return self::run_lifecycle_worker_operation( 'verify_readback', static function () use ( $campaign_id, $scheduled_version, $schedule_digest ) { return self::cron_verify_readback_fenced( $campaign_id, $scheduled_version, $schedule_digest ); } );
	}

	private static function cron_verify_readback_fenced( $campaign_id, $scheduled_version, $schedule_digest ) {
		global $wpdb;
		$quarantine = self::assert_public_quarantine_clear( false );
		if ( is_wp_error( $quarantine ) ) { self::enqueue_reconcile_trigger( time() + 1 ); return; }
		$loaded = self::load_campaign( (string) $campaign_id );
		if ( is_wp_error( $loaded ) ) { return; }
		$effective = self::effective_campaign_state( $loaded );
		if ( is_wp_error( $effective ) ) { return $effective; }
		if ( is_array( $effective['overlay'] ?? null ) ) { return true; }
		$state = $loaded['state'];
		if ( ! self::campaign_callback_eligible( 'verify', $loaded, $campaign_id, $scheduled_version, $schedule_digest ) ) { return true; }
		$tables = self::table_names();
		$wpdb->last_error = '';
		$candidates = $wpdb->get_results( $wpdb->prepare( "SELECT * FROM {$tables['placements']} WHERE campaign_id=%s AND campaign_version=%d AND package_digest=%s AND status='pending_readback' ORDER BY id ASC LIMIT 2", $campaign_id, $scheduled_version, $state['runtime']['scheduledPackageDigest'] ), ARRAY_A );
		if ( '' !== (string) $wpdb->last_error || ! is_array( $candidates ) ) { return new WP_Error( 'complete99_campaign_readback_placement_query_failed', 'Readback placement truth could not be inspected.', array( 'status' => 503, 'retryStored' => true, 'stored' => 'pre' ) ); }
		if ( 1 !== count( $candidates ) ) { return true; }
		$public_transaction = self::begin_public_read_transaction();
		if ( is_wp_error( $public_transaction ) ) { self::mark_schedule_retry( $loaded, $public_transaction->get_error_code(), 'retry_pending', $loaded ); return; }
		$context = self::locked_public_placement_context( (string) $candidates[0]['readback_token'], array( 'pending_readback' ) );
		if ( is_wp_error( $context ) ) { self::rollback_transaction(); if ( ! self::suppress_public_context_error( $context ) ) { self::mark_schedule_retry( $loaded, $context->get_error_code(), 'retry_pending', $loaded ); } return; }
		$public_commit = self::commit_public_read_transaction();
		if ( is_wp_error( $public_commit ) ) { self::mark_schedule_retry( $loaded, $public_commit->get_error_code(), 'retry_pending', $loaded ); return; }
		$row = $context['row'];
		$loaded = $context['campaign'];
		$page_url = self::placement_public_url( (string) $row['slot_key'] );
		$event_endpoint = (string) ( $context['public']['eventEndpoint'] ?? '' );
		if ( is_wp_error( $page_url ) ) { self::mark_schedule_retry( $loaded, $page_url->get_error_code(), 'retry_pending', $loaded ); return; }
		$purged = self::purge_public_placement_caches_with_retry( 'pre_readback', (string) $campaign_id );
		if ( is_wp_error( $purged ) ) { self::mark_schedule_retry( $loaded, $purged->get_error_code(), 'retry_pending', $loaded ); return; }
		if ( ! self::is_first_party_url( $page_url ) || ! self::is_first_party_url( $event_endpoint ) ) { self::mark_schedule_retry( $loaded, 'readback_origin_invalid', 'retry_pending', $loaded ); return; }
		$response = wp_safe_remote_get( $page_url, array( 'timeout' => 5, 'redirection' => 0, 'limit_response_size' => 1048577, 'headers' => array( 'Cache-Control' => 'no-cache', 'X-Complete99-Readback' => $row['placement_id'], 'X-Complete99-Readback-Token' => $row['readback_token'] ) ) );
		$code = is_wp_error( $response ) ? 0 : (int) wp_remote_retrieve_response_code( $response );
		$body = is_wp_error( $response ) ? '' : (string) wp_remote_retrieve_body( $response );
		$content_type = is_wp_error( $response ) ? '' : strtolower( trim( (string) wp_remote_retrieve_header( $response, 'content-type' ) ) );
		$markers = array( 'data-c99-campaign-id="' . $row['campaign_id'] . '"', 'data-c99-placement-id="' . $row['placement_id'] . '"', 'data-c99-public-digest="' . $row['public_digest'] . '"', 'data-c99-campaign-event-endpoint="' . esc_attr( $event_endpoint ) . '"', 'data-c99-campaign-event-token="' . $row['readback_token'] . '"', 'data-c99-consent-basis="' . self::WEBSITE_CONSENT_BASIS . '"', 'data-c99-measurement-mode="' . self::WEBSITE_MEASUREMENT_MODE . '"', 'data-c99-measurement-purpose="' . self::WEBSITE_MEASUREMENT_PURPOSE . '"', 'data-c99-measurement-scope="' . $row['readback_token'] . '"' );
		$copy_match = false;
		foreach ( array( 'he', 'en' ) as $locale ) {
			if ( false !== strpos( $body, 'data-c99-rendered-body-digest="' . self::rendered_copy_digest( json_decode( (string) $row['public_json'], true ), $locale ) . '"' ) ) { $copy_match = true; break; }
		}
		$markers_match = true;
		foreach ( $markers as $marker ) { if ( false === strpos( $body, $marker ) ) { $markers_match = false; break; } }
		if ( 200 !== $code || '' === $body || strlen( $body ) > 1048576 || ! preg_match( '/\A(?:text\/html|application\/xhtml\+xml)(?:;|\z)/', $content_type ) || ! $copy_match || ! $markers_match ) {
			self::mark_schedule_retry( $loaded, 'independent_public_html_readback_failed', 'retry_pending', $loaded ); return;
		}
		$result = self::commit_verified_readback( $row, $loaded, $page_url );
		if ( is_wp_error( $result ) ) {
			if ( 'complete99_campaign_readback_commit_outcome_unknown' === $result->get_error_code() ) { self::enqueue_reconcile_trigger( time() + 1 ); return; }
			self::mark_schedule_retry( $loaded, $result->get_error_code(), 'retry_pending', $loaded ); return;
		}
		$watchdog = self::schedule_next_reconcile_trigger();
		if ( is_wp_error( $watchdog ) ) { self::mark_schedule_retry( $loaded, $watchdog->get_error_code(), 'retry_pending', $loaded ); }
	}

	private static function commit_verified_readback( $expected_row, $loaded, $proof_url ) {
		global $wpdb;
		$tables = self::table_names();
		if ( is_wp_error( self::begin_transaction( self::CAPACITY_ROLE_RECOVERY ) ) ) { return new WP_Error( 'complete99_campaign_readback_transaction_failed', 'Verified readback transaction could not start.' ); }
		$lock = self::is_sqlite_database() ? '' : ' FOR UPDATE';
		$row = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$tables['placements']} WHERE id=%d LIMIT 1{$lock}", (int) $expected_row['id'] ), ARRAY_A );
		$context = is_array( $row ) ? self::locked_public_placement_context( (string) $row['readback_token'], array( 'pending_readback' ) ) : new WP_Error( 'complete99_campaign_readback_context_missing', 'Readback placement is missing.' );
		if ( is_wp_error( $context ) ) { self::rollback_transaction(); return $context; }
		$row = $context['row'];
		$current = $context['campaign'];
		$current_state = is_wp_error( $current ) ? array() : $current['state'];
		$locked_heartbeat = self::cron_heartbeat_status();
		$expected_state = (array) ( $loaded['state'] ?? array() );
		$starts_at = is_array( $row ) ? strtotime( (string) $row['starts_at'] . ' UTC' ) : false;
		$expires_at = is_array( $row ) ? strtotime( (string) $row['expires_at'] . ' UTC' ) : false;
		if ( ! is_array( $row ) || is_wp_error( $current )
			|| 'pending_readback' !== (string) $row['status']
			|| false === $starts_at || false === $expires_at || $starts_at > time() || $expires_at <= time()
			|| ! self::campaign_schedule_snapshot_matches( $loaded, $current )
			|| ! self::campaign_callback_eligible( 'verify', $current, (string) ( $expected_state['campaignId'] ?? '' ), (int) ( $expected_state['runtime']['scheduledVersion'] ?? 0 ), (string) ( $expected_state['runtime']['scheduleDigest'] ?? '' ) )
			|| ! hash_equals( (string) $row['campaign_id'], (string) $expected_row['campaign_id'] )
			|| ! hash_equals( (string) $row['placement_id'], (string) $expected_row['placement_id'] )
			|| ! hash_equals( (string) $row['public_digest'], (string) $expected_row['public_digest'] )
			|| ! hash_equals( (string) $row['package_digest'], (string) $expected_row['package_digest'] )
			|| (int) $row['campaign_version'] !== (int) ( $current_state['runtime']['scheduledVersion'] ?? 0 )
			|| (int) ( $current_state['runtime']['scheduledVersion'] ?? 0 ) !== (int) ( $expected_state['runtime']['scheduledVersion'] ?? -1 )
			|| ! hash_equals( (string) ( $current_state['runtime']['scheduledPackageId'] ?? '' ), (string) ( $expected_state['runtime']['scheduledPackageId'] ?? '' ) )
			|| ! hash_equals( (string) $row['package_digest'], (string) ( $current_state['runtime']['scheduledPackageDigest'] ?? '' ) )
			|| ! hash_equals( (string) ( $current_state['runtime']['scheduledPackageDigest'] ?? '' ), (string) ( $expected_state['runtime']['scheduledPackageDigest'] ?? '' ) )
			|| ! hash_equals( (string) ( $current_state['runtime']['scheduleDigest'] ?? '' ), (string) ( $expected_state['runtime']['scheduleDigest'] ?? '' ) )
			|| ! hash_equals( (string) ( $current_state['runtime']['scheduledApprovalDigest'] ?? '' ), (string) ( $expected_state['runtime']['scheduledApprovalDigest'] ?? '' ) )
			|| is_wp_error( self::authority_snapshot_is_current( $current['state'] ) ) || empty( $locked_heartbeat['ready'] ) ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_readback_stale', 'Readback authority or cron-runner truth changed before commit.' ); }
		$receipt_id = self::system_readback_receipt_id( (string) $row['placement_id'] );
		$receipt_rows = self::system_readback_receipts( $row, true );
		if ( is_wp_error( $receipt_rows ) ) { self::rollback_transaction(); return $receipt_rows; }
		if ( 1 < count( $receipt_rows ) ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_readback_receipt_duplicated', 'The logical system readback receipt is duplicated.' ); }
		$receipt = 1 === count( $receipt_rows ) ? $receipt_rows[0] : null;
		if ( is_array( $receipt ) && ! self::verified_readback_receipt_matches( $receipt, $row, $context['package'], $proof_url ) ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_readback_receipt_mismatch', 'Existing readback evidence failed exact verification.' ); }
		if ( ! is_array( $receipt ) && 1 !== $wpdb->insert( $tables['provider_receipts'], array( 'receipt_id' => $receipt_id, 'campaign_id' => $row['campaign_id'], 'campaign_version' => $row['campaign_version'], 'channel' => 'website', 'provider_key' => 'wordpress-owned', 'provider_account_ref' => 'complete99-wordpress', 'receipt_status' => 'confirmed', 'proof_level' => 'system_verified', 'external_state' => 'owned_active', 'external_id' => $row['placement_id'], 'proof_ref' => $proof_url, 'material_digest' => $current['state']['runtime']['scheduledApprovalDigest'], 'payload_digest' => $row['public_digest'], 'occurred_at' => current_time( 'mysql', true ), 'created_by' => 0, 'created_at' => current_time( 'mysql', true ) ) ) ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_readback_receipt_failed', 'Verified readback receipt could not be stored.' ); }
		$stored_receipts = self::system_readback_receipts( $row, true );
		$stored_receipt = is_array( $stored_receipts ) && 1 === count( $stored_receipts ) ? $stored_receipts[0] : null;
		if ( is_wp_error( $stored_receipts ) || ! self::verified_readback_receipt_matches( $stored_receipt, $row, $context['package'], $proof_url ) ) { self::rollback_transaction(); return is_wp_error( $stored_receipts ) ? $stored_receipts : new WP_Error( 'complete99_campaign_readback_receipt_readback_failed', 'Verified readback receipt failed exact post-write verification.' ); }
		if ( 'pending_readback' === (string) $row['status'] && 1 !== $wpdb->update( $tables['placements'], array( 'status' => 'active', 'activated_at' => current_time( 'mysql', true ), 'updated_at' => current_time( 'mysql', true ) ), array( 'id' => (int) $row['id'], 'status' => 'pending_readback' ) ) ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_readback_placement_failed', 'Verified placement state could not be stored.' ); }
		$cleanup_inputs = self::capture_cleanup_inputs( $current );
		if ( is_wp_error( $cleanup_inputs ) ) { self::rollback_transaction(); return $cleanup_inputs; }
		$cleanup_inputs['cronActions'] = array_values( array_filter( $cleanup_inputs['cronActions'], static function ( $cron ) { return in_array( (string) ( $cron['hook'] ?? '' ), array( 'complete99_campaign_activate', 'complete99_campaign_verify_readback' ), true ); } ) );
		$state = $current['state'];
		$state['runtime']['lifecycleState'] = 'active';
		$state['runtime']['externalState'] = 'owned_active';
		$state['runtime']['jobState'] = 'readback_verified';
		$state['runtime']['nextAttemptAt'] = gmdate( 'Y-m-d\TH:i:s\Z', min( (int) ( $state['runtime']['expiryTimestamp'] ?? 0 ), time() + self::AUTHORITY_WATCHDOG_SECONDS ) );
		$state['runtime']['lastErrorCode'] = '';
		$saved = self::save_campaign( $current, $state, 'owned_readback_verified', 0 );
		if ( is_wp_error( $saved ) ) { self::rollback_transaction(); return $saved; }
		$cleanup = self::append_cleanup_obligation( $saved, 'verified_readback', (string) ( $state['runtime']['scheduleDigest'] ?? '' ) . '|generation:' . (int) ( $state['runtime']['activationGeneration'] ?? 0 ) . '|readback', $cleanup_inputs, 'present' );
		if ( is_wp_error( $cleanup ) ) { self::rollback_transaction(); return $cleanup; }
		$wpdb->last_error = '';
		$post_row = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$tables['placements']} WHERE id=%d LIMIT 1{$lock}", (int) $row['id'] ), ARRAY_A );
		if ( '' !== (string) $wpdb->last_error || ! is_array( $post_row ) || 'active' !== (string) ( $post_row['status'] ?? '' ) ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_readback_post_state_invalid', 'Verified placement failed exact post-state readback.', array( 'status' => 503, 'retryStored' => true, 'stored' => 'pre' ) ); }
		$commit = self::commit_transaction();
		self::enqueue_reconcile_trigger( time() + 1 );
		return is_wp_error( $commit ) ? new WP_Error( 'complete99_campaign_readback_commit_outcome_unknown', 'Verified readback commit acknowledgement was ambiguous; durable cleanup reconciliation was queued.', array( 'status' => 503, 'stored' => self::classify_campaign_placement_commit( (string) $row['campaign_id'], $current, $cleanup, (string) $row['placement_id'], $row, $post_row ), 'retryStored' => true, 'cause' => $commit->get_error_code() ) ) : true;
	}

	private static function expiry_callback_state_matches( $expected, $current, $campaign_id, $scheduled_version, $schedule_digest, $require_due = false ) {
		if ( ! self::campaign_schedule_snapshot_matches( $expected, $current ) ) { return false; }
		if ( ! self::campaign_callback_eligible( 'expire', $current, $campaign_id, $scheduled_version, $schedule_digest ) ) { return false; }
		$state = $current['state'];
		$expiry = (int) ( $state['runtime']['expiryTimestamp'] ?? 0 );
		return 0 < $expiry && ( ! $require_due || $expiry <= time() );
	}

	private static function expiry_placement_truth_is_current( $loaded, $for_update = false ) {
		global $wpdb;
		$state = $loaded['state'];
		$lifecycle = (string) ( $state['runtime']['lifecycleState'] ?? '' );
		$expected_id = self::owned_placement_id( (string) $state['campaignId'], (string) ( $state['runtime']['scheduleDigest'] ?? '' ), (int) ( $state['runtime']['activationGeneration'] ?? 0 ) );
		if ( ! preg_match( '/\Aplc_[a-f0-9]{48}\z/', $expected_id ) ) { return new WP_Error( 'complete99_campaign_expiry_placement_identity_invalid', 'Campaign expiry placement identity is invalid.', array( 'status' => 503 ) ); }
		$lock = $for_update && ! self::is_sqlite_database() ? ' FOR UPDATE' : '';
		$wpdb->last_error = '';
		$rows = $wpdb->get_results( $wpdb->prepare( "SELECT placement_id,campaign_id,campaign_version,package_digest,slot_key,status FROM " . self::table_names()['placements'] . " WHERE campaign_id=%s AND status IN ('scheduled','pending_readback','active','suppressed_authority','suppressed_readback') ORDER BY id ASC LIMIT 2{$lock}", (string) $state['campaignId'] ), ARRAY_A );
		if ( '' !== (string) $wpdb->last_error || ! is_array( $rows ) || 1 < count( $rows ) || ( 'active' === $lifecycle && 1 !== count( $rows ) ) ) { return new WP_Error( 'complete99_campaign_expiry_placement_truth_invalid', 'Campaign expiry placement truth is unavailable, duplicated, or missing.', array( 'status' => 503 ) ); }
		if ( 1 === count( $rows ) && ( ! hash_equals( $expected_id, (string) ( $rows[0]['placement_id'] ?? '' ) ) || ! hash_equals( (string) $state['campaignId'], (string) ( $rows[0]['campaign_id'] ?? '' ) )
			|| (int) ( $state['runtime']['scheduledVersion'] ?? 0 ) !== (int) ( $rows[0]['campaign_version'] ?? -1 ) || ! hash_equals( (string) ( $state['runtime']['scheduledPackageDigest'] ?? '' ), (string) ( $rows[0]['package_digest'] ?? '' ) )
			|| ! hash_equals( (string) ( $state['governance']['slotKey'] ?? '' ), (string) ( $rows[0]['slot_key'] ?? '' ) ) ) ) { return new WP_Error( 'complete99_campaign_expiry_placement_truth_invalid', 'Campaign expiry placement truth is not bound to the current generation.', array( 'status' => 503 ) ); }
		return true;
	}

	public static function cron_expire( $campaign_id, $scheduled_version, $schedule_digest ) {
		return self::run_lifecycle_worker_operation( 'expire', static function () use ( $campaign_id, $scheduled_version, $schedule_digest ) { return self::cron_expire_fenced( $campaign_id, $scheduled_version, $schedule_digest ); } );
	}

	private static function cron_expire_fenced( $campaign_id, $scheduled_version, $schedule_digest ) {
		$quarantine = self::assert_public_quarantine_clear( false );
		if ( is_wp_error( $quarantine ) ) { self::enqueue_reconcile_trigger( time() + 1 ); return $quarantine; }
		$loaded = self::load_campaign( (string) $campaign_id );
		if ( is_wp_error( $loaded ) ) { return; }
		$effective = self::effective_campaign_state( $loaded );
		if ( is_wp_error( $effective ) ) { return $effective; }
		if ( is_array( $effective['overlay'] ?? null ) ) { return true; }
		$state = $loaded['state'];
		if ( ! self::expiry_callback_state_matches( $loaded, $loaded, $campaign_id, $scheduled_version, $schedule_digest, false ) ) { return true; }
		$args = array( (string) $campaign_id, (int) $scheduled_version, (string) $schedule_digest );
		$expiry_at = (int) ( $state['runtime']['expiryTimestamp'] ?? 0 );
		if ( $expiry_at > time() ) {
			$fence = self::begin_campaign_cron_mutation_fence();
			if ( is_wp_error( $fence ) ) { return $fence; }
			$requeued = true;
			$released = false;
			try {
				$current = self::load_campaign( (string) $campaign_id );
				if ( is_wp_error( $current ) ) { $requeued = $current; }
				else {
					$current_effective = self::effective_campaign_state( $current );
					if ( is_wp_error( $current_effective ) ) { $requeued = $current_effective; }
					elseif ( is_array( $current_effective['overlay'] ?? null ) || ! self::expiry_callback_state_matches( $loaded, $current, $campaign_id, $scheduled_version, $schedule_digest, false ) ) { $requeued = true; }
					else {
						$placement = self::expiry_placement_truth_is_current( $current, false );
						$requeued = is_wp_error( $placement ) ? $placement : self::ensure_exact_campaign_event_locked( 'complete99_campaign_expire', (int) $current['state']['runtime']['expiryTimestamp'], $args, 'expiry_early' );
					}
				}
			} finally {
				$released = self::end_campaign_cron_mutation_fence( $fence );
			}
			if ( ! $released ) { return new WP_Error( 'complete99_campaign_expiry_early_lock_release_unknown', 'Campaign expiry early-event fence ownership became uncertain.', array( 'status' => 503 ) ); }
			if ( is_wp_error( $requeued ) ) { self::schedule_expiry_retry( $loaded, $args, $requeued->get_error_code() ); }
			return $requeued;
		}
		global $wpdb;
		$tables = self::table_names();
		if ( is_wp_error( self::begin_transaction( self::CAPACITY_ROLE_RECOVERY ) ) ) { self::schedule_expiry_retry( $loaded, $args, 'expiry_transaction_failed' ); return; }
		$locked_quarantine = self::assert_public_quarantine_clear( true );
		if ( is_wp_error( $locked_quarantine ) ) {
			self::rollback_transaction();
			self::enqueue_reconcile_trigger( time() + 1 );
			return $locked_quarantine;
		}
		$current = self::load_campaign( (string) $campaign_id, true );
		if ( is_wp_error( $current ) || ! self::expiry_callback_state_matches( $loaded, $current, $campaign_id, $scheduled_version, $schedule_digest, true ) ) { self::rollback_transaction(); return is_wp_error( $current ) ? $current : true; }
		$current_effective = self::effective_campaign_state( $current );
		$placement_current = is_wp_error( $current_effective ) ? $current_effective : ( is_array( $current_effective['overlay'] ?? null ) ? true : self::expiry_placement_truth_is_current( $current, true ) );
		if ( is_wp_error( $placement_current ) || is_array( $current_effective['overlay'] ?? null ) ) { self::rollback_transaction(); return is_wp_error( $placement_current ) ? $placement_current : true; }
		$loaded = $current;
		$state = $current['state'];
		$cleanup_inputs = self::capture_cleanup_inputs( $current );
		if ( is_wp_error( $cleanup_inputs ) ) { self::rollback_transaction(); self::schedule_expiry_retry( $loaded, $args, $cleanup_inputs->get_error_code() ); return; }
		$updated = $wpdb->query( $wpdb->prepare( "UPDATE {$tables['placements']} SET status = 'expired', stopped_at = %s, updated_at = %s WHERE campaign_id = %s AND status IN ('active','pending_readback','suppressed_authority','suppressed_readback')", current_time( 'mysql', true ), current_time( 'mysql', true ), $campaign_id ) );
		$remaining = $wpdb->get_var( $wpdb->prepare( "SELECT COUNT(*) FROM {$tables['placements']} WHERE campaign_id=%s AND status IN ('active','pending_readback','suppressed_authority','suppressed_readback')", $campaign_id ) );
		if ( false === $updated || ! is_numeric( $remaining ) || 0 !== (int) $remaining ) { self::rollback_transaction(); self::schedule_expiry_retry( $loaded, $args, 'expiry_placement_failed' ); return; }
		$state['runtime']['lifecycleState'] = 'expired';
		$state['runtime']['jobState'] = 'expired';
		$state['runtime']['externalState'] = 'expired';
		$state['runtime']['nextAttemptAt'] = '';
		$saved = self::save_campaign( $loaded, $state, 'expired', 0 );
		if ( is_wp_error( $saved ) ) { self::rollback_transaction(); self::schedule_expiry_retry( $loaded, $args, 'expiry_state_failed' ); return; }
		$cleanup = self::append_cleanup_obligation( $saved, 'expiry', (string) $schedule_digest . '|expiry', $cleanup_inputs, 'absent' );
		if ( is_wp_error( $cleanup ) ) { self::rollback_transaction(); self::schedule_expiry_retry( $loaded, $args, $cleanup->get_error_code() ); return; }
		$commit = self::commit_transaction();
		self::enqueue_reconcile_trigger( time() + 1 );
		if ( is_wp_error( $commit ) ) { return; }
	}

	private static function schedule_expiry_retry( $loaded, $args, $error_code ) {
		$stored = self::mark_schedule_retry( $loaded, $error_code, 'expiry_retry_pending', $loaded );
		if ( is_wp_error( $stored ) || ! is_array( $stored ) ) { return $stored; }
		$when = time() + 30;
		$next = wp_next_scheduled( 'complete99_campaign_expire', $args );
		if ( false === $next ) {
			$scheduled = self::ensure_exact_campaign_event( 'complete99_campaign_expire', $when, $args, 'expiry_retry' );
			if ( is_wp_error( $scheduled ) ) { return new WP_Error( $scheduled->get_error_code(), $scheduled->get_error_message(), array( 'status' => 503, 'stored' => 'post', 'retryStored' => true ) ); }
		}
		$queued = self::enqueue_reconcile_trigger( $when );
		if ( is_wp_error( $queued ) ) { return new WP_Error( $queued->get_error_code(), $queued->get_error_message(), array( 'status' => 503, 'stored' => 'post', 'retryStored' => true ) ); }
		return $stored;
	}

	public static function rest_public_event( WP_REST_Request $request ) {
		$event = sanitize_key( (string) $request->get_param( 'event' ) );
		if ( ! in_array( $event, array( 'impression', 'click' ), true ) ) {
			return new WP_Error( 'complete99_campaign_event_invalid', 'Event is unsupported.', array( 'status' => 422 ) );
		}
		$claim = self::claim_public_event_budget( (string) $request['token'], $event, $request->get_param( 'event_id' ) );
		if ( is_wp_error( $claim ) ) {
			if ( in_array( $claim->get_error_code(), array( 'complete99_campaign_event_id_invalid', 'complete99_campaign_event_rate_limited', 'complete99_campaign_event_unavailable' ), true ) ) { return $claim; }
			return new WP_Error( 'complete99_campaign_event_temporarily_unavailable', 'Anonymous campaign event recording is temporarily unavailable.', array( 'status' => 503 ) );
		}
		if ( false === $claim ) { return rest_ensure_response( array( 'recorded' => false, 'duplicate' => true, 'evidenceLevel' => 'anonymous_unverified' ) ); }
		return rest_ensure_response( array( 'recorded' => true, 'duplicate' => false, 'evidenceLevel' => 'anonymous_unverified' ) );
	}

	/** Atomically claim one durable anonymous event and its hourly capacity. */
	private static function claim_public_event_budget( $token, $event, $event_id ) {
		if ( ! is_string( $event_id ) || ! preg_match( '/\A[A-Za-z0-9_-]{20,80}\z/', $event_id ) ) {
			return new WP_Error( 'complete99_campaign_event_id_invalid', 'A bounded anonymous event ID is required.', array( 'status' => 422 ) );
		}
		global $wpdb;
		$tables = self::table_names();
		$quarantine = self::assert_public_quarantine_clear( false );
		if ( is_wp_error( $quarantine ) ) { return new WP_Error( 'complete99_campaign_event_unavailable', 'Placement is unavailable.', array( 'status' => 404 ) ); }
		$placement = $wpdb->get_row( $wpdb->prepare( "SELECT placement_id,campaign_id FROM {$tables['placements']} WHERE readback_token=%s AND status='active' AND starts_at <= %s AND expires_at > %s LIMIT 1", (string) $token, current_time( 'mysql', true ), current_time( 'mysql', true ) ), ARRAY_A );
		if ( ! is_array( $placement ) ) { return new WP_Error( 'complete99_campaign_event_unavailable', 'Placement is unavailable.', array( 'status' => 404 ) ); }
		$bucket = gmdate( 'YmdH' );
		$date = gmdate( 'Y-m-d' );
		$now = current_time( 'mysql', true );
		$budget_key = 'budget_' . substr( $bucket, 8, 2 );
		$budget_digest = hash( 'sha256', 'budget|' . $placement['placement_id'] . '|' . $bucket );
		$claim_digest = hash( 'sha256', $event_id );
		$claim_key = 'claim_' . $claim_digest;
		$preexisting = $wpdb->get_row( $wpdb->prepare( "SELECT claim_digest FROM {$tables['event_aggregates']} WHERE placement_id=%s AND event_date=%s AND event_key=%s LIMIT 1", $placement['placement_id'], $date, $claim_key ), ARRAY_A );
		$prebudget = $wpdb->get_var( $wpdb->prepare( "SELECT event_count FROM {$tables['event_aggregates']} WHERE placement_id=%s AND event_date=%s AND event_key=%s LIMIT 1", $placement['placement_id'], $date, $budget_key ) );
		if ( is_array( $preexisting ) || ( is_numeric( $prebudget ) && self::PUBLIC_EVENTS_PER_HOUR <= (int) $prebudget ) ) {
			$read = self::begin_public_read_transaction();
			if ( is_wp_error( $read ) ) { return $read; }
			$context = self::locked_public_placement_context( (string) $token, array( 'active' ) );
			if ( is_wp_error( $context ) ) { self::rollback_transaction(); self::suppress_public_context_error( $context ); return new WP_Error( 'complete99_campaign_event_unavailable', 'Placement is unavailable.', array( 'status' => 404 ) ); }
			$locked_existing = $wpdb->get_row( $wpdb->prepare( "SELECT claim_digest FROM {$tables['event_aggregates']} WHERE placement_id=%s AND event_date=%s AND event_key=%s LIMIT 1", $context['row']['placement_id'], $date, $claim_key ), ARRAY_A );
			$locked_budget = $wpdb->get_var( $wpdb->prepare( "SELECT event_count FROM {$tables['event_aggregates']} WHERE placement_id=%s AND event_date=%s AND event_key=%s LIMIT 1", $context['row']['placement_id'], $date, $budget_key ) );
			$read_committed = self::commit_public_read_transaction();
			if ( is_wp_error( $read_committed ) ) { return $read_committed; }
			if ( is_array( $locked_existing ) ) { return hash_equals( (string) $locked_existing['claim_digest'], $claim_digest ) ? false : new WP_Error( 'complete99_campaign_event_claim_collision', 'Anonymous event identity collision failed closed.', array( 'status' => 503 ) ); }
			if ( is_numeric( $locked_budget ) && self::PUBLIC_EVENTS_PER_HOUR <= (int) $locked_budget ) { return new WP_Error( 'complete99_campaign_event_rate_limited', 'Anonymous campaign event capacity is temporarily exhausted.', array( 'status' => 429 ) ); }
		}
		$transaction = self::begin_public_event_transaction();
		if ( is_wp_error( $transaction ) ) { return $transaction; }
		$context = self::locked_public_placement_context( (string) $token, array( 'active' ) );
		if ( is_wp_error( $context ) ) { self::rollback_transaction(); self::suppress_public_context_error( $context ); return new WP_Error( 'complete99_campaign_event_unavailable', 'Placement is unavailable.', array( 'status' => 404 ) ); }
		$reserve = self::assert_public_event_reserve();
		if ( is_wp_error( $reserve ) ) { self::rollback_transaction(); return $reserve; }
		$placement = $context['row'];
		$budget = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$tables['event_aggregates']} WHERE placement_id=%s AND event_date=%s AND event_key=%s LIMIT 1", $placement['placement_id'], $date, $budget_key ), ARRAY_A );
		if ( ! is_array( $budget ) ) {
			if ( 1 !== $wpdb->insert( $tables['event_aggregates'], array( 'campaign_id' => $placement['campaign_id'], 'placement_id' => $placement['placement_id'], 'event_date' => $date, 'event_hour' => $bucket, 'event_key' => $budget_key, 'provenance_key' => 'anonymous_unverified_budget', 'claim_digest' => $budget_digest, 'event_count' => 0, 'first_at' => $now, 'last_at' => $now ) ) ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_event_budget_failed', 'Anonymous event capacity could not be created.', array( 'status' => 503 ) ); }
		}
		$lock = self::is_sqlite_database() ? '' : ' FOR UPDATE';
		$budget = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$tables['event_aggregates']} WHERE placement_id=%s AND event_date=%s AND event_key=%s LIMIT 1{$lock}", $placement['placement_id'], $date, $budget_key ), ARRAY_A );
		if ( ! is_array( $budget ) || ! hash_equals( (string) $budget['claim_digest'], $budget_digest ) ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_event_budget_failed', 'Anonymous event capacity could not be locked.', array( 'status' => 503 ) ); }
		$existing = $wpdb->get_row( $wpdb->prepare( "SELECT claim_digest FROM {$tables['event_aggregates']} WHERE placement_id=%s AND event_date=%s AND event_key=%s LIMIT 1{$lock}", $placement['placement_id'], $date, $claim_key ), ARRAY_A );
		if ( is_array( $existing ) ) { self::rollback_transaction(); return hash_equals( (string) $existing['claim_digest'], $claim_digest ) ? false : new WP_Error( 'complete99_campaign_event_claim_collision', 'Anonymous event identity collision failed closed.', array( 'status' => 503 ) ); }
		if ( (int) $budget['event_count'] >= self::PUBLIC_EVENTS_PER_HOUR ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_event_rate_limited', 'Anonymous campaign event capacity is temporarily exhausted.', array( 'status' => 429 ) ); }
		if ( 1 !== $wpdb->insert( $tables['event_aggregates'], array( 'campaign_id' => $placement['campaign_id'], 'placement_id' => $placement['placement_id'], 'event_date' => $date, 'event_hour' => $bucket, 'event_key' => $claim_key, 'provenance_key' => 'anonymous_unverified_claim', 'claim_digest' => $claim_digest, 'event_count' => 0, 'first_at' => $now, 'last_at' => $now ) ) ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_event_claim_failed', 'Anonymous event claim could not be stored.', array( 'status' => 503 ) ); }
		$aggregate_digest = hash( 'sha256', 'aggregate|' . $placement['placement_id'] . '|' . $date . '|' . $event );
		$aggregate = $wpdb->query( $wpdb->prepare( "UPDATE {$tables['event_aggregates']} SET event_count=event_count+1,last_at=%s WHERE placement_id=%s AND event_date=%s AND event_key=%s AND provenance_key='anonymous_unverified_web'", $now, $placement['placement_id'], $date, $event ) );
		if ( false === $aggregate || ( 0 === $aggregate && 1 !== $wpdb->insert( $tables['event_aggregates'], array( 'campaign_id' => $placement['campaign_id'], 'placement_id' => $placement['placement_id'], 'event_date' => $date, 'event_hour' => 'aggregate', 'event_key' => $event, 'provenance_key' => 'anonymous_unverified_web', 'claim_digest' => $aggregate_digest, 'event_count' => 1, 'first_at' => $now, 'last_at' => $now ) ) ) ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_event_aggregate_failed', 'Anonymous event aggregate could not be stored.', array( 'status' => 503 ) ); }
		if ( 1 !== $wpdb->query( $wpdb->prepare( "UPDATE {$tables['event_aggregates']} SET event_count=event_count+1,last_at=%s WHERE id=%d AND event_count=%d", $now, (int) $budget['id'], (int) $budget['event_count'] ) ) ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_event_budget_race', 'Anonymous event capacity changed concurrently.', array( 'status' => 503 ) ); }
		$committed = self::commit_public_event_transaction();
		if ( is_wp_error( $committed ) ) { return $committed; }
		return true;
	}

	public static function render_public_placement() {
		if ( is_admin() || ( ! is_front_page() && ! ( function_exists( 'is_shop' ) && is_shop() ) ) ) { return; }
		global $wpdb;
		$tables = self::table_names();
		$slot = function_exists( 'is_shop' ) && is_shop() ? 'store_banner' : 'home_banner';
		$probe_id = isset( $_SERVER['HTTP_X_COMPLETE99_READBACK'] ) && is_string( $_SERVER['HTTP_X_COMPLETE99_READBACK'] ) ? $_SERVER['HTTP_X_COMPLETE99_READBACK'] : '';
		$probe_token = isset( $_SERVER['HTTP_X_COMPLETE99_READBACK_TOKEN'] ) && is_string( $_SERVER['HTTP_X_COMPLETE99_READBACK_TOKEN'] ) ? $_SERVER['HTTP_X_COMPLETE99_READBACK_TOKEN'] : '';
		$probe_requested = '' !== $probe_id || '' !== $probe_token;
		if ( $probe_requested && ( ! preg_match( '/\Aplc_[a-f0-9]{48}\z/', $probe_id ) || ! preg_match( '/\A[a-f0-9]{64}\z/', $probe_token ) ) ) { return; }
		$transaction = self::begin_public_read_transaction();
		if ( is_wp_error( $transaction ) ) { return; }
		$quarantine = self::assert_public_quarantine_clear( true );
		if ( is_wp_error( $quarantine ) ) { self::rollback_transaction(); return; }
		$lock = self::is_sqlite_database() ? '' : ' FOR UPDATE';
		$wpdb->last_error = '';
		if ( $probe_requested ) {
			$row = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$tables['placements']} WHERE slot_key=%s AND placement_id=%s AND readback_token=%s AND status='pending_readback' AND starts_at<=%s AND expires_at>%s ORDER BY created_at DESC LIMIT 1{$lock}", $slot, $probe_id, $probe_token, current_time( 'mysql', true ), current_time( 'mysql', true ) ), ARRAY_A );
		} else {
			$row = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$tables['placements']} WHERE slot_key=%s AND status='active' AND starts_at<=%s AND expires_at>%s ORDER BY created_at DESC LIMIT 1{$lock}", $slot, current_time( 'mysql', true ), current_time( 'mysql', true ) ), ARRAY_A );
		}
		if ( '' !== (string) $wpdb->last_error || ! is_array( $row ) ) { self::rollback_transaction(); return; }
		$context = self::locked_public_placement_context( (string) $row['readback_token'], array( $probe_requested ? 'pending_readback' : 'active' ) );
		if ( is_wp_error( $context ) ) { self::rollback_transaction(); self::suppress_public_context_error( $context ); return; }
		if ( ! hash_equals( (string) $row['placement_id'], (string) ( $context['row']['placement_id'] ?? '' ) ) || ! hash_equals( $slot, (string) ( $context['row']['slot_key'] ?? '' ) ) ) { self::rollback_transaction(); return; }
		$row = $context['row'];
		$data = $context['public'];
		$runtime = (array) ( $context['campaign']['state']['runtime'] ?? array() );
		if ( $probe_requested ) {
			if ( 'schedule_requested' !== (string) ( $runtime['lifecycleState'] ?? '' ) || in_array( (string) ( $runtime['jobState'] ?? '' ), array( 'operator_attention', 'suspended' ), true ) ) { self::rollback_transaction(); return; }
		} else {
			if ( 'active' !== (string) ( $runtime['lifecycleState'] ?? '' ) || 'readback_verified' !== (string) ( $runtime['jobState'] ?? '' ) ) { self::rollback_transaction(); return; }
			if ( ! is_array( $context['receipt'] ?? null ) ) { self::rollback_transaction(); return; }
		}
		$is_en = 0 === strpos( trim( (string) wp_parse_url( home_url( add_query_arg( array(), $GLOBALS['wp']->request ?? '' ) ), PHP_URL_PATH ), '/' ), 'en/' );
		$lang  = $is_en ? 'en' : 'he';
		$copy  = $data['copy'][ $lang ] ?? array();
		$rendered_digest = self::rendered_copy_digest( $data, $lang );
		$event_endpoint = (string) ( $data['eventEndpoint'] ?? '' );
		$expected_event_endpoint = rest_url( self::REST_NAMESPACE . '/campaign-events/' . $row['readback_token'] );
		if ( self::WEBSITE_CONSENT_BASIS !== (string) ( $data['consentBasis'] ?? '' ) || self::WEBSITE_MEASUREMENT_MODE !== (string) ( $data['measurementMode'] ?? '' )
			|| self::WEBSITE_MEASUREMENT_PURPOSE !== (string) ( $data['measurementPurpose'] ?? '' ) || ! preg_match( '/\A[a-f0-9]{64}\z/', (string) $row['readback_token'] )
			|| ! hash_equals( $expected_event_endpoint, $event_endpoint ) || ! self::is_first_party_url( $event_endpoint ) || ! self::is_first_party_url( $data['privacyUrl'] ?? '' ) ) { self::rollback_transaction(); return; }
		if ( $probe_requested ) {
			try {
				if ( function_exists( 'nocache_headers' ) ) { nocache_headers(); }
				if ( ! headers_sent() ) { header( 'Cache-Control: no-store, private, max-age=0', true ); header( 'X-Robots-Tag: noindex, nofollow, noarchive', true ); }
				printf(
					'<div hidden data-c99-readback-probe="1" data-c99-campaign-id="%1$s" data-c99-placement-id="%2$s" data-c99-public-digest="%3$s" data-c99-rendered-body-digest="%4$s" data-c99-campaign-event-endpoint="%5$s" data-c99-campaign-event-token="%6$s" data-c99-consent-basis="%7$s" data-c99-measurement-mode="%8$s" data-c99-measurement-purpose="%9$s" data-c99-measurement-scope="%10$s"></div>',
					esc_attr( $row['campaign_id'] ), esc_attr( $row['placement_id'] ), esc_attr( $row['public_digest'] ), esc_attr( $rendered_digest ), esc_attr( $event_endpoint ), esc_attr( $row['readback_token'] ), esc_attr( self::WEBSITE_CONSENT_BASIS ), esc_attr( self::WEBSITE_MEASUREMENT_MODE ), esc_attr( self::WEBSITE_MEASUREMENT_PURPOSE ), esc_attr( $row['readback_token'] )
				);
			} finally {
				self::commit_public_read_transaction();
			}
			return;
		}
		try {
		?>
		<aside class="c99-public-campaign"
			data-c99-campaign-id="<?php echo esc_attr( $row['campaign_id'] ); ?>"
			data-c99-placement-id="<?php echo esc_attr( $row['placement_id'] ); ?>"
			data-c99-public-digest="<?php echo esc_attr( $row['public_digest'] ); ?>"
			data-c99-rendered-body-digest="<?php echo esc_attr( $rendered_digest ); ?>"
			data-c99-campaign-event-endpoint="<?php echo esc_url( $event_endpoint ); ?>"
			data-c99-campaign-event-token="<?php echo esc_attr( $row['readback_token'] ); ?>"
			data-c99-consent-basis="<?php echo esc_attr( self::WEBSITE_CONSENT_BASIS ); ?>"
			data-c99-measurement-mode="<?php echo esc_attr( self::WEBSITE_MEASUREMENT_MODE ); ?>"
			data-c99-measurement-purpose="<?php echo esc_attr( self::WEBSITE_MEASUREMENT_PURPOSE ); ?>"
			data-c99-measurement-scope="<?php echo esc_attr( $row['readback_token'] ); ?>"
			aria-labelledby="c99-public-campaign-title">
			<?php if ( ! empty( $data['asset']['url'] ) ) : ?>
				<img src="<?php echo esc_url( $data['asset']['url'] ); ?>" alt="<?php echo esc_attr( $copy['headline'] ?? '' ); ?>" loading="lazy" decoding="async">
			<?php endif; ?>
			<div>
				<h2 id="c99-public-campaign-title"><?php echo esc_html( $copy['headline'] ?? '' ); ?></h2>
				<p><?php echo esc_html( $copy['body'] ?? '' ); ?></p>
				<a href="<?php echo esc_url( $data['landingUrl'] ?? '' ); ?>" data-c99-campaign-click><?php echo esc_html( $copy['cta'] ?? '' ); ?></a>
				<div class="c99-public-campaign__measurement" aria-labelledby="c99-public-campaign-measurement-title">
					<p id="c99-public-campaign-measurement-title">מדידת אינטראקציה אופציונלית לבאנר / Optional banner interaction measurement</p>
					<p>רק לאחר אישור, הבאנר ישלח אותות חשיפה ולחיצה עם מזהה אקראי זמני למניעת כפילויות; צבירות מוגבלות נשמרות 90 יום. / Only after you allow it, this banner sends impression and click signals with a temporary random deduplication identifier; bounded aggregates are retained for 90 days.</p>
					<p data-c99-measurement-status role="status" aria-live="polite"
						data-c99-status-unavailable="המדידה האופציונלית אינה זמינה כרגע. / Optional measurement is currently unavailable."
						data-c99-status-undecided="לא נשלח דבר עד לבחירה. / Nothing is sent until you choose."
						data-c99-status-granted="אישרת מדידת אינטראקציות עבור באנר זה. / You allowed interaction measurement for this banner."
						data-c99-status-denied="המדידה כבויה עבור באנר זה. / Measurement is off for this banner."
						data-c99-status-privacy-signal="אות הפרטיות בדפדפן משאיר את המדידה כבויה. / Your browser privacy signal keeps measurement off."
						data-c99-status-error="המדידה נשארה כבויה מפני שלא ניתן לשמור את הבחירה. / Measurement remains off because the choice could not be stored.">המדידה האופציונלית אינה זמינה כרגע. / Optional measurement is currently unavailable.</p>
					<button type="button" data-c99-measurement-grant hidden disabled aria-disabled="true" tabindex="-1">אישור מדידה / Allow measurement</button>
					<button type="button" data-c99-measurement-decline hidden disabled aria-disabled="true" tabindex="-1">ללא מדידה / No measurement</button>
					<button type="button" data-c99-measurement-change hidden disabled aria-disabled="true" tabindex="-1">שינוי בחירת המדידה / Change measurement choice</button>
					<a href="<?php echo esc_url( $data['privacyUrl'] ); ?>" rel="privacy-policy">מדיניות פרטיות / Privacy policy</a>
				</div>
			</div>
		</aside>
		<?php
		} finally {
			self::commit_public_read_transaction();
		}
	}

	/**
	 * Fail closed when an active campaign cannot prove exactly one coherent public row.
	 *
	 * This path deliberately does not require a caller-supplied placement: zero-row and
	 * duplicate-row drift must both suppress current campaign truth immediately.
	 */
	private static function suppress_active_campaign_coherence( $loaded, $error_code ) {
		global $wpdb;
		$campaign_id = (string) ( $loaded['state']['campaignId'] ?? '' );
		$error_code = substr( sanitize_key( (string) $error_code ), 0, 96 );
		$schedule_digest = (string) ( $loaded['state']['runtime']['scheduleDigest'] ?? '' );
		$governed_slot = (string) ( $loaded['state']['governance']['slotKey'] ?? '' );
		if ( ! preg_match( '/\A[a-z0-9_-]{8,64}\z/', $campaign_id ) || ! preg_match( '/\A[a-z0-9_:-]{3,96}\z/', $error_code )
			|| ! preg_match( '/\A[a-f0-9]{64}\z/', $schedule_digest ) || ! in_array( $governed_slot, array( 'home_banner', 'store_banner' ), true ) ) {
			return new WP_Error( 'complete99_campaign_active_coherence_suppression_invalid', 'Active public-coherence suppression identity is invalid.', array( 'status' => 503 ) );
		}
		/* This O(1) transition deliberately avoids every cohort/capacity scan. */
		$transaction = self::begin_public_read_transaction();
		if ( is_wp_error( $transaction ) ) { return $transaction; }
		$status = self::public_quarantine_status( true );
		if ( empty( $status['inspectable'] ) ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_public_quarantine_invalid', 'The public quarantine singleton is unavailable.', array( 'status' => 503 ) ); }
		if ( ! empty( $status['active'] ) ) {
			self::rollback_transaction();
			$queued = self::enqueue_reconcile_trigger( time() + 1 );
			return is_wp_error( $queued ) ? $queued : true;
		}
		/* The caller may have released its public-read transaction before this
		 * O(1) fence is opened. Re-lock the exact initiating campaign so an edit
		 * or cancellation cannot be bound to stale schedule/origin truth. */
		$current = self::load_campaign( $campaign_id, true );
		if ( is_wp_error( $current )
			|| (int) ( $current['row']['version'] ?? -1 ) !== (int) ( $loaded['row']['version'] ?? -2 )
			|| ! hash_equals( (string) ( $current['row']['state_digest'] ?? '' ), (string) ( $loaded['row']['state_digest'] ?? '' ) )
			|| ! hash_equals( $schedule_digest, (string) ( $current['state']['runtime']['scheduleDigest'] ?? '' ) )
			|| ! hash_equals( $governed_slot, (string) ( $current['state']['governance']['slotKey'] ?? '' ) ) ) {
			self::rollback_transaction();
			return new WP_Error( 'complete99_campaign_public_quarantine_initiator_stale', 'Public quarantine was not opened because initiating campaign truth changed.', array( 'status' => 409 ) );
		}
		$epoch = (int) ( $status['payload']['epoch'] ?? -1 );
		if ( 0 > $epoch || PHP_INT_MAX - 1 <= $epoch ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_public_quarantine_epoch', 'The public quarantine epoch is unavailable.', array( 'status' => 503 ) ); }
		$origins = self::public_quarantine_current_origins( $governed_slot );
		if ( is_wp_error( $origins ) ) { self::rollback_transaction(); return $origins; }
		$payload = self::public_quarantine_payload( 'active', $epoch + 1, $error_code, $campaign_id, $schedule_digest, $governed_slot, gmdate( 'Y-m-d\TH:i:s\Z' ), gmdate( 'Y-m-d\TH:i:s\Z', time() + 1 ), $origins );
		$values = self::public_quarantine_row_values( $payload );
		$stored = $wpdb->update(
			self::table_names()['placements'],
			$values,
			array( 'id' => (int) $status['row']['id'], 'placement_id' => self::public_quarantine_placement_id(), 'campaign_version' => $epoch, 'status' => self::PUBLIC_QUARANTINE_STATUS_CLEAR, 'public_digest' => (string) $status['row']['public_digest'] )
		);
		if ( 1 !== $stored || '' !== (string) $wpdb->last_error ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_public_quarantine_concurrent', 'Public quarantine changed concurrently.', array( 'status' => 409 ) ); }
		$readback = self::public_quarantine_status( true );
		if ( empty( $readback['inspectable'] ) || empty( $readback['active'] ) || ! hash_equals( self::canonical_json( $payload ), self::canonical_json( (array) ( $readback['payload'] ?? array() ) ) ) ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_public_quarantine_readback', 'Public quarantine failed exact locked readback.', array( 'status' => 503 ) ); }
		$commit = self::commit_public_read_transaction();
		if ( is_wp_error( $commit ) ) {
			$fresh = self::public_quarantine_status( false );
			if ( empty( $fresh['inspectable'] ) || empty( $fresh['active'] ) || ! hash_equals( self::canonical_json( $payload ), self::canonical_json( (array) ( $fresh['payload'] ?? array() ) ) ) ) { return $commit; }
		}
		$queued = self::enqueue_reconcile_trigger( time() + 1 );
		return is_wp_error( $queued ) ? $queued : true;
	}

	private static function suppress_stale_placement( $row, $loaded, $error_code ) {
		global $wpdb;
		$tables = self::table_names();
		if ( is_wp_error( self::begin_transaction( self::CAPACITY_ROLE_RECOVERY ) ) ) { return false; }
		$lock = self::is_sqlite_database() ? '' : ' FOR UPDATE';
		$current = self::load_campaign( (string) ( $row['campaign_id'] ?? '' ), true );
		$fresh_row = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$tables['placements']} WHERE id=%d LIMIT 1{$lock}", (int) ( $row['id'] ?? 0 ) ), ARRAY_A );
		if ( is_wp_error( $current ) || ! is_array( $fresh_row ) || ! hash_equals( (string) ( $row['placement_id'] ?? '' ), (string) ( $fresh_row['placement_id'] ?? '' ) ) || ! in_array( (string) ( $fresh_row['status'] ?? '' ), array( 'active', 'pending_readback', 'suppressed_authority' ), true ) ) { self::rollback_transaction(); return false; }
		$existing_runtime = (array) ( $current['state']['runtime'] ?? array() );
		$existing_retry_at = strtotime( (string) ( $existing_runtime['nextAttemptAt'] ?? '' ) );
		if ( 'suppressed_authority' === (string) $fresh_row['status'] && 'suppressed' === (string) ( $existing_runtime['externalState'] ?? '' )
			&& 'authority_retry_pending' === (string) ( $existing_runtime['jobState'] ?? '' ) && false !== $existing_retry_at && $existing_retry_at > time()
			&& $existing_retry_at <= time() + self::AUTHORITY_WATCHDOG_SECONDS && is_array( $existing_runtime['authoritySuppression'] ?? null ) ) {
			return self::rollback_transaction();
		}
		$locked_context_error = null;
		if ( in_array( (string) $fresh_row['status'], array( 'active', 'pending_readback' ), true ) ) {
			$locked_context = self::locked_public_placement_context( (string) $fresh_row['readback_token'], array( (string) $fresh_row['status'] ) );
			if ( ! is_wp_error( $locked_context ) ) { return self::rollback_transaction(); }
			$locked_context_error = $locked_context;
		}
		$fresh_authority = self::build_authority_snapshot( $current['state'] );
		$fresh_heartbeat = self::cron_heartbeat_status();
		$stored_authority = is_array( $current['state']['authoritySnapshot'] ?? null ) ? $current['state']['authoritySnapshot'] : array();
		$old_authority_digest = preg_match( '/\A[a-f0-9]{64}\z/', (string) ( $stored_authority['sha256'] ?? '' ) ) ? (string) $stored_authority['sha256'] : hash( 'sha256', self::canonical_json( $stored_authority ) );
		$observed_authority_digest = is_wp_error( $fresh_authority )
			? hash( 'sha256', self::canonical_json( array( 'errorCode' => $fresh_authority->get_error_code(), 'errorMessage' => $fresh_authority->get_error_message() ) ) )
			: (string) ( $fresh_authority['sha256'] ?? hash( 'sha256', self::canonical_json( $fresh_authority ) ) );
		$authority_stale = is_wp_error( $fresh_authority ) || ! hash_equals( hash( 'sha256', self::canonical_json( $stored_authority ) ), hash( 'sha256', self::canonical_json( $fresh_authority ) ) );
		$heartbeat_stale = empty( $fresh_heartbeat['ready'] );
		$heartbeat_digest = self::cron_heartbeat_digest( $fresh_heartbeat );
		$context_data = is_wp_error( $locked_context_error ) ? $locked_context_error->get_error_data() : null;
		$context_error_code = is_array( $context_data ) && is_string( $context_data['authorityCode'] ?? null ) ? sanitize_key( $context_data['authorityCode'] ) : ( is_wp_error( $locked_context_error ) ? sanitize_key( $locked_context_error->get_error_code() ) : '' );
		$context_stale = '' !== $context_error_code;
		if ( ! $authority_stale && ! $heartbeat_stale && ! $context_stale && 'suppressed_authority' !== (string) $fresh_row['status'] ) { return self::rollback_transaction(); }
		$error_code = $authority_stale ? ( is_wp_error( $fresh_authority ) ? $fresh_authority->get_error_code() : 'campaign_authority_snapshot_stale' ) : ( $heartbeat_stale ? 'campaign_cron_watchdog_stale' : ( '' !== $context_error_code ? $context_error_code : sanitize_key( (string) $error_code ) ) );
		$cleanup_inputs = self::capture_cleanup_inputs( $current );
		if ( is_wp_error( $cleanup_inputs ) ) { self::rollback_transaction(); return false; }
		$cleanup_inputs['cronActions'] = array_values( array_filter( $cleanup_inputs['cronActions'], static function ( $cron ) { return 'complete99_campaign_expire' !== (string) ( $cron['hook'] ?? '' ); } ) );
		if ( 'suppressed_authority' !== (string) $fresh_row['status'] ) {
			$updated = $wpdb->update( $tables['placements'], array( 'status' => 'suppressed_authority', 'stopped_at' => current_time( 'mysql', true ), 'updated_at' => current_time( 'mysql', true ) ), array( 'id' => (int) $fresh_row['id'], 'status' => (string) $fresh_row['status'] ) );
			if ( 1 !== $updated ) { self::rollback_transaction(); return false; }
		}
		$loaded = $current;
		$state = $current['state'];
		$coherence_digest = hash( 'sha256', self::canonical_json( array( 'placementId' => (string) $fresh_row['placement_id'], 'placementStatus' => (string) $fresh_row['status'], 'packageDigest' => (string) $fresh_row['package_digest'], 'publicDigest' => (string) $fresh_row['public_digest'], 'errorCode' => sanitize_key( $error_code ) ) ) );
		$suppression = array( 'schemaVersion' => 'complete99-campaign-public-safety-suppression/v1', 'oldAuthorityDigest' => $old_authority_digest, 'observedAuthorityDigest' => $observed_authority_digest, 'cronHeartbeatDigest' => $heartbeat_digest, 'publicCoherenceDigest' => $coherence_digest, 'errorCode' => sanitize_key( $error_code ) );
		$next_attempt = strtotime( (string) ( $state['runtime']['nextAttemptAt'] ?? '' ) );
		$idempotent = 'suppressed_authority' === (string) $fresh_row['status'] && 'suppressed' === (string) ( $state['runtime']['externalState'] ?? '' ) && 'authority_retry_pending' === (string) ( $state['runtime']['jobState'] ?? '' )
			&& false !== $next_attempt && $next_attempt > time() && $next_attempt <= time() + self::AUTHORITY_WATCHDOG_SECONDS
			&& hash_equals( self::canonical_json( $suppression ), self::canonical_json( (array) ( $state['runtime']['authoritySuppression'] ?? array() ) ) );
		if ( $idempotent ) {
			$saved = $current;
		} else {
			$state['runtime']['externalState'] = 'suppressed';
			$state['runtime']['jobState'] = 'authority_retry_pending';
			$state['runtime']['lastErrorCode'] = sanitize_key( $error_code );
			$state['runtime']['nextAttemptAt'] = gmdate( 'Y-m-d\TH:i:s\Z', time() + self::AUTHORITY_WATCHDOG_SECONDS );
			$state['runtime']['authoritySuppression'] = $suppression;
			$saved = self::save_campaign( $loaded, $state, 'active_authority_suppressed', 0 );
			if ( is_wp_error( $saved ) ) { self::rollback_transaction(); return false; }
		}
		$suppression_identity = self::authority_suppression_cleanup_identity( $state, $fresh_row, $suppression );
		if ( is_wp_error( $suppression_identity ) ) { self::rollback_transaction(); return false; }
		$cleanup = self::append_cleanup_obligation( $saved, 'authority_suppression', $suppression_identity, $cleanup_inputs, 'absent' );
		if ( is_wp_error( $cleanup ) ) { self::rollback_transaction(); return false; }
		$commit = self::commit_transaction();
		self::enqueue_reconcile_trigger( time() + 1 );
		return ! is_wp_error( $commit );
	}

	/** Bind every authority-suppression cleanup receipt to one exact public generation. */
	private static function authority_suppression_cleanup_identity( $state, $row, $suppression ) {
		$schedule_digest = (string) ( $state['runtime']['scheduleDigest'] ?? '' );
		$generation = $state['runtime']['activationGeneration'] ?? null;
		$placement_id = (string) ( $row['placement_id'] ?? '' );
		$old_authority = (string) ( $suppression['oldAuthorityDigest'] ?? '' );
		$observed_authority = (string) ( $suppression['observedAuthorityDigest'] ?? '' );
		$heartbeat = (string) ( $suppression['cronHeartbeatDigest'] ?? '' );
		$coherence = (string) ( $suppression['publicCoherenceDigest'] ?? '' );
		$error_code = sanitize_key( (string) ( $suppression['errorCode'] ?? '' ) );
		if ( ! preg_match( '/\A[a-f0-9]{64}\z/', $schedule_digest ) || ! is_int( $generation ) || 0 > $generation || self::ACTIVATION_GENERATION_MAX < $generation
			|| ! preg_match( '/\Aplc_[a-f0-9]{48}\z/', $placement_id ) || '' === $error_code ) {
			return new WP_Error( 'complete99_campaign_authority_suppression_identity_invalid', 'Authority-suppression cleanup identity is malformed.', array( 'status' => 503 ) );
		}
		foreach ( array( $old_authority, $observed_authority, $heartbeat, $coherence ) as $digest ) {
			if ( ! preg_match( '/\A[a-f0-9]{64}\z/', $digest ) ) { return new WP_Error( 'complete99_campaign_authority_suppression_identity_invalid', 'Authority-suppression cleanup identity is malformed.', array( 'status' => 503 ) ); }
		}
		return hash( 'sha256', $schedule_digest . '|generation:' . $generation . '|placement:' . $placement_id . '|' . $old_authority . '|' . $observed_authority . '|' . $heartbeat . '|' . $coherence . '|' . $error_code );
	}

	/** Record manual evidence only as human-attested; provider truth is adapter-only. */
	public static function rest_provider_receipts( WP_REST_Request $request ) {
		$id = (string) $request['campaign_id'];
		return self::run_mutation(
			$request,
			'provider_receipts',
			$id,
			static function ( $identity ) use ( $id ) {
				global $wpdb;
				$loaded = self::load_campaign( $id );
				if ( is_wp_error( $loaded ) ) { return $loaded; }
				$scope = self::require_location_scope( $loaded['state']['locationId'], 'evidence' );
				if ( is_wp_error( $scope ) ) { return $scope; }
				$expected = self::expected_version( $identity['body'], $loaded );
				if ( is_wp_error( $expected ) ) { return $expected; }
				if ( 'website' === $loaded['state']['primaryChannel'] ) {
					return new WP_Error( 'complete99_campaign_owned_receipt_internal', 'Website verification is created only by the owned readback verifier.', array( 'status' => 422 ) );
				}
				$proof = self::normalize_human_proof( $identity['body'], $loaded );
				if ( is_wp_error( $proof ) ) { return $proof; }
				$external_id = self::optional_text( $identity['body']['externalId'] ?? '', 191 );
				$outcome = self::required_enum( $identity['body']['outcome'] ?? '', array( 'queued', 'human_attested', 'failed' ), 'Manual receipt outcome is invalid.' );
				if ( is_wp_error( $outcome ) ) { return $outcome; }
				$package_digest = self::request_digest( $identity['body']['packageDigest'] ?? '' );
				if ( is_wp_error( $package_digest ) ) { return $package_digest; }
				$tables = self::table_names();
				$bound_package_id = (string) ( $loaded['state']['runtime']['scheduledPackageId'] ?? '' );
				if ( '' !== $bound_package_id ) {
					$package = $wpdb->get_row( $wpdb->prepare( "SELECT package_id,package_digest,approval_snapshot_digest FROM {$tables['prepared_packages']} WHERE package_id=%s AND campaign_id=%s AND channel=%s AND package_digest=%s AND approval_snapshot_digest=%s AND status='prepared' LIMIT 1", $bound_package_id, $id, $loaded['state']['primaryChannel'], $package_digest, $loaded['state']['runtime']['scheduledApprovalDigest'] ), ARRAY_A );
				} else {
					$package = $wpdb->get_row( $wpdb->prepare( "SELECT package_id,package_digest,approval_snapshot_digest FROM {$tables['prepared_packages']} WHERE campaign_id=%s AND campaign_version=%d AND channel=%s AND package_digest=%s AND approval_snapshot_digest=%s AND status='prepared' LIMIT 1", $id, $expected, $loaded['state']['primaryChannel'], $package_digest, $loaded['state']['runtime']['approvalDigest'] ), ARRAY_A );
				}
				if ( ! is_array( $package ) ) {
					return new WP_Error( 'complete99_campaign_receipt_package_unbound', 'Manual evidence must bind the exact current prepared package.', array( 'status' => 409 ) );
				}
				$receipt_id = 'rcp_' . substr( hash( 'sha256', $identity['command_id'] . '|human-attested' ), 0, 48 );
				$row = array(
					'receipt_id' => $receipt_id, 'campaign_id' => $id, 'campaign_version' => $expected,
					'channel' => $loaded['state']['primaryChannel'], 'provider_key' => (string) $loaded['state']['authoritySnapshot']['account']['providerKey'],
					'provider_account_ref' => (string) $loaded['state']['authoritySnapshot']['account']['accountRef'], 'receipt_status' => $outcome,
					'proof_level' => 'human_attested', 'external_state' => 'unverified', 'external_id' => '' === $external_id ? null : $external_id,
					'proof_ref' => $proof['ref'], 'material_digest' => (string) $loaded['state']['runtime']['approvalDigest'],
					'payload_digest' => hash( 'sha256', self::canonical_json( array( 'packageId' => $package['package_id'], 'packageDigest' => $package_digest, 'proof' => $proof, 'outcome' => $outcome, 'externalId' => $external_id ) ) ),
					'occurred_at' => current_time( 'mysql', true ), 'created_by' => $identity['actor'], 'created_at' => current_time( 'mysql', true ),
				);
				if ( 1 !== $wpdb->insert( $tables['provider_receipts'], $row ) ) {
					return new WP_Error( 'complete99_campaign_receipt_store_failed', 'Manual receipt could not be stored.', array( 'status' => 500 ) );
				}
				return array( 'before_version' => $expected, 'after_version' => $expected, 'response' => array( 'receipt' => self::public_receipt_row( $row ), 'publicationClaim' => false ) );
			}
		);
	}

	/** Record a bounded observed result; users cannot mint verified measurements. */
	public static function rest_results( WP_REST_Request $request ) {
		$id = (string) $request['campaign_id'];
		return self::run_mutation(
			$request,
			'results',
			$id,
			static function ( $identity ) use ( $id ) {
				global $wpdb;
				$loaded = self::load_campaign( $id );
				if ( is_wp_error( $loaded ) ) { return $loaded; }
				$scope = self::require_location_scope( $loaded['state']['locationId'], 'results' );
				if ( is_wp_error( $scope ) ) { return $scope; }
				$expected = self::expected_version( $identity['body'], $loaded );
				if ( is_wp_error( $expected ) ) { return $expected; }
				$metric = self::request_key( $identity['body']['metricKey'] ?? '', 96 );
				if ( is_wp_error( $metric ) ) { return $metric; }
				if ( ! hash_equals( (string) $loaded['state']['governance']['successMetric'], $metric ) ) {
					return new WP_Error( 'complete99_campaign_result_metric_unapproved', 'The result must use the approved success metric.', array( 'status' => 422 ) );
				}
				$value = $identity['body']['value'] ?? null;
				if ( ! is_int( $value ) && ! is_float( $value ) ) {
					return new WP_Error( 'complete99_campaign_result_value_invalid', 'Result value must be a JSON number.', array( 'status' => 422 ) );
				}
				$value = (float) $value;
				if ( ! is_finite( $value ) || abs( $value ) > 1000000000000 ) {
					return new WP_Error( 'complete99_campaign_result_value_invalid', 'Result value is outside the supported range.', array( 'status' => 422 ) );
				}
				$unit = self::request_key( $identity['body']['unit'] ?? '', 32 );
				if ( is_wp_error( $unit ) ) { return $unit; }
				$proof = self::normalize_human_proof( $identity['body'], $loaded );
				if ( is_wp_error( $proof ) ) { return $proof; }
				$result_id = 'res_' . substr( hash( 'sha256', $identity['command_id'] . '|observed-result' ), 0, 48 );
				$row = array( 'result_id' => $result_id, 'campaign_id' => $id, 'campaign_version' => $expected, 'metric_key' => $metric, 'value_decimal' => number_format( $value, 6, '.', '' ), 'unit' => $unit, 'observation_type' => 'observed', 'evidence_level' => 'human_attested', 'source_ref' => $proof['ref'], 'provider_receipt_id' => null, 'observed_at' => current_time( 'mysql', true ), 'created_by' => $identity['actor'], 'created_at' => current_time( 'mysql', true ) );
				$tables = self::table_names();
				if ( 1 !== $wpdb->insert( $tables['results'], $row ) ) {
					return new WP_Error( 'complete99_campaign_result_store_failed', 'Observed result could not be stored.', array( 'status' => 500 ) );
				}
				return array( 'before_version' => $expected, 'after_version' => $expected, 'response' => array( 'result' => self::public_result_row( $row ), 'verified' => false ) );
			}
		);
	}

	/** Open a campaign-linked moderation/escalation issue in the existing Ops ledger. */
	public static function rest_moderation_issues( WP_REST_Request $request ) {
		$id = (string) $request['campaign_id'];
		return self::run_mutation(
			$request,
			'moderation_issues',
			$id,
			static function ( $identity ) use ( $id ) {
				global $wpdb;
				$loaded = self::load_campaign( $id );
				if ( is_wp_error( $loaded ) ) { return $loaded; }
				$scope = self::require_location_scope( $loaded['state']['locationId'], 'moderate' );
				if ( is_wp_error( $scope ) ) { return $scope; }
				$expected = self::expected_version( $identity['body'], $loaded );
				if ( is_wp_error( $expected ) ) { return $expected; }
				$title = self::optional_text( $identity['body']['title'] ?? '', 191, false );
				if ( is_wp_error( $title ) ) { return $title; }
				$summary = self::optional_text( $identity['body']['summary'] ?? '', 2000, false );
				if ( is_wp_error( $summary ) ) { return $summary; }
				$severity = self::required_enum( $identity['body']['severity'] ?? '', array( 'low', 'normal', 'high', 'critical' ), 'Moderation severity is invalid.' );
				if ( is_wp_error( $severity ) ) { return $severity; }
				$assignee = $identity['body']['assigneeUserId'] ?? 0;
				if ( ! is_int( $assignee ) || ! self::accountable_user_is_authorized( $assignee, $loaded['state']['locationId'], self::MODERATE_CAPABILITY, 'moderate' ) ) {
					return new WP_Error( 'complete99_campaign_issue_assignee_invalid', 'Issue assignee must be an authorized moderation user for this location.', array( 'status' => 422 ) );
				}
				$sla = self::request_iso_datetime( $identity['body']['slaDueAt'] ?? '' );
				if ( is_wp_error( $sla ) || strtotime( $sla ) <= time() ) {
					return is_wp_error( $sla ) ? $sla : new WP_Error( 'complete99_campaign_issue_sla_invalid', 'Issue SLA must be in the future.', array( 'status' => 422 ) );
				}
				$issue_id = 'issue_' . substr( hash( 'sha256', $identity['command_id'] . '|campaign-issue' ), 0, 48 );
				$history = array( 'commandId' => $identity['command_id'], 'action' => 'created', 'issueId' => $issue_id, 'status' => 'open', 'severity' => $severity, 'assigneeUserId' => $assignee, 'issueVersion' => 1, 'slaDueAt' => $sla, 'outcome' => '', 'occurredAt' => current_time( 'mysql', true ), 'actorUserId' => $identity['actor'] );
				$details = array( 'schemaVersion' => 'complete99-campaign-moderation-link/v2', 'campaignId' => $id, 'campaignVersion' => $expected, 'campaignStateDigest' => (string) $loaded['row']['state_digest'], 'ownerUserId' => (int) $loaded['state']['governance']['moderationOwnerUserId'], 'escalationOwnerUserId' => (int) $loaded['state']['governance']['escalationOwnerUserId'], 'assigneeUserId' => $assignee, 'severity' => $severity, 'slaDueAt' => $sla, 'summary' => $summary, 'history' => array( $history ) );
				$details_json = self::canonical_json( $details );
				if ( strlen( $details_json ) > self::MAX_EVIDENCE_BYTES ) {
					return new WP_Error( 'complete99_campaign_issue_too_large', 'Moderation evidence exceeds 8 KiB.', array( 'status' => 413 ) );
				}
				$ops = Complete99_Ops::table_names();
				$row = array( 'public_id' => $issue_id, 'location_id' => (int) $loaded['state']['locationId'], 'title' => $title, 'details' => $details_json, 'status' => 'open', 'severity' => $severity, 'reported_by' => $identity['actor'], 'assigned_user_id' => $assignee, 'version' => 1, 'created_at' => current_time( 'mysql', true ), 'updated_at' => current_time( 'mysql', true ) );
				if ( 1 !== $wpdb->insert( $ops['issues'], $row ) ) {
					return new WP_Error( 'complete99_campaign_issue_store_failed', 'Moderation issue could not be stored.', array( 'status' => 500 ) );
				}
				return array( 'before_version' => $expected, 'after_version' => $expected, 'response' => array( 'moderationAction' => $history ) );
			}
		);
	}

	public static function rest_moderation_resolve( WP_REST_Request $request ) { return self::moderation_transition( $request, 'resolve' ); }
	public static function rest_moderation_escalate( WP_REST_Request $request ) { return self::moderation_transition( $request, 'escalate' ); }
	public static function rest_moderation_outcome( WP_REST_Request $request ) { return self::moderation_transition( $request, 'outcome' ); }

	/** Idempotent, optimistic moderation lifecycle transition in the Ops issue ledger. */
	private static function moderation_transition( WP_REST_Request $request, $action ) {
		$campaign_id = (string) $request['campaign_id'];
		$issue_id = (string) $request['issue_id'];
		return self::run_mutation(
			$request,
			'moderation_' . $action,
			$campaign_id,
			static function ( $identity ) use ( $campaign_id, $issue_id, $action ) {
				global $wpdb;
				$loaded = self::load_campaign( $campaign_id );
				if ( is_wp_error( $loaded ) ) { return $loaded; }
				$scope = self::require_location_scope( $loaded['state']['locationId'], 'moderate' );
				if ( is_wp_error( $scope ) ) { return $scope; }
				$expected = self::expected_version( $identity['body'], $loaded );
				if ( is_wp_error( $expected ) ) { return $expected; }
				if ( ! hash_equals( $issue_id, (string) ( $identity['body']['issueId'] ?? '' ) ) ) { return new WP_Error( 'complete99_campaign_issue_identity_mismatch', 'Moderation issue identity is invalid.', array( 'status' => 409 ) ); }
				$issue_expected = $identity['body']['issueExpectedVersion'] ?? null;
				if ( ! is_int( $issue_expected ) || 1 > $issue_expected ) { return new WP_Error( 'complete99_campaign_issue_version_required', 'Exact issueExpectedVersion is required.', array( 'status' => 400 ) ); }
				$ops = Complete99_Ops::table_names();
				$lock = self::is_sqlite_database() ? '' : ' FOR UPDATE';
				$row = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$ops['issues']} WHERE public_id=%s LIMIT 1{$lock}", $issue_id ), ARRAY_A );
				$details = is_array( $row ) ? json_decode( (string) $row['details'], true ) : null;
				if ( ! is_array( $row ) || ! is_array( $details ) || 'complete99-campaign-moderation-link/v2' !== (string) ( $details['schemaVersion'] ?? '' )
					|| ! hash_equals( $campaign_id, (string) ( $details['campaignId'] ?? '' ) ) || (int) $row['location_id'] !== (int) $loaded['state']['locationId'] ) {
					return new WP_Error( 'complete99_campaign_issue_unavailable', 'Moderation issue is unavailable.', array( 'status' => 404 ) );
				}
				if ( (int) $row['version'] !== $issue_expected ) { return new WP_Error( 'complete99_campaign_issue_version_conflict', 'Moderation issue changed; reload before retrying.', array( 'status' => 409, 'currentVersion' => (int) $row['version'] ) ); }
				$allowed = array( 'resolve' => array( 'open', 'escalated' ), 'escalate' => array( 'open' ), 'outcome' => array( 'resolved' ) );
				if ( ! in_array( (string) $row['status'], $allowed[ $action ], true ) ) { return new WP_Error( 'complete99_campaign_issue_transition_invalid', 'Moderation issue cannot make that transition.', array( 'status' => 409 ) ); }
				$reason = self::optional_text( $identity['body']['reason'] ?? '', 500, false );
				if ( is_wp_error( $reason ) ) { return $reason; }
				$final_outcome = null;
				if ( 'outcome' === $action ) {
					$outcome_statement = self::optional_text( $identity['body']['outcome'] ?? '', 1000, false );
					if ( is_wp_error( $outcome_statement ) ) { return $outcome_statement; }
					$final_outcome = array(
						'schemaVersion' => 'complete99-campaign-moderation-outcome/v1',
						'statement'     => $outcome_statement,
						'evidenceLevel' => 'human_attested',
						'provenance'    => 'human_attested_operator_record',
						'actorUserId'   => (int) $identity['actor'],
						'recordedAt'    => gmdate( 'Y-m-d\TH:i:s\Z' ),
					);
				}
				$status = array( 'resolve' => 'resolved', 'escalate' => 'escalated', 'outcome' => 'closed' )[ $action ];
				$assignee = (int) $row['assigned_user_id'];
				if ( 'escalate' === $action ) {
					$assignee = (int) ( $loaded['state']['governance']['escalationOwnerUserId'] ?? 0 );
					if ( ! self::accountable_user_is_authorized( $assignee, $loaded['state']['locationId'], self::MODERATE_CAPABILITY, 'moderate' ) ) { return new WP_Error( 'complete99_campaign_issue_escalation_owner_invalid', 'Escalation owner is no longer authorized.', array( 'status' => 409 ) ); }
				}
				$next_version = $issue_expected + 1;
				$history = array( 'commandId' => $identity['command_id'], 'action' => $action, 'issueId' => $issue_id, 'status' => $status, 'severity' => (string) $row['severity'], 'assigneeUserId' => $assignee, 'issueVersion' => $next_version, 'slaDueAt' => (string) ( $details['slaDueAt'] ?? '' ), 'reason' => $reason, 'finalOutcome' => $final_outcome, 'occurredAt' => current_time( 'mysql', true ), 'actorUserId' => $identity['actor'] );
				$details['assigneeUserId'] = $assignee;
				if ( is_array( $final_outcome ) ) { $details['finalOutcome'] = $final_outcome; }
				$details['history'] = array_values( array_merge( (array) ( $details['history'] ?? array() ), array( $history ) ) );
				$details_json = self::canonical_json( $details );
				if ( strlen( $details_json ) > self::MAX_EVIDENCE_BYTES ) { return new WP_Error( 'complete99_campaign_issue_history_full', 'Moderation issue history reached its bounded evidence limit.', array( 'status' => 507 ) ); }
				$updated = $wpdb->update( $ops['issues'], array( 'details' => $details_json, 'status' => $status, 'assigned_user_id' => $assignee, 'version' => $next_version, 'updated_at' => current_time( 'mysql', true ) ), array( 'id' => (int) $row['id'], 'version' => $issue_expected, 'status' => (string) $row['status'] ) );
				if ( 1 !== $updated ) { return new WP_Error( 'complete99_campaign_issue_concurrent_change', 'Moderation issue changed concurrently.', array( 'status' => 409 ) ); }
				return array( 'before_version' => $expected, 'after_version' => $expected, 'response' => array( 'moderationAction' => $history ) );
			}
		);
	}

	private static function optional_text( $value, $max, $allow_empty = true ) {
		if ( ! is_string( $value ) ) { return new WP_Error( 'complete99_campaign_string_required', 'The field must be a string.', array( 'status' => 422 ) ); }
		$value = sanitize_textarea_field( $value );
		if ( strlen( $value ) > $max || ( ! $allow_empty && '' === trim( $value ) ) ) { return new WP_Error( 'complete99_campaign_string_invalid', 'The field is missing or too long.', array( 'status' => 422 ) ); }
		return $value;
	}

	private static function request_key( $value, $max ) {
		try { return self::bounded_key( $value, $max ); } catch ( \InvalidArgumentException $error ) { return new WP_Error( 'complete99_campaign_key_invalid', $error->getMessage(), array( 'status' => 422 ) ); }
	}

	private static function request_digest( $value ) {
		try { return self::digest_value( $value ); } catch ( \InvalidArgumentException $error ) { return new WP_Error( 'complete99_campaign_digest_invalid', $error->getMessage(), array( 'status' => 422 ) ); }
	}

	private static function required_enum( $value, $allowed, $message ) {
		try { return self::strict_enum( $value, $allowed, $message ); } catch ( \InvalidArgumentException $error ) { return new WP_Error( 'complete99_campaign_enum_invalid', $error->getMessage(), array( 'status' => 422 ) ); }
	}

	private static function request_iso_datetime( $value ) {
		try { return self::iso_datetime( $value ); } catch ( \InvalidArgumentException $error ) { return new WP_Error( 'complete99_campaign_timestamp_invalid', $error->getMessage(), array( 'status' => 422 ) ); }
	}

	/** Invalidate only the low-level keys populated by direct post/postmeta reads. */
	private static function invalidate_private_evidence_cache_keys( $attachment_id, $committed = false ) {
		$attachment_id = (int) $attachment_id;
		if ( 1 > $attachment_id ) { return; }
		wp_cache_delete( $attachment_id, 'posts' );
		wp_cache_delete( 'post_parent:' . $attachment_id, 'posts' );
		wp_cache_delete( $attachment_id, 'post_meta' );
		if ( $committed ) {
			if ( function_exists( 'wp_cache_set_posts_last_changed' ) ) { wp_cache_set_posts_last_changed(); }
			else { wp_cache_set( 'last_changed', microtime(), 'posts' ); }
		}
	}

	private static function private_evidence_transactional_storage_ready() {
		$schema = self::schema_status();
		return ! empty( $schema['ready'] ) && empty( $schema['invalid_engines'] ) && empty( $schema['invalid_core_engines'] )
			? true
			: new WP_Error( 'complete99_campaign_private_transactional_storage_required', 'Private evidence requires transactional wp_posts, wp_postmeta, Ops, and Campaign storage.', array( 'status' => 503 ) );
	}

	private static function private_evidence_root_path() {
		return defined( 'COMPLETE99_PRIVATE_EVIDENCE_DIR' ) ? (string) COMPLETE99_PRIVATE_EVIDENCE_DIR : dirname( untrailingslashit( ABSPATH ), 2 ) . DIRECTORY_SEPARATOR . 'complete99-private-evidence';
	}

	private static function private_evidence_root( $create = false ) {
		$root = self::private_evidence_root_path();
		if ( ! is_string( $root ) || '' === $root || false !== strpos( $root, "\0" ) || is_link( $root ) ) { return new WP_Error( 'complete99_campaign_private_storage_unavailable', 'Private evidence storage path is invalid.', array( 'status' => 503 ) ); }
		if ( $create && ! is_dir( $root ) ) {
			$parent = dirname( $root );
			$parent_real = realpath( $parent );
			$parent_expected = wp_normalize_path( untrailingslashit( $parent ) );
			$parent_observed = false === $parent_real ? '' : wp_normalize_path( untrailingslashit( $parent_real ) );
			$parent_matches = '\\' === DIRECTORY_SEPARATOR ? 0 === strcasecmp( $parent_expected, $parent_observed ) : hash_equals( $parent_expected, $parent_observed );
			if ( ! $parent_matches || is_link( $parent ) || ! wp_mkdir_p( $root ) ) { return new WP_Error( 'complete99_campaign_private_storage_unavailable', 'Private evidence storage could not be created without following links.', array( 'status' => 503 ) ); }
		}
		$resolved = realpath( $root );
		$public_roots = array( realpath( ABSPATH ), realpath( WP_CONTENT_DIR ), realpath( (string) ( $_SERVER['DOCUMENT_ROOT'] ?? '' ) ) );
		$uploads = wp_upload_dir( null, false );
		$public_roots[] = realpath( (string) ( $uploads['basedir'] ?? '' ) );
		if ( false === $resolved || is_link( $root ) ) { return new WP_Error( 'complete99_campaign_private_storage_unavailable', 'Private evidence storage is unavailable.', array( 'status' => 503 ) ); }
		$root_expected = wp_normalize_path( untrailingslashit( $root ) );
		$root_observed = wp_normalize_path( untrailingslashit( $resolved ) );
		$root_matches = '\\' === DIRECTORY_SEPARATOR ? 0 === strcasecmp( $root_expected, $root_observed ) : hash_equals( $root_expected, $root_observed );
		if ( ! $root_matches ) { return new WP_Error( 'complete99_campaign_private_storage_linked', 'Private evidence storage cannot traverse a symbolic-link or junction component.', array( 'status' => 503 ) ); }
		if ( $create && '\\' !== DIRECTORY_SEPARATOR && ( ! chmod( $resolved, 0700 ) || 0700 !== ( fileperms( $resolved ) & 0777 ) ) ) { return new WP_Error( 'complete99_campaign_private_storage_permissions', 'Private evidence storage permissions could not be enforced.', array( 'status' => 503 ) ); }
		$resolved_normal = trailingslashit( wp_normalize_path( $resolved ) );
		foreach ( $public_roots as $public_root ) {
			if ( false !== $public_root && 0 === strpos( $resolved_normal, trailingslashit( wp_normalize_path( $public_root ) ) ) ) {
				return new WP_Error( 'complete99_campaign_private_storage_public', 'Evidence storage must resolve outside every web-served WordPress directory.', array( 'status' => 503 ) );
			}
		}
		return untrailingslashit( $resolved );
	}

	private static function private_evidence_file( $attachment_id ) {
		global $wpdb;
		$root = self::private_evidence_root();
		if ( is_wp_error( $root ) ) { return $root; }
		$wpdb->last_error = '';
		$paths = $wpdb->get_col( $wpdb->prepare( "SELECT meta_value FROM {$wpdb->postmeta} WHERE post_id=%d AND meta_key='_wp_attached_file' ORDER BY meta_id ASC LIMIT 2", (int) $attachment_id ) );
		if ( '' !== (string) $wpdb->last_error || ! is_array( $paths ) || 1 !== count( $paths ) || ! is_string( $paths[0] ) ) { return new WP_Error( 'complete99_campaign_private_path_invalid', 'Evidence has no unique authoritative private path.', array( 'status' => 503 ) ); }
		if ( ! self::private_evidence_path_is_controlled( $paths[0] ) || is_link( $paths[0] ) ) { return new WP_Error( 'complete99_campaign_private_storage_escape', 'Evidence bytes failed the no-follow private-path boundary.', array( 'status' => 422 ) ); }
		$resolved = realpath( $paths[0] );
		if ( false === $resolved || 0 !== strpos( trailingslashit( wp_normalize_path( dirname( $resolved ) ) ), trailingslashit( wp_normalize_path( $root ) ) ) ) {
			return new WP_Error( 'complete99_campaign_private_storage_escape', 'Evidence bytes are not in Complete99 private storage.', array( 'status' => 422 ) );
		}
		return $resolved;
	}

	private static function private_evidence_permissions_ready( $file ) {
		if ( '\\' === DIRECTORY_SEPARATOR ) { return false; }
		$mode = @fileperms( (string) $file );
		return false !== $mode && 0600 === ( $mode & 0777 );
	}

	/** Tri-state direct marker lookup; database uncertainty is never treated as public. */
	private static function private_evidence_marker_state( $attachment_id ) {
		global $wpdb;
		if ( 1 > (int) $attachment_id ) { return 'public'; }
		$marker_key = '_complete99_private_evidence';
		$prefix = '_complete99_evidence_';
		$wpdb->last_error = '';
		$marker_rows = $wpdb->get_results( $wpdb->prepare( "SELECT meta_key,meta_value FROM {$wpdb->postmeta} WHERE post_id=%d AND meta_key=%s ORDER BY meta_id ASC LIMIT 3", (int) $attachment_id, $marker_key ), ARRAY_A );
		$marker_error = (string) $wpdb->last_error;
		$wpdb->last_error = '';
		$shape_rows = $wpdb->get_results( $wpdb->prepare( "SELECT meta_key FROM {$wpdb->postmeta} WHERE post_id=%d AND meta_key LIKE %s ORDER BY meta_id ASC LIMIT 258", (int) $attachment_id, $wpdb->esc_like( $prefix ) . '%' ), ARRAY_A );
		if ( '' !== $marker_error || '' !== (string) $wpdb->last_error || ! is_array( $marker_rows ) || ! is_array( $shape_rows ) || 2 < count( $marker_rows ) || 257 < count( $shape_rows ) ) { return 'error'; }
		$marker_exact = array_values( array_filter( $marker_rows, static function ( $row ) use ( $marker_key ) { return is_array( $row ) && is_string( $row['meta_key'] ?? null ) && hash_equals( $marker_key, (string) $row['meta_key'] ); } ) );
		$marker_yes = array_values( array_filter( $marker_exact, static function ( $row ) { return is_string( $row['meta_value'] ?? null ) && hash_equals( 'yes', (string) $row['meta_value'] ); } ) );
		$shape_exact = array_values( array_filter( $shape_rows, static function ( $row ) use ( $prefix ) { return is_array( $row ) && is_string( $row['meta_key'] ?? null ) && 0 === strpos( (string) $row['meta_key'], $prefix ); } ) );
		$selector_aliases = count( $marker_rows ) !== count( $marker_exact ) || count( $shape_rows ) !== count( $shape_exact );
		if ( empty( $marker_rows ) && empty( $shape_rows ) ) { return 'public'; }
		return ! $selector_aliases && 1 === count( $marker_exact ) && 1 === count( $marker_yes ) ? 'private' : 'error';
	}

	private static function is_private_evidence_attachment_direct( $attachment_id ) {
		return 'public' !== self::private_evidence_marker_state( $attachment_id );
	}

	/** Primitive-capability and active-location check without attachment-cap recursion. */
	private static function private_evidence_actor_mode( $record, $user_id, $require_approve = false ) {
		$user = get_userdata( (int) $user_id );
		if ( ! $user || ! is_array( $record ) ) { return new WP_Error( 'complete99_campaign_private_access_denied', 'Private evidence access is denied.', array( 'status' => 403 ) ); }
		$allcaps = is_array( $user->allcaps ?? null ) ? $user->allcaps : array();
		if ( ! empty( $allcaps['manage_options'] ) ) { return 'custodian'; }
		if ( empty( $allcaps[ self::EVIDENCE_CAPABILITY ] ) ) { return new WP_Error( 'complete99_campaign_private_access_denied', 'Private evidence access is denied.', array( 'status' => 403 ) ); }
		$location_id = (int) ( $record['locationId'] ?? -1 );
		if ( 0 >= $location_id || ! self::accountable_user_is_authorized( (int) $user_id, $location_id, self::EVIDENCE_CAPABILITY, 'evidence' ) ) {
			return new WP_Error( 'complete99_campaign_private_scope_denied', 'Private evidence location scope is denied.', array( 'status' => 403 ) );
		}
		if ( ! $require_approve && (int) ( $record['ownerUserId'] ?? 0 ) === (int) $user_id ) { return 'owner'; }
		if ( empty( $allcaps[ self::APPROVE_CAPABILITY ] ) || ! self::accountable_user_is_authorized( (int) $user_id, $location_id, self::APPROVE_CAPABILITY, 'approve' ) ) {
			return new WP_Error( 'complete99_campaign_private_custody_denied', 'Private evidence custody requires evidence and approval duty at this location.', array( 'status' => 403 ) );
		}
		return 'custodian';
	}

	/** Deny core attachment capabilities; only the protected endpoint may expose bytes. */
	public static function map_private_evidence_meta_cap( $caps, $cap, $user_id, $args ) {
		if ( ! in_array( (string) $cap, array( 'read_post', 'edit_post', 'delete_post' ), true ) || empty( $args[0] ) ) { return $caps; }
		$state = self::private_evidence_marker_state( (int) $args[0] );
		if ( 'public' === $state ) { return $caps; }
		if ( 'error' === $state ) { return array( 'do_not_allow' ); }
		return array( 'do_not_allow' );
	}

	/** Exclude evidence from every generic attachment collection before row materialization. */
	public static function exclude_private_evidence_query( $query ) {
		$query = is_array( $query ) ? $query : array();
		$existing = isset( $query['meta_query'] ) && is_array( $query['meta_query'] ) ? $query['meta_query'] : array();
		$query['meta_query'] = array( 'relation' => 'AND', $existing, array( 'key' => '_complete99_private_evidence', 'compare' => 'NOT EXISTS' ) );
		return $query;
	}

	public static function exclude_private_evidence_posts( $posts, $query ) {
		if ( ! is_array( $posts ) ) { return array(); }
		return array_values( array_filter( $posts, static function ( $post ) {
			if ( ! is_object( $post ) || 'attachment' !== (string) ( $post->post_type ?? '' ) ) { return true; }
			return 'public' === self::private_evidence_marker_state( (int) ( $post->ID ?? 0 ) );
		} ) );
	}

	public static function hide_private_evidence_attachment_js( $response, $attachment, $meta ) {
		$attachment_id = is_object( $attachment ) ? (int) ( $attachment->ID ?? 0 ) : 0;
		return 'public' === self::private_evidence_marker_state( $attachment_id ) ? $response : false;
	}

	public static function hide_private_evidence_attachment_url( $url, $attachment_id ) {
		return 'public' === self::private_evidence_marker_state( (int) $attachment_id ) ? $url : '';
	}

	public static function deny_private_evidence_rest_item( $response, $post, $request ) {
		$post_id = is_object( $post ) ? (int) ( $post->ID ?? 0 ) : 0;
		return 'public' === self::private_evidence_marker_state( $post_id ) ? $response : new WP_Error( 'complete99_campaign_private_core_rest_denied', 'Private evidence is available only through the protected Campaign Studio endpoint.', array( 'status' => 403 ) );
	}

	public static function guard_private_evidence_delete( $delete, $post, $force_delete = false ) {
		$attachment_id = is_object( $post ) ? (int) ( $post->ID ?? 0 ) : (int) $post;
		return self::is_private_evidence_attachment_direct( $attachment_id ) ? false : $delete;
	}

	public static function guard_private_evidence_trash( $trash, $post, $previous_status = '' ) {
		$post_id = is_object( $post ) ? (int) ( $post->ID ?? 0 ) : (int) $post;
		return self::is_private_evidence_attachment_direct( $post_id ) ? false : $trash;
	}

	public static function guard_private_evidence_post_update( $data, $postarr ) {
		$post_id = is_array( $postarr ) ? (int) ( $postarr['ID'] ?? 0 ) : 0;
		$marker_state = 0 < $post_id ? self::private_evidence_marker_state( $post_id ) : 'public';
		if ( 'error' === $marker_state ) { throw new \RuntimeException( 'Private evidence marker truth is unavailable; attachment update denied.' ); }
		if ( 'private' === $marker_state && empty( self::$private_evidence_write_context[ $post_id ] ) ) {
			$data['post_type'] = 'attachment';
			$data['post_status'] = 'private';
		}
		return $data;
	}

	public static function guard_private_evidence_file_move( $file, $attachment_id ) {
		global $wpdb;
		$attachment_id = (int) $attachment_id;
		if ( empty( self::$private_evidence_write_context[ $attachment_id ] ) && self::is_private_evidence_attachment_direct( $attachment_id ) ) {
			$prior = $wpdb->get_var( $wpdb->prepare( "SELECT meta_value FROM {$wpdb->postmeta} WHERE post_id=%d AND meta_key='_wp_attached_file' ORDER BY meta_id ASC LIMIT 1", $attachment_id ) );
			return is_string( $prior ) && '' !== $prior ? $prior : '';
		}
		return $file;
	}

	private static function exact_object_keys( $value, $expected ) {
		if ( ! is_array( $value ) || array_keys( $value ) === range( 0, count( $value ) - 1 ) ) { return false; }
		$actual = array_keys( $value );
		$expected = array_values( (array) $expected );
		sort( $actual, SORT_STRING );
		sort( $expected, SORT_STRING );
		return $actual === $expected;
	}

	/** Fresh direct-DB and byte readback; WordPress object-cache state is never authoritative. */
	private static function private_evidence_authoritative_record( $attachment_id, $expected = array(), $require_bytes = true ) {
		global $wpdb;
		$attachment_id = (int) $attachment_id;
		$lock = self::$transaction_active && ! self::is_sqlite_database() ? ' FOR UPDATE' : '';
		$wpdb->last_error = '';
		$post = $wpdb->get_row( $wpdb->prepare( "SELECT ID,post_type,post_status,post_author,post_mime_type FROM {$wpdb->posts} WHERE ID=%d LIMIT 1{$lock}", $attachment_id ), ARRAY_A );
		$post_error = (string) $wpdb->last_error;
		$wpdb->last_error = '';
		$meta_rows = $wpdb->get_results( $wpdb->prepare( "SELECT meta_id,meta_key,meta_value FROM {$wpdb->postmeta} WHERE post_id=%d ORDER BY meta_id ASC LIMIT 257{$lock}", $attachment_id ), ARRAY_A );
		$meta_error = (string) $wpdb->last_error;
		if ( '' !== $post_error || '' !== $meta_error || ! is_array( $post ) || ! is_array( $meta_rows ) || 256 < count( $meta_rows )
			|| 'attachment' !== (string) ( $post['post_type'] ?? '' ) || 'private' !== (string) ( $post['post_status'] ?? '' ) ) {
			return new WP_Error( 'complete99_campaign_private_readback_invalid', 'Private evidence database truth is incomplete.', array( 'status' => 503 ) );
		}
		$meta = array();
		$commands = array();
		$lifecycle_receipts = array();
		$allowed_evidence_meta = array_fill_keys( array(
			'_complete99_evidence_campaign_id', '_complete99_evidence_command_id', '_complete99_evidence_disposal_residue_path',
			'_complete99_evidence_disposed_at', '_complete99_evidence_disposition_actor_id', '_complete99_evidence_disposition_attempts',
			'_complete99_evidence_disposition_command_id', '_complete99_evidence_disposition_custody_mode', '_complete99_evidence_disposition_journal',
			'_complete99_evidence_disposition_last_error', '_complete99_evidence_disposition_next_attempt_at', '_complete99_evidence_disposition_phase',
			'_complete99_evidence_disposition_reason', '_complete99_evidence_legal_hold', '_complete99_evidence_legal_hold_actor_id',
			'_complete99_evidence_legal_hold_reason', '_complete99_evidence_legal_hold_updated_at', '_complete99_evidence_lifecycle_receipt', '_complete99_evidence_terminal_release_receipt',
			'_complete99_evidence_location_id', '_complete99_evidence_owner_user_id', '_complete99_evidence_retention_state',
