		return array( 'attachmentId' => $attachment_id, 'campaignId' => $campaign_id, 'locationId' => (int) $location_id, 'ownerUserId' => (int) $owner_id, 'originalOwnerUserId' => (int) $owner_id, 'mimeType' => (string) ( $post['post_mime_type'] ?? '' ), 'sha256' => $digest, 'sizeBytes' => (int) $size, 'retentionState' => $retention_state, 'retentionUntil' => $retention_until, 'legalHold' => $legal_hold, 'journalPhase' => $journal_phase, 'commands' => $commands, 'boundCommandIds' => $bound_command_ids, 'lifecycleReceipts' => $lifecycle_receipts, 'lifecycleReceiptCount' => $ordinary_lifecycle_receipt_count, 'terminalReleaseReceipt' => $terminal_release_receipt, 'file' => $file, 'meta' => $meta );
	}

	/**
	 * Enumerate every evidence-shaped attachment and every byte under the private
	 * root. This is the shared fail-closed source for readiness, recovery and
	 * quota; corrupt marker/meta rows and crash-orphan bytes cannot disappear.
	 */
	private static function private_evidence_raw_paths( $attachment_id ) {
		global $wpdb;
		$keys = array( '_wp_attached_file', '_complete99_evidence_upload_target', '_complete99_evidence_upload_staging', '_complete99_evidence_disposal_residue_path' );
		$placeholders = implode( ',', array_fill( 0, count( $keys ), '%s' ) );
		$args = array_merge( array( (int) $attachment_id ), $keys );
		$wpdb->last_error = '';
		$rows = $wpdb->get_results( $wpdb->prepare( "SELECT meta_key,meta_value FROM {$wpdb->postmeta} WHERE post_id=%d AND meta_key IN ({$placeholders}) ORDER BY meta_id ASC LIMIT 9", $args ), ARRAY_A );
		if ( '' !== (string) $wpdb->last_error || ! is_array( $rows ) || 8 < count( $rows ) ) { return new WP_Error( 'complete99_campaign_private_path_projection_unavailable', 'Evidence-shaped path metadata could not be projected within its bound.', array( 'status' => 503 ) ); }
		$paths = array();
		foreach ( $rows as $row ) {
			$value = is_array( $row ) ? (string) ( $row['meta_value'] ?? '' ) : '';
			if ( '' !== $value && false === strpos( $value, "\0" ) ) { $paths[] = wp_normalize_path( untrailingslashit( $value ) ); }
		}
		return array_values( array_unique( $paths ) );
	}

	private static function private_evidence_inventory_projection() {
		global $wpdb;
		// Use the same conservative 4,500-record bound as the protected mutation
		// cohorts so terminal abandoned intents cannot hide active evidence merely
		// by exceeding the live-file quota. Anything beyond it fails readiness.
		$limit = self::CAPACITY_MAX_ROWS + 1;
		$wpdb->last_error = '';
		$marker_ids = $wpdb->get_col( $wpdb->prepare( "SELECT DISTINCT post_id FROM {$wpdb->postmeta} WHERE meta_key=%s ORDER BY post_id ASC LIMIT {$limit}", '_complete99_private_evidence' ) );
		$marker_error = (string) $wpdb->last_error;
		$wpdb->last_error = '';
		$prefix_ids = $wpdb->get_col( $wpdb->prepare( "SELECT DISTINCT post_id FROM {$wpdb->postmeta} WHERE meta_key LIKE %s ORDER BY post_id ASC LIMIT {$limit}", $wpdb->esc_like( '_complete99_evidence_' ) . '%' ) );
		$prefix_error = (string) $wpdb->last_error;
		$ids = is_array( $marker_ids ) && is_array( $prefix_ids ) ? array_values( array_unique( array_map( 'intval', array_merge( $marker_ids, $prefix_ids ) ) ) ) : null;
		if ( is_array( $ids ) ) { sort( $ids, SORT_NUMERIC ); }
		if ( '' !== $marker_error || '' !== $prefix_error || ! is_array( $ids ) || self::CAPACITY_MAX_ROWS < count( $marker_ids ) || self::CAPACITY_MAX_ROWS < count( $prefix_ids ) || self::CAPACITY_MAX_ROWS < count( $ids ) ) {
			return array( 'inspectable' => false, 'ready' => false, 'invalid' => null, 'pending' => null, 'recoverablePending' => array(), 'pathProjectionReady' => false, 'records' => array(), 'totals' => array(), 'campaignTotals' => array(), 'nextAttemptAt' => null );
		}
		$records = array();
		$invalid = array();
		$pending = array();
		$expected_paths = array();
		$path_owners = array();
		$path_projection_ready = true;
		$totals = array( 'files' => 0, 'bytes' => 0 );
		$campaign_totals = array();
		$next_attempt = '';
		foreach ( $ids as $attachment_id ) {
			$attachment_id = (int) $attachment_id;
			$record = self::private_evidence_authoritative_record( $attachment_id, array( 'retentionStates' => array( 'retained', 'upload_pending', 'upload_abandoned', 'disposition_pending', 'disposition_recovery_required', 'disposed' ) ), false );
			if ( is_wp_error( $record ) ) {
				$invalid[ $attachment_id ] = $record->get_error_code();
				$raw_paths = self::private_evidence_raw_paths( $attachment_id );
				if ( is_wp_error( $raw_paths ) ) { $path_projection_ready = false; continue; }
				foreach ( $raw_paths as $raw_path ) { $path_owners[ $raw_path ][] = $attachment_id; $expected_paths[ $raw_path ] = $attachment_id; }
				continue;
			}
			$records[ $attachment_id ] = $record;
			$state = (string) $record['retentionState'];
			$phase = (string) $record['journalPhase'];
			$source = (string) ( $record['meta']['_wp_attached_file'] ?? '' );
			$residue = (string) ( $record['meta']['_complete99_evidence_disposal_residue_path'] ?? '' );
			$staging = (string) ( $record['meta']['_complete99_evidence_upload_staging'] ?? '' );
			$source_state = self::private_evidence_byte_path_state( $source, $record );
			$residue_state = '' === $residue ? 'missing' : self::private_evidence_byte_path_state( $residue, $record );
			$staging_state = '' === $staging ? 'missing' : self::private_evidence_byte_path_state( $staging, $record );
			$matrix_ready = false;
			if ( 'retained' === $state ) { $matrix_ready = 'valid' === $source_state && 'missing' === $residue_state && 'missing' === $staging_state; }
			elseif ( 'upload_pending' === $state ) { $matrix_ready = ( 'missing' === $source_state && in_array( $staging_state, array( 'missing', 'valid' ), true ) || 'valid' === $source_state && 'missing' === $staging_state ) && 'missing' === $residue_state; }
			elseif ( 'upload_abandoned' === $state ) { $matrix_ready = 'missing' === $source_state && 'missing' === $residue_state && 'missing' === $staging_state; }
			elseif ( in_array( $state, array( 'disposition_pending', 'disposition_recovery_required' ), true ) ) { $matrix_ready = 'missing' === $staging_state && ( ( 'valid' === $source_state && 'missing' === $residue_state ) || ( 'missing' === $source_state && 'valid' === $residue_state ) ); }
			elseif ( 'disposed' === $state && 'committed' === $phase ) { $matrix_ready = 'missing' === $staging_state && 'missing' === $source_state && 'valid' === $residue_state; }
			elseif ( 'disposed' === $state && 'complete' === $phase ) {
				$command = (string) ( $record['meta']['_complete99_evidence_disposition_command_id'] ?? '' );
				$deterministic_residue = $source . '.disposing-' . substr( hash( 'sha256', $command ), 0, 16 );
				$matrix_ready = 'missing' === $staging_state && 'missing' === $source_state && 'missing' === $residue_state && 'missing' === self::private_evidence_byte_path_state( $deterministic_residue, $record );
				$deterministic_key = wp_normalize_path( $deterministic_residue );
				$path_owners[ $deterministic_key ][] = $attachment_id;
				$expected_paths[ $deterministic_key ] = $attachment_id;
			}
			if ( ! $matrix_ready ) { $invalid[ $attachment_id ] = 'complete99_campaign_private_byte_matrix_invalid'; }
			foreach ( array_filter( array( $source, $residue, $staging ) ) as $path ) {
				$key = wp_normalize_path( $path );
				$path_owners[ $key ][] = $attachment_id;
				$expected_paths[ $key ] = $attachment_id;
			}
			if ( ! ( 'disposed' === $state && 'complete' === $phase ) && 'upload_abandoned' !== $state ) {
				++$totals['files'];
				$totals['bytes'] += (int) $record['sizeBytes'];
				if ( ! isset( $campaign_totals[ $record['campaignId'] ] ) ) { $campaign_totals[ $record['campaignId'] ] = array( 'files' => 0, 'bytes' => 0 ); }
				++$campaign_totals[ $record['campaignId'] ]['files'];
				$campaign_totals[ $record['campaignId'] ]['bytes'] += (int) $record['sizeBytes'];
			}
			if ( 'upload_pending' === $state || in_array( $state, array( 'disposition_pending', 'disposition_recovery_required' ), true ) || ( 'disposed' === $state && 'complete' !== $phase ) ) {
				$candidate = (string) ( $record['meta']['_complete99_evidence_disposition_next_attempt_at'] ?? '' );
				if ( 'upload_pending' === $state ) { $candidate = (string) ( $record['meta']['_complete99_evidence_upload_next_attempt_at'] ?? '' ); }
				if ( '' !== $candidate && false !== strtotime( $candidate ) && ( '' === $next_attempt || strtotime( $candidate ) < strtotime( $next_attempt ) ) ) { $next_attempt = $candidate; }
				$pending[ $attachment_id ] = array( 'state' => $state, 'nextAttemptAt' => $candidate );
			}
		}
		foreach ( $path_owners as $owners ) {
			$owners = array_values( array_unique( array_map( 'intval', $owners ) ) );
			if ( 1 < count( $owners ) ) { foreach ( $owners as $owner ) { $invalid[ $owner ] = 'complete99_campaign_private_path_shared'; } }
		}
		$root_path = self::private_evidence_root_path();
		$actual_files = 0;
		$actual_bytes = 0;
		if ( is_dir( $root_path ) ) {
			$root = self::private_evidence_root();
			if ( is_wp_error( $root ) ) { return array( 'inspectable' => false, 'ready' => false, 'invalid' => null, 'pending' => null, 'recoverablePending' => array(), 'pathProjectionReady' => false, 'records' => $records, 'totals' => $totals, 'campaignTotals' => $campaign_totals, 'nextAttemptAt' => null ); }
			if ( is_link( $root_path ) || ( '\\' !== DIRECTORY_SEPARATOR && 0700 !== ( fileperms( $root ) & 0777 ) ) ) { $invalid['root'] = 'complete99_campaign_private_root_permissions'; }
			try {
				$iterator = new \RecursiveIteratorIterator( new \RecursiveDirectoryIterator( $root, \FilesystemIterator::SKIP_DOTS ), \RecursiveIteratorIterator::SELF_FIRST );
				$iterator->setMaxDepth( self::PRIVATE_EVIDENCE_ROOT_MAX_DEPTH );
				$entry_count = 0;
				foreach ( $iterator as $entry ) {
					++$entry_count;
					if ( self::PRIVATE_EVIDENCE_ROOT_MAX_ENTRIES < $entry_count || self::PRIVATE_EVIDENCE_ROOT_MAX_DEPTH < $iterator->getDepth() ) { throw new \RuntimeException( 'Private evidence root traversal exceeded its entry or depth bound.' ); }
					$path = wp_normalize_path( $entry->getPathname() );
					if ( $entry->isLink() ) { $invalid[ 'path:' . hash( 'sha256', $path ) ] = 'complete99_campaign_private_root_symlink'; continue; }
					if ( $entry->isDir() ) {
						if ( self::PRIVATE_EVIDENCE_ROOT_MAX_DEPTH <= $iterator->getDepth() ) { $invalid[ 'path:' . hash( 'sha256', $path ) ] = 'complete99_campaign_private_root_depth_exceeded'; }
						if ( '\\' !== DIRECTORY_SEPARATOR && 0700 !== ( $entry->getPerms() & 0777 ) ) { $invalid[ 'path:' . hash( 'sha256', $path ) ] = 'complete99_campaign_private_directory_permissions'; }
						continue;
					}
					if ( ! $entry->isFile() ) { $invalid[ 'path:' . hash( 'sha256', $path ) ] = 'complete99_campaign_private_root_entry_invalid'; continue; }
					++$actual_files;
					if ( self::MAX_PRIVATE_EVIDENCE_FILES_TOTAL * 3 < $actual_files ) { throw new \RuntimeException( 'Private evidence root contains too many files.' ); }
					$bytes = $entry->getSize();
					if ( ! is_int( $bytes ) || 0 > $bytes || PHP_INT_MAX - $actual_bytes < $bytes ) { throw new \RuntimeException( 'Private evidence root byte count is invalid.' ); }
					$actual_bytes += $bytes;
					if ( ! isset( $expected_paths[ $path ] ) ) { $invalid[ 'path:' . hash( 'sha256', $path ) ] = 'complete99_campaign_private_root_orphan'; }
				}
			} catch ( \Throwable $error ) {
				return array( 'inspectable' => false, 'ready' => false, 'invalid' => null, 'pending' => null, 'recoverablePending' => array(), 'pathProjectionReady' => false, 'records' => $records, 'totals' => $totals, 'campaignTotals' => $campaign_totals, 'nextAttemptAt' => null );
			}
		} elseif ( ! empty( $records ) || ! empty( $ids ) ) {
			$invalid['root'] = 'complete99_campaign_private_root_missing';
		}
		$totals['rootFiles'] = $actual_files;
		$totals['rootBytes'] = $actual_bytes;
		$totals['files'] = max( $totals['files'], $actual_files );
		$totals['bytes'] = max( $totals['bytes'], $actual_bytes );
		if ( self::MAX_PRIVATE_EVIDENCE_FILES_TOTAL < $totals['files'] || self::MAX_PRIVATE_EVIDENCE_BYTES_TOTAL < $totals['bytes'] ) { $invalid['quota:global'] = 'complete99_campaign_private_quota_exceeded'; }
		foreach ( $campaign_totals as $campaign_id => $campaign_total ) {
			if ( self::MAX_PRIVATE_EVIDENCE_FILES_PER_CAMPAIGN < (int) $campaign_total['files'] || self::MAX_PRIVATE_EVIDENCE_BYTES_PER_CAMPAIGN < (int) $campaign_total['bytes'] ) { $invalid[ 'quota:' . hash( 'sha256', (string) $campaign_id ) ] = 'complete99_campaign_private_campaign_quota_exceeded'; }
		}
		$recoverable_pending = array();
		if ( $path_projection_ready ) { foreach ( $pending as $attachment_id => $pending_truth ) { if ( ! isset( $invalid[ $attachment_id ] ) ) { $recoverable_pending[ $attachment_id ] = $pending_truth; } } }
		$recoverable_next_attempt = '';
		foreach ( $recoverable_pending as $pending_truth ) {
			$candidate = (string) ( is_array( $pending_truth ) ? ( $pending_truth['nextAttemptAt'] ?? '' ) : '' );
			if ( '' !== $candidate && false !== strtotime( $candidate ) && ( '' === $recoverable_next_attempt || strtotime( $candidate ) < strtotime( $recoverable_next_attempt ) ) ) { $recoverable_next_attempt = $candidate; }
		}
		$invalid_next_attempt = $invalid ? gmdate( 'Y-m-d\TH:i:s\Z', time() + self::AUTHORITY_WATCHDOG_SECONDS ) : '';
		$next_attempt = $recoverable_next_attempt;
		if ( '' !== $invalid_next_attempt && ( '' === $next_attempt || strtotime( $invalid_next_attempt ) < strtotime( $next_attempt ) ) ) { $next_attempt = $invalid_next_attempt; }
		return array( 'inspectable' => true, 'ready' => empty( $pending ) && empty( $invalid ), 'invalid' => $invalid, 'pending' => $pending, 'recoverablePending' => $recoverable_pending, 'recoverableNextAttemptAt' => $recoverable_next_attempt, 'invalidNextAttemptAt' => $invalid_next_attempt, 'pathProjectionReady' => $path_projection_ready, 'records' => $records, 'totals' => $totals, 'campaignTotals' => $campaign_totals, 'nextAttemptAt' => $next_attempt );
	}

	/** Exact private-evidence file/byte totals, including pending intents and root orphans. */
	private static function private_evidence_quota_status( $campaign_id = '' ) {
		$projection = self::private_evidence_inventory_projection();
		if ( empty( $projection['inspectable'] ) || ! empty( $projection['invalid'] ) ) { return new WP_Error( 'complete99_campaign_private_quota_unavailable', 'Private evidence quota could not be verified.', array( 'status' => 503 ) ); }
		if ( '' === (string) $campaign_id ) { return array( 'files' => (int) ( $projection['totals']['files'] ?? 0 ), 'bytes' => (int) ( $projection['totals']['bytes'] ?? 0 ) ); }
		$campaign = $projection['campaignTotals'][ (string) $campaign_id ] ?? array( 'files' => 0, 'bytes' => 0 );
		return array( 'files' => (int) $campaign['files'], 'bytes' => (int) $campaign['bytes'] );
	}

	/** Find the one exact deduplicated attachment bound to this campaign and owner. */
	private static function find_private_evidence_attachment( $campaign_id, $location_id, $owner_id, $digest ) {
		global $wpdb;
		$bindings = array(
			'_complete99_private_evidence' => 'yes',
			'_complete99_evidence_retention_state' => 'retained',
			'_complete99_evidence_campaign_id' => (string) $campaign_id,
			'_complete99_evidence_location_id' => (string) (int) $location_id,
			'_complete99_evidence_owner_user_id' => (string) (int) $owner_id,
			'_complete99_evidence_sha256' => (string) $digest,
		);
		$candidates = null;
		foreach ( $bindings as $meta_key => $meta_value ) {
			$wpdb->last_error = '';
			$rows = $wpdb->get_col( $wpdb->prepare( "SELECT post_id FROM {$wpdb->postmeta} WHERE meta_key=%s AND meta_value=%s ORDER BY post_id ASC,meta_id ASC LIMIT " . ( self::CAPACITY_MAX_ROWS + 1 ), $meta_key, $meta_value ) );
			if ( '' !== (string) $wpdb->last_error || ! is_array( $rows ) || self::CAPACITY_MAX_ROWS < count( $rows ) ) { return new WP_Error( 'complete99_campaign_private_dedupe_unavailable', 'Private evidence identity candidates exceed their protected bound or could not be inspected.', array( 'status' => 503 ) ); }
			$set = array();
			foreach ( $rows as $post_id ) {
				if ( ! is_numeric( $post_id ) || 1 > (int) $post_id ) { return new WP_Error( 'complete99_campaign_private_dedupe_unavailable', 'Private evidence identity contains an invalid attachment candidate.', array( 'status' => 503 ) ); }
				$set[ (int) $post_id ] = true;
			}
			$candidates = null === $candidates ? $set : array_intersect_key( $candidates, $set );
			if ( empty( $candidates ) ) { return 0; }
		}
		$ids = array_map( 'intval', array_keys( (array) $candidates ) );
		if ( 1 < count( $ids ) ) { return new WP_Error( 'complete99_campaign_private_dedupe_unavailable', 'Private evidence identity is duplicated.', array( 'status' => 503 ) ); }
		$attachment_id = (int) $ids[0];
		$record = self::private_evidence_authoritative_record( $attachment_id, array( 'campaignId' => (string) $campaign_id, 'locationId' => (int) $location_id, 'ownerUserId' => (int) $owner_id, 'sha256' => (string) $digest, 'retentionStates' => array( 'retained' ) ), true );
		return is_wp_error( $record ) ? $record : $attachment_id;
	}

	private static function bind_private_evidence_command( $attachment_id, $command_id ) {
		global $wpdb;
		$wpdb->last_error = '';
		$commands = $wpdb->get_col( $wpdb->prepare( "SELECT meta_value FROM {$wpdb->postmeta} WHERE post_id=%d AND meta_key='_complete99_evidence_command_id' ORDER BY meta_id ASC LIMIT %d", (int) $attachment_id, self::PRIVATE_EVIDENCE_MAX_UPLOAD_BINDINGS + 1 ) );
		if ( '' !== (string) $wpdb->last_error || ! is_array( $commands ) || self::PRIVATE_EVIDENCE_MAX_UPLOAD_BINDINGS < count( $commands ) ) { return new WP_Error( 'complete99_campaign_private_command_capacity', 'Private evidence upload replay bindings cannot be extended safely.', array( 'status' => 507 ) ); }
		if ( in_array( (string) $command_id, $commands, true ) ) { return true; }
		if ( self::PRIVATE_EVIDENCE_MAX_UPLOAD_BINDINGS <= count( $commands ) || false === add_post_meta( (int) $attachment_id, '_complete99_evidence_command_id', (string) $command_id, false ) ) { return new WP_Error( 'complete99_campaign_private_command_store', 'Private evidence upload replay binding could not be stored.', array( 'status' => 503 ) ); }
		$verified = self::private_evidence_authoritative_record( (int) $attachment_id, array( 'commandId' => (string) $command_id ), true );
		return is_wp_error( $verified ) ? $verified : true;
	}

	/** Immutable evidence identity stored under the mutation receipt digest. */
	private static function private_evidence_receipt_response( $attachment_id, $digest, $command_id = '' ) {
		$attachment_id = (int) $attachment_id;
		$digest = (string) $digest;
		$expected = array( 'sha256' => $digest );
		if ( '' !== (string) $command_id ) { $expected['commandId'] = (string) $command_id; }
		$record = self::private_evidence_authoritative_record( $attachment_id, $expected, true );
		if ( is_wp_error( $record ) ) { return $record; }
		return array(
			'schemaVersion'    => 'complete99-private-evidence-upload/v3',
			'attachmentId'     => $attachment_id,
			'sha256'           => $digest,
			'campaignId'       => $record['campaignId'],
			'locationId'       => $record['locationId'],
			'ownerUserId'      => $record['ownerUserId'],
			'retentionUntil'   => $record['retentionUntil'],
			'retentionState'   => $record['retentionState'],
			'legalHold'        => $record['legalHold'],
			'publicationClaim' => false,
		);
	}

	/** Add request-ephemeral access only after immutable receipt verification. */
	private static function decorate_mutation_response( $action, $response ) {
		if ( 'evidence_upload' === $action && is_array( $response )
			&& isset( $response['attachmentId'] ) && 0 < (int) $response['attachmentId'] ) {
			$verified = self::private_evidence_authoritative_record( (int) $response['attachmentId'], array( 'campaignId' => (string) ( $response['campaignId'] ?? '' ), 'sha256' => (string) ( $response['sha256'] ?? '' ) ), true );
			if ( ! is_wp_error( $verified ) ) { $response['accessUrl'] = self::private_evidence_access_url( (int) $response['attachmentId'] ); }
		}
		return $response;
	}

	/**
	 * Commit a born-private, hook-suppressed upload intent before any final byte
	 * move. A killed request therefore leaves either no identity or one fully
	 * enumerable upload_pending attachment that replay/recovery can resume.
	 */
	private static function ensure_private_evidence_upload_intent( WP_REST_Request $request, $campaign_id, $file, $checked, $mime, $digest ) {
		global $wpdb;
		$identity = self::mutation_identity( $request, 'evidence_upload' );
		if ( is_wp_error( $identity ) ) { return $identity; }
		$transaction = self::begin_transaction( self::CAPACITY_ROLE_EVIDENCE );
		if ( is_wp_error( $transaction ) ) { return $transaction; }
		$schema = self::private_evidence_transactional_storage_ready();
		if ( is_wp_error( $schema ) ) {
			self::rollback_transaction();
			return $schema;
		}
		$loaded = self::load_campaign( (string) $campaign_id, true );
		if ( is_wp_error( $loaded ) ) { self::rollback_transaction(); return $loaded; }
		$location = (int) $loaded['state']['locationId'];
		$owner = (int) $identity['actor'];
		$scope = self::require_location_scope( $location, 'evidence' );
		if ( is_wp_error( $scope ) ) { self::rollback_transaction(); return $scope; }
		$ops = Complete99_Ops::table_names();
		$lock = self::is_sqlite_database() ? '' : ' FOR UPDATE';
		$wpdb->last_error = '';
		$existing_command = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$ops['commands']} WHERE command_id=%s LIMIT 1{$lock}", $identity['command_id'] ), ARRAY_A );
		if ( '' !== (string) $wpdb->last_error ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_private_intent_command_read_failed', 'Private upload command truth could not be locked.', array( 'status' => 503 ) ); }
		if ( is_array( $existing_command ) && ( (int) $existing_command['actor_user_id'] !== $owner || ! hash_equals( 'campaign.evidence_upload', (string) $existing_command['command_type'] ) || ! hash_equals( (string) $campaign_id, (string) $existing_command['aggregate_id'] ) || ! hash_equals( (string) $identity['payload_digest'], (string) $existing_command['payload_digest'] ) || ! in_array( (string) $existing_command['status'], array( 'received', 'completed' ), true ) ) ) {
			self::rollback_transaction();
			return new WP_Error( 'complete99_campaign_idempotency_reused', 'The Idempotency-Key was already used for a different command.', array( 'status' => 409 ) );
		}
		$wpdb->last_error = '';
		$bound_ids = $wpdb->get_col( $wpdb->prepare( "SELECT post_id FROM {$wpdb->postmeta} WHERE meta_key='_complete99_evidence_command_id' AND meta_value=%s ORDER BY post_id ASC LIMIT 2", $identity['command_id'] ) );
		if ( '' !== (string) $wpdb->last_error || ! is_array( $bound_ids ) || 1 < count( $bound_ids ) ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_private_intent_identity', 'Upload intent identity is unavailable or duplicated.', array( 'status' => 503 ) ); }
