			'_complete99_evidence_legal_hold' => 'no', '_complete99_evidence_disposed_at' => '', '_complete99_evidence_disposition_command_id' => '', '_complete99_evidence_disposal_residue_path' => '',
			'_complete99_evidence_disposition_phase' => 'none', '_complete99_evidence_disposition_journal' => '', '_complete99_evidence_disposition_attempts' => '0', '_complete99_evidence_disposition_next_attempt_at' => '',
			'_complete99_evidence_disposition_last_error' => '', '_complete99_evidence_legal_hold_reason' => '', '_complete99_evidence_legal_hold_updated_at' => '', '_complete99_evidence_legal_hold_actor_id' => '0',
			'_complete99_evidence_terminal_release_receipt' => '',
			'_complete99_evidence_upload_intent' => self::canonical_json( $intent ), '_complete99_evidence_upload_intent_state' => 'pending', '_complete99_evidence_upload_target' => $target, '_complete99_evidence_upload_staging' => $staging,
			'_complete99_evidence_upload_attempts' => '0', '_complete99_evidence_upload_next_attempt_at' => $intent_created_at, '_complete99_evidence_upload_last_error' => '', '_complete99_evidence_upload_abandoned_at' => '',
