		$marker_meta_id = (int) $wpdb->insert_id;
		if ( '' !== (string) $wpdb->last_error || 1 !== $marker_inserted || 1 > $marker_meta_id ) { self::rollback_transaction(); self::invalidate_private_evidence_cache_keys( $attachment_id ); return new WP_Error( 'complete99_campaign_private_intent_marker', 'Private upload intent marker could not be stored first and transactionally.', array( 'status' => 503 ) ); }
