	public static function rest_upload_evidence( WP_REST_Request $request ) {
		$id = (string) $request['campaign_id'];
		$loaded = self::load_campaign( $id );
		if ( is_wp_error( $loaded ) ) { return $loaded; }
		$scope = self::require_location_scope( $loaded['state']['locationId'], 'evidence' );
		if ( is_wp_error( $scope ) ) { return $scope; }
		$files = $request->get_file_params();
		$file = is_array( $files['proof'] ?? null ) ? $files['proof'] : array();
		if ( UPLOAD_ERR_OK !== (int) ( $file['error'] ?? -1 ) || ! is_uploaded_file( (string) ( $file['tmp_name'] ?? '' ) )
			|| 1 > (int) ( $file['size'] ?? 0 ) || self::MAX_PRIVATE_EVIDENCE_FILE_BYTES < (int) $file['size'] ) {
			return new WP_Error( 'complete99_campaign_private_upload_invalid', 'Evidence upload is missing or exceeds 8 MiB.', array( 'status' => 422 ) );
		}
		$checked = wp_check_filetype_and_ext( (string) $file['tmp_name'], sanitize_file_name( (string) ( $file['name'] ?? '' ) ) );
		$mime = (string) ( $checked['type'] ?? '' );
		if ( ! in_array( $mime, array( 'application/pdf', 'image/jpeg', 'image/png', 'image/webp', 'text/plain' ), true ) ) { return new WP_Error( 'complete99_campaign_private_upload_type', 'Evidence file type is not allowed.', array( 'status' => 422 ) ); }
		$digest = (string) hash_file( 'sha256', (string) $file['tmp_name'] );
		if ( ! preg_match( '/\A[a-f0-9]{64}\z/', $digest ) ) { return new WP_Error( 'complete99_campaign_private_upload_digest', 'Evidence digest could not be verified.', array( 'status' => 422 ) ); }
		$intent = self::ensure_private_evidence_upload_intent( $request, $id, $file, $checked, $mime, $digest );
		if ( is_wp_error( $intent ) ) { return $intent; }
		$intent_attachment_id = (int) $intent['attachmentId'];
		$response = self::run_mutation(
			$request,
			'evidence_upload',
			$id,
			static function ( $identity ) use ( $id, $file, $mime, $digest, $intent_attachment_id ) {
				$loaded = self::load_campaign( $id, true );
				if ( is_wp_error( $loaded ) ) { return $loaded; }
				$owner = (int) $identity['actor'];
				$location = (int) $loaded['state']['locationId'];
				$scope = self::require_location_scope( $location, 'evidence' );
				if ( is_wp_error( $scope ) ) { return $scope; }
				$record = self::private_evidence_authoritative_record( $intent_attachment_id, array( 'campaignId' => $id, 'locationId' => $location, 'ownerUserId' => $owner, 'sha256' => $digest, 'sizeBytes' => (int) $file['size'], 'commandId' => $identity['command_id'], 'retentionStates' => array( 'upload_pending', 'retained' ) ), false );
				if ( is_wp_error( $record ) ) { return $record; }
				if ( 'upload_pending' === (string) $record['retentionState'] ) {
					$target = (string) ( $record['meta']['_complete99_evidence_upload_target'] ?? '' );
					$staging = (string) ( $record['meta']['_complete99_evidence_upload_staging'] ?? '' );
					$byte_state = self::private_evidence_byte_path_state( $target, $record );
					$staging_state = self::private_evidence_byte_path_state( $staging, $record );
					if ( 'missing' === $byte_state && 'missing' === $staging_state ) {
						if ( ! self::private_evidence_path_is_controlled( $target ) || ! self::private_evidence_path_is_controlled( $staging ) || false !== @lstat( $target ) || false !== @lstat( $staging ) || ! move_uploaded_file( (string) $file['tmp_name'], $staging ) || ! self::private_evidence_path_is_controlled( $staging ) || is_link( $staging ) ) { return new WP_Error( 'complete99_campaign_private_upload_store', 'Evidence bytes could not be moved into the committed private intent staging path.', array( 'status' => 503 ) ); }
					}
					$staging_state = self::private_evidence_byte_path_state( $staging, $record );
					if ( 'missing' === $byte_state && ( ! self::private_evidence_path_is_controlled( $staging ) || is_link( $staging ) || ! chmod( $staging, 0600 ) || 'valid' !== self::private_evidence_byte_path_state( $staging, $record ) || ! self::private_evidence_path_is_controlled( $target ) || false !== @lstat( $target ) || ! rename( $staging, $target ) || ! self::private_evidence_path_is_controlled( $target ) ) ) { return new WP_Error( 'complete99_campaign_private_upload_stage', 'Evidence bytes could not be verified and atomically promoted from the committed staging path.', array( 'status' => 503 ) ); }
					if ( ! self::private_evidence_path_is_controlled( $target ) || is_link( $target ) || ! chmod( $target, 0600 ) || 'valid' !== self::private_evidence_byte_path_state( $target, $record ) ) { return new WP_Error( 'complete99_campaign_private_upload_permissions', 'Private evidence bytes failed exact target, permission, size, or digest readback.', array( 'status' => 503 ) ); }
					if ( 'missing' !== self::private_evidence_byte_path_state( $staging, $record ) ) { return new WP_Error( 'complete99_campaign_private_upload_staging_residue', 'Private evidence staging bytes remain after atomic promotion.', array( 'status' => 503 ) ); }
					foreach ( array( '_complete99_evidence_upload_intent_state' => 'finalized', '_complete99_evidence_retention_state' => 'retained', '_complete99_evidence_upload_next_attempt_at' => '', '_complete99_evidence_upload_last_error' => '' ) as $key => $value ) {
						$stored = self::set_private_evidence_meta( $intent_attachment_id, $key, $value );
						if ( is_wp_error( $stored ) ) { return $stored; }
					}
				}
				$verified = self::private_evidence_authoritative_record( $intent_attachment_id, array( 'campaignId' => $id, 'locationId' => $location, 'ownerUserId' => $owner, 'sha256' => $digest, 'sizeBytes' => (int) $file['size'], 'commandId' => $identity['command_id'], 'retentionStates' => array( 'retained' ) ), true );
				if ( is_wp_error( $verified ) ) { return $verified; }
				$receipt_response = self::private_evidence_receipt_response( $intent_attachment_id, $digest, $identity['command_id'] );
				if ( is_wp_error( $receipt_response ) ) { return $receipt_response; }
				return array( 'before_version' => (int) $loaded['row']['version'], 'after_version' => (int) $loaded['row']['version'], 'response' => $receipt_response );
			}
		);
		if ( is_wp_error( $response ) ) {
			clean_post_cache( $intent_attachment_id );
			wp_cache_delete( $intent_attachment_id, 'post_meta' );
			$stored = self::private_evidence_authoritative_record( $intent_attachment_id, array( 'campaignId' => $id, 'sha256' => $digest, 'retentionStates' => array( 'upload_pending', 'retained' ) ), false );
			if ( ! is_wp_error( $stored ) ) {
				return new WP_Error( 'complete99_campaign_private_upload_stored_recoverable', 'A protected upload intent is durable; retry the same Idempotency-Key to resume exact finalization.', array( 'status' => 503, 'stored' => true, 'attachmentId' => $intent_attachment_id, 'intentState' => (string) $stored['retentionState'], 'cause' => $response->get_error_code() ) );
			}
		}
		return $response;
	}

	/** Update singleton evidence metadata with exact direct readback. */
	private static function set_private_evidence_meta( $attachment_id, $key, $value ) {
		global $wpdb;
		$attachment_id = (int) $attachment_id;
		$key = (string) $key;
		$value = (string) $value;
		$wpdb->last_error = '';
		$rows = $wpdb->get_results( $wpdb->prepare( "SELECT meta_id,meta_value FROM {$wpdb->postmeta} WHERE post_id=%d AND meta_key=%s ORDER BY meta_id ASC LIMIT 2", $attachment_id, $key ), ARRAY_A );
		if ( '' !== (string) $wpdb->last_error || ! is_array( $rows ) || 1 < count( $rows ) ) { return new WP_Error( 'complete99_campaign_private_meta_unavailable', 'Private evidence metadata is not uniquely writable.', array( 'status' => 503 ) ); }
		if ( empty( $rows ) ) {
			if ( false === add_post_meta( $attachment_id, $key, $value, true ) ) { return new WP_Error( 'complete99_campaign_private_meta_store_failed', 'Private evidence metadata could not be stored.', array( 'status' => 503 ) ); }
		} elseif ( ! hash_equals( (string) $rows[0]['meta_value'], $value ) ) {
			if ( 1 !== $wpdb->update( $wpdb->postmeta, array( 'meta_value' => $value ), array( 'meta_id' => (int) $rows[0]['meta_id'], 'meta_value' => (string) $rows[0]['meta_value'] ) ) ) { return new WP_Error( 'complete99_campaign_private_meta_store_failed', 'Private evidence metadata changed concurrently.', array( 'status' => 409 ) ); }
		}
		clean_post_cache( $attachment_id );
		wp_cache_delete( $attachment_id, 'post_meta' );
		$wpdb->last_error = '';
		$stored = $wpdb->get_var( $wpdb->prepare( "SELECT meta_value FROM {$wpdb->postmeta} WHERE post_id=%d AND meta_key=%s ORDER BY meta_id ASC LIMIT 1", $attachment_id, $key ) );
		return '' === (string) $wpdb->last_error && is_string( $stored ) && hash_equals( $value, $stored )
			? true
			: new WP_Error( 'complete99_campaign_private_meta_readback_failed', 'Private evidence metadata failed exact readback.', array( 'status' => 503 ) );
	}

	private static function private_evidence_reference_counts_batch( $records, $location_id ) {
		global $wpdb;
		$records = array_values( (array) $records );
		if ( empty( $records ) ) { return array(); }
		if ( 100 < count( $records ) ) { return new WP_Error( 'complete99_campaign_private_reference_batch_bound', 'Private evidence references exceed their 100-record inspection bound.', array( 'status' => 503 ) ); }
		$tables = self::table_names();
		$references = array();
		$reference_to_id = array();
		$counts = array();
		foreach ( $records as $record ) {
			if ( ! is_array( $record ) || ! is_int( $record['attachmentId'] ?? null ) || 1 > $record['attachmentId'] || ! is_string( $record['sha256'] ?? null ) || ! preg_match( '/\A[a-f0-9]{64}\z/', $record['sha256'] ) || (int) ( $record['locationId'] ?? -1 ) !== (int) $location_id ) {
				return new WP_Error( 'complete99_campaign_private_reference_batch_shape', 'Private evidence reference input is not exactly bound.', array( 'status' => 503 ) );
			}
			$reference = 'c99-private-attachment:' . $record['attachmentId'] . '#sha256=' . $record['sha256'];
			if ( isset( $reference_to_id[ $reference ] ) || isset( $counts[ $record['attachmentId'] ] ) ) { return new WP_Error( 'complete99_campaign_private_reference_batch_duplicate', 'Private evidence reference input is duplicated.', array( 'status' => 503 ) ); }
			$references[] = $reference;
			$reference_to_id[ $reference ] = $record['attachmentId'];
			$counts[ $record['attachmentId'] ] = array( 'providerReceipts' => 0, 'results' => 0, 'moderationIssues' => 0, 'total' => 0 );
		}
		$placeholders = implode( ',', array_fill( 0, count( $references ), '%s' ) );
		$grouped_queries = array( 'providerReceipts' => array( $tables['provider_receipts'], 'proof_ref' ), 'results' => array( $tables['results'], 'source_ref' ) );
		foreach ( $grouped_queries as $count_key => $query ) {
			$wpdb->last_error = '';
			$rows = $wpdb->get_results( $wpdb->prepare( "SELECT {$query[1]} AS evidence_reference,COUNT(*) AS reference_count FROM {$query[0]} WHERE {$query[1]} IN ({$placeholders}) GROUP BY {$query[1]} ORDER BY {$query[1]} ASC LIMIT 101", $references ), ARRAY_A );
			if ( '' !== (string) $wpdb->last_error || ! is_array( $rows ) || 100 < count( $rows ) ) { return new WP_Error( 'complete99_campaign_private_reference_query_failed', 'Private evidence references could not be inspected in one bounded projection.', array( 'status' => 503 ) ); }
			$seen = array();
			foreach ( $rows as $row ) {
				$reference = is_array( $row ) && is_string( $row['evidence_reference'] ?? null ) ? $row['evidence_reference'] : '';
				$count = is_array( $row ) ? ( $row['reference_count'] ?? null ) : null;
				if ( ! isset( $reference_to_id[ $reference ] ) || isset( $seen[ $reference ] ) || ! is_numeric( $count ) || 0 > (int) $count ) { return new WP_Error( 'complete99_campaign_private_reference_shape_invalid', 'Private evidence grouped reference truth is invalid.', array( 'status' => 503 ) ); }
				$seen[ $reference ] = true;
				$counts[ $reference_to_id[ $reference ] ][ $count_key ] = (int) $count;
			}
		}
		$ops = Complete99_Ops::table_names();
		$wpdb->last_error = '';
		$issues = $wpdb->get_results( $wpdb->prepare( "SELECT details FROM {$ops['issues']} WHERE location_id=%d ORDER BY id ASC LIMIT %d", (int) $location_id, self::CAPACITY_MAX_ROWS + 1 ), ARRAY_A );
		if ( '' !== (string) $wpdb->last_error || ! is_array( $issues ) || self::CAPACITY_MAX_ROWS < count( $issues ) ) { return new WP_Error( 'complete99_campaign_private_moderation_reference_query_failed', 'Moderation references could not be proven absent.', array( 'status' => 503 ) ); }
		foreach ( $issues as $issue ) {
			if ( ! is_array( $issue ) || ! is_string( $issue['details'] ?? null ) || self::MAX_EVIDENCE_BYTES < strlen( $issue['details'] ) ) { return new WP_Error( 'complete99_campaign_private_moderation_reference_shape', 'Moderation reference shape is invalid.', array( 'status' => 503 ) ); }
			$details = json_decode( $issue['details'], true );
			if ( ! is_array( $details ) ) { return new WP_Error( 'complete99_campaign_private_moderation_reference_shape', 'Moderation reference shape is invalid.', array( 'status' => 503 ) ); }
			$stack = array( array( 'value' => $details, 'depth' => 0 ) );
			$visited = 0;
			$matched = array();
			while ( ! empty( $stack ) ) {
				$node = array_pop( $stack );
				if ( 1024 < ++$visited || 16 < (int) $node['depth'] ) { return new WP_Error( 'complete99_campaign_private_moderation_reference_shape', 'Moderation reference nesting exceeds its inspection bound.', array( 'status' => 503 ) ); }
				$value = $node['value'];
				if ( is_string( $value ) && isset( $reference_to_id[ $value ] ) ) { $matched[ $reference_to_id[ $value ] ] = true; continue; }
				if ( ! is_array( $value ) ) { continue; }
				foreach ( $value as $child ) { $stack[] = array( 'value' => $child, 'depth' => (int) $node['depth'] + 1 ); }
			}
			foreach ( array_keys( $matched ) as $attachment_id ) { ++$counts[ $attachment_id ]['moderationIssues']; }
		}
		foreach ( $counts as &$record_counts ) { $record_counts['total'] = $record_counts['providerReceipts'] + $record_counts['results'] + $record_counts['moderationIssues']; }
		unset( $record_counts );
		return $counts;
	}

	private static function private_evidence_reference_counts( $attachment_id, $digest, $location_id ) {
		$batch = self::private_evidence_reference_counts_batch( array( array( 'attachmentId' => (int) $attachment_id, 'sha256' => (string) $digest, 'locationId' => (int) $location_id ) ), (int) $location_id );
		return is_wp_error( $batch ) ? $batch : ( $batch[ (int) $attachment_id ] ?? new WP_Error( 'complete99_campaign_private_reference_missing', 'Private evidence reference truth is missing.', array( 'status' => 503 ) ) );
	}

	private static function private_evidence_has_references( $attachment_id, $digest, $location_id ) {
		$counts = self::private_evidence_reference_counts( $attachment_id, $digest, $location_id );
		return is_wp_error( $counts ) ? $counts : 0 < (int) $counts['total'];
	}

	private static function private_evidence_eligibility( $record, $campaign, $counts = null ) {
		if ( null === $counts ) { $counts = self::private_evidence_reference_counts( $record['attachmentId'], $record['sha256'], $record['locationId'] ); }
		if ( is_wp_error( $counts ) ) { return $counts; }
		$reasons = array();
		if ( 'upload_abandoned' === (string) ( $record['retentionState'] ?? '' ) ) { $reasons[] = 'upload_abandoned'; }
		if ( ! in_array( (string) ( $campaign['state']['runtime']['lifecycleState'] ?? '' ), array( 'completed', 'expired', 'cancelled_internal', 'superseded' ), true ) ) { $reasons[] = 'campaign_nonterminal'; }
		if ( strtotime( (string) $record['retentionUntil'] ) > time() ) { $reasons[] = 'retention_active'; }
		if ( 'no' !== (string) $record['legalHold'] ) { $reasons[] = 'legal_hold'; }
		if ( 0 < (int) $counts['total'] ) { $reasons[] = 'referenced'; }
		if ( 'retained' !== (string) $record['retentionState'] ) { $reasons[] = 'disposition_in_progress'; }
		return array( 'eligible' => empty( $reasons ), 'reasons' => $reasons, 'referenceCounts' => $counts );
	}

	/** Protected, actor-scoped evidence inventory; campaign detail never embeds it. */
	public static function rest_evidence_inventory( WP_REST_Request $request ) {
		$campaign_id = (string) $request['campaign_id'];
		$campaign = self::load_campaign( $campaign_id );
		if ( is_wp_error( $campaign ) ) { return $campaign; }
		$actor = get_current_user_id();
		$owner_probe = array( 'locationId' => (int) $campaign['state']['locationId'], 'ownerUserId' => $actor );
		$owner_mode = self::private_evidence_actor_mode( $owner_probe, $actor, false );
		if ( is_wp_error( $owner_mode ) ) { return $owner_mode; }
		$custodian_mode = self::private_evidence_actor_mode( $owner_probe, $actor, true );
		$is_custodian = ! is_wp_error( $custodian_mode );
		$projection = self::private_evidence_inventory_projection();
		if ( empty( $projection['inspectable'] ) || ! empty( $projection['invalid'] ) ) { return new WP_Error( 'complete99_campaign_private_inventory_unavailable', 'Protected evidence inventory is unavailable while any evidence-shaped record or private-root byte is unverified.', array( 'status' => 503 ) ); }
		$ids = array();
		foreach ( (array) $projection['records'] as $attachment_id => $record ) {
			if ( ! is_array( $record ) || ! hash_equals( $campaign_id, (string) $record['campaignId'] ) || (int) $campaign['state']['locationId'] !== (int) $record['locationId']
				|| ! in_array( (string) $record['retentionState'], array( 'retained', 'upload_abandoned', 'disposition_pending', 'disposition_recovery_required' ), true )
				|| ( ! $is_custodian && (int) $record['ownerUserId'] !== $actor ) ) { continue; }
			$ids[] = (int) $attachment_id;
		}
		sort( $ids, SORT_NUMERIC );
		if ( 100 < count( $ids ) ) { return new WP_Error( 'complete99_campaign_private_inventory_unavailable', 'Protected evidence inventory cannot be proven within its 100-record bound.', array( 'status' => 503 ) ); }
		$inventory_records = array();
		foreach ( $ids as $attachment_id ) {
			$record = self::private_evidence_authoritative_record( (int) $attachment_id, array( 'campaignId' => $campaign_id, 'locationId' => (int) $campaign['state']['locationId'], 'retentionStates' => array( 'retained', 'upload_abandoned', 'disposition_pending', 'disposition_recovery_required' ) ), false );
			if ( is_wp_error( $record ) ) { return $record; }
			if ( 'retained' === $record['retentionState'] ) {
				$record = self::private_evidence_authoritative_record( (int) $attachment_id, array( 'campaignId' => $campaign_id, 'locationId' => (int) $campaign['state']['locationId'], 'retentionStates' => array( 'retained' ) ), true );
				if ( is_wp_error( $record ) ) { return $record; }
			}
			$inventory_records[ (int) $attachment_id ] = $record;
		}
		$reference_counts = self::private_evidence_reference_counts_batch( array_values( $inventory_records ), (int) $campaign['state']['locationId'] );
		if ( is_wp_error( $reference_counts ) ) { return $reference_counts; }
		$items = array();
		foreach ( $ids as $attachment_id ) {
			$record = $inventory_records[ (int) $attachment_id ];
			$mode = self::private_evidence_actor_mode( $record, $actor, false );
			if ( is_wp_error( $mode ) ) { return $mode; }
			$eligibility = self::private_evidence_eligibility( $record, $campaign, $reference_counts[ (int) $attachment_id ] ?? null );
			if ( is_wp_error( $eligibility ) ) { return $eligibility; }
			$hold_mode = self::private_evidence_actor_mode( $record, $actor, true );
			$access_url = '';
			if ( 'retained' === $record['retentionState'] ) { $access_url = self::private_evidence_access_url( (int) $attachment_id ); }
			$items[] = array(
				'attachmentId' => (int) $attachment_id, 'sha256' => $record['sha256'], 'sizeBytes' => $record['sizeBytes'], 'mimeType' => $record['mimeType'],
				'originalOwnerUserId' => $record['ownerUserId'], 'retentionState' => $record['retentionState'], 'retentionUntil' => $record['retentionUntil'],
				'legalHold' => 'yes' === $record['legalHold'], 'referenceCounts' => $eligibility['referenceCounts'], 'eligibleToDispose' => (bool) $eligibility['eligible'],
				'eligibilityReasons' => $eligibility['reasons'], 'accessUrl' => $access_url, 'canDispose' => (bool) $eligibility['eligible'],
				'canSetLegalHold' => 'upload_abandoned' !== $record['retentionState'] && ! is_wp_error( $hold_mode ) && 'no' === $record['legalHold'], 'canReleaseLegalHold' => 'upload_abandoned' !== $record['retentionState'] && ! is_wp_error( $hold_mode ) && 'yes' === $record['legalHold'],
				'custodyMode' => $mode,
			);
		}
		return rest_ensure_response( array( 'schemaVersion' => 1, 'campaignId' => $campaign_id, 'locationId' => (int) $campaign['state']['locationId'], 'custodyMode' => $is_custodian ? 'custodian' : 'owner', 'items' => $items ) );
	}

	private static function private_evidence_hold_response( $record, $command_id, $actor, $mode, $reason ) {
		return array( 'schemaVersion' => 'complete99-private-evidence-legal-hold/v1', 'attachmentId' => (int) $record['attachmentId'], 'campaignId' => $record['campaignId'], 'originalOwnerUserId' => (int) $record['ownerUserId'], 'custodianActorId' => (int) $actor, 'custodyMode' => (string) $mode, 'legalHold' => 'yes' === $record['legalHold'], 'reason' => (string) $reason, 'legalHoldCommandId' => (string) $command_id, 'publicationClaim' => false );
	}

	public static function rest_evidence_legal_hold( WP_REST_Request $request ) {
		$campaign_id = (string) $request['campaign_id'];
		$attachment_id = (int) $request['attachment_id'];
		return self::run_mutation( $request, 'evidence_legal_hold', $campaign_id, static function ( $identity ) use ( $campaign_id, $attachment_id ) {
			$storage = self::private_evidence_transactional_storage_ready();
			if ( is_wp_error( $storage ) ) { return $storage; }
			if ( ! is_int( $identity['body']['attachmentId'] ?? null ) || $attachment_id !== (int) $identity['body']['attachmentId'] || ! is_bool( $identity['body']['legalHold'] ?? null ) ) { return new WP_Error( 'complete99_campaign_private_hold_identity', 'Legal-hold command must bind the exact attachment and boolean state.', array( 'status' => 422 ) ); }
			$reason = self::optional_text( $identity['body']['reason'] ?? '', 500, false );
			if ( is_wp_error( $reason ) ) { return $reason; }
			$campaign = self::load_campaign( $campaign_id, true );
			if ( is_wp_error( $campaign ) ) { return $campaign; }
			$record = self::private_evidence_authoritative_record( $attachment_id, array( 'campaignId' => $campaign_id, 'locationId' => (int) $campaign['state']['locationId'], 'retentionStates' => array( 'retained' ) ), true );
			if ( is_wp_error( $record ) ) { return $record; }
			$mode = self::private_evidence_actor_mode( $record, (int) $identity['actor'], true );
			if ( is_wp_error( $mode ) ) { return $mode; }
			$hold = $identity['body']['legalHold'] ? 'yes' : 'no';
			if ( hash_equals( (string) $record['legalHold'], $hold ) ) { return new WP_Error( 'complete99_campaign_private_hold_unchanged', 'Legal-hold state is already exact; no receipt was consumed.', array( 'status' => 409 ) ); }
			$receipt_count = (int) ( $record['lifecycleReceiptCount'] ?? count( (array) $record['lifecycleReceipts'] ) );
			if ( 'yes' === $hold && self::PRIVATE_EVIDENCE_MAX_LIFECYCLE_RECEIPTS - self::PRIVATE_EVIDENCE_LIFECYCLE_RELEASE_RESERVE <= $receipt_count ) { return new WP_Error( 'complete99_campaign_private_hold_release_reserve', 'Legal hold cannot consume the reserved release receipt.', array( 'status' => 507 ) ); }
			$terminal_release = 'no' === $hold && self::PRIVATE_EVIDENCE_MAX_LIFECYCLE_RECEIPTS <= $receipt_count;
			if ( $terminal_release && ( 'custodian' !== $mode || '' !== (string) ( $record['terminalReleaseReceipt'] ?? '' ) ) ) { return new WP_Error( 'complete99_campaign_private_hold_terminal_release_denied', 'A full lifecycle ledger may be released only once by an exact custodian terminal-release receipt.', array( 'status' => 507 ) ); }
			foreach ( array( '_complete99_evidence_legal_hold' => $hold, '_complete99_evidence_legal_hold_reason' => $reason, '_complete99_evidence_legal_hold_updated_at' => gmdate( 'Y-m-d\TH:i:s\Z' ), '_complete99_evidence_legal_hold_actor_id' => (string) $identity['actor'] ) as $key => $value ) {
				$stored = self::set_private_evidence_meta( $attachment_id, $key, $value );
				if ( is_wp_error( $stored ) ) { return $stored; }
			}
			$receipt_record = $record;
			$receipt_record['legalHold'] = $hold;
			$response = self::private_evidence_hold_response( $receipt_record, $identity['command_id'], $identity['actor'], $mode, $reason );
			$receipt_json = self::canonical_json( array( 'commandId' => $identity['command_id'], 'response' => $response ) );
			if ( $terminal_release ) {
				$stored_terminal = self::set_private_evidence_meta( $attachment_id, '_complete99_evidence_terminal_release_receipt', $receipt_json );
				if ( is_wp_error( $stored_terminal ) ) { return $stored_terminal; }
			} elseif ( false === add_post_meta( $attachment_id, '_complete99_evidence_lifecycle_receipt', $receipt_json, false ) ) { return new WP_Error( 'complete99_campaign_private_hold_receipt_store', 'Legal-hold receipt could not be stored.', array( 'status' => 507 ) ); }
			$verified_receipt = self::private_evidence_lifecycle_receipt( $attachment_id, $identity['command_id'] );
			if ( is_wp_error( $verified_receipt ) || ! hash_equals( hash( 'sha256', self::canonical_json( $response ) ), hash( 'sha256', self::canonical_json( $verified_receipt ) ) ) ) { return is_wp_error( $verified_receipt ) ? $verified_receipt : new WP_Error( 'complete99_campaign_private_hold_receipt_readback', 'Legal-hold receipt failed exact readback.', array( 'status' => 503 ) ); }
			return array( 'before_version' => (int) $campaign['row']['version'], 'after_version' => (int) $campaign['row']['version'], 'response' => $response );
		} );
	}

	private static function private_evidence_lifecycle_receipt( $attachment_id, $command_id ) {
		$record = self::private_evidence_authoritative_record( (int) $attachment_id, array( 'retentionStates' => array( 'retained', 'upload_abandoned', 'disposition_pending', 'disposition_recovery_required', 'disposed' ) ), false );
		if ( is_wp_error( $record ) ) { return $record; }
		$matched = array();
		foreach ( $record['lifecycleReceipts'] as $json ) {
			$decoded = json_decode( $json, true );
			if ( is_array( $decoded ) && hash_equals( (string) $command_id, (string) ( $decoded['commandId'] ?? '' ) ) && is_array( $decoded['response'] ?? null ) ) { $matched[] = $decoded['response']; }
		}
		return 1 === count( $matched ) ? $matched[0] : new WP_Error( 'complete99_campaign_private_lifecycle_receipt_invalid', 'Private evidence lifecycle receipt is missing or duplicated.', array( 'status' => 503 ) );
	}

	private static function private_evidence_disposition_response( $attachment_id, $command_id ) {
		$record = self::private_evidence_authoritative_record( (int) $attachment_id, array( 'retentionStates' => array( 'disposition_pending', 'disposition_recovery_required', 'disposed' ) ), false );
		if ( is_wp_error( $record ) || ! hash_equals( (string) $command_id, (string) ( $record['meta']['_complete99_evidence_disposition_command_id'] ?? '' ) ) ) { return new WP_Error( 'complete99_campaign_private_disposition_unavailable', 'Private evidence disposition receipt cannot be reconstructed.', array( 'status' => 503 ) ); }
		return array( 'schemaVersion' => 'complete99-private-evidence-disposition/v2', 'attachmentId' => (int) $attachment_id, 'campaignId' => $record['campaignId'], 'sha256' => $record['sha256'], 'originalOwnerUserId' => $record['ownerUserId'], 'custodianActorId' => (int) ( $record['meta']['_complete99_evidence_disposition_actor_id'] ?? 0 ), 'custodyMode' => (string) ( $record['meta']['_complete99_evidence_disposition_custody_mode'] ?? '' ), 'reason' => (string) ( $record['meta']['_complete99_evidence_disposition_reason'] ?? '' ), 'retentionUntil' => $record['retentionUntil'], 'dispositionCommandId' => (string) $command_id, 'dispositionAccepted' => true, 'publicationClaim' => false );
	}

	public static function rest_dispose_evidence( WP_REST_Request $request ) {
		$id = (string) $request['campaign_id'];
		$attachment_id = (int) $request['attachment_id'];
		$response = self::run_mutation(
			$request,
			'evidence_dispose',
			$id,
			static function ( $identity ) use ( $id, $attachment_id ) {
				$storage = self::private_evidence_transactional_storage_ready();
				if ( is_wp_error( $storage ) ) { return $storage; }
				if ( ! is_int( $identity['body']['attachmentId'] ?? null ) || (int) $identity['body']['attachmentId'] !== $attachment_id ) { return new WP_Error( 'complete99_campaign_private_disposition_identity', 'Disposition body must bind the exact route attachment.', array( 'status' => 422 ) ); }
				$loaded = self::load_campaign( $id, true );
				if ( is_wp_error( $loaded ) ) { return $loaded; }
				$scope = self::require_location_scope( $loaded['state']['locationId'], 'evidence' );
				if ( is_wp_error( $scope ) ) { return $scope; }
				$record = self::private_evidence_authoritative_record( $attachment_id, array( 'campaignId' => $id, 'locationId' => (int) $loaded['state']['locationId'], 'retentionStates' => array( 'retained' ) ), true );
				if ( is_wp_error( $record ) ) { return $record; }
				$mode = self::private_evidence_actor_mode( $record, (int) $identity['actor'], false );
				if ( is_wp_error( $mode ) ) { return $mode; }
				$reason = self::optional_text( $identity['body']['reason'] ?? '', 500, false );
				if ( is_wp_error( $reason ) ) { return $reason; }
				if ( ! in_array( (string) $loaded['state']['runtime']['lifecycleState'], array( 'completed', 'expired', 'cancelled_internal', 'superseded' ), true ) ) { return new WP_Error( 'complete99_campaign_private_disposition_nonterminal', 'Private evidence can be disposed only after the campaign is terminal.', array( 'status' => 409 ) ); }
				if ( strtotime( $record['retentionUntil'] ) > time() ) { return new WP_Error( 'complete99_campaign_private_disposition_retained', 'Private evidence is still inside its 365-day retention period.', array( 'status' => 409 ) ); }
				if ( 'no' !== $record['legalHold'] ) { return new WP_Error( 'complete99_campaign_private_disposition_legal_hold', 'Private evidence is under legal hold.', array( 'status' => 409 ) ); }
				$referenced = self::private_evidence_has_references( $attachment_id, $record['sha256'], $record['locationId'] );
				if ( is_wp_error( $referenced ) ) { return $referenced; }
				if ( $referenced ) { return new WP_Error( 'complete99_campaign_private_disposition_referenced', 'Private evidence is still referenced by a receipt, result, or moderation record.', array( 'status' => 409 ) ); }
				$source = $record['file'];
				$residue = $source . '.disposing-' . substr( hash( 'sha256', (string) $identity['command_id'] ), 0, 16 );
				$journal = array( 'schemaVersion' => 'complete99-private-evidence-disposition-journal/v1', 'phase' => 'prepared', 'attachmentId' => $attachment_id, 'campaignId' => $id, 'locationId' => $record['locationId'], 'originalOwnerUserId' => $record['ownerUserId'], 'custodianActorId' => (int) $identity['actor'], 'custodyMode' => $mode, 'reason' => $reason, 'commandId' => $identity['command_id'], 'sha256' => $record['sha256'], 'sizeBytes' => $record['sizeBytes'], 'sourcePathDigest' => hash( 'sha256', wp_normalize_path( $source ) ), 'residuePath' => $residue, 'preparedAt' => gmdate( 'Y-m-d\TH:i:s\Z' ) );
				foreach ( array( '_complete99_evidence_disposition_command_id' => $identity['command_id'], '_complete99_evidence_disposition_actor_id' => (string) $identity['actor'], '_complete99_evidence_disposition_custody_mode' => $mode, '_complete99_evidence_disposition_reason' => $reason, '_complete99_evidence_disposal_residue_path' => $residue, '_complete99_evidence_disposition_journal' => self::canonical_json( $journal ), '_complete99_evidence_disposition_phase' => 'prepared', '_complete99_evidence_retention_state' => 'disposition_pending' ) as $key => $value ) {
					$stored = self::set_private_evidence_meta( $attachment_id, $key, $value );
					if ( is_wp_error( $stored ) ) { return $stored; }
				}
				$receipt = self::private_evidence_disposition_response( $attachment_id, $identity['command_id'] );
				if ( is_wp_error( $receipt ) ) { return $receipt; }
				return array( 'before_version' => (int) $loaded['row']['version'], 'after_version' => (int) $loaded['row']['version'], 'response' => $receipt );
			}
		);
		if ( is_wp_error( $response ) ) { clean_post_cache( $attachment_id ); wp_cache_delete( $attachment_id, 'post_meta' ); return $response; }
		$data = $response instanceof WP_REST_Response ? $response->get_data() : null;
		$command_id = is_array( $data ) ? (string) ( $data['dispositionCommandId'] ?? '' ) : '';
		$finalized = self::finalize_private_evidence_disposition( $attachment_id, $command_id );
		if ( is_wp_error( $finalized ) ) {
			$retry_at = self::record_private_evidence_disposition_retry( $attachment_id, $finalized->get_error_code() );
			if ( ! is_wp_error( $retry_at ) ) { self::enqueue_reconcile_trigger( $retry_at ); }
			return new WP_Error( 'complete99_campaign_private_disposition_pending', 'Disposition was recorded, but byte cleanup remains pending; replay the same command.', array( 'status' => 503, 'stored' => true ) );
		}
		return $response;
	}

	private static function finalize_private_evidence_disposition( $attachment_id, $command_id ) {
		$attachment_id = (int) $attachment_id;
		$record = self::private_evidence_authoritative_record( $attachment_id, array( 'commandId' => (string) $command_id, 'retentionStates' => array( 'disposition_pending', 'disposition_recovery_required', 'disposed' ) ), false );
		if ( is_wp_error( $record ) || ! hash_equals( (string) $command_id, (string) ( $record['meta']['_complete99_evidence_disposition_command_id'] ?? '' ) ) ) { return is_wp_error( $record ) ? $record : new WP_Error( 'complete99_campaign_private_disposition_binding_invalid', 'Disposition binding is invalid.' ); }
		$journal = json_decode( (string) ( $record['meta']['_complete99_evidence_disposition_journal'] ?? '' ), true );
		if ( ! is_array( $journal ) || 'complete99-private-evidence-disposition-journal/v1' !== (string) ( $journal['schemaVersion'] ?? '' )
			|| ! hash_equals( (string) $command_id, (string) ( $journal['commandId'] ?? '' ) ) || $attachment_id !== (int) ( $journal['attachmentId'] ?? 0 )
			|| ! hash_equals( $record['sha256'], (string) ( $journal['sha256'] ?? '' ) ) || $record['sizeBytes'] !== (int) ( $journal['sizeBytes'] ?? -1 )
			|| ! hash_equals( (string) $record['journalPhase'], (string) ( $journal['phase'] ?? '' ) )
			|| ! hash_equals( (string) ( $record['meta']['_complete99_evidence_disposal_residue_path'] ?? '' ), (string) ( $journal['residuePath'] ?? '' ) ) ) {
			return self::mark_private_evidence_recovery_required( $record, is_array( $journal ) ? $journal : array(), 'journal_invalid' );
		}
		$source = (string) ( $record['meta']['_wp_attached_file'] ?? '' );
		$residue = (string) $journal['residuePath'];
		$deterministic_residue = wp_normalize_path( $source . '.disposing-' . substr( hash( 'sha256', (string) $command_id ), 0, 16 ) );
		if ( 'disposed' === $record['retentionState'] && 'complete' === $record['journalPhase'] ) {
			$source_state = self::private_evidence_byte_path_state( $source, $record );
			$deterministic_residue_state = self::private_evidence_byte_path_state( $deterministic_residue, $record );
			return self::private_evidence_path_is_controlled( $source ) && self::private_evidence_path_is_controlled( $deterministic_residue ) && '' === $residue
				&& 'missing' === $source_state && 'missing' === $deterministic_residue_state
				? true
				: self::mark_private_evidence_recovery_required( $record, $journal, 'complete_byte_matrix_invalid', 'missing' === $deterministic_residue_state ? null : $deterministic_residue );
		}
		if ( ! self::private_evidence_path_is_controlled( $source ) || ! self::private_evidence_path_is_controlled( $residue )
			|| ! hash_equals( (string) $journal['sourcePathDigest'], hash( 'sha256', wp_normalize_path( $source ) ) )
			|| ! hash_equals( $deterministic_residue, wp_normalize_path( $residue ) ) ) {
			return self::mark_private_evidence_recovery_required( $record, $journal, 'journal_path_invalid' );
		}
		$source_state = self::private_evidence_byte_path_state( $source, $record );
		$residue_state = self::private_evidence_byte_path_state( $residue, $record );
		if ( 'disposed' === $record['retentionState'] ) {
			if ( 'valid' === $source_state || 'invalid' === $source_state || 'invalid' === $residue_state ) { return self::mark_private_evidence_recovery_required( $record, $journal, 'disposed_byte_matrix_invalid' ); }
			if ( 'valid' === $residue_state ) {
				if ( ! self::private_evidence_path_is_controlled( $residue ) || is_link( $residue ) || 'valid' !== self::private_evidence_byte_path_state( $residue, $record ) ) { return self::mark_private_evidence_recovery_required( $record, $journal, 'residue_delete_path_invalid' ); }
				$unlinked = self::private_evidence_unlink_exact( $residue, $record );
				if ( is_wp_error( $unlinked ) ) { return $unlinked; }
				$residue_state = self::private_evidence_byte_path_state( $residue, $record );
			}
			if ( 'missing' !== $residue_state ) { return new WP_Error( 'complete99_campaign_private_disposition_residue', 'Disposed private bytes remain in controlled cleanup state.', array( 'status' => 503 ) ); }
			$journal['phase'] = 'complete';
			$journal['residuePath'] = '';
			return self::transition_private_evidence_disposition( $record, $journal, 'disposed', 'complete', '' );
		}
		if ( 'disposition_recovery_required' === $record['retentionState'] ) {
			if ( 'valid' === $source_state && 'missing' === $residue_state ) {
				$journal['phase'] = 'prepared';
				unset( $journal['recoveryReason'], $journal['recoveryMarkedAt'] );
				$recovered = self::transition_private_evidence_disposition( $record, $journal, 'disposition_pending', 'prepared', $residue );
				if ( is_wp_error( $recovered ) ) { return $recovered; }
				return self::finalize_private_evidence_disposition( $attachment_id, $command_id );
			}
			if ( 'missing' === $source_state && 'valid' === $residue_state ) {
				$journal['phase'] = 'staged';
				$recovered = self::transition_private_evidence_disposition( $record, $journal, 'disposition_pending', 'staged', $residue );
				if ( is_wp_error( $recovered ) ) { return $recovered; }
				return self::finalize_private_evidence_disposition( $attachment_id, $command_id );
			}
			return new WP_Error( 'complete99_campaign_private_disposition_recovery_required', 'Private evidence disposition requires controlled operator recovery.', array( 'status' => 503 ) );
		}
		if ( 'valid' === $source_state && 'missing' === $residue_state ) {
			if ( ! self::private_evidence_path_is_controlled( $source ) || ! self::private_evidence_path_is_controlled( $residue ) || is_link( $source ) || false !== @lstat( $residue ) || 'valid' !== self::private_evidence_byte_path_state( $source, $record ) || ! rename( $source, $residue ) || ! self::private_evidence_path_is_controlled( $residue ) || is_link( $residue ) ) {
				$source_state = self::private_evidence_byte_path_state( $source, $record );
				$residue_state = self::private_evidence_byte_path_state( $residue, $record );
				if ( 'valid' === $source_state && 'missing' === $residue_state ) { return new WP_Error( 'complete99_campaign_private_disposition_stage', 'Private evidence bytes could not enter controlled disposition.', array( 'status' => 503 ) ); }
			}
			$source_state = self::private_evidence_byte_path_state( $source, $record );
			$residue_state = self::private_evidence_byte_path_state( $residue, $record );
		}
		if ( 'missing' !== $source_state || 'valid' !== $residue_state ) { return self::mark_private_evidence_recovery_required( $record, $journal, 'staged_byte_matrix_invalid' ); }
		if ( 'staged' !== $record['journalPhase'] ) {
			$journal['phase'] = 'staged';
			$staged = self::transition_private_evidence_disposition( $record, $journal, 'disposition_pending', 'staged', $residue );
			if ( is_wp_error( $staged ) ) { return $staged; }
			$record = self::private_evidence_authoritative_record( $attachment_id, array( 'commandId' => (string) $command_id, 'retentionStates' => array( 'disposition_pending' ) ), false );
			if ( is_wp_error( $record ) ) { return $record; }
		}
		$journal['phase'] = 'committed';
		$journal['committedAt'] = gmdate( 'Y-m-d\TH:i:s\Z' );
		$committed = self::transition_private_evidence_disposition( $record, $journal, 'disposed', 'committed', $residue, $journal['committedAt'] );
		if ( is_wp_error( $committed ) ) { return $committed; }
		return self::finalize_private_evidence_disposition( $attachment_id, $command_id );
	}

	private static function private_evidence_path_is_controlled( $path ) {
		$root = self::private_evidence_root();
		if ( is_wp_error( $root ) || ! is_string( $path ) || '' === $path || false !== strpos( $path, "\0" ) ) { return false; }
		$normal = wp_normalize_path( untrailingslashit( $path ) );
		$root_normal = wp_normalize_path( untrailingslashit( $root ) );
		$prefix_matches = '\\' === DIRECTORY_SEPARATOR ? 0 === stripos( $normal, trailingslashit( $root_normal ) ) : 0 === strpos( $normal, trailingslashit( $root_normal ) );
		if ( ! $prefix_matches || preg_match( '#(?:^|/)\.\.(?:/|$)#', $normal ) ) { return false; }
		$parent = dirname( $path );
		$parent_real = realpath( $parent );
		if ( false === $parent_real || is_link( $parent ) ) { return false; }
		$parent_normal = wp_normalize_path( untrailingslashit( $parent ) );
		$parent_observed = wp_normalize_path( untrailingslashit( $parent_real ) );
		$parent_matches = '\\' === DIRECTORY_SEPARATOR ? 0 === strcasecmp( $parent_normal, $parent_observed ) : hash_equals( $parent_normal, $parent_observed );
		if ( ! $parent_matches ) { return false; }
		$leaf_stat = @lstat( $path );
		if ( false !== $leaf_stat ) {
			if ( is_link( $path ) ) { return false; }
			$leaf_real = realpath( $path );
			$leaf_observed = false === $leaf_real ? '' : wp_normalize_path( untrailingslashit( $leaf_real ) );
			$leaf_matches = '\\' === DIRECTORY_SEPARATOR ? 0 === strcasecmp( $normal, $leaf_observed ) : hash_equals( $normal, $leaf_observed );
			if ( ! $leaf_matches ) { return false; }
		}
		return true;
	}

	private static function private_evidence_byte_path_state( $path, $record ) {
		if ( ! is_string( $path ) || '' === $path ) { return 'missing'; }
		if ( ! self::private_evidence_path_is_controlled( $path ) || is_link( $path ) ) { return 'invalid'; }
		if ( ! file_exists( $path ) ) { return 'missing'; }
		if ( ! is_file( $path ) || ! is_readable( $path ) || ! self::private_evidence_permissions_ready( $path ) || (int) filesize( $path ) !== (int) $record['sizeBytes'] ) { return 'invalid'; }
		$digest = hash_file( 'sha256', $path );
		return is_string( $digest ) && hash_equals( (string) $record['sha256'], $digest ) ? 'valid' : 'invalid';
	}

	/** Delete one already-verified private leaf without WordPress' filterable path substitution. */
	private static function private_evidence_unlink_exact( $path, $record ) {
		$path = (string) $path;
		$stat = false !== strpos( $path, "\0" ) ? false : lstat( $path );
		if ( ! self::private_evidence_path_is_controlled( $path ) || is_link( $path ) || ! is_array( $stat )
			|| 0100000 !== ( (int) ( $stat['mode'] ?? 0 ) & 0170000 ) || 'valid' !== self::private_evidence_byte_path_state( $path, $record ) ) {
			return new WP_Error( 'complete99_campaign_private_unlink_precondition', 'Private evidence residue failed the exact no-follow deletion precondition.', array( 'status' => 503 ) );
		}
		if ( ! unlink( $path ) ) { return new WP_Error( 'complete99_campaign_private_unlink_failed', 'Private evidence residue could not be removed exactly.', array( 'status' => 503 ) ); }
		clearstatcache( true, $path );
		if ( false !== lstat( $path ) || 'missing' !== self::private_evidence_byte_path_state( $path, $record ) ) {
			return new WP_Error( 'complete99_campaign_private_unlink_readback', 'Private evidence residue deletion failed exact byte readback.', array( 'status' => 503 ) );
		}
		return true;
	}

	private static function transition_private_evidence_disposition( $record, $journal, $retention_state, $phase, $residue, $disposed_at = '' ) {
		$journal['phase'] = (string) $phase;
		$journal['residuePath'] = (string) $residue;
		$target_journal_json = self::canonical_json( $journal );
		$transaction = self::begin_transaction( self::CAPACITY_ROLE_EVIDENCE );
		if ( is_wp_error( $transaction ) ) { return $transaction; }
		$fresh = self::private_evidence_authoritative_record( (int) $record['attachmentId'], array( 'commandId' => (string) $journal['commandId'], 'retentionStates' => array( 'disposition_pending', 'disposition_recovery_required', 'disposed' ) ), false );
		if ( is_wp_error( $fresh ) ) { self::rollback_transaction(); return $fresh; }
		$already_target = hash_equals( (string) $retention_state, (string) $fresh['retentionState'] ) && hash_equals( (string) $phase, (string) $fresh['journalPhase'] )
			&& hash_equals( (string) $residue, (string) ( $fresh['meta']['_complete99_evidence_disposal_residue_path'] ?? '' ) )
			&& hash_equals( $target_journal_json, (string) ( $fresh['meta']['_complete99_evidence_disposition_journal'] ?? '' ) )
			&& ( '' === (string) $disposed_at || hash_equals( (string) $disposed_at, (string) ( $fresh['meta']['_complete99_evidence_disposed_at'] ?? '' ) ) );
		if ( $already_target ) { return self::rollback_transaction() ? true : new WP_Error( 'complete99_campaign_private_disposition_transition_lock_unknown', 'Disposition transition lock ownership is uncertain.', array( 'status' => 503 ) ); }
		$source_journal_json = (string) ( $record['meta']['_complete99_evidence_disposition_journal'] ?? '' );
		$source_matches = hash_equals( (string) $record['retentionState'], (string) $fresh['retentionState'] ) && hash_equals( (string) $record['journalPhase'], (string) $fresh['journalPhase'] )
			&& hash_equals( (string) ( $record['meta']['_complete99_evidence_disposal_residue_path'] ?? '' ), (string) ( $fresh['meta']['_complete99_evidence_disposal_residue_path'] ?? '' ) )
			&& hash_equals( $source_journal_json, (string) ( $fresh['meta']['_complete99_evidence_disposition_journal'] ?? '' ) );
		if ( ! $source_matches ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_private_disposition_transition_stale', 'Disposition state changed before its exact transition.', array( 'status' => 409 ) ); }
		$writes = array( '_complete99_evidence_disposition_journal' => $target_journal_json, '_complete99_evidence_disposition_phase' => (string) $phase, '_complete99_evidence_disposal_residue_path' => (string) $residue, '_complete99_evidence_retention_state' => (string) $retention_state );
		if ( '' !== (string) $disposed_at ) { $writes['_complete99_evidence_disposed_at'] = (string) $disposed_at; }
		if ( 'complete' === (string) $phase ) { $writes['_complete99_evidence_disposition_next_attempt_at'] = ''; $writes['_complete99_evidence_disposition_last_error'] = ''; }
		foreach ( $writes as $key => $value ) { $stored = self::set_private_evidence_meta( (int) $record['attachmentId'], $key, $value ); if ( is_wp_error( $stored ) ) { self::rollback_transaction(); return $stored; } }
		$commit = self::commit_transaction();
		if ( is_wp_error( $commit ) ) { return $commit; }
		$verified = self::private_evidence_authoritative_record( (int) $record['attachmentId'], array( 'commandId' => (string) $journal['commandId'], 'retentionStates' => array( (string) $retention_state ) ), false );
		if ( ! is_wp_error( $verified ) && hash_equals( (string) $phase, (string) $verified['journalPhase'] ) && hash_equals( (string) $residue, (string) ( $verified['meta']['_complete99_evidence_disposal_residue_path'] ?? '' ) ) && hash_equals( $target_journal_json, (string) ( $verified['meta']['_complete99_evidence_disposition_journal'] ?? '' ) ) && ( '' === (string) $disposed_at || hash_equals( (string) $disposed_at, (string) ( $verified['meta']['_complete99_evidence_disposed_at'] ?? '' ) ) ) ) { return true; }
		return is_wp_error( $verified ) ? $verified : new WP_Error( 'complete99_campaign_private_disposition_transition_readback', 'Disposition transition failed exact readback.', array( 'status' => 503 ) );
	}

	private static function mark_private_evidence_recovery_required( $record, $journal, $reason, $residue_override = null ) {
		if ( ! is_array( $journal ) ) { $journal = array(); }
		$residue = null === $residue_override ? (string) ( $record['meta']['_complete99_evidence_disposal_residue_path'] ?? '' ) : (string) $residue_override;
		$journal['schemaVersion'] = 'complete99-private-evidence-disposition-journal/v1';
		$journal['phase'] = 'recovery_required';
		$journal['residuePath'] = $residue;
		$journal['recoveryReason'] = sanitize_key( (string) $reason );
		$journal['recoveryMarkedAt'] = gmdate( 'Y-m-d\TH:i:s\Z' );
		if ( empty( $journal['commandId'] ) ) { $journal['commandId'] = (string) ( $record['meta']['_complete99_evidence_disposition_command_id'] ?? '' ); }
		$transition = self::transition_private_evidence_disposition( $record, $journal, 'disposition_recovery_required', 'recovery_required', $residue );
		return is_wp_error( $transition ) ? $transition : new WP_Error( 'complete99_campaign_private_disposition_recovery_required', 'Private evidence disposition requires controlled operator recovery.', array( 'status' => 503 ) );
	}

	private static function record_private_evidence_disposition_retry( $attachment_id, $error_code ) {
		global $wpdb;
		$transaction = self::begin_transaction( self::CAPACITY_ROLE_EVIDENCE );
		if ( is_wp_error( $transaction ) ) { return $transaction; }
		$lock = self::is_sqlite_database() ? '' : ' FOR UPDATE';
		$wpdb->last_error = '';
		$locked = $wpdb->get_col( $wpdb->prepare( "SELECT meta_id FROM {$wpdb->postmeta} WHERE post_id=%d AND meta_key IN ('_complete99_evidence_retention_state','_complete99_evidence_disposition_attempts','_complete99_evidence_disposition_next_attempt_at') ORDER BY meta_id ASC{$lock}", (int) $attachment_id ) );
		if ( '' !== (string) $wpdb->last_error || ! is_array( $locked ) || 3 !== count( $locked ) ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_private_disposition_retry_lock', 'Private disposition retry truth could not be locked exactly.', array( 'status' => 503 ) ); }
		$record = self::private_evidence_authoritative_record( (int) $attachment_id, array( 'retentionStates' => array( 'disposition_pending', 'disposition_recovery_required', 'disposed' ) ), false );
		if ( is_wp_error( $record ) ) { self::rollback_transaction(); return $record; }
		if ( 'complete' === (string) ( $record['journalPhase'] ?? '' ) ) { return self::rollback_transaction() ? true : new WP_Error( 'complete99_campaign_private_disposition_retry_lock_unknown', 'Private disposition retry lock release is uncertain.', array( 'status' => 503 ) ); }
		$attempts = min( self::SCHEDULE_MAX_ATTEMPTS, (int) ( $record['meta']['_complete99_evidence_disposition_attempts'] ?? 0 ) + 1 );
		$retry_at = time() + min( 3600, 30 * ( 2 ** min( 6, $attempts ) ) );
		$writes = array( '_complete99_evidence_disposition_attempts' => (string) $attempts, '_complete99_evidence_disposition_next_attempt_at' => gmdate( 'Y-m-d\TH:i:s\Z', $retry_at ), '_complete99_evidence_disposition_last_error' => sanitize_key( (string) $error_code ) );
		foreach ( $writes as $key => $value ) {
			$stored = self::set_private_evidence_meta( (int) $attachment_id, $key, $value );
			if ( is_wp_error( $stored ) ) { self::rollback_transaction(); return $stored; }
		}
		$verified = self::private_evidence_authoritative_record( (int) $attachment_id, array( 'retentionStates' => array( 'disposition_pending', 'disposition_recovery_required', 'disposed' ) ), false );
		if ( is_wp_error( $verified ) || (int) ( $verified['meta']['_complete99_evidence_disposition_attempts'] ?? -1 ) !== $attempts || ! hash_equals( $writes['_complete99_evidence_disposition_next_attempt_at'], (string) ( $verified['meta']['_complete99_evidence_disposition_next_attempt_at'] ?? '' ) ) || ! hash_equals( $writes['_complete99_evidence_disposition_last_error'], (string) ( $verified['meta']['_complete99_evidence_disposition_last_error'] ?? '' ) ) ) { self::rollback_transaction(); return is_wp_error( $verified ) ? $verified : new WP_Error( 'complete99_campaign_private_disposition_retry_readback', 'Private disposition retry truth failed exact readback.', array( 'status' => 503 ) ); }
		$commit = self::commit_transaction();
		return is_wp_error( $commit ) ? $commit : $retry_at;
	}

	/** Persist bounded retry truth for a committed upload intent without creating another Ops receipt. */
	private static function record_private_evidence_upload_retry( $record, $error_code ) {
		if ( ! self::$transaction_active || ! is_array( $record ) || 'upload_pending' !== (string) ( $record['retentionState'] ?? '' ) ) {
			return new WP_Error( 'complete99_campaign_private_upload_retry_context', 'Private upload retry truth requires the locked pending intent.', array( 'status' => 503 ) );
		}
		$attempts = min( self::CACHE_RETRY_MAX_ATTEMPTS, (int) ( $record['meta']['_complete99_evidence_upload_attempts'] ?? 0 ) + 1 );
		$retry_at = time() + min( 3600, 30 * ( 2 ** min( 6, $attempts ) ) );
		$writes = array(
			'_complete99_evidence_upload_attempts' => (string) $attempts,
			'_complete99_evidence_upload_next_attempt_at' => gmdate( 'Y-m-d\TH:i:s\Z', $retry_at ),
			'_complete99_evidence_upload_last_error' => sanitize_key( (string) $error_code ),
		);
		foreach ( $writes as $key => $value ) {
			$stored = self::set_private_evidence_meta( (int) $record['attachmentId'], $key, $value );
			if ( is_wp_error( $stored ) ) { return $stored; }
		}
		$verified = self::private_evidence_authoritative_record( (int) $record['attachmentId'], array( 'retentionStates' => array( 'upload_pending' ) ), false );
		if ( is_wp_error( $verified ) || (int) ( $verified['meta']['_complete99_evidence_upload_attempts'] ?? -1 ) !== $attempts || ! hash_equals( $writes['_complete99_evidence_upload_next_attempt_at'], (string) ( $verified['meta']['_complete99_evidence_upload_next_attempt_at'] ?? '' ) ) || ! hash_equals( $writes['_complete99_evidence_upload_last_error'], (string) ( $verified['meta']['_complete99_evidence_upload_last_error'] ?? '' ) ) ) {
			return is_wp_error( $verified ) ? $verified : new WP_Error( 'complete99_campaign_private_upload_retry_readback', 'Private upload retry truth failed exact readback.', array( 'status' => 503 ) );
		}
		return $retry_at;
	}

	/** Terminalize a stale byte-less intent with one bounded lifecycle receipt and one Ops audit row. */
	private static function abandon_private_evidence_upload_intent( $record ) {
		global $wpdb;
		if ( ! self::$transaction_active || ! is_array( $record ) || 'upload_pending' !== (string) ( $record['retentionState'] ?? '' ) ) {
			return new WP_Error( 'complete99_campaign_private_upload_abandon_context', 'Private upload abandonment requires the locked pending intent.', array( 'status' => 503 ) );
		}
		$intent = json_decode( (string) ( $record['meta']['_complete99_evidence_upload_intent'] ?? '' ), true );
		$created_at = is_array( $intent ) ? strtotime( (string) ( $intent['createdAt'] ?? '' ) ) : false;
		if ( false === $created_at || time() - $created_at < self::PRIVATE_EVIDENCE_UPLOAD_ABANDON_SECONDS ) {
			return new WP_Error( 'complete99_campaign_private_upload_abandon_too_early', 'Private upload intent is still inside its protected replay window.', array( 'status' => 409 ) );
		}
		$target = (string) ( $record['meta']['_complete99_evidence_upload_target'] ?? '' );
		$staging = (string) ( $record['meta']['_complete99_evidence_upload_staging'] ?? '' );
		if ( 'missing' !== self::private_evidence_byte_path_state( $target, $record ) || 'missing' !== self::private_evidence_byte_path_state( $staging, $record ) || 'no' !== (string) $record['legalHold'] ) {
			return new WP_Error( 'complete99_campaign_private_upload_abandon_unsafe', 'Private upload abandonment requires exact missing-byte and no-hold truth.', array( 'status' => 409 ) );
		}
		$references = self::private_evidence_reference_counts( (int) $record['attachmentId'], (string) $record['sha256'], (int) $record['locationId'] );
		if ( is_wp_error( $references ) || 0 !== (int) ( $references['total'] ?? -1 ) ) {
			return is_wp_error( $references ) ? $references : new WP_Error( 'complete99_campaign_private_upload_abandon_referenced', 'A referenced upload intent cannot be abandoned.', array( 'status' => 409 ) );
		}
		$original_command = (string) ( $intent['commandId'] ?? '' );
		$command_id = 'cmp_' . substr( hash( 'sha256', 'private-evidence-upload-abandon|' . (int) $record['attachmentId'] . '|' . $original_command ), 0, 60 );
		$abandoned_at = gmdate( 'Y-m-d\TH:i:s\Z' );
		$response = array(
			'schemaVersion' => 'complete99-private-evidence-upload-abandon/v1',
			'attachmentId' => (int) $record['attachmentId'],
			'campaignId' => (string) $record['campaignId'],
			'originalOwnerUserId' => (int) $record['ownerUserId'],
			'uploadCommandId' => $original_command,
			'abandonCommandId' => $command_id,
			'abandonedAt' => $abandoned_at,
			'reason' => 'stale_upload_intent_bytes_missing',
			'publicationClaim' => false,
		);
		$receipt_json = self::canonical_json( array( 'commandId' => $command_id, 'response' => $response ) );
		if ( self::PRIVATE_EVIDENCE_MAX_LIFECYCLE_RECEIPTS <= count( (array) $record['lifecycleReceipts'] ) ) {
			return new WP_Error( 'complete99_campaign_private_upload_abandon_receipt_capacity', 'Private upload abandonment receipt capacity is exhausted.', array( 'status' => 507 ) );
		}
		$writes = array(
			'_complete99_evidence_upload_intent_state' => 'abandoned',
			'_complete99_evidence_retention_state' => 'upload_abandoned',
			'_complete99_evidence_upload_next_attempt_at' => '',
			'_complete99_evidence_upload_last_error' => 'stale_upload_intent_abandoned',
			'_complete99_evidence_upload_abandoned_at' => $abandoned_at,
		);
		foreach ( $writes as $key => $value ) {
			$stored = self::set_private_evidence_meta( (int) $record['attachmentId'], $key, $value );
			if ( is_wp_error( $stored ) ) { return $stored; }
		}
		if ( false === add_post_meta( (int) $record['attachmentId'], '_complete99_evidence_lifecycle_receipt', $receipt_json, false ) ) {
			return new WP_Error( 'complete99_campaign_private_upload_abandon_receipt_store', 'Private upload abandonment receipt could not be stored.', array( 'status' => 503 ) );
		}
		$ops = Complete99_Ops::table_names();
		$payload_digest = hash( 'sha256', self::canonical_json( $response ) );
		$event_id = 'evt_' . substr( hash( 'sha256', $command_id . '|audit' ), 0, 60 );
		$wpdb->last_error = '';
		$existing = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$ops['audit_events']} WHERE event_id=%s LIMIT 1", $event_id ), ARRAY_A );
		if ( '' !== (string) $wpdb->last_error || is_array( $existing ) || 1 !== $wpdb->insert( $ops['audit_events'], array( 'event_id' => $event_id, 'actor_user_id' => 0, 'action' => 'campaign.evidence_upload_abandoned', 'subject_type' => 'private_evidence', 'subject_id' => (string) (int) $record['attachmentId'], 'command_id' => null, 'payload_digest' => $payload_digest, 'occurred_at' => current_time( 'mysql', true ) ) ) ) {
			return new WP_Error( 'complete99_campaign_private_upload_abandon_audit_store', 'Private upload abandonment audit could not be stored exactly.', array( 'status' => 503 ) );
		}
		$verified = self::private_evidence_authoritative_record( (int) $record['attachmentId'], array( 'commandId' => $command_id, 'retentionStates' => array( 'upload_abandoned' ) ), false );
		$wpdb->last_error = '';
		$audit = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$ops['audit_events']} WHERE event_id=%s LIMIT 1", $event_id ), ARRAY_A );
		if ( is_wp_error( $verified ) || '' !== (string) $wpdb->last_error || ! is_array( $audit ) || ! hash_equals( 'campaign.evidence_upload_abandoned', (string) ( $audit['action'] ?? '' ) ) || ! hash_equals( $payload_digest, (string) ( $audit['payload_digest'] ?? '' ) ) || ! in_array( $receipt_json, (array) ( $verified['lifecycleReceipts'] ?? array() ), true ) ) {
			return is_wp_error( $verified ) ? $verified : new WP_Error( 'complete99_campaign_private_upload_abandon_readback', 'Private upload abandonment failed exact receipt and audit readback.', array( 'status' => 503 ) );
		}
		return $response;
	}

	private static function private_evidence_recovery_status() {
		$projection = self::private_evidence_inventory_projection();
		return array(
			'ready' => ! empty( $projection['ready'] ),
			'inspectable' => ! empty( $projection['inspectable'] ),
			'pending' => is_array( $projection['pending'] ?? null ) ? count( $projection['pending'] ) : null,
			'recoverablePending' => is_array( $projection['recoverablePending'] ?? null ) ? count( $projection['recoverablePending'] ) : null,
			'invalid' => is_array( $projection['invalid'] ?? null ) ? count( $projection['invalid'] ) : null,
			'nextAttemptAt' => $projection['nextAttemptAt'] ?? null,
			'recoverableNextAttemptAt' => $projection['recoverableNextAttemptAt'] ?? null,
			'invalidNextAttemptAt' => $projection['invalidNextAttemptAt'] ?? null,
			'rootFiles' => (int) ( $projection['totals']['rootFiles'] ?? 0 ),
			'rootBytes' => (int) ( $projection['totals']['rootBytes'] ?? 0 ),
		);
	}

	/** Finalize a committed upload intent whose exact target bytes already exist. */
	private static function reconcile_private_evidence_upload_intent( $attachment_id ) {
		global $wpdb;
		$transaction = self::begin_transaction( self::CAPACITY_ROLE_EVIDENCE );
		if ( is_wp_error( $transaction ) ) { return $transaction; }
		$lock = self::is_sqlite_database() ? '' : ' FOR UPDATE';
		$wpdb->last_error = '';
		$locked = $wpdb->get_col( $wpdb->prepare( "SELECT meta_id FROM {$wpdb->postmeta} WHERE post_id=%d AND (meta_key='_complete99_evidence_retention_state' OR meta_key='_complete99_evidence_upload_intent_state') ORDER BY meta_id ASC{$lock}", (int) $attachment_id ) );
		if ( '' !== (string) $wpdb->last_error || ! is_array( $locked ) || 2 !== count( $locked ) ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_private_upload_intent_lock_failed', 'Private upload intent could not be locked exactly.', array( 'status' => 503 ) ); }
		$record = self::private_evidence_authoritative_record( (int) $attachment_id, array( 'retentionStates' => array( 'upload_pending', 'upload_abandoned', 'retained' ) ), false );
		if ( is_wp_error( $record ) ) { self::rollback_transaction(); return $record; }
		if ( in_array( (string) $record['retentionState'], array( 'retained', 'upload_abandoned' ), true ) ) { return self::rollback_transaction() ? true : new WP_Error( 'complete99_campaign_private_upload_intent_lock_unknown', 'Private upload intent lock release is uncertain.', array( 'status' => 503 ) ); }
		$target = (string) ( $record['meta']['_complete99_evidence_upload_target'] ?? '' );
		$staging = (string) ( $record['meta']['_complete99_evidence_upload_staging'] ?? '' );
		$state = self::private_evidence_byte_path_state( $target, $record );
		$staging_state = self::private_evidence_byte_path_state( $staging, $record );
		if ( 'missing' === $state && 'valid' === $staging_state ) {
			if ( ! self::private_evidence_path_is_controlled( $staging ) || ! self::private_evidence_path_is_controlled( $target ) || is_link( $staging ) || false !== @lstat( $target ) || ! rename( $staging, $target ) || ! self::private_evidence_path_is_controlled( $target ) || is_link( $target ) ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_private_upload_intent_promote_failed', 'Committed private upload staging bytes could not be promoted atomically within the no-follow boundary.', array( 'status' => 503 ) ); }
			$state = self::private_evidence_byte_path_state( $target, $record );
			$staging_state = self::private_evidence_byte_path_state( $staging, $record );
		}
		if ( 'missing' === $state && 'missing' === $staging_state ) {
			$intent = json_decode( (string) ( $record['meta']['_complete99_evidence_upload_intent'] ?? '' ), true );
			$created_at = is_array( $intent ) ? strtotime( (string) ( $intent['createdAt'] ?? '' ) ) : false;
			if ( false !== $created_at && time() - $created_at >= self::PRIVATE_EVIDENCE_UPLOAD_ABANDON_SECONDS ) {
				$abandoned = self::abandon_private_evidence_upload_intent( $record );
				if ( is_wp_error( $abandoned ) ) { self::rollback_transaction(); return $abandoned; }
				$commit = self::commit_transaction();
				return is_wp_error( $commit ) ? $commit : true;
			}
			$retry_at = self::record_private_evidence_upload_retry( $record, 'private_upload_bytes_missing' );
			if ( is_wp_error( $retry_at ) ) { self::rollback_transaction(); return $retry_at; }
			$commit = self::commit_transaction();
			if ( is_wp_error( $commit ) ) { return $commit; }
			return new WP_Error( 'complete99_campaign_private_upload_intent_bytes_pending', 'Committed private upload intent is waiting for exact bytes or operator replay.', array( 'status' => 503, 'retryStored' => true, 'retryAt' => (int) $retry_at ) );
		}
		if ( 'valid' !== $state || 'missing' !== $staging_state || ! self::private_evidence_path_is_controlled( $target ) || is_link( $target ) ) { self::rollback_transaction(); return new WP_Error( 'complete99_campaign_private_upload_intent_bytes_invalid', 'Committed private upload bytes failed exact no-follow path, digest, size, or permission proof.', array( 'status' => 503 ) ); }
		foreach ( array( '_complete99_evidence_upload_intent_state' => 'finalized', '_complete99_evidence_retention_state' => 'retained', '_complete99_evidence_upload_next_attempt_at' => '', '_complete99_evidence_upload_last_error' => '' ) as $key => $value ) {
			$stored = self::set_private_evidence_meta( (int) $attachment_id, $key, $value );
			if ( is_wp_error( $stored ) ) { self::rollback_transaction(); return $stored; }
		}
		$verified = self::private_evidence_authoritative_record( (int) $attachment_id, array( 'retentionStates' => array( 'retained' ) ), true );
		if ( is_wp_error( $verified ) ) { self::rollback_transaction(); return $verified; }
		return self::commit_transaction();
	}

	/** Resume at most 50 enumerated upload/disposition journals from byte/DB truth. */
	private static function reconcile_private_evidence_dispositions() {
		$storage = self::private_evidence_transactional_storage_ready();
		if ( is_wp_error( $storage ) ) { return $storage; }
		$projection = self::private_evidence_inventory_projection();
		if ( empty( $projection['inspectable'] ) ) { return new WP_Error( 'complete99_campaign_private_recovery_query_failed', 'Private evidence recovery queue could not be inspected.', array( 'status' => 503 ) ); }
		$pending = (array) ( $projection['recoverablePending'] ?? array() );
		$now = time();
		$due = array();
		foreach ( $pending as $attachment_id => $truth ) {
			$next = strtotime( (string) ( is_array( $truth ) ? ( $truth['nextAttemptAt'] ?? '' ) : '' ) );
			if ( false === $next || $next <= $now ) { $due[] = array( 'id' => (int) $attachment_id, 'due' => false === $next ? 0 : $next ); }
		}
		usort( $due, static function ( $left, $right ) { $by_due = (int) $left['due'] <=> (int) $right['due']; return 0 !== $by_due ? $by_due : (int) $left['id'] <=> (int) $right['id']; } );
		$more = 50 < count( $due );
		$failures = array();
		foreach ( array_slice( $due, 0, 50 ) as $due_item ) {
			$attachment_id = (int) $due_item['id'];
			$record = $projection['records'][ (int) $attachment_id ] ?? null;
			if ( ! is_array( $record ) ) { $failures[] = (int) $attachment_id; continue; }
			if ( 'upload_pending' === (string) $record['retentionState'] ) {
				$result = self::reconcile_private_evidence_upload_intent( (int) $attachment_id );
			} else {
				$command_id = (string) ( $record['meta']['_complete99_evidence_disposition_command_id'] ?? '' );
				$result = self::finalize_private_evidence_disposition( (int) $attachment_id, $command_id );
			}
			if ( is_wp_error( $result ) ) {
				$failures[] = (int) $attachment_id;
				$error_data = $result->get_error_data();
				if ( 'upload_pending' !== (string) $record['retentionState'] ) { self::record_private_evidence_disposition_retry( (int) $attachment_id, $result->get_error_code() ); }
				elseif ( is_array( $error_data ) && ! empty( $error_data['retryStored'] ) ) { /* The next pass is durably deferred; continue to later IDs. */ }
			}
		}
		if ( $more ) { self::enqueue_reconcile_trigger( time() + 1 ); }
		if ( ! empty( $projection['invalid'] ) ) { return new WP_Error( 'complete99_campaign_private_recovery_invalid', 'Malformed private evidence requires operator recovery; disjoint valid records were still processed.', array( 'status' => 503, 'attachments' => array_keys( (array) $projection['invalid'] ), 'processedFailures' => $failures ) ); }
		return empty( $failures ) ? true : new WP_Error( 'complete99_campaign_private_recovery_pending', 'One or more private evidence dispositions remain in controlled recovery.', array( 'status' => 503, 'attachments' => $failures ) );
	}

	private static function private_evidence_access_url( $attachment_id ) {
		return wp_nonce_url( admin_url( 'admin-post.php?action=complete99_campaign_evidence&attachment_id=' . (int) $attachment_id ), 'complete99_campaign_evidence_' . (int) $attachment_id );
	}

	public static function serve_private_evidence() {
		$attachment_id = isset( $_GET['attachment_id'] ) ? absint( $_GET['attachment_id'] ) : 0;
		if ( 1 > $attachment_id || ! is_user_logged_in() || ! current_user_can( self::EVIDENCE_CAPABILITY )
			|| ! check_admin_referer( 'complete99_campaign_evidence_' . $attachment_id ) ) { wp_die( 'Evidence access denied.', 'Access denied', array( 'response' => 403 ) ); }
		$record = self::private_evidence_authoritative_record( $attachment_id, array( 'retentionStates' => array( 'retained' ) ), true );
		$mode = is_wp_error( $record ) ? $record : self::private_evidence_actor_mode( $record, get_current_user_id(), false );
		if ( is_wp_error( $record ) || is_wp_error( $mode ) ) { wp_die( 'Evidence verification failed.', 'Unavailable', array( 'response' => 404 ) ); }
		nocache_headers();
		header( 'Content-Type: ' . $record['mimeType'] );
		header( 'Content-Length: ' . (string) $record['sizeBytes'] );
		header( 'Content-Disposition: inline; filename="evidence-' . $attachment_id . '"' );
		readfile( $record['file'] );
		exit;
	}

	private static function normalize_human_proof( $body, $loaded ) {
		if ( ! is_array( $body ) ) { return new WP_Error( 'complete99_campaign_proof_required', 'Evidence is required.', array( 'status' => 422 ) ); }
		if ( isset( $body['proofUrl'] ) && '' !== $body['proofUrl'] ) {
			try {
				$url = self::https_url( $body['proofUrl'] );
				if ( null !== wp_parse_url( $url, PHP_URL_USER ) || null !== wp_parse_url( $url, PHP_URL_PASS ) ) { throw new \InvalidArgumentException( 'Evidence URLs cannot contain credentials.' ); }
				return array( 'kind' => 'https', 'ref' => $url, 'sha256' => hash( 'sha256', $url ) );
			} catch ( \InvalidArgumentException $error ) { return new WP_Error( 'complete99_campaign_proof_url_invalid', $error->getMessage(), array( 'status' => 422 ) ); }
		}
		$attachment_id = $body['proofAttachmentId'] ?? 0;
		$digest = self::request_digest( $body['proofSha256'] ?? '' );
		if ( is_wp_error( $digest ) ) { return $digest; }
		$record = is_int( $attachment_id ) ? self::private_evidence_authoritative_record( $attachment_id, array( 'campaignId' => (string) $loaded['state']['campaignId'], 'locationId' => (int) $loaded['state']['locationId'], 'sha256' => $digest, 'retentionStates' => array( 'retained' ) ), true ) : new WP_Error( 'complete99_campaign_proof_attachment_invalid', 'Evidence attachment identity is invalid.' );
		$mode = is_wp_error( $record ) ? $record : self::private_evidence_actor_mode( $record, get_current_user_id(), false );
		if ( ! is_int( $attachment_id ) || 1 > $attachment_id || is_wp_error( $record ) || is_wp_error( $mode ) ) {
			return new WP_Error( 'complete99_campaign_proof_attachment_invalid', 'Evidence must be a Complete99 private WordPress attachment.', array( 'status' => 422 ) );
		}
		return array( 'kind' => 'private_attachment', 'ref' => 'c99-private-attachment:' . $attachment_id . '#sha256=' . $digest, 'sha256' => $digest );
	}

	private static function evidence_summary( $reference, $include_reference ) {
		$reference = (string) $reference;
		if ( ! $include_reference ) { return array( 'kind' => 'redacted' ); }
		$summary = array( 'kind' => 'unknown', 'referenceDigest' => hash( 'sha256', $reference ) );
		if ( 0 === strpos( $reference, 'https://' ) ) {
			$summary['kind'] = 'https';
			$summary['host'] = strtolower( (string) wp_parse_url( $reference, PHP_URL_HOST ) );
		} elseif ( preg_match( '/\Ac99-private-attachment:([1-9][0-9]*)#sha256=([a-f0-9]{64})\z/', $reference, $match ) ) {
			$verified = self::private_evidence_authoritative_record( (int) $match[1], array( 'sha256' => $match[2], 'retentionStates' => array( 'retained' ) ), true );
			$mode = ! is_wp_error( $verified ) && is_array( $verified ) ? self::private_evidence_actor_mode( $verified, get_current_user_id(), false ) : $verified;
			if ( is_wp_error( $verified ) || is_wp_error( $mode ) ) { return array( 'kind' => 'redacted' ); }
			$summary = array(
				'kind'             => 'private_attachment',
				'attachmentDigest' => (string) $verified['sha256'],
				'attachmentId'     => (int) $verified['attachmentId'],
				'mimeType'         => (string) $verified['mimeType'],
				'sizeBytes'        => (int) $verified['sizeBytes'],
				'retentionUntil'   => (string) $verified['retentionUntil'],
				'accessUrl'        => self::private_evidence_access_url( (int) $verified['attachmentId'] ),
			);
		}
		if ( $include_reference && 'private_attachment' !== $summary['kind'] ) { $summary['reference'] = $reference; }
		return $summary;
	}

	private static function public_receipt_row( $row ) {
		return array( 'receiptId' => $row['receipt_id'], 'campaignId' => $row['campaign_id'], 'campaignVersion' => (int) $row['campaign_version'], 'channel' => $row['channel'], 'status' => $row['receipt_status'], 'proofLevel' => $row['proof_level'], 'externalState' => $row['external_state'], 'externalId' => (string) ( $row['external_id'] ?? '' ), 'proofRef' => $row['proof_ref'], 'materialDigest' => $row['material_digest'], 'payloadDigest' => $row['payload_digest'] );
	}

	private static function public_result_row( $row ) {
		return array( 'resultId' => $row['result_id'], 'campaignId' => $row['campaign_id'], 'campaignVersion' => (int) $row['campaign_version'], 'metricKey' => $row['metric_key'], 'value' => (float) $row['value_decimal'], 'unit' => $row['unit'], 'observationType' => $row['observation_type'], 'evidenceLevel' => $row['evidence_level'], 'sourceRef' => $row['source_ref'], 'observedAt' => mysql_to_rfc3339( $row['observed_at'] ) );
	}

	private static function public_issue_row( $row, $details ) {
		return array( 'issueId' => $row['public_id'], 'locationId' => (int) $row['location_id'], 'title' => $row['title'], 'status' => $row['status'], 'severity' => $row['severity'], 'assignedUserId' => (int) $row['assigned_user_id'], 'version' => (int) $row['version'], 'updatedAt' => mysql_to_rfc3339( $row['updated_at'] ), 'campaignLink' => $details );
	}
}
